INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u5-C1','math',3,2,'u5',2,'들이 비교하기 — 옮겨 담기·모양과 크기가 같은 그릇에 옮겨 담기·같은 컵으로 몇 번 들어가는지 세기로 들이를 견주고, 재는 그릇이 다르면 수가 달라져 같은 단위가 필요함을 알기',ARRAY['4수03-04']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u5-C2','math',3,2,'u5',2,'들이의 단위 L와 mL — 1 L = 1000 mL를 알고 「몇 L 몇 mL」를 쓰고 읽으며, 몇 L 몇 mL ↔ 몇 mL로 바꾸어 크기를 견주기',ARRAY['4수03-04']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u5-C3','math',3,2,'u5',3,'들이 어림하고 재기 — 아는 들이와 견주어 어림하고 「약」을 붙이며, 눈금 한 칸의 크기를 먼저 구해 비커를 읽고, 들이에 알맞은 단위(mL·L)를 고르기',ARRAY['4수03-04']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u5-C4','math',3,2,'u5',4,'들이의 덧셈과 뺄셈 — L는 L끼리, mL는 mL끼리 계산하고, mL끼리의 합이 1000 이상이면 1 L로 올리고 모자라면 1 L를 1000 mL로 내려 계산하기',ARRAY['4수03-04']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u5-C5','math',3,2,'u5',5,'무게 비교하기 — 양손·양팔저울로 견주고(내려간 쪽이 무거움), 바둑돌·공깃돌 같은 단위 물건의 개수로 얼마나 더 무거운지 재며, 단위 물건이 다르면 결과가 달라짐을 알기',ARRAY['4수03-04']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u5-C6','math',3,2,'u5',6,'무게의 단위 kg과 g — 1 kg = 1000 g을 알고 「몇 kg 몇 g」을 쓰고 읽으며, 몇 kg 몇 g ↔ 몇 g으로 바꾸어 크기를 견주고 저울 눈금을 읽기',ARRAY['4수03-04']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u5-C7','math',3,2,'u5',6,'무게의 단위 t — 아주 무거운 무게는 t으로 나타내고 1 t = 1000 kg임을 알아 t ↔ kg으로 바꾸기',ARRAY['4수03-04']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u5-C8','math',3,2,'u5',7,'무게 어림하고 재기 — 아는 무게(클립 약 1 g, 밀가루 1 kg)와 견주어 어림하고 「약」을 붙이며, 저울 눈금 한 칸의 크기를 먼저 구해 읽고, 알맞은 단위(g·kg·t)를 고르기',ARRAY['4수03-04']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u5-C9','math',3,2,'u5',8,'무게의 덧셈과 뺄셈 — kg은 kg끼리, g은 g끼리 계산하고, g끼리의 합이 1000 이상이면 1 kg으로 올리고 모자라면 1 kg을 1000 g으로 내려 계산하기',ARRAY['4수03-04']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u5-C10','math',3,2,'u5',9,'남김없이 나누어 담기 — 예상하고 확인하며 여러 통·봉지에 남김없이 나누어 담는 방법을 찾고, 담은 양을 모두 더해 목표와 견주며 합의 일의 자리·표로 빠짐없이 찾기',ARRAY['4수03-04']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u5-X02','math',3,'u5',ARRAY['M3-2-u5-C1']::text[],'옮겨 담은 결과를 거꾸로 읽는다(부었더니 넘쳤는데 받은 그릇의 들이가 더 많다고 한다)','넘치면 받은 그릇이 작아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u5-X03','math',3,'u5',ARRAY['M3-2-u5-C1','M3-2-u5-C5']::text[],'재는 그릇(단위 물건)이 다른데 횟수·개수만 견주거나, 횟수가 많을수록 재는 그릇이 크다고 한다','같은 단위로 재기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u5-X04','math',3,'u5',ARRAY['M3-2-u5-C2','M3-2-u5-C6']::text[],'1 L = 100 mL(1 kg = 100 g)처럼 바꾼다(3 L 150 mL → 450 mL)','1 L = 1000 mL') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u5-X05','math',3,'u5',ARRAY['M3-2-u5-C2','M3-2-u5-C6']::text[],'몇 L 몇 mL를 몇 mL로 바꿀 때 자리의 0을 빠뜨리거나 수를 이어 쓴다(7 L 50 mL → 750 mL·7500 mL)','1000씩 + 나머지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u5-X06','math',3,'u5',ARRAY['M3-2-u5-C2','M3-2-u5-C6','M3-2-u5-C7']::text[],'큰 단위와 작은 단위를 바꾸어 쓰거나 읽는다(3 L 300 mL → 3 밀리리터 300 리터)','앞이 큰 단위') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u5-X07','math',3,'u5',ARRAY['M3-2-u5-C3','M3-2-u5-C6','M3-2-u5-C8']::text[],'눈금 한 칸의 크기를 구하지 않고 칸 수를 그대로 읽거나 칸을 하나 더·덜 센다(한 칸 200 g인 7칸 → 700 g)','한 칸의 크기부터') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u5-X08','math',3,'u5',ARRAY['M3-2-u5-C3','M3-2-u5-C8']::text[],'아는 양과 견주지 않고 어림하거나 「약」을 빼거나 잘못 붙이고, 어림한 값과 잰 값이 다르면 틀렸다고 한다','어림은 약 ○○') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u5-X09','math',3,'u5',ARRAY['M3-2-u5-C3','M3-2-u5-C7','M3-2-u5-C8']::text[],'물건에 알맞지 않은 크기의 단위를 고른다(어항 약 25 mL, 코끼리 약 3 kg)','작으면 작은 단위') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u5-X10','math',3,'u5',ARRAY['M3-2-u5-C3','M3-2-u5-C8']::text[],'들이의 단위(L·mL)와 무게의 단위(kg·g·t)를 섞어 쓴다','들이 L·mL, 무게 kg·g') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u5-X11','math',3,'u5',ARRAY['M3-2-u5-C4','M3-2-u5-C9']::text[],'다른 단위의 수끼리 더하거나 뺀다(L의 수와 mL의 수를 셈한다)','같은 단위끼리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u5-X12','math',3,'u5',ARRAY['M3-2-u5-C4','M3-2-u5-C9']::text[],'작은 단위끼리의 합이 1000 이상인데 큰 단위로 올리지 않는다(3 L 1200 mL로 둔다·1 L를 빠뜨린다)','1000 mL = 1 L') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u5-X13','math',3,'u5',ARRAY['M3-2-u5-C4','M3-2-u5-C9']::text[],'작은 단위끼리 뺄 수 없을 때 1 L를 1000 mL로 내리지 않고 큰 수에서 작은 수를 빼거나, 1 L를 100 mL로 내린다','1 L → 1000 mL') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u5-X14','math',3,'u5',ARRAY['M3-2-u5-C4','M3-2-u5-C9','M3-2-u5-C10']::text[],'덧셈과 뺄셈을 바꾸어 한다(남은 양·더 필요한 양을 묻는데 더한다)','모두·남은·더 필요한') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u5-X15','math',3,'u5',ARRAY['M3-2-u5-C5']::text[],'양팔저울에서 위로 올라간 쪽이 더 무겁다고 한다','내려간 쪽이 무거움') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u5-X16','math',3,'u5',ARRAY['M3-2-u5-C5']::text[],'크기가 크면 더 무겁다고 하거나, 단위 물건의 종류는 보지 않고 개수만 같으면 무게가 같다고 한다','크기 ≠ 무게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u5-X17','math',3,'u5',ARRAY['M3-2-u5-C7']::text[],'1 t = 100 kg(또는 10000 kg)처럼 바꾼다(6 t → 600 kg)','1 t = 1000 kg') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u5-X18','math',3,'u5',ARRAY['M3-2-u5-C4','M3-2-u5-C9','M3-2-u5-C10']::text[],'남김없이 담기에서 담은 양을 모두 더해 목표와 견주지 않는다(통의 수만 맞추거나 합이 모자라거나 넘친다)','모두 더해 확인하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u5-X19','math',3,'u5',ARRAY['M3-2-u5-C10']::text[],'통의 개수와 통에 담는 양을 헷갈리거나, 있는 통보다 많이 쓴다','통 수 × 통 하나의 양') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u5-X20','math',3,'u5',ARRAY['M3-2-u5-C1','M3-2-u5-C2','M3-2-u5-C3','M3-2-u5-C4','M3-2-u5-C5','M3-2-u5-C6','M3-2-u5-C7','M3-2-u5-C8','M3-2-u5-C9','M3-2-u5-C10']::text[],'묻는 말을 거꾸로 읽는다 — 많은↔적은, 무거운↔가벼운, 남은↔쓴, 더↔덜','물음의 핵심 말에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u5-X21','math',3,'u5',ARRAY['M3-2-u5-C1','M3-2-u5-C2','M3-2-u5-C3','M3-2-u5-C5','M3-2-u5-C6','M3-2-u5-C8','M3-2-u5-C10']::text[],'견줄 수 있는데도 「같다」·「알 수 없다」고 하거나, 차를 묻는데 한쪽의 양을 답한다','단위를 맞추어 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L02_basic#1','math',3,2,'u5','L02','g3_2_math_u5_L02_basic','lesson_basic','M3-2-u5-C1',1,'mc','auto','빨간색 컵에 물을 가득 채워 초록색 컵에 옮겨 담았더니 가득 차지 않았어요. 들이가 더 많은 것은 무엇인가요?',ARRAY['M3-2-u5-X02','M3-2-u5-X21']::text[],true,'{"seq":1,"concept":"M3-2-u5-C1","difficulty":1,"kind":"mc","stem":"빨간색 컵에 물을 가득 채워 초록색 컵에 옮겨 담았더니 가득 차지 않았어요. 들이가 더 많은 것은 무엇인가요?","options":[{"t":"초록색 컵","correct":true},{"t":"빨간색 컵","mis":"M3-2-u5-X02"},{"t":"두 그릇의 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["빨간색 컵에 가득 담은 물을 초록색 컵에 부었어요.","가득 차지 않았어요 — 초록색 컵에 빈 곳이 남았으니 초록색 컵의 들이가 더 많아요.","들이가 더 많은 것은 초록색 컵이에요."],"asset":{"type":"cups","items":[{"label":"초록색 컵","w":3,"h":4},{"label":"빨간색 컵","w":2,"h":5}],"pour":{"from":1,"to":0}},"variant_rule":{"alt":[{"stem":"물병에 물을 가득 채워 보온병에 옮겨 담았더니 넘쳤어요. 들이가 더 적은 것은 무엇인가요?","options":[{"t":"보온병","correct":true},{"t":"물병","mis":"M3-2-u5-X20"},{"t":"두 그릇의 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["물병에 가득 담은 물을 보온병에 부었어요.","넘쳤어요 — 물병의 들이가 더 많아서 다 담기지 못했어요.","들이가 더 적은 것은 보온병이에요."],"asset":{"type":"cups","items":[{"label":"물병","w":4,"h":6},{"label":"보온병","w":4,"h":4}],"pour":{"from":0,"to":1}}},{"stem":"㉮ 컵에 물을 가득 채워 ㉯ 컵에 옮겨 담았더니 가득 차지 않았어요. 들이가 더 많은 것은 무엇인가요?","options":[{"t":"㉯ 컵","correct":true},{"t":"㉮ 컵","mis":"M3-2-u5-X02"},{"t":"두 그릇의 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["㉮ 컵에 가득 담은 물을 ㉯ 컵에 부었어요.","가득 차지 않았어요 — ㉯ 컵에 빈 곳이 남았으니 ㉯ 컵의 들이가 더 많아요.","들이가 더 많은 것은 ㉯ 컵이에요."],"asset":{"type":"cups","items":[{"label":"㉮ 컵","w":3,"h":5},{"label":"㉯ 컵","w":3,"h":6}],"pour":{"from":0,"to":1}}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L02_basic#2','math',3,2,'u5','L02','g3_2_math_u5_L02_basic','lesson_basic','M3-2-u5-C2',1,'sa','auto','3 L 150 mL는 몇 mL인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u5-C2","difficulty":1,"kind":"sa","stem":"3 L 150 mL는 몇 mL인가요? 숫자로 쓰세요.","answer":["3150"],"explanation":["1 L = 1000 mL — 3 L = 3000 mL.","3000 mL + 150 mL = 3150 mL.","3 L 150 mL = 3150 mL."],"variant_rule":{"alt":[{"stem":"9 L 80 mL는 몇 mL인가요? 숫자로 쓰세요.","answer":["9080"],"explanation":["1 L = 1000 mL — 9 L = 9000 mL.","9000 mL + 80 mL = 9080 mL.","9 L 80 mL = 9080 mL."],"asset":null},{"stem":"6 L 70 mL는 몇 mL인가요? 숫자로 쓰세요.","answer":["6070"],"explanation":["1 L = 1000 mL — 6 L = 6000 mL.","6000 mL + 70 mL = 6070 mL.","6 L 70 mL = 6070 mL."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L02_basic#3','math',3,2,'u5','L02','g3_2_math_u5_L02_basic','lesson_basic','M3-2-u5-C1',1,'mc','auto','물병과 꽃병에 물을 가득 채워 모양과 크기가 같은 수조에 각각 옮겨 담았어요. 들이가 더 많은 것은 무엇인가요?',ARRAY['M3-2-u5-X20','M3-2-u5-X21']::text[],true,'{"seq":3,"concept":"M3-2-u5-C1","difficulty":1,"kind":"mc","stem":"물병과 꽃병에 물을 가득 채워 모양과 크기가 같은 수조에 각각 옮겨 담았어요. 들이가 더 많은 것은 무엇인가요?","options":[{"t":"물병","correct":true},{"t":"꽃병","mis":"M3-2-u5-X20"},{"t":"두 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["모양과 크기가 같은 수조라서 물의 높이로 견줄 수 있어요.","물병의 물을 담은 수조의 물이 더 높아요.","들이가 더 많은 것은 물병이에요."],"asset":{"type":"cups","items":[{"label":"물병 물","w":3,"h":5,"fill":0.8},{"label":"꽃병 물","w":3,"h":5,"fill":0.5}],"same":true},"variant_rule":{"alt":[{"stem":"냄비와 대접에 물을 가득 채워 모양과 크기가 같은 수조에 각각 옮겨 담았어요. 들이가 더 많은 것은 무엇인가요?","options":[{"t":"냄비","correct":true},{"t":"대접","mis":"M3-2-u5-X20"},{"t":"두 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["모양과 크기가 같은 수조라서 물의 높이로 견줄 수 있어요.","냄비의 물을 담은 수조의 물이 더 높아요.","들이가 더 많은 것은 냄비예요."],"asset":{"type":"cups","items":[{"label":"냄비 물","w":3,"h":5,"fill":0.9},{"label":"대접 물","w":3,"h":5,"fill":0.5}],"same":true}},{"stem":"보온병과 우유병에 물을 가득 채워 모양과 크기가 같은 수조에 각각 옮겨 담았어요. 들이가 더 많은 것은 무엇인가요?","options":[{"t":"우유병","correct":true},{"t":"보온병","mis":"M3-2-u5-X20"},{"t":"두 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["모양과 크기가 같은 수조라서 물의 높이로 견줄 수 있어요.","우유병의 물을 담은 수조의 물이 더 높아요.","들이가 더 많은 것은 우유병이에요."],"asset":{"type":"cups","items":[{"label":"보온병 물","w":3,"h":5,"fill":0.4},{"label":"우유병 물","w":3,"h":5,"fill":0.7}],"same":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L02_basic#4','math',3,2,'u5','L02','g3_2_math_u5_L02_basic','lesson_basic','M3-2-u5-C2',1,'sa','auto','4800 mL는 몇 L 몇 mL인가요? L 앞에 올 수를 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u5-C2","difficulty":1,"kind":"sa","stem":"4800 mL는 몇 L 몇 mL인가요? L 앞에 올 수를 쓰세요.","answer":["4"],"explanation":["1000 mL = 1 L예요.","4800 = 4000 + 800.","4800 mL = 4 L 800 mL — L 앞은 4."],"variant_rule":{"alt":[{"stem":"8646 mL는 몇 L 몇 mL인가요? L 앞에 올 수를 쓰세요.","answer":["8"],"explanation":["1000 mL = 1 L예요.","8646 = 8000 + 646.","8646 mL = 8 L 646 mL — L 앞은 8."],"asset":null},{"stem":"6449 mL는 몇 L 몇 mL인가요? L 앞에 올 수를 쓰세요.","answer":["6"],"explanation":["1000 mL = 1 L예요.","6449 = 6000 + 449.","6449 mL = 6 L 449 mL — L 앞은 6."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L02_basic#5','math',3,2,'u5','L02','g3_2_math_u5_L02_basic','lesson_basic','M3-2-u5-C1',2,'sa','auto','㉮ 그릇에는 작은 컵으로 8번, ㉯ 그릇에는 같은 작은 컵으로 5번 물이 들어갔어요. ㉮ 그릇은 ㉯ 그릇보다 작은 컵 몇 개만큼 물이 더 많이 들어가나요?','{}'::text[],true,'{"seq":5,"concept":"M3-2-u5-C1","difficulty":2,"kind":"sa","stem":"㉮ 그릇에는 작은 컵으로 8번, ㉯ 그릇에는 같은 작은 컵으로 5번 물이 들어갔어요. ㉮ 그릇은 ㉯ 그릇보다 작은 컵 몇 개만큼 물이 더 많이 들어가나요?","answer":["3"],"explanation":["같은 작은 컵으로 재었으니 횟수로 견줄 수 있어요.","㉮ 8번, ㉯ 5번이에요.","8 − 5 = 3 — 작은 컵 3개만큼 더 많아요."],"variant_rule":{"alt":[{"stem":"㉮ 그릇에는 작은 컵으로 6번, ㉯ 그릇에는 같은 작은 컵으로 8번 물이 들어갔어요. ㉯ 그릇은 ㉮ 그릇보다 작은 컵 몇 개만큼 물이 더 많이 들어가나요?","answer":["2"],"explanation":["같은 작은 컵으로 재었으니 횟수로 견줄 수 있어요.","㉮ 6번, ㉯ 8번이에요.","8 − 6 = 2 — 작은 컵 2개만큼 더 많아요."],"asset":null},{"stem":"㉮ 그릇에는 작은 컵으로 11번, ㉯ 그릇에는 같은 작은 컵으로 7번 물이 들어갔어요. ㉮ 그릇은 ㉯ 그릇보다 작은 컵 몇 개만큼 물이 더 많이 들어가나요?","answer":["4"],"explanation":["같은 작은 컵으로 재었으니 횟수로 견줄 수 있어요.","㉮ 11번, ㉯ 7번이에요.","11 − 7 = 4 — 작은 컵 4개만큼 더 많아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L02_basic#6','math',3,2,'u5','L02','g3_2_math_u5_L02_basic','lesson_basic','M3-2-u5-C2',2,'mc','auto','3 L 300 mL를 바르게 읽은 것은 무엇인가요?',ARRAY['M3-2-u5-X06','M3-2-u5-X05']::text[],true,'{"seq":6,"concept":"M3-2-u5-C2","difficulty":2,"kind":"mc","stem":"3 L 300 mL를 바르게 읽은 것은 무엇인가요?","options":[{"t":"3 리터 300 밀리리터","correct":true},{"t":"3 밀리리터 300 리터","mis":"M3-2-u5-X06"},{"t":"3300 리터","mis":"M3-2-u5-X05"},{"t":"3 리터 300 리터","mis":"M3-2-u5-X06"}],"explanation":["1 L는 1 리터라고 읽어요.","3 L 300 mL의 앞은 리터, 뒤는 밀리리터.","3 L 300 mL — 3 리터 300 밀리리터."],"variant_rule":{"alt":[{"stem":"4 L 80 mL를 바르게 읽은 것은 무엇인가요?","options":[{"t":"4 리터 80 밀리리터","correct":true},{"t":"4 밀리리터 80 리터","mis":"M3-2-u5-X06"},{"t":"480 리터","mis":"M3-2-u5-X05"},{"t":"4 리터 80 리터","mis":"M3-2-u5-X06"}],"explanation":["1 L는 1 리터라고 읽어요.","4 L 80 mL의 앞은 리터, 뒤는 밀리리터.","4 L 80 mL — 4 리터 80 밀리리터."],"asset":null},{"stem":"5 L 900 mL를 바르게 읽은 것은 무엇인가요?","options":[{"t":"5 리터 900 밀리리터","correct":true},{"t":"5 밀리리터 900 리터","mis":"M3-2-u5-X06"},{"t":"5900 리터","mis":"M3-2-u5-X05"},{"t":"5 리터 900 리터","mis":"M3-2-u5-X06"}],"explanation":["1 L는 1 리터라고 읽어요.","5 L 900 mL의 앞은 리터, 뒤는 밀리리터.","5 L 900 mL — 5 리터 900 밀리리터."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L02_basic#7','math',3,2,'u5','L02','g3_2_math_u5_L02_basic','lesson_basic','M3-2-u5-C1',2,'mc','auto','같은 컵으로 물을 부어 그릇을 가득 채웠어요. 양동이 11번, 어항 3번, 물뿌리개 9번이 들어갔어요. 들이가 많은 것부터 차례로 쓴 것은 무엇인가요?',ARRAY['M3-2-u5-X20','M3-2-u5-X03']::text[],true,'{"seq":7,"concept":"M3-2-u5-C1","difficulty":2,"kind":"mc","stem":"같은 컵으로 물을 부어 그릇을 가득 채웠어요. 양동이 11번, 어항 3번, 물뿌리개 9번이 들어갔어요. 들이가 많은 것부터 차례로 쓴 것은 무엇인가요?","options":[{"t":"양동이, 물뿌리개, 어항","correct":true},{"t":"어항, 물뿌리개, 양동이","mis":"M3-2-u5-X20"},{"t":"양동이, 어항, 물뿌리개","mis":"M3-2-u5-X03"},{"t":"어항, 양동이, 물뿌리개","mis":"M3-2-u5-X03"}],"explanation":["같은 컵으로 재었으니 부은 횟수가 많을수록 들이가 많아요.","횟수: 양동이 11번, 어항 3번, 물뿌리개 9번.","많은 것부터: 양동이, 물뿌리개, 어항."],"variant_rule":{"alt":[{"stem":"같은 컵으로 물을 부어 그릇을 가득 채웠어요. 물통 11번, 냄비 7번, 주전자 12번이 들어갔어요. 들이가 많은 것부터 차례로 쓴 것은 무엇인가요?","options":[{"t":"주전자, 물통, 냄비","correct":true},{"t":"냄비, 물통, 주전자","mis":"M3-2-u5-X20"},{"t":"물통, 냄비, 주전자","mis":"M3-2-u5-X03"},{"t":"물통, 주전자, 냄비","mis":"M3-2-u5-X03"}],"explanation":["같은 컵으로 재었으니 부은 횟수가 많을수록 들이가 많아요.","횟수: 물통 11번, 냄비 7번, 주전자 12번.","많은 것부터: 주전자, 물통, 냄비."],"asset":null},{"stem":"같은 컵으로 물을 부어 그릇을 가득 채웠어요. 보온병 10번, 물병 9번, 세제 통 6번이 들어갔어요. 들이가 많은 것부터 차례로 쓴 것은 무엇인가요?","options":[{"t":"보온병, 물병, 세제 통","correct":true},{"t":"세제 통, 물병, 보온병","mis":"M3-2-u5-X20"},{"t":"보온병, 세제 통, 물병","mis":"M3-2-u5-X03"},{"t":"물병, 보온병, 세제 통","mis":"M3-2-u5-X03"}],"explanation":["같은 컵으로 재었으니 부은 횟수가 많을수록 들이가 많아요.","횟수: 보온병 10번, 물병 9번, 세제 통 6번.","많은 것부터: 보온병, 물병, 세제 통."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L02_basic#8','math',3,2,'u5','L02','g3_2_math_u5_L02_basic','lesson_basic','M3-2-u5-C1',2,'ox','auto','같은 물통에 물을 가득 채우는 데 그릇으로는 2번, 컵으로는 4번 부었어요. 「컵으로 부은 횟수가 더 많으니 컵의 들이가 그릇보다 더 많아.」',ARRAY['M3-2-u5-X03']::text[],true,'{"seq":8,"concept":"M3-2-u5-C1","difficulty":2,"kind":"ox","stem":"같은 물통에 물을 가득 채우는 데 그릇으로는 2번, 컵으로는 4번 부었어요. 「컵으로 부은 횟수가 더 많으니 컵의 들이가 그릇보다 더 많아.」","answer":"X","reason_options":[{"t":"들이가 적은 그릇일수록 더 여러 번 부어야 해서","correct":true},{"t":"횟수가 많을수록 그릇이 커서","mis":"M3-2-u5-X03"}],"mis":"M3-2-u5-X03","explanation":["같은 물통을 채우려면 들이가 적은 그릇일수록 많이 부어야 해요.","그릇 2번 < 컵 4번.","컵의 들이가 더 적어요 — ×."],"variant_rule":{"alt":[{"stem":"같은 물통에 물을 가득 채우는 데 대접으로는 2번, 종이컵으로는 6번 부었어요. 「종이컵으로 부은 횟수가 더 많으니 종이컵의 들이가 대접보다 더 많아.」","answer":"X","reason_options":[{"t":"들이가 적은 그릇일수록 더 여러 번 부어야 해서","correct":true},{"t":"횟수가 많을수록 그릇이 커서","mis":"M3-2-u5-X03"}],"explanation":["같은 물통을 채우려면 들이가 적은 그릇일수록 많이 부어야 해요.","대접 2번 < 종이컵 6번.","종이컵의 들이가 더 적어요 — ×."],"asset":null},{"stem":"같은 물통에 물을 가득 채우는 데 대접으로는 3번, 종이컵으로는 9번 부었어요. 「종이컵으로 부은 횟수가 더 많으니 종이컵의 들이가 대접보다 더 많아.」","answer":"X","reason_options":[{"t":"들이가 적은 그릇일수록 더 여러 번 부어야 해서","correct":true},{"t":"횟수가 많을수록 그릇이 커서","mis":"M3-2-u5-X03"}],"explanation":["같은 물통을 채우려면 들이가 적은 그릇일수록 많이 부어야 해요.","대접 3번 < 종이컵 9번.","종이컵의 들이가 더 적어요 — ×."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L02_basic#9','math',3,2,'u5','L02','g3_2_math_u5_L02_basic','lesson_basic','M3-2-u5-C2',2,'mc','auto','㉮는 5 L 50 mL, ㉯는 4850 mL예요. 들이가 더 많은 것은 무엇인가요?',ARRAY['M3-2-u5-X04','M3-2-u5-X21']::text[],true,'{"seq":9,"concept":"M3-2-u5-C2","difficulty":2,"kind":"mc","stem":"㉮는 5 L 50 mL, ㉯는 4850 mL예요. 들이가 더 많은 것은 무엇인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M3-2-u5-X04"},{"t":"두 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"단위가 달라서 견줄 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["한 가지 단위로 바꾸어 견주어요.","5 L 50 mL = 5050 mL.","5050 mL > 4850 mL — 들이가 더 많은 것은 ㉮예요."],"variant_rule":{"alt":[{"stem":"㉮는 1 L 550 mL, ㉯는 2150 mL예요. 들이가 더 많은 것은 무엇인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M3-2-u5-X20"},{"t":"두 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"단위가 달라서 견줄 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["한 가지 단위로 바꾸어 견주어요.","1 L 550 mL = 1550 mL.","1550 mL < 2150 mL — 들이가 더 많은 것은 ㉯예요."],"asset":null},{"stem":"㉮는 6 L 50 mL, ㉯는 5600 mL예요. 들이가 더 많은 것은 무엇인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M3-2-u5-X04"},{"t":"두 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"단위가 달라서 견줄 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["한 가지 단위로 바꾸어 견주어요.","6 L 50 mL = 6050 mL.","6050 mL > 5600 mL — 들이가 더 많은 것은 ㉮예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L02_basic#10','math',3,2,'u5','L02','g3_2_math_u5_L02_basic','lesson_basic','M3-2-u5-C2',3,'mc','auto','1 L 200 mL, 1 L 8 mL, 1 L 20 mL 중에서 들이가 가장 많은 것은 무엇인가요?',ARRAY['M3-2-u5-X20','M3-2-u5-X05','M3-2-u5-X21']::text[],true,'{"seq":10,"concept":"M3-2-u5-C2","difficulty":3,"kind":"mc","stem":"1 L 200 mL, 1 L 8 mL, 1 L 20 mL 중에서 들이가 가장 많은 것은 무엇인가요?","options":[{"t":"1 L 200 mL","correct":true},{"t":"1 L 8 mL","mis":"M3-2-u5-X20"},{"t":"1 L 20 mL","mis":"M3-2-u5-X05"},{"t":"모두 같아요","mis":"M3-2-u5-X21"}],"explanation":["모두 mL로 바꾸어요.","1200 mL, 1008 mL, 1020 mL.","가장 많은 것은 1 L 200 mL예요."],"variant_rule":{"alt":[{"stem":"1 L 30 mL, 1003 mL, 1 L 900 mL 중에서 들이가 가장 많은 것은 무엇인가요?","options":[{"t":"1 L 900 mL","correct":true},{"t":"1003 mL","mis":"M3-2-u5-X20"},{"t":"1 L 30 mL","mis":"M3-2-u5-X05"},{"t":"모두 같아요","mis":"M3-2-u5-X21"}],"explanation":["모두 mL로 바꾸어요.","1030 mL, 1003 mL, 1900 mL.","가장 많은 것은 1 L 900 mL예요."],"asset":null},{"stem":"1 L 7 mL, 1 L 20 mL, 1800 mL 중에서 들이가 가장 많은 것은 무엇인가요?","options":[{"t":"1800 mL","correct":true},{"t":"1 L 7 mL","mis":"M3-2-u5-X20"},{"t":"1 L 20 mL","mis":"M3-2-u5-X05"},{"t":"모두 같아요","mis":"M3-2-u5-X21"}],"explanation":["모두 mL로 바꾸어요.","1007 mL, 1020 mL, 1800 mL.","가장 많은 것은 1800 mL예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L02_challenge#1','math',3,2,'u5','L02','g3_2_math_u5_L02_challenge','lesson_challenge','M3-2-u5-C2',2,'mc','auto','7 L 50 mL는 몇 mL인가요?',ARRAY['M3-2-u5-X04','M3-2-u5-X05','M3-2-u5-X11']::text[],true,'{"seq":1,"concept":"M3-2-u5-C2","difficulty":2,"kind":"mc","stem":"7 L 50 mL는 몇 mL인가요?","options":[{"t":"7050 mL","correct":true},{"t":"750 mL","mis":"M3-2-u5-X04"},{"t":"7500 mL","mis":"M3-2-u5-X05"},{"t":"57 mL","mis":"M3-2-u5-X11"}],"explanation":["1 L = 1000 mL — 7 L = 7000 mL.","7000 mL + 50 mL = 7050 mL.","7 L 50 mL = 7050 mL."],"variant_rule":{"alt":[{"stem":"6 L 354 mL는 몇 mL인가요?","options":[{"t":"6354 mL","correct":true},{"t":"60354 mL","mis":"M3-2-u5-X05"},{"t":"954 mL","mis":"M3-2-u5-X04"},{"t":"360 mL","mis":"M3-2-u5-X11"}],"explanation":["1 L = 1000 mL — 6 L = 6000 mL.","6000 mL + 354 mL = 6354 mL.","6 L 354 mL = 6354 mL."],"asset":null},{"stem":"3 L 529 mL는 몇 mL인가요?","options":[{"t":"3529 mL","correct":true},{"t":"30529 mL","mis":"M3-2-u5-X05"},{"t":"829 mL","mis":"M3-2-u5-X04"},{"t":"532 mL","mis":"M3-2-u5-X11"}],"explanation":["1 L = 1000 mL — 3 L = 3000 mL.","3000 mL + 529 mL = 3529 mL.","3 L 529 mL = 3529 mL."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L02_challenge#2','math',3,2,'u5','L02','g3_2_math_u5_L02_challenge','lesson_challenge','M3-2-u5-C1',2,'mc','auto','머그잔에 물을 가득 채워 유리컵에 옮겨 담았더니 넘쳤어요. 들이가 더 적은 것은 무엇인가요?',ARRAY['M3-2-u5-X20','M3-2-u5-X21']::text[],true,'{"seq":2,"concept":"M3-2-u5-C1","difficulty":2,"kind":"mc","stem":"머그잔에 물을 가득 채워 유리컵에 옮겨 담았더니 넘쳤어요. 들이가 더 적은 것은 무엇인가요?","options":[{"t":"유리컵","correct":true},{"t":"머그잔","mis":"M3-2-u5-X20"},{"t":"두 그릇의 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["머그잔에 가득 담은 물을 유리컵에 부었어요.","넘쳤어요 — 머그잔의 들이가 더 많아서 다 담기지 못했어요.","들이가 더 적은 것은 유리컵이에요."],"asset":{"type":"cups","items":[{"label":"머그잔","w":4,"h":4},{"label":"유리컵","w":4,"h":3}],"pour":{"from":0,"to":1}},"variant_rule":{"alt":[{"stem":"주스병에 물을 가득 채워 우유갑에 옮겨 담았더니 넘쳤어요. 들이가 더 많은 것은 무엇인가요?","options":[{"t":"주스병","correct":true},{"t":"우유갑","mis":"M3-2-u5-X02"},{"t":"두 그릇의 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["주스병에 가득 담은 물을 우유갑에 부었어요.","넘쳤어요 — 주스병의 들이가 더 많아서 다 담기지 못했어요.","들이가 더 많은 것은 주스병이에요."],"asset":{"type":"cups","items":[{"label":"우유갑","w":3,"h":4},{"label":"주스병","w":3,"h":5}],"pour":{"from":1,"to":0}}},{"stem":"초록색 컵에 물을 가득 채워 빨간색 컵에 옮겨 담았더니 넘쳤어요. 들이가 더 많은 것은 무엇인가요?","options":[{"t":"초록색 컵","correct":true},{"t":"빨간색 컵","mis":"M3-2-u5-X02"},{"t":"두 그릇의 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["초록색 컵에 가득 담은 물을 빨간색 컵에 부었어요.","넘쳤어요 — 초록색 컵의 들이가 더 많아서 다 담기지 못했어요.","들이가 더 많은 것은 초록색 컵이에요."],"asset":{"type":"cups","items":[{"label":"초록색 컵","w":2,"h":6},{"label":"빨간색 컵","w":2,"h":5}],"pour":{"from":0,"to":1}}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L02_challenge#3','math',3,2,'u5','L02','g3_2_math_u5_L02_challenge','lesson_challenge','M3-2-u5-C2',3,'mc','auto','㉮는 6 L 80 mL, ㉯는 6805 mL예요. 들이가 더 많은 것은 무엇인가요?',ARRAY['M3-2-u5-X20','M3-2-u5-X21']::text[],true,'{"seq":3,"concept":"M3-2-u5-C2","difficulty":3,"kind":"mc","stem":"㉮는 6 L 80 mL, ㉯는 6805 mL예요. 들이가 더 많은 것은 무엇인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M3-2-u5-X20"},{"t":"두 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"단위가 달라서 견줄 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["한 가지 단위로 바꾸어 견주어요.","6 L 80 mL = 6080 mL.","6080 mL < 6805 mL — 들이가 더 많은 것은 ㉯예요."],"variant_rule":{"alt":[{"stem":"㉮는 5 L 80 mL, ㉯는 5805 mL예요. 들이가 더 많은 것은 무엇인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M3-2-u5-X20"},{"t":"두 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"단위가 달라서 견줄 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["한 가지 단위로 바꾸어 견주어요.","5 L 80 mL = 5080 mL.","5080 mL < 5805 mL — 들이가 더 많은 것은 ㉯예요."],"asset":null},{"stem":"㉮는 4 L 10 mL, ㉯는 4100 mL예요. 들이가 더 많은 것은 무엇인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M3-2-u5-X20"},{"t":"두 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"단위가 달라서 견줄 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["한 가지 단위로 바꾸어 견주어요.","4 L 10 mL = 4010 mL.","4010 mL < 4100 mL — 들이가 더 많은 것은 ㉯예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L02_challenge#4','math',3,2,'u5','L02','g3_2_math_u5_L02_challenge','lesson_challenge','M3-2-u5-C1',3,'mc','auto','㉮ 물통은 큰 컵으로 7번, ㉯ 물통은 작은 컵으로 8번 부어 가득 채웠어요. 이것만 보고 들이를 바르게 말한 것은 무엇인가요?',ARRAY['M3-2-u5-X03','M3-2-u5-X21']::text[],true,'{"seq":4,"concept":"M3-2-u5-C1","difficulty":3,"kind":"mc","stem":"㉮ 물통은 큰 컵으로 7번, ㉯ 물통은 작은 컵으로 8번 부어 가득 채웠어요. 이것만 보고 들이를 바르게 말한 것은 무엇인가요?","options":[{"t":"재는 컵이 달라서 알 수 없어요","correct":true},{"t":"㉯ 물통의 들이가 더 많아요","mis":"M3-2-u5-X03"},{"t":"㉮ 물통의 들이가 더 많아요","mis":"M3-2-u5-X03"},{"t":"두 물통의 들이가 같아요","mis":"M3-2-u5-X21"}],"explanation":["㉮는 큰 컵, ㉯는 작은 컵 — 재는 그릇이 달라요.","횟수만으로는 들이를 견줄 수 없어요.","같은 컵(같은 단위)으로 재야 견줄 수 있어요."],"variant_rule":{"alt":[{"stem":"㉮ 물통은 큰 컵으로 5번, ㉯ 물통은 작은 컵으로 6번 부어 가득 채웠어요. 이것만 보고 들이를 바르게 말한 것은 무엇인가요?","options":[{"t":"재는 컵이 달라서 알 수 없어요","correct":true},{"t":"㉯ 물통의 들이가 더 많아요","mis":"M3-2-u5-X03"},{"t":"㉮ 물통의 들이가 더 많아요","mis":"M3-2-u5-X03"},{"t":"두 물통의 들이가 같아요","mis":"M3-2-u5-X21"}],"explanation":["㉮는 큰 컵, ㉯는 작은 컵 — 재는 그릇이 달라요.","횟수만으로는 들이를 견줄 수 없어요.","같은 컵(같은 단위)으로 재야 견줄 수 있어요."],"asset":null},{"stem":"㉮ 물통은 큰 컵으로 6번, ㉯ 물통은 작은 컵으로 8번 부어 가득 채웠어요. 이것만 보고 들이를 바르게 말한 것은 무엇인가요?","options":[{"t":"재는 컵이 달라서 알 수 없어요","correct":true},{"t":"㉯ 물통의 들이가 더 많아요","mis":"M3-2-u5-X03"},{"t":"㉮ 물통의 들이가 더 많아요","mis":"M3-2-u5-X03"},{"t":"두 물통의 들이가 같아요","mis":"M3-2-u5-X21"}],"explanation":["㉮는 큰 컵, ㉯는 작은 컵 — 재는 그릇이 달라요.","횟수만으로는 들이를 견줄 수 없어요.","같은 컵(같은 단위)으로 재야 견줄 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L02_challenge#5','math',3,2,'u5','L02','g3_2_math_u5_L02_challenge','lesson_challenge','M3-2-u5-C2',3,'sa','auto','6040 mL는 몇 L 몇 mL인가요? L 앞에 올 수를 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u5-C2","difficulty":3,"kind":"sa","stem":"6040 mL는 몇 L 몇 mL인가요? L 앞에 올 수를 쓰세요.","answer":["6"],"explanation":["1000 mL = 1 L예요.","6040 = 6000 + 40.","6040 mL = 6 L 40 mL — L 앞은 6."],"variant_rule":{"alt":[{"stem":"3080 mL는 몇 L 몇 mL인가요? L 앞에 올 수를 쓰세요.","answer":["3"],"explanation":["1000 mL = 1 L예요.","3080 = 3000 + 80.","3080 mL = 3 L 80 mL — L 앞은 3."],"asset":null},{"stem":"4040 mL는 몇 L 몇 mL인가요? L 앞에 올 수를 쓰세요.","answer":["4"],"explanation":["1000 mL = 1 L예요.","4040 = 4000 + 40.","4040 mL = 4 L 40 mL — L 앞은 4."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L02_challenge#6','math',3,2,'u5','L02','g3_2_math_u5_L02_challenge','lesson_challenge','M3-2-u5-C2',3,'error','auto','들이의 단위를 바꾸며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u5-X05','M3-2-u5-X21']::text[],true,'{"seq":6,"concept":"M3-2-u5-C2","difficulty":3,"kind":"error","stem":"들이의 단위를 바꾸며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「3010 mL = 3 L 100 mL」","correct":true,"mis_target":"M3-2-u5-X05"},{"t":"민아 — 「1 L = 1000 mL」","mis":"M3-2-u5-X21"},{"t":"서준 — 「4 L = 4000 mL」","mis":"M3-2-u5-X21"},{"t":"하윤 — 「4010 mL = 4 L 10 mL」","mis":"M3-2-u5-X21"}],"explanation":["1 L = 1000 mL예요.","3 L 10 mL = 3010 mL.","도윤의 말이 틀렸어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 들이의 단위를 바꾸며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"채원 — 「4 L 50 mL = 450 mL」","correct":true,"mis_target":"M3-2-u5-X05"},{"t":"민아 — 「1 L = 1000 mL」","mis":"M3-2-u5-X21"},{"t":"하윤 — 「5 L = 5000 mL」","mis":"M3-2-u5-X21"},{"t":"은비 — 「5050 mL = 5 L 50 mL」","mis":"M3-2-u5-X21"}],"explanation":["1 L = 1000 mL예요.","4 L 50 mL = 4050 mL.","채원의 말이 틀렸어요."],"asset":null},{"stem":"이번에는 다른 문제예요. 들이의 단위를 바꾸며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서준 — 「4090 mL = 4 L 900 mL」","correct":true,"mis_target":"M3-2-u5-X05"},{"t":"은비 — 「1 L = 1000 mL」","mis":"M3-2-u5-X21"},{"t":"민아 — 「5 L = 5000 mL」","mis":"M3-2-u5-X21"},{"t":"지아 — 「5090 mL = 5 L 90 mL」","mis":"M3-2-u5-X21"}],"explanation":["1 L = 1000 mL예요.","4 L 90 mL = 4090 mL.","서준의 말이 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L02_challenge#7','math',3,2,'u5','L02','g3_2_math_u5_L02_challenge','lesson_challenge','M3-2-u5-C2',3,'mc','auto','3 L 20 mL, 3 L 200 mL, 3007 mL 중에서 들이가 가장 적은 것은 무엇인가요?',ARRAY['M3-2-u5-X20','M3-2-u5-X05','M3-2-u5-X21']::text[],true,'{"seq":7,"concept":"M3-2-u5-C2","difficulty":3,"kind":"mc","stem":"3 L 20 mL, 3 L 200 mL, 3007 mL 중에서 들이가 가장 적은 것은 무엇인가요?","options":[{"t":"3007 mL","correct":true},{"t":"3 L 200 mL","mis":"M3-2-u5-X20"},{"t":"3 L 20 mL","mis":"M3-2-u5-X05"},{"t":"모두 같아요","mis":"M3-2-u5-X21"}],"explanation":["모두 mL로 바꾸어요.","3020 mL, 3200 mL, 3007 mL.","가장 적은 것은 3007 mL예요."],"variant_rule":{"alt":[{"stem":"2 L 20 mL, 2 L 1 mL, 2 L 500 mL 중에서 들이가 가장 적은 것은 무엇인가요?","options":[{"t":"2 L 1 mL","correct":true},{"t":"2 L 500 mL","mis":"M3-2-u5-X20"},{"t":"2 L 20 mL","mis":"M3-2-u5-X05"},{"t":"모두 같아요","mis":"M3-2-u5-X21"}],"explanation":["모두 mL로 바꾸어요.","2020 mL, 2001 mL, 2500 mL.","가장 적은 것은 2 L 1 mL예요."],"asset":null},{"stem":"3 L 50 mL, 3700 mL, 3008 mL 중에서 들이가 가장 적은 것은 무엇인가요?","options":[{"t":"3008 mL","correct":true},{"t":"3700 mL","mis":"M3-2-u5-X20"},{"t":"3 L 50 mL","mis":"M3-2-u5-X05"},{"t":"모두 같아요","mis":"M3-2-u5-X21"}],"explanation":["모두 mL로 바꾸어요.","3050 mL, 3700 mL, 3008 mL.","가장 적은 것은 3008 mL예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L02_challenge#8','math',3,2,'u5','L02','g3_2_math_u5_L02_challenge','lesson_challenge','M3-2-u5-C1',4,'essay','teacher','은비가 초록색 컵과 빨간색 컵 중 들이가 더 많은 컵을 사려고 해요. 두 컵은 높이가 비슷해서 눈으로 보아서는 알기 어려워요. 어느 컵의 들이가 더 많은지 알아보는 방법을 두 가지 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u5-C1","difficulty":4,"kind":"essay","stem":"은비가 초록색 컵과 빨간색 컵 중 들이가 더 많은 컵을 사려고 해요. 두 컵은 높이가 비슷해서 눈으로 보아서는 알기 어려워요. 어느 컵의 들이가 더 많은지 알아보는 방법을 두 가지 설명해 보세요.","answer_guide":{"answer":"예: ① 빨간색 컵에 물을 가득 채워 초록색 컵에 옮겨 담는다. 넘치면 빨간색 컵이, 빈 곳이 남으면 초록색 컵의 들이가 더 많다. ② 두 컵에 물을 가득 채워 모양과 크기가 같은 수조에 각각 옮겨 담고 물의 높이가 더 높은 쪽의 들이가 더 많다. (같은 작은 컵으로 몇 번 들어가는지 세어 견주어도 된다.)","scoring_points":["옮겨 담아 견주는 방법을 썼는가","같은 그릇(수조·작은 컵)을 이용하는 방법을 썼는가","어떤 결과일 때 어느 컵이 더 많은지 판단 기준을 썼는가"]},"explanation":["한 컵의 물을 다른 컵에 부어 봐요.","같은 수조·같은 작은 컵으로 견주어요.","넘치는지·물 높이·횟수로 판단해요."],"asset":{"type":"cups","items":[{"label":"초록색 컵","w":3,"h":4},{"label":"빨간색 컵","w":2,"h":5}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L02_challenge#9','math',3,2,'u5','L02','g3_2_math_u5_L02_challenge','lesson_challenge','M3-2-u5-C2',4,'essay','teacher','정후는 「7 L 50 mL는 750 mL야.」라고 했어요. 정후의 말이 맞는지 판단하고, 7 L 50 mL는 몇 mL인지 1 L와 1 mL의 관계를 이용해 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u5-C2","difficulty":4,"kind":"essay","stem":"정후는 「7 L 50 mL는 750 mL야.」라고 했어요. 정후의 말이 맞는지 판단하고, 7 L 50 mL는 몇 mL인지 1 L와 1 mL의 관계를 이용해 설명해 보세요.","answer_guide":{"answer":"예: 틀렸다. 1 L = 1000 mL이므로 7 L는 7000 mL이다. 7000 mL와 50 mL를 더하면 7050 mL이다. 정후는 7과 50을 이어 써서 백의 자리 0을 빠뜨렸다.","scoring_points":["틀렸다고 판단했는가","7 L = 7000 mL라고 썼는가","7050 mL라고 답했는가"]},"explanation":["1 L = 1000 mL.","7 L = 7000 mL.","7000 + 50 = 7050 mL."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L02_challenge#10','math',3,2,'u5','L02','g3_2_math_u5_L02_challenge','lesson_challenge','M3-2-u5-C2',4,'mc','auto','㉮는 6 L 20 mL, ㉯는 6200 mL예요. 들이가 더 적은 것은 무엇인가요?',ARRAY['M3-2-u5-X20','M3-2-u5-X21']::text[],true,'{"seq":10,"concept":"M3-2-u5-C2","difficulty":4,"kind":"mc","stem":"㉮는 6 L 20 mL, ㉯는 6200 mL예요. 들이가 더 적은 것은 무엇인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M3-2-u5-X20"},{"t":"두 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"단위가 달라서 견줄 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["한 가지 단위로 바꾸어 견주어요.","6 L 20 mL = 6020 mL.","6020 mL < 6200 mL — 들이가 더 적은 것은 ㉮예요."],"variant_rule":{"alt":[{"stem":"㉮는 2 L 80 mL, ㉯는 2800 mL예요. 들이가 더 적은 것은 무엇인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M3-2-u5-X20"},{"t":"두 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"단위가 달라서 견줄 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["한 가지 단위로 바꾸어 견주어요.","2 L 80 mL = 2080 mL.","2080 mL < 2800 mL — 들이가 더 적은 것은 ㉮예요."],"asset":null},{"stem":"㉮는 4 L 20 mL, ㉯는 4205 mL예요. 들이가 더 적은 것은 무엇인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M3-2-u5-X20"},{"t":"두 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"단위가 달라서 견줄 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["한 가지 단위로 바꾸어 견주어요.","4 L 20 mL = 4020 mL.","4020 mL < 4205 mL — 들이가 더 적은 것은 ㉮예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L03_basic#1','math',3,2,'u5','L03','g3_2_math_u5_L03_basic','lesson_basic','M3-2-u5-C3',1,'sa','auto','비커의 큰 눈금 0과 500 mL 사이가 똑같이 5칸으로 나뉘어 있어요. 세제를 재었더니 물이 0에서부터 3칸째 눈금까지 올라와 있어요. 몇 mL인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u5-C3","difficulty":1,"kind":"sa","stem":"비커의 큰 눈금 0과 500 mL 사이가 똑같이 5칸으로 나뉘어 있어요. 세제를 재었더니 물이 0에서부터 3칸째 눈금까지 올라와 있어요. 몇 mL인가요? 숫자로 쓰세요.","answer":["300"],"explanation":["한 칸의 크기부터: 500 ÷ 5 = 100 mL.","3칸 → 100 × 3 = 300.","300 mL예요."],"variant_rule":{"alt":[{"stem":"비커의 큰 눈금 0과 1000 mL 사이가 똑같이 4칸으로 나뉘어 있어요. 우유를 재었더니 물이 0에서부터 3칸째 눈금까지 올라와 있어요. 몇 mL인가요? 숫자로 쓰세요.","answer":["750"],"explanation":["한 칸의 크기부터: 1000 ÷ 4 = 250 mL.","3칸 → 250 × 3 = 750.","750 mL예요."],"asset":null},{"stem":"비커의 큰 눈금 0과 1000 mL 사이가 똑같이 5칸으로 나뉘어 있어요. 양치 컵의 물을 재었더니 물이 0에서부터 3칸째 눈금까지 올라와 있어요. 몇 mL인가요? 숫자로 쓰세요.","answer":["600"],"explanation":["한 칸의 크기부터: 1000 ÷ 5 = 200 mL.","3칸 → 200 × 3 = 600.","600 mL예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L03_basic#2','math',3,2,'u5','L03','g3_2_math_u5_L03_basic','lesson_basic','M3-2-u5-C3',1,'mc','auto','어항의 들이는 약 25 ○예요. ○에 알맞은 단위는 무엇인가요?',ARRAY['M3-2-u5-X09','M3-2-u5-X10']::text[],true,'{"seq":2,"concept":"M3-2-u5-C3","difficulty":1,"kind":"mc","stem":"어항의 들이는 약 25 ○예요. ○에 알맞은 단위는 무엇인가요?","options":[{"t":"L","correct":true},{"t":"mL","mis":"M3-2-u5-X09"},{"t":"kg","mis":"M3-2-u5-X10"},{"t":"g","mis":"M3-2-u5-X10"}],"explanation":["어항을 아는 들이와 견주어 봐요.","들이에 쓰는 단위는 mL·L.","어항의 들이는 약 25 L예요."],"variant_rule":{"alt":[{"stem":"종이컵의 들이는 약 180 ○예요. ○에 알맞은 단위는 무엇인가요?","options":[{"t":"mL","correct":true},{"t":"L","mis":"M3-2-u5-X09"},{"t":"kg","mis":"M3-2-u5-X10"},{"t":"g","mis":"M3-2-u5-X10"}],"explanation":["종이컵을 아는 들이와 견주어 봐요.","들이에 쓰는 단위는 mL·L.","종이컵의 들이는 약 180 mL예요."],"asset":null},{"stem":"세제 통의 들이는 약 3 ○예요. ○에 알맞은 단위는 무엇인가요?","options":[{"t":"L","correct":true},{"t":"mL","mis":"M3-2-u5-X09"},{"t":"kg","mis":"M3-2-u5-X10"},{"t":"g","mis":"M3-2-u5-X10"}],"explanation":["세제 통을 아는 들이와 견주어 봐요.","들이에 쓰는 단위는 mL·L.","세제 통의 들이는 약 3 L예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L03_basic#3','math',3,2,'u5','L03','g3_2_math_u5_L03_basic','lesson_basic','M3-2-u5-C3',1,'mc','auto','도윤이 다회용 컵의 들이를 200 mL쯤 될 것 같다고 어림했어요. 어림한 들이를 바르게 나타낸 것은 무엇인가요?',ARRAY['M3-2-u5-X08','M3-2-u5-X09']::text[],true,'{"seq":3,"concept":"M3-2-u5-C3","difficulty":1,"kind":"mc","stem":"도윤이 다회용 컵의 들이를 200 mL쯤 될 것 같다고 어림했어요. 어림한 들이를 바르게 나타낸 것은 무엇인가요?","options":[{"t":"약 200 mL","correct":true},{"t":"200 mL 약","mis":"M3-2-u5-X08"},{"t":"딱 200 mL","mis":"M3-2-u5-X08"},{"t":"약 200 L","mis":"M3-2-u5-X09"}],"explanation":["어림한 값은 앞에 「약」을 붙여요.","200 mL쯤 → 약 200 mL.","단위도 그대로 — 약 200 mL."],"variant_rule":{"alt":[{"stem":"정후가 양치 컵의 들이를 300 mL쯤 될 것 같다고 어림했어요. 어림한 들이를 바르게 나타낸 것은 무엇인가요?","options":[{"t":"약 300 mL","correct":true},{"t":"300 mL 약","mis":"M3-2-u5-X08"},{"t":"딱 300 mL","mis":"M3-2-u5-X08"},{"t":"약 300 L","mis":"M3-2-u5-X09"}],"explanation":["어림한 값은 앞에 「약」을 붙여요.","300 mL쯤 → 약 300 mL.","단위도 그대로 — 약 300 mL."],"asset":null},{"stem":"지아가 주스병의 들이를 600 mL쯤 될 것 같다고 어림했어요. 어림한 들이를 바르게 나타낸 것은 무엇인가요?","options":[{"t":"약 600 mL","correct":true},{"t":"600 mL 약","mis":"M3-2-u5-X08"},{"t":"딱 600 mL","mis":"M3-2-u5-X08"},{"t":"약 600 L","mis":"M3-2-u5-X09"}],"explanation":["어림한 값은 앞에 「약」을 붙여요.","600 mL쯤 → 약 600 mL.","단위도 그대로 — 약 600 mL."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L03_basic#4','math',3,2,'u5','L03','g3_2_math_u5_L03_basic','lesson_basic','M3-2-u5-C3',1,'sa','auto','비커의 큰 눈금 0과 1000 mL 사이가 똑같이 10칸으로 나뉘어 있어요. 눈금 한 칸은 몇 mL인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u5-C3","difficulty":1,"kind":"sa","stem":"비커의 큰 눈금 0과 1000 mL 사이가 똑같이 10칸으로 나뉘어 있어요. 눈금 한 칸은 몇 mL인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["0부터 1000 mL까지를 10칸으로 똑같이 나누었어요.","1000 ÷ 10 = 100.","한 칸은 100 mL예요."],"variant_rule":{"alt":[{"stem":"비커의 큰 눈금 0과 100 mL 사이가 똑같이 10칸으로 나뉘어 있어요. 눈금 한 칸은 몇 mL인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["0부터 100 mL까지를 10칸으로 똑같이 나누었어요.","100 ÷ 10 = 10.","한 칸은 10 mL예요."],"asset":null},{"stem":"비커의 큰 눈금 0과 200 mL 사이가 똑같이 2칸으로 나뉘어 있어요. 눈금 한 칸은 몇 mL인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["0부터 200 mL까지를 2칸으로 똑같이 나누었어요.","200 ÷ 2 = 100.","한 칸은 100 mL예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L03_basic#5','math',3,2,'u5','L03','g3_2_math_u5_L03_basic','lesson_basic','M3-2-u5-C3',2,'mc','auto','요구르트병의 들이는 약 65 ○예요. ○에 알맞은 단위는 무엇인가요?',ARRAY['M3-2-u5-X09','M3-2-u5-X10']::text[],true,'{"seq":5,"concept":"M3-2-u5-C3","difficulty":2,"kind":"mc","stem":"요구르트병의 들이는 약 65 ○예요. ○에 알맞은 단위는 무엇인가요?","options":[{"t":"mL","correct":true},{"t":"L","mis":"M3-2-u5-X09"},{"t":"kg","mis":"M3-2-u5-X10"},{"t":"g","mis":"M3-2-u5-X10"}],"explanation":["요구르트병을 아는 들이와 견주어 봐요.","들이에 쓰는 단위는 mL·L.","요구르트병의 들이는 약 65 mL예요."],"variant_rule":{"alt":[{"stem":"우유갑의 들이는 약 200 ○예요. ○에 알맞은 단위는 무엇인가요?","options":[{"t":"mL","correct":true},{"t":"L","mis":"M3-2-u5-X09"},{"t":"kg","mis":"M3-2-u5-X10"},{"t":"g","mis":"M3-2-u5-X10"}],"explanation":["우유갑을 아는 들이와 견주어 봐요.","들이에 쓰는 단위는 mL·L.","우유갑의 들이는 약 200 mL예요."],"asset":null},{"stem":"세제 통의 들이는 약 3 ○예요. ○에 알맞은 단위는 무엇인가요?","options":[{"t":"L","correct":true},{"t":"mL","mis":"M3-2-u5-X09"},{"t":"kg","mis":"M3-2-u5-X10"},{"t":"g","mis":"M3-2-u5-X10"}],"explanation":["세제 통을 아는 들이와 견주어 봐요.","들이에 쓰는 단위는 mL·L.","세제 통의 들이는 약 3 L예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L03_basic#6','math',3,2,'u5','L03','g3_2_math_u5_L03_basic','lesson_basic','M3-2-u5-C3',2,'mc','auto','주스병의 들이를 어림했어요 — 지아 약 800 mL, 채원 약 1 L, 서준 약 1 L 150 mL. 재어 보니 850 mL였어요. 가장 가깝게 어림한 친구는 누구인가요?',ARRAY['M3-2-u5-X08','M3-2-u5-X21']::text[],true,'{"seq":6,"concept":"M3-2-u5-C3","difficulty":2,"kind":"mc","stem":"주스병의 들이를 어림했어요 — 지아 약 800 mL, 채원 약 1 L, 서준 약 1 L 150 mL. 재어 보니 850 mL였어요. 가장 가깝게 어림한 친구는 누구인가요?","options":[{"t":"지아","correct":true},{"t":"채원","mis":"M3-2-u5-X08"},{"t":"서준","mis":"M3-2-u5-X08"},{"t":"모두 똑같이 알맞아요","mis":"M3-2-u5-X21"}],"explanation":["잰 값 850 mL와 어림한 값의 차를 견주어요.","지아 50 mL, 채원 150 mL, 서준 300 mL 차이.","차가 가장 작은 지아가 가장 가깝게 어림했어요."],"variant_rule":{"alt":[{"stem":"세제 통의 들이를 어림했어요 — 지아 약 1 L 350 mL, 민아 약 1 L 450 mL, 정후 약 1 L 200 mL. 재어 보니 1 L 500 mL였어요. 가장 가깝게 어림한 친구는 누구인가요?","options":[{"t":"민아","correct":true},{"t":"지아","mis":"M3-2-u5-X08"},{"t":"정후","mis":"M3-2-u5-X08"},{"t":"모두 똑같이 알맞아요","mis":"M3-2-u5-X21"}],"explanation":["잰 값 1 L 500 mL와 어림한 값의 차를 견주어요.","지아 150 mL, 민아 50 mL, 정후 300 mL 차이.","차가 가장 작은 민아가 가장 가깝게 어림했어요."],"asset":null},{"stem":"주스병의 들이를 어림했어요 — 소율 약 1 L 850 mL, 서준 약 1 L 650 mL, 준우 약 2 L 100 mL. 재어 보니 1 L 800 mL였어요. 가장 가깝게 어림한 친구는 누구인가요?","options":[{"t":"소율","correct":true},{"t":"서준","mis":"M3-2-u5-X08"},{"t":"준우","mis":"M3-2-u5-X08"},{"t":"모두 똑같이 알맞아요","mis":"M3-2-u5-X21"}],"explanation":["잰 값 1 L 800 mL와 어림한 값의 차를 견주어요.","소율 50 mL, 서준 150 mL, 준우 300 mL 차이.","차가 가장 작은 소율이 가장 가깝게 어림했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L03_basic#7','math',3,2,'u5','L03','g3_2_math_u5_L03_basic','lesson_basic','M3-2-u5-C3',2,'sa','auto','물통의 물을 1000 mL 비커에 옮겨 담았더니 비커 2개가 가득 차고 300 mL가 더 있어요. 물통에 담긴 물은 모두 몇 mL인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u5-C3","difficulty":2,"kind":"sa","stem":"물통의 물을 1000 mL 비커에 옮겨 담았더니 비커 2개가 가득 차고 300 mL가 더 있어요. 물통에 담긴 물은 모두 몇 mL인가요? 숫자로 쓰세요.","answer":["2300"],"explanation":["1000 mL 비커 2개 → 2000 mL.","나머지 300 mL.","2000 + 300 = 2300 — 2300 mL예요."],"variant_rule":{"alt":[{"stem":"물통의 물을 1000 mL 비커에 옮겨 담았더니 비커 4개가 가득 차고 400 mL가 더 있어요. 물통에 담긴 물은 모두 몇 mL인가요? 숫자로 쓰세요.","answer":["4400"],"explanation":["1000 mL 비커 4개 → 4000 mL.","나머지 400 mL.","4000 + 400 = 4400 — 4400 mL예요."],"asset":null},{"stem":"물통의 물을 1000 mL 비커에 옮겨 담았더니 비커 5개가 가득 차고 600 mL가 더 있어요. 물통에 담긴 물은 모두 몇 mL인가요? 숫자로 쓰세요.","answer":["5600"],"explanation":["1000 mL 비커 5개 → 5000 mL.","나머지 600 mL.","5000 + 600 = 5600 — 5600 mL예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L03_basic#8','math',3,2,'u5','L03','g3_2_math_u5_L03_basic','lesson_basic','M3-2-u5-C3',2,'sa','auto','큰 병에 가득 담긴 물 1000 mL를 들이가 200 mL인 작은 컵에 옮기면 작은 컵 몇 개를 가득 채울 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u5-C3","difficulty":2,"kind":"sa","stem":"큰 병에 가득 담긴 물 1000 mL를 들이가 200 mL인 작은 컵에 옮기면 작은 컵 몇 개를 가득 채울 수 있나요? 숫자로 쓰세요.","answer":["5"],"explanation":["작은 컵 하나에 200 mL씩 담아요.","1000 ÷ 200 = 5.","작은 컵 5개를 채워요."],"variant_rule":{"alt":[{"stem":"큰 병에 가득 담긴 물 1000 mL를 들이가 250 mL인 작은 컵에 옮기면 작은 컵 몇 개를 가득 채울 수 있나요? 숫자로 쓰세요.","answer":["4"],"explanation":["작은 컵 하나에 250 mL씩 담아요.","1000 ÷ 250 = 4.","작은 컵 4개를 채워요."],"asset":null},{"stem":"큰 병에 가득 담긴 물 600 mL를 들이가 200 mL인 작은 컵에 옮기면 작은 컵 몇 개를 가득 채울 수 있나요? 숫자로 쓰세요.","answer":["3"],"explanation":["작은 컵 하나에 200 mL씩 담아요.","600 ÷ 200 = 3.","작은 컵 3개를 채워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L03_basic#9','math',3,2,'u5','L03','g3_2_math_u5_L03_basic','lesson_basic','M3-2-u5-C3',2,'ox','auto','도윤은 양치 컵의 들이를 약 200 mL로 어림하고 재어 보니 180 mL였어요. 「어림한 값과 잰 값이 다르니 어림을 잘못한 거야.」',ARRAY['M3-2-u5-X08']::text[],true,'{"seq":9,"concept":"M3-2-u5-C3","difficulty":2,"kind":"ox","stem":"도윤은 양치 컵의 들이를 약 200 mL로 어림하고 재어 보니 180 mL였어요. 「어림한 값과 잰 값이 다르니 어림을 잘못한 거야.」","answer":"X","reason_options":[{"t":"어림은 아는 양과 견주어 얼마쯤인지 나타낸 것이라서","correct":true},{"t":"어림한 값은 잰 값과 꼭 같아야 해서","mis":"M3-2-u5-X08"}],"mis":"M3-2-u5-X08","explanation":["어림은 재기 전에 얼마쯤인지 생각해 보는 거예요.","약 200 mL와 180 mL — 차이 20 mL.","달라도 괜찮아요 — 무엇과 견주어 어림했는지가 중요해요 ×."],"variant_rule":{"alt":[{"stem":"은비는 주스병의 들이를 약 400 mL로 어림하고 재어 보니 460 mL였어요. 「어림한 값과 잰 값이 다르니 어림을 잘못한 거야.」","answer":"X","reason_options":[{"t":"어림은 아는 양과 견주어 얼마쯤인지 나타낸 것이라서","correct":true},{"t":"어림한 값은 잰 값과 꼭 같아야 해서","mis":"M3-2-u5-X08"}],"explanation":["어림은 재기 전에 얼마쯤인지 생각해 보는 거예요.","약 400 mL와 460 mL — 차이 60 mL.","달라도 괜찮아요 — 무엇과 견주어 어림했는지가 중요해요 ×."],"asset":null},{"stem":"서준은 세제 통의 들이를 약 500 mL로 어림하고 재어 보니 530 mL였어요. 「어림한 값과 잰 값이 다르니 어림을 잘못한 거야.」","answer":"X","reason_options":[{"t":"어림은 아는 양과 견주어 얼마쯤인지 나타낸 것이라서","correct":true},{"t":"어림한 값은 잰 값과 꼭 같아야 해서","mis":"M3-2-u5-X08"}],"explanation":["어림은 재기 전에 얼마쯤인지 생각해 보는 거예요.","약 500 mL와 530 mL — 차이 30 mL.","달라도 괜찮아요 — 무엇과 견주어 어림했는지가 중요해요 ×."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L03_basic#10','math',3,2,'u5','L03','g3_2_math_u5_L03_basic','lesson_basic','M3-2-u5-C3',3,'mc','auto','비커의 큰 눈금 0과 500 mL 사이가 똑같이 10칸으로 나뉘어 있어요. 우유를 재었더니 물이 0에서부터 2칸째 눈금까지 올라와 있어요. 몇 mL인가요?',ARRAY['M3-2-u5-X07']::text[],true,'{"seq":10,"concept":"M3-2-u5-C3","difficulty":3,"kind":"mc","stem":"비커의 큰 눈금 0과 500 mL 사이가 똑같이 10칸으로 나뉘어 있어요. 우유를 재었더니 물이 0에서부터 2칸째 눈금까지 올라와 있어요. 몇 mL인가요?","options":[{"t":"100 mL","correct":true},{"t":"2 mL","mis":"M3-2-u5-X07"},{"t":"200 mL","mis":"M3-2-u5-X07"},{"t":"150 mL","mis":"M3-2-u5-X07"}],"explanation":["한 칸의 크기부터: 500 ÷ 10 = 50 mL.","2칸 → 50 × 2 = 100.","100 mL예요."],"variant_rule":{"alt":[{"stem":"비커의 큰 눈금 0과 1000 mL 사이가 똑같이 10칸으로 나뉘어 있어요. 양치 컵의 물을 재었더니 물이 0에서부터 2칸째 눈금까지 올라와 있어요. 몇 mL인가요?","options":[{"t":"200 mL","correct":true},{"t":"2 mL","mis":"M3-2-u5-X07"},{"t":"20 mL","mis":"M3-2-u5-X07"},{"t":"300 mL","mis":"M3-2-u5-X07"}],"explanation":["한 칸의 크기부터: 1000 ÷ 10 = 100 mL.","2칸 → 100 × 2 = 200.","200 mL예요."],"asset":null},{"stem":"비커의 큰 눈금 0과 500 mL 사이가 똑같이 10칸으로 나뉘어 있어요. 다회용 컵의 물을 재었더니 물이 0에서부터 5칸째 눈금까지 올라와 있어요. 몇 mL인가요?","options":[{"t":"250 mL","correct":true},{"t":"5 mL","mis":"M3-2-u5-X07"},{"t":"500 mL","mis":"M3-2-u5-X07"},{"t":"300 mL","mis":"M3-2-u5-X07"}],"explanation":["한 칸의 크기부터: 500 ÷ 10 = 50 mL.","5칸 → 50 × 5 = 250.","250 mL예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L03_challenge#1','math',3,2,'u5','L03','g3_2_math_u5_L03_challenge','lesson_challenge','M3-2-u5-C3',2,'mc','auto','들이를 알맞게 어림한 것은 무엇인가요?',ARRAY['M3-2-u5-X09','M3-2-u5-X10']::text[],true,'{"seq":1,"concept":"M3-2-u5-C3","difficulty":2,"kind":"mc","stem":"들이를 알맞게 어림한 것은 무엇인가요?","options":[{"t":"종이컵의 들이는 약 200 mL예요","correct":true},{"t":"종이컵의 들이는 약 200 L예요","mis":"M3-2-u5-X09"},{"t":"욕조의 들이는 약 200 mL예요","mis":"M3-2-u5-X09"},{"t":"물병의 들이는 약 500 g이에요","mis":"M3-2-u5-X10"}],"explanation":["물건과 단위의 크기를 견주어 봐요.","들이의 단위는 mL·L.","알맞은 것은 「종이컵의 들이는 약 200 mL예요」."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 들이를 알맞게 어림한 것은 무엇인가요?","options":[{"t":"어항의 들이는 약 25 L예요","correct":true},{"t":"어항의 들이는 약 25 mL예요","mis":"M3-2-u5-X09"},{"t":"숟가락의 들이는 약 15 L예요","mis":"M3-2-u5-X09"},{"t":"어항의 무게는 약 25 L예요","mis":"M3-2-u5-X10"}],"explanation":["물건과 단위의 크기를 견주어 봐요.","들이의 단위는 mL·L.","알맞은 것은 「어항의 들이는 약 25 L예요」."],"asset":null},{"stem":"이번에는 다른 문제예요. 들이를 알맞게 어림한 것은 무엇인가요?","options":[{"t":"양동이의 들이는 약 10 L예요","correct":true},{"t":"양동이의 들이는 약 10 mL예요","mis":"M3-2-u5-X09"},{"t":"요구르트병의 들이는 약 65 L예요","mis":"M3-2-u5-X09"},{"t":"양동이의 들이는 약 10 kg이에요","mis":"M3-2-u5-X10"}],"explanation":["물건과 단위의 크기를 견주어 봐요.","들이의 단위는 mL·L.","알맞은 것은 「양동이의 들이는 약 10 L예요」."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L03_challenge#2','math',3,2,'u5','L03','g3_2_math_u5_L03_challenge','lesson_challenge','M3-2-u5-C3',2,'sa','auto','냄비에 500 mL 컵으로 물을 부으면 약 5번 들어갈 것 같아요. 냄비의 들이는 약 몇 mL로 어림할 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u5-C3","difficulty":2,"kind":"sa","stem":"냄비에 500 mL 컵으로 물을 부으면 약 5번 들어갈 것 같아요. 냄비의 들이는 약 몇 mL로 어림할 수 있나요? 숫자로 쓰세요.","answer":["2500"],"explanation":["아는 들이 500 mL가 몇 번인지 헤아려요.","500 × 5 = 2500.","약 2500 mL예요."],"variant_rule":{"alt":[{"stem":"물병에 100 mL 컵으로 물을 부으면 약 5번 들어갈 것 같아요. 물병의 들이는 약 몇 mL로 어림할 수 있나요? 숫자로 쓰세요.","answer":["500"],"explanation":["아는 들이 100 mL가 몇 번인지 헤아려요.","100 × 5 = 500.","약 500 mL예요."],"asset":null},{"stem":"물병에 500 mL 컵으로 물을 부으면 약 3번 들어갈 것 같아요. 물병의 들이는 약 몇 mL로 어림할 수 있나요? 숫자로 쓰세요.","answer":["1500"],"explanation":["아는 들이 500 mL가 몇 번인지 헤아려요.","500 × 3 = 1500.","약 1500 mL예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L03_challenge#3','math',3,2,'u5','L03','g3_2_math_u5_L03_challenge','lesson_challenge','M3-2-u5-C3',3,'mc','auto','비커의 큰 눈금 0과 1000 mL 사이가 똑같이 5칸으로 나뉘어 있어요. 세제를 재었더니 물이 0에서부터 3칸째 눈금까지 올라와 있어요. 몇 mL인가요?',ARRAY['M3-2-u5-X07']::text[],true,'{"seq":3,"concept":"M3-2-u5-C3","difficulty":3,"kind":"mc","stem":"비커의 큰 눈금 0과 1000 mL 사이가 똑같이 5칸으로 나뉘어 있어요. 세제를 재었더니 물이 0에서부터 3칸째 눈금까지 올라와 있어요. 몇 mL인가요?","options":[{"t":"600 mL","correct":true},{"t":"3 mL","mis":"M3-2-u5-X07"},{"t":"300 mL","mis":"M3-2-u5-X07"},{"t":"800 mL","mis":"M3-2-u5-X07"}],"explanation":["한 칸의 크기부터: 1000 ÷ 5 = 200 mL.","3칸 → 200 × 3 = 600.","600 mL예요."],"variant_rule":{"alt":[{"stem":"비커의 큰 눈금 0과 500 mL 사이가 똑같이 10칸으로 나뉘어 있어요. 우유를 재었더니 물이 0에서부터 3칸째 눈금까지 올라와 있어요. 몇 mL인가요?","options":[{"t":"150 mL","correct":true},{"t":"3 mL","mis":"M3-2-u5-X07"},{"t":"300 mL","mis":"M3-2-u5-X07"},{"t":"200 mL","mis":"M3-2-u5-X07"}],"explanation":["한 칸의 크기부터: 500 ÷ 10 = 50 mL.","3칸 → 50 × 3 = 150.","150 mL예요."],"asset":null},{"stem":"비커의 큰 눈금 0과 1000 mL 사이가 똑같이 10칸으로 나뉘어 있어요. 양치 컵의 물을 재었더니 물이 0에서부터 3칸째 눈금까지 올라와 있어요. 몇 mL인가요?","options":[{"t":"300 mL","correct":true},{"t":"3 mL","mis":"M3-2-u5-X07"},{"t":"30 mL","mis":"M3-2-u5-X07"},{"t":"400 mL","mis":"M3-2-u5-X07"}],"explanation":["한 칸의 크기부터: 1000 ÷ 10 = 100 mL.","3칸 → 100 × 3 = 300.","300 mL예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L03_challenge#4','math',3,2,'u5','L03','g3_2_math_u5_L03_challenge','lesson_challenge','M3-2-u5-C3',3,'sa','auto','비커의 큰 눈금 0과 1000 mL 사이가 똑같이 10칸으로 나뉘어 있어요. 우유를 재었더니 물이 0에서부터 17칸째 눈금까지 올라와 있어요. 몇 mL인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u5-C3","difficulty":3,"kind":"sa","stem":"비커의 큰 눈금 0과 1000 mL 사이가 똑같이 10칸으로 나뉘어 있어요. 우유를 재었더니 물이 0에서부터 17칸째 눈금까지 올라와 있어요. 몇 mL인가요? 숫자로 쓰세요.","answer":["1700"],"explanation":["한 칸의 크기부터: 1000 ÷ 10 = 100 mL.","17칸 → 100 × 17 = 1700.","1700 mL예요."],"variant_rule":{"alt":[{"stem":"비커의 큰 눈금 0과 1000 mL 사이가 똑같이 4칸으로 나뉘어 있어요. 양치 컵의 물을 재었더니 물이 0에서부터 5칸째 눈금까지 올라와 있어요. 몇 mL인가요? 숫자로 쓰세요.","answer":["1250"],"explanation":["한 칸의 크기부터: 1000 ÷ 4 = 250 mL.","5칸 → 250 × 5 = 1250.","1250 mL예요."],"asset":null},{"stem":"비커의 큰 눈금 0과 1000 mL 사이가 똑같이 10칸으로 나뉘어 있어요. 다회용 컵의 물을 재었더니 물이 0에서부터 11칸째 눈금까지 올라와 있어요. 몇 mL인가요? 숫자로 쓰세요.","answer":["1100"],"explanation":["한 칸의 크기부터: 1000 ÷ 10 = 100 mL.","11칸 → 100 × 11 = 1100.","1100 mL예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L03_challenge#5','math',3,2,'u5','L03','g3_2_math_u5_L03_challenge','lesson_challenge','M3-2-u5-C3',3,'mc','auto','물통의 들이를 어림했어요 — 지아 약 350 mL, 소율 약 900 mL, 채원 약 700 mL. 재어 보니 850 mL였어요. 가장 가깝게 어림한 친구는 누구인가요?',ARRAY['M3-2-u5-X08','M3-2-u5-X21']::text[],true,'{"seq":5,"concept":"M3-2-u5-C3","difficulty":3,"kind":"mc","stem":"물통의 들이를 어림했어요 — 지아 약 350 mL, 소율 약 900 mL, 채원 약 700 mL. 재어 보니 850 mL였어요. 가장 가깝게 어림한 친구는 누구인가요?","options":[{"t":"소율","correct":true},{"t":"지아","mis":"M3-2-u5-X08"},{"t":"채원","mis":"M3-2-u5-X08"},{"t":"모두 똑같이 알맞아요","mis":"M3-2-u5-X21"}],"explanation":["잰 값 850 mL와 어림한 값의 차를 견주어요.","지아 500 mL, 소율 50 mL, 채원 150 mL 차이.","차가 가장 작은 소율이 가장 가깝게 어림했어요."],"variant_rule":{"alt":[{"stem":"물통의 들이를 어림했어요 — 정후 약 1 L 800 mL, 지아 약 2 L 350 mL, 은비 약 2 L. 재어 보니 2 L 300 mL였어요. 가장 가깝게 어림한 친구는 누구인가요?","options":[{"t":"지아","correct":true},{"t":"정후","mis":"M3-2-u5-X08"},{"t":"은비","mis":"M3-2-u5-X08"},{"t":"모두 똑같이 알맞아요","mis":"M3-2-u5-X21"}],"explanation":["잰 값 2 L 300 mL와 어림한 값의 차를 견주어요.","정후 500 mL, 지아 50 mL, 은비 300 mL 차이.","차가 가장 작은 지아가 가장 가깝게 어림했어요."],"asset":null},{"stem":"주스병의 들이를 어림했어요 — 준우 약 1 L 950 mL, 정후 약 1 L 500 mL, 소율 약 1 L 750 mL. 재어 보니 1 L 800 mL였어요. 가장 가깝게 어림한 친구는 누구인가요?","options":[{"t":"소율","correct":true},{"t":"준우","mis":"M3-2-u5-X08"},{"t":"정후","mis":"M3-2-u5-X08"},{"t":"모두 똑같이 알맞아요","mis":"M3-2-u5-X21"}],"explanation":["잰 값 1 L 800 mL와 어림한 값의 차를 견주어요.","준우 150 mL, 정후 300 mL, 소율 50 mL 차이.","차가 가장 작은 소율이 가장 가깝게 어림했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L03_challenge#6','math',3,2,'u5','L03','g3_2_math_u5_L03_challenge','lesson_challenge','M3-2-u5-C3',3,'sa','auto','큰 병에 가득 담긴 물 1800 mL를 들이가 300 mL인 작은 컵에 옮기면 작은 컵 몇 개를 가득 채울 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u5-C3","difficulty":3,"kind":"sa","stem":"큰 병에 가득 담긴 물 1800 mL를 들이가 300 mL인 작은 컵에 옮기면 작은 컵 몇 개를 가득 채울 수 있나요? 숫자로 쓰세요.","answer":["6"],"explanation":["작은 컵 하나에 300 mL씩 담아요.","1800 ÷ 300 = 6.","작은 컵 6개를 채워요."],"variant_rule":{"alt":[{"stem":"큰 병에 가득 담긴 물 800 mL를 들이가 200 mL인 작은 컵에 옮기면 작은 컵 몇 개를 가득 채울 수 있나요? 숫자로 쓰세요.","answer":["4"],"explanation":["작은 컵 하나에 200 mL씩 담아요.","800 ÷ 200 = 4.","작은 컵 4개를 채워요."],"asset":null},{"stem":"큰 병에 가득 담긴 물 750 mL를 들이가 150 mL인 작은 컵에 옮기면 작은 컵 몇 개를 가득 채울 수 있나요? 숫자로 쓰세요.","answer":["5"],"explanation":["작은 컵 하나에 150 mL씩 담아요.","750 ÷ 150 = 5.","작은 컵 5개를 채워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L03_challenge#7','math',3,2,'u5','L03','g3_2_math_u5_L03_challenge','lesson_challenge','M3-2-u5-C3',3,'sa','auto','물통의 물을 1000 mL 비커에 옮겨 담았더니 비커 4개가 가득 차고 200 mL가 더 있어요. 물통에 담긴 물은 모두 몇 mL인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u5-C3","difficulty":3,"kind":"sa","stem":"물통의 물을 1000 mL 비커에 옮겨 담았더니 비커 4개가 가득 차고 200 mL가 더 있어요. 물통에 담긴 물은 모두 몇 mL인가요? 숫자로 쓰세요.","answer":["4200"],"explanation":["1000 mL 비커 4개 → 4000 mL.","나머지 200 mL.","4000 + 200 = 4200 — 4200 mL예요."],"variant_rule":{"alt":[{"stem":"물통의 물을 1000 mL 비커에 옮겨 담았더니 비커 1개가 가득 차고 800 mL가 더 있어요. 물통에 담긴 물은 모두 몇 mL인가요? 숫자로 쓰세요.","answer":["1800"],"explanation":["1000 mL 비커 1개 → 1000 mL.","나머지 800 mL.","1000 + 800 = 1800 — 1800 mL예요."],"asset":null},{"stem":"물통의 물을 1000 mL 비커에 옮겨 담았더니 비커 4개가 가득 차고 500 mL가 더 있어요. 물통에 담긴 물은 모두 몇 mL인가요? 숫자로 쓰세요.","answer":["4500"],"explanation":["1000 mL 비커 4개 → 4000 mL.","나머지 500 mL.","4000 + 500 = 4500 — 4500 mL예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L03_challenge#8','math',3,2,'u5','L03','g3_2_math_u5_L03_challenge','lesson_challenge','M3-2-u5-C3',4,'essay','teacher','서준이는 다회용 컵의 들이를 어림하려고 해요. 「약 몇 mL」인지 어림하는 방법을 두 가지 쓰고, 어림한 값과 비커로 잰 값이 다를 때 어떻게 생각하면 되는지 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u5-C3","difficulty":4,"kind":"essay","stem":"서준이는 다회용 컵의 들이를 어림하려고 해요. 「약 몇 mL」인지 어림하는 방법을 두 가지 쓰고, 어림한 값과 비커로 잰 값이 다를 때 어떻게 생각하면 되는지 설명해 보세요.","answer_guide":{"answer":"예: ① 들이를 아는 우유갑(200 mL)과 견주어 「우유갑보다 조금 많으니 약 250 mL」라고 어림한다. ② 200 mL 컵으로 몇 번쯤 들어갈지 헤아린다. 어림한 값 앞에는 「약」을 붙인다. 어림한 값과 잰 값이 달라도 괜찮고, 무엇과 견주어 어림했는지가 중요하며 다음에는 잰 값에 더 가깝게 어림할 수 있다.","scoring_points":["아는 들이와 견주는 방법을 썼는가","몇 번 들어가는지 헤아리는(또는 합하는) 방법을 썼는가","어림한 값과 잰 값이 달라도 된다고 설명했는가"]},"explanation":["아는 들이와 견주어요.","몇 번 들어가는지 헤아려요.","어림은 「약」, 달라도 괜찮아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L03_challenge#9','math',3,2,'u5','L03','g3_2_math_u5_L03_challenge','lesson_challenge','M3-2-u5-C3',4,'essay','teacher','지아는 비커의 큰 눈금 0과 500 mL 사이가 5칸으로 나뉜 것을 보고, 물이 3칸째 눈금까지 올라온 것을 「3 mL」라고 읽었어요. 잘못을 고치고 바르게 읽는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u5-C3","difficulty":4,"kind":"essay","stem":"지아는 비커의 큰 눈금 0과 500 mL 사이가 5칸으로 나뉜 것을 보고, 물이 3칸째 눈금까지 올라온 것을 「3 mL」라고 읽었어요. 잘못을 고치고 바르게 읽는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 먼저 눈금 한 칸의 크기를 구해야 한다. 500 mL를 5칸으로 나누었으므로 한 칸은 100 mL이다. 물이 3칸째까지 올라왔으므로 100 × 3 = 300 mL이다. 지아는 칸 수를 그대로 읽어서 틀렸다.","scoring_points":["한 칸이 100 mL임을 구했는가","300 mL라고 바르게 읽었는가","칸 수를 그대로 읽은 잘못을 짚었는가"]},"explanation":["500 ÷ 5 = 100 mL — 한 칸.","3칸 = 300 mL.","칸 수가 아니라 한 칸의 크기 × 칸 수."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L03_challenge#10','math',3,2,'u5','L03','g3_2_math_u5_L03_challenge','lesson_challenge','M3-2-u5-C3',4,'sa','auto','비커의 큰 눈금 0과 1000 mL 사이가 똑같이 10칸으로 나뉘어 있어요. 세제를 재었더니 물이 0에서부터 11칸째 눈금까지 올라와 있어요. 몇 mL인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-2-u5-C3","difficulty":4,"kind":"sa","stem":"비커의 큰 눈금 0과 1000 mL 사이가 똑같이 10칸으로 나뉘어 있어요. 세제를 재었더니 물이 0에서부터 11칸째 눈금까지 올라와 있어요. 몇 mL인가요? 숫자로 쓰세요.","answer":["1100"],"explanation":["한 칸의 크기부터: 1000 ÷ 10 = 100 mL.","11칸 → 100 × 11 = 1100.","1100 mL예요."],"variant_rule":{"alt":[{"stem":"비커의 큰 눈금 0과 1000 mL 사이가 똑같이 4칸으로 나뉘어 있어요. 우유를 재었더니 물이 0에서부터 6칸째 눈금까지 올라와 있어요. 몇 mL인가요? 숫자로 쓰세요.","answer":["1500"],"explanation":["한 칸의 크기부터: 1000 ÷ 4 = 250 mL.","6칸 → 250 × 6 = 1500.","1500 mL예요."],"asset":null},{"stem":"비커의 큰 눈금 0과 1000 mL 사이가 똑같이 10칸으로 나뉘어 있어요. 양치 컵의 물을 재었더니 물이 0에서부터 12칸째 눈금까지 올라와 있어요. 몇 mL인가요? 숫자로 쓰세요.","answer":["1200"],"explanation":["한 칸의 크기부터: 1000 ÷ 10 = 100 mL.","12칸 → 100 × 12 = 1200.","1200 mL예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L04_basic#1','math',3,2,'u5','L04','g3_2_math_u5_L04_basic','lesson_basic','M3-2-u5-C4',1,'sa','auto','3 L 200 mL + 2 L 500 mL = □ L 700 mL에서 □ 안에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u5-C4","difficulty":1,"kind":"sa","stem":"3 L 200 mL + 2 L 500 mL = □ L 700 mL에서 □ 안에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["mL끼리: 200 + 500 = 700.","L끼리: 3 + 2 = 5.","3 L 200 mL + 2 L 500 mL = 5 L 700 mL."],"variant_rule":{"alt":[{"stem":"1 L 400 mL + 4 L 400 mL = □ L 800 mL에서 □ 안에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["mL끼리: 400 + 400 = 800.","L끼리: 1 + 4 = 5.","1 L 400 mL + 4 L 400 mL = 5 L 800 mL."],"asset":null},{"stem":"1 L 200 mL + 5 L 650 mL = □ L 850 mL에서 □ 안에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["mL끼리: 200 + 650 = 850.","L끼리: 1 + 5 = 6.","1 L 200 mL + 5 L 650 mL = 6 L 850 mL."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L04_basic#2','math',3,2,'u5','L04','g3_2_math_u5_L04_basic','lesson_basic','M3-2-u5-C4',1,'sa','auto','8 L 900 mL − 4 L 400 mL = 4 L □ mL에서 □ 안에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u5-C4","difficulty":1,"kind":"sa","stem":"8 L 900 mL − 4 L 400 mL = 4 L □ mL에서 □ 안에 알맞은 수를 쓰세요.","answer":["500"],"explanation":["mL끼리: 900 − 400 = 500.","L끼리: 8 − 4 = 4.","8 L 900 mL − 4 L 400 mL = 4 L 500 mL."],"variant_rule":{"alt":[{"stem":"8 L 650 mL − 6 L 550 mL = 2 L □ mL에서 □ 안에 알맞은 수를 쓰세요.","answer":["100"],"explanation":["mL끼리: 650 − 550 = 100.","L끼리: 8 − 6 = 2.","8 L 650 mL − 6 L 550 mL = 2 L 100 mL."],"asset":null},{"stem":"4 L 700 mL − 3 L 300 mL = 1 L □ mL에서 □ 안에 알맞은 수를 쓰세요.","answer":["400"],"explanation":["mL끼리: 700 − 300 = 400.","L끼리: 4 − 3 = 1.","4 L 700 mL − 3 L 300 mL = 1 L 400 mL."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L04_basic#3','math',3,2,'u5','L04','g3_2_math_u5_L04_basic','lesson_basic','M3-2-u5-C4',1,'mc','auto','물통에 물이 1 L 300 mL 있었는데 1 L 150 mL를 더 부었어요. 물통의 물은 모두 얼마인가요?',ARRAY['M3-2-u5-X12','M3-2-u5-X14']::text[],true,'{"seq":3,"concept":"M3-2-u5-C4","difficulty":1,"kind":"mc","stem":"물통에 물이 1 L 300 mL 있었는데 1 L 150 mL를 더 부었어요. 물통의 물은 모두 얼마인가요?","options":[{"t":"2 L 450 mL","correct":true},{"t":"3 L 450 mL","mis":"M3-2-u5-X12"},{"t":"150 mL","mis":"M3-2-u5-X14"},{"t":"1 L 450 mL","mis":"M3-2-u5-X12"}],"explanation":["mL끼리: 300 + 150 = 450.","L끼리: 1 + 1 = 2.","1 L 300 mL + 1 L 150 mL = 2 L 450 mL."],"variant_rule":{"alt":[{"stem":"세제 통에 세제가 4 L 300 mL 들어 있어요. 4 L 500 mL를 더 넣었어요. 세제는 모두 얼마인가요?","options":[{"t":"8 L 800 mL","correct":true},{"t":"9 L 800 mL","mis":"M3-2-u5-X12"},{"t":"200 mL","mis":"M3-2-u5-X14"},{"t":"7 L 800 mL","mis":"M3-2-u5-X12"}],"explanation":["mL끼리: 300 + 500 = 800.","L끼리: 4 + 4 = 8.","4 L 300 mL + 4 L 500 mL = 8 L 800 mL."],"asset":null},{"stem":"식혜가 한 병에 2 L 550 mL, 다른 병에 2 L 150 mL 있어요. 식혜는 모두 얼마인가요?","options":[{"t":"4 L 700 mL","correct":true},{"t":"5 L 700 mL","mis":"M3-2-u5-X12"},{"t":"400 mL","mis":"M3-2-u5-X14"},{"t":"3 L 700 mL","mis":"M3-2-u5-X12"}],"explanation":["mL끼리: 550 + 150 = 700.","L끼리: 2 + 2 = 4.","2 L 550 mL + 2 L 150 mL = 4 L 700 mL."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L04_basic#4','math',3,2,'u5','L04','g3_2_math_u5_L04_basic','lesson_basic','M3-2-u5-C4',1,'sa','auto','주전자에 물이 2 L 550 mL 있었는데 300 mL를 썼어요. 남은 물은 몇 mL인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u5-C4","difficulty":1,"kind":"sa","stem":"주전자에 물이 2 L 550 mL 있었는데 300 mL를 썼어요. 남은 물은 몇 mL인가요? 숫자로 쓰세요.","answer":["2250"],"explanation":["mL끼리: 550 − 300 = 250.","L끼리: 2 − 0 = 2.","2 L 250 mL = 2250 mL예요."],"variant_rule":{"alt":[{"stem":"우유 4 L 900 mL 중에서 3 L 400 mL를 마셨어요. 남은 우유는 몇 mL인가요? 숫자로 쓰세요.","answer":["1500"],"explanation":["mL끼리: 900 − 400 = 500.","L끼리: 4 − 3 = 1.","1 L 500 mL = 1500 mL예요."],"asset":null},{"stem":"수조에 물이 2 L 760 mL 있어요. 1 L 110 mL를 퍼냈어요. 수조에 남은 물은 몇 mL인가요? 숫자로 쓰세요.","answer":["1650"],"explanation":["mL끼리: 760 − 110 = 650.","L끼리: 2 − 1 = 1.","1 L 650 mL = 1650 mL예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L04_basic#5','math',3,2,'u5','L04','g3_2_math_u5_L04_basic','lesson_basic','M3-2-u5-C4',2,'mc','auto','물병의 물 1 L 200 mL와 컵의 물 250 mL를 주전자에 부었더니 400 mL가 넘쳤어요. 주전자의 들이는 얼마인가요?',ARRAY['M3-2-u5-X14','M3-2-u5-X21','M3-2-u5-X12']::text[],true,'{"seq":5,"concept":"M3-2-u5-C4","difficulty":2,"kind":"mc","stem":"물병의 물 1 L 200 mL와 컵의 물 250 mL를 주전자에 부었더니 400 mL가 넘쳤어요. 주전자의 들이는 얼마인가요?","options":[{"t":"1 L 50 mL","correct":true},{"t":"1 L 850 mL","mis":"M3-2-u5-X14"},{"t":"1 L 450 mL","mis":"M3-2-u5-X21"},{"t":"2 L 50 mL","mis":"M3-2-u5-X12"}],"explanation":["부은 물: 1 L 200 mL + 250 mL = 1 L 450 mL.","넘친 400 mL는 주전자에 담기지 못했어요.","1 L 450 mL − 400 mL = 1 L 50 mL."],"variant_rule":{"alt":[{"stem":"물병의 물 3 L 700 mL와 컵의 물 350 mL를 주전자에 부었더니 100 mL가 넘쳤어요. 주전자의 들이는 얼마인가요?","options":[{"t":"3 L 950 mL","correct":true},{"t":"4 L 150 mL","mis":"M3-2-u5-X14"},{"t":"4 L 50 mL","mis":"M3-2-u5-X21"},{"t":"4 L 950 mL","mis":"M3-2-u5-X12"}],"explanation":["부은 물: 3 L 700 mL + 350 mL = 4 L 50 mL.","넘친 100 mL는 주전자에 담기지 못했어요.","4 L 50 mL − 100 mL = 3 L 950 mL."],"asset":null},{"stem":"물병의 물 2 L 100 mL와 컵의 물 200 mL를 주전자에 부었더니 450 mL가 넘쳤어요. 주전자의 들이는 얼마인가요?","options":[{"t":"1 L 850 mL","correct":true},{"t":"2 L 750 mL","mis":"M3-2-u5-X14"},{"t":"2 L 300 mL","mis":"M3-2-u5-X21"},{"t":"2 L 850 mL","mis":"M3-2-u5-X12"}],"explanation":["부은 물: 2 L 100 mL + 200 mL = 2 L 300 mL.","넘친 450 mL는 주전자에 담기지 못했어요.","2 L 300 mL − 450 mL = 1 L 850 mL."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L04_basic#6','math',3,2,'u5','L04','g3_2_math_u5_L04_basic','lesson_basic','M3-2-u5-C4',2,'sa','auto','간장병에는 1 L 300 mL, 주스병에는 1 L 400 mL 들어 있어요. 주스병이 몇 mL 더 많은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u5-C4","difficulty":2,"kind":"sa","stem":"간장병에는 1 L 300 mL, 주스병에는 1 L 400 mL 들어 있어요. 주스병이 몇 mL 더 많은가요? 숫자로 쓰세요.","answer":["100"],"explanation":["차는 큰 쪽에서 작은 쪽을 빼요.","1 L 400 mL − 1 L 300 mL = 100 mL.","주스병이 100 mL 더 많아요."],"variant_rule":{"alt":[{"stem":"간장병에는 2 L 200 mL, 주스병에는 2 L 400 mL 들어 있어요. 주스병이 몇 mL 더 많은가요? 숫자로 쓰세요.","answer":["200"],"explanation":["차는 큰 쪽에서 작은 쪽을 빼요.","2 L 400 mL − 2 L 200 mL = 200 mL.","주스병이 200 mL 더 많아요."],"asset":null},{"stem":"간장병에는 2 L 800 mL, 주스병에는 2 L 700 mL 들어 있어요. 간장병이 몇 mL 더 많은가요? 숫자로 쓰세요.","answer":["100"],"explanation":["차는 큰 쪽에서 작은 쪽을 빼요.","2 L 800 mL − 2 L 700 mL = 100 mL.","간장병이 100 mL 더 많아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L04_basic#7','math',3,2,'u5','L04','g3_2_math_u5_L04_basic','lesson_basic','M3-2-u5-C4',2,'mc','auto','세제 2 L 700 mL 중에서 빨래에 1 L 100 mL를 썼어요. 남은 세제는 얼마인가요?',ARRAY['M3-2-u5-X13','M3-2-u5-X14']::text[],true,'{"seq":7,"concept":"M3-2-u5-C4","difficulty":2,"kind":"mc","stem":"세제 2 L 700 mL 중에서 빨래에 1 L 100 mL를 썼어요. 남은 세제는 얼마인가요?","options":[{"t":"1 L 600 mL","correct":true},{"t":"2 L 600 mL","mis":"M3-2-u5-X13"},{"t":"600 mL","mis":"M3-2-u5-X13"},{"t":"3 L 800 mL","mis":"M3-2-u5-X14"}],"explanation":["mL끼리: 700 − 100 = 600.","L끼리: 2 − 1 = 1.","2 L 700 mL − 1 L 100 mL = 1 L 600 mL."],"variant_rule":{"alt":[{"stem":"주전자에 물이 8 L 600 mL 있었는데 5 L 500 mL를 썼어요. 남은 물은 얼마인가요?","options":[{"t":"3 L 100 mL","correct":true},{"t":"4 L 100 mL","mis":"M3-2-u5-X13"},{"t":"2 L 100 mL","mis":"M3-2-u5-X13"},{"t":"14 L 100 mL","mis":"M3-2-u5-X14"}],"explanation":["mL끼리: 600 − 500 = 100.","L끼리: 8 − 5 = 3.","8 L 600 mL − 5 L 500 mL = 3 L 100 mL."],"asset":null},{"stem":"우유 2 L 900 mL 중에서 1 L 500 mL를 마셨어요. 남은 우유는 얼마인가요?","options":[{"t":"1 L 400 mL","correct":true},{"t":"2 L 400 mL","mis":"M3-2-u5-X13"},{"t":"400 mL","mis":"M3-2-u5-X13"},{"t":"4 L 400 mL","mis":"M3-2-u5-X14"}],"explanation":["mL끼리: 900 − 500 = 400.","L끼리: 2 − 1 = 1.","2 L 900 mL − 1 L 500 mL = 1 L 400 mL."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L04_basic#8','math',3,2,'u5','L04','g3_2_math_u5_L04_basic','lesson_basic','M3-2-u5-C4',2,'sa','auto','4 L 950 mL + 4 L 920 mL = 9 L □ mL에서 □ 안에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u5-C4","difficulty":2,"kind":"sa","stem":"4 L 950 mL + 4 L 920 mL = 9 L □ mL에서 □ 안에 알맞은 수를 쓰세요.","answer":["870"],"explanation":["mL끼리: 950 + 920 = 1870 — 1000 mL = 1 L로 올려요.","L끼리: 1 + 4 + 4 = 9.","4 L 950 mL + 4 L 920 mL = 9 L 870 mL."],"variant_rule":{"alt":[{"stem":"2 L 670 mL + 1 L 430 mL = □ L 100 mL에서 □ 안에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["mL끼리: 670 + 430 = 1100 — 1000 mL = 1 L로 올려요.","L끼리: 1 + 2 + 1 = 4.","2 L 670 mL + 1 L 430 mL = 4 L 100 mL."],"asset":null},{"stem":"1 L 800 mL + 2 L 800 mL = 4 L □ mL에서 □ 안에 알맞은 수를 쓰세요.","answer":["600"],"explanation":["mL끼리: 800 + 800 = 1600 — 1000 mL = 1 L로 올려요.","L끼리: 1 + 1 + 2 = 4.","1 L 800 mL + 2 L 800 mL = 4 L 600 mL."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L04_basic#9','math',3,2,'u5','L04','g3_2_math_u5_L04_basic','lesson_basic','M3-2-u5-C4',2,'sa','auto','들이가 3 L인 물통에 ㉮ 그릇의 물 1 L 400 mL와 ㉯ 그릇의 물 750 mL를 부었어요. 물통을 가득 채우려면 몇 mL를 더 부어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u5-C4","difficulty":2,"kind":"sa","stem":"들이가 3 L인 물통에 ㉮ 그릇의 물 1 L 400 mL와 ㉯ 그릇의 물 750 mL를 부었어요. 물통을 가득 채우려면 몇 mL를 더 부어야 하나요? 숫자로 쓰세요.","answer":["850"],"explanation":["담은 양: 1 L 400 mL + 750 mL = 2 L 150 mL.","3 L − 2 L 150 mL = 850 mL.","850 mL 더 부어야 해요."],"variant_rule":{"alt":[{"stem":"들이가 5 L 500 mL인 물통에 ㉮ 그릇의 물 2 L 800 mL와 ㉯ 그릇의 물 1 L 400 mL를 부었어요. 물통을 가득 채우려면 몇 mL를 더 부어야 하나요? 숫자로 쓰세요.","answer":["1300"],"explanation":["담은 양: 2 L 800 mL + 1 L 400 mL = 4 L 200 mL.","5 L 500 mL − 4 L 200 mL = 1 L 300 mL.","1300 mL 더 부어야 해요."],"asset":null},{"stem":"들이가 4 L 500 mL인 물통에 ㉮ 그릇의 물 1 L 300 mL와 ㉯ 그릇의 물 1 L 450 mL를 부었어요. 물통을 가득 채우려면 몇 mL를 더 부어야 하나요? 숫자로 쓰세요.","answer":["1750"],"explanation":["담은 양: 1 L 300 mL + 1 L 450 mL = 2 L 750 mL.","4 L 500 mL − 2 L 750 mL = 1 L 750 mL.","1750 mL 더 부어야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L04_basic#10','math',3,2,'u5','L04','g3_2_math_u5_L04_basic','lesson_basic','M3-2-u5-C4',3,'mc','auto','물통의 들이는 2 L 200 mL예요. 그릇의 물은 ㉮ 1 L 400 mL, ㉯ 1 L 100 mL, ㉰ 1 L 200 mL, ㉱ 400 mL예요. 두 그릇을 골라 물통에 부어 넘치지 않으면서 가장 많이 채우려면 어느 두 그릇을 골라야 하나요?',ARRAY['M3-2-u5-X18','M3-2-u5-X20']::text[],true,'{"seq":10,"concept":"M3-2-u5-C4","difficulty":3,"kind":"mc","stem":"물통의 들이는 2 L 200 mL예요. 그릇의 물은 ㉮ 1 L 400 mL, ㉯ 1 L 100 mL, ㉰ 1 L 200 mL, ㉱ 400 mL예요. 두 그릇을 골라 물통에 부어 넘치지 않으면서 가장 많이 채우려면 어느 두 그릇을 골라야 하나요?","options":[{"t":"㉮, ㉱","correct":true},{"t":"㉮, ㉯","mis":"M3-2-u5-X18"},{"t":"㉮, ㉰","mis":"M3-2-u5-X18"},{"t":"㉰, ㉱","mis":"M3-2-u5-X20"}],"explanation":["두 그릇씩 더해 2 L 200 mL와 견주어요.","㉮, ㉱: 1 L 400 mL + 400 mL = 1 L 800 mL.","넘치지 않는 합 가운데 가장 커요."],"variant_rule":{"alt":[{"stem":"물통의 들이는 1 L 900 mL예요. 그릇의 물은 ㉮ 1 L 200 mL, ㉯ 300 mL, ㉰ 1 L 300 mL, ㉱ 900 mL예요. 두 그릇을 골라 물통에 부어 넘치지 않으면서 가장 많이 채우려면 어느 두 그릇을 골라야 하나요?","options":[{"t":"㉯, ㉰","correct":true},{"t":"㉮, ㉰","mis":"M3-2-u5-X18"},{"t":"㉮, ㉱","mis":"M3-2-u5-X18"},{"t":"㉮, ㉯","mis":"M3-2-u5-X20"}],"explanation":["두 그릇씩 더해 1 L 900 mL와 견주어요.","㉯, ㉰: 300 mL + 1 L 300 mL = 1 L 600 mL.","넘치지 않는 합 가운데 가장 커요."],"asset":null},{"stem":"물통의 들이는 2 L예요. 그릇의 물은 ㉮ 1 L 200 mL, ㉯ 1 L 300 mL, ㉰ 1 L, ㉱ 600 mL예요. 두 그릇을 골라 물통에 부어 넘치지 않으면서 가장 많이 채우려면 어느 두 그릇을 골라야 하나요?","options":[{"t":"㉯, ㉱","correct":true},{"t":"㉮, ㉯","mis":"M3-2-u5-X18"},{"t":"㉮, ㉰","mis":"M3-2-u5-X18"},{"t":"㉮, ㉱","mis":"M3-2-u5-X20"}],"explanation":["두 그릇씩 더해 2 L와 견주어요.","㉯, ㉱: 1 L 300 mL + 600 mL = 1 L 900 mL.","넘치지 않는 합 가운데 가장 커요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L04_challenge#1','math',3,2,'u5','L04','g3_2_math_u5_L04_challenge','lesson_challenge','M3-2-u5-C4',2,'mc','auto','물통에 물이 4 L 250 mL 있었는데 1 L 850 mL를 더 부었어요. 물통의 물은 모두 얼마인가요?',ARRAY['M3-2-u5-X12','M3-2-u5-X14']::text[],true,'{"seq":1,"concept":"M3-2-u5-C4","difficulty":2,"kind":"mc","stem":"물통에 물이 4 L 250 mL 있었는데 1 L 850 mL를 더 부었어요. 물통의 물은 모두 얼마인가요?","options":[{"t":"6 L 100 mL","correct":true},{"t":"5 L 1100 mL","mis":"M3-2-u5-X12"},{"t":"5 L 100 mL","mis":"M3-2-u5-X12"},{"t":"2 L 400 mL","mis":"M3-2-u5-X14"}],"explanation":["mL끼리: 250 + 850 = 1100 — 1000 mL = 1 L로 올려요.","L끼리: 1 + 4 + 1 = 6.","4 L 250 mL + 1 L 850 mL = 6 L 100 mL."],"variant_rule":{"alt":[{"stem":"세제 통에 세제가 4 L 700 mL 들어 있어요. 4 L 500 mL를 더 넣었어요. 세제는 모두 얼마인가요?","options":[{"t":"9 L 200 mL","correct":true},{"t":"8 L 1200 mL","mis":"M3-2-u5-X12"},{"t":"8 L 200 mL","mis":"M3-2-u5-X12"},{"t":"200 mL","mis":"M3-2-u5-X14"}],"explanation":["mL끼리: 700 + 500 = 1200 — 1000 mL = 1 L로 올려요.","L끼리: 1 + 4 + 4 = 9.","4 L 700 mL + 4 L 500 mL = 9 L 200 mL."],"asset":null},{"stem":"식혜가 한 병에 2 L 980 mL, 다른 병에 4 L 960 mL 있어요. 식혜는 모두 얼마인가요?","options":[{"t":"7 L 940 mL","correct":true},{"t":"6 L 1940 mL","mis":"M3-2-u5-X12"},{"t":"6 L 940 mL","mis":"M3-2-u5-X12"},{"t":"1 L 980 mL","mis":"M3-2-u5-X14"}],"explanation":["mL끼리: 980 + 960 = 1940 — 1000 mL = 1 L로 올려요.","L끼리: 1 + 2 + 4 = 7.","2 L 980 mL + 4 L 960 mL = 7 L 940 mL."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L04_challenge#2','math',3,2,'u5','L04','g3_2_math_u5_L04_challenge','lesson_challenge','M3-2-u5-C4',2,'sa','auto','6 L 150 mL − 4 L 850 mL = 1 L □ mL에서 □ 안에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u5-C4","difficulty":2,"kind":"sa","stem":"6 L 150 mL − 4 L 850 mL = 1 L □ mL에서 □ 안에 알맞은 수를 쓰세요.","answer":["300"],"explanation":["150 mL에서 850을 뺄 수 없어 1 L를 1000 mL로 내려요: 1150 − 850 = 300.","L끼리: 6 − 1 − 4 = 1.","6 L 150 mL − 4 L 850 mL = 1 L 300 mL."],"variant_rule":{"alt":[{"stem":"9 L 50 mL − 2 L 350 mL = □ L 700 mL에서 □ 안에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["50 mL에서 350을 뺄 수 없어 1 L를 1000 mL로 내려요: 1050 − 350 = 700.","L끼리: 9 − 1 − 2 = 6.","9 L 50 mL − 2 L 350 mL = 6 L 700 mL."],"asset":null},{"stem":"4 L 100 mL − 3 L 700 mL = □ mL에서 □ 안에 알맞은 수를 쓰세요.","answer":["400"],"explanation":["100 mL에서 700을 뺄 수 없어 1 L를 1000 mL로 내려요: 1100 − 700 = 400.","L끼리: 4 − 1 − 3 = 0.","4 L 100 mL − 3 L 700 mL = 400 mL."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L04_challenge#3','math',3,2,'u5','L04','g3_2_math_u5_L04_challenge','lesson_challenge','M3-2-u5-C4',3,'mc','auto','우유 5 L 200 mL 중에서 4 L 600 mL를 마셨어요. 남은 우유는 얼마인가요?',ARRAY['M3-2-u5-X13','M3-2-u5-X14']::text[],true,'{"seq":3,"concept":"M3-2-u5-C4","difficulty":3,"kind":"mc","stem":"우유 5 L 200 mL 중에서 4 L 600 mL를 마셨어요. 남은 우유는 얼마인가요?","options":[{"t":"600 mL","correct":true},{"t":"1 L 400 mL","mis":"M3-2-u5-X13"},{"t":"1 L 600 mL","mis":"M3-2-u5-X13"},{"t":"9 L 800 mL","mis":"M3-2-u5-X14"}],"explanation":["200 mL에서 600을 뺄 수 없어 1 L를 1000 mL로 내려요: 1200 − 600 = 600.","L끼리: 5 − 1 − 4 = 0.","5 L 200 mL − 4 L 600 mL = 600 mL."],"variant_rule":{"alt":[{"stem":"수조에 물이 2 L 200 mL 있어요. 1 L 600 mL를 퍼냈어요. 수조에 남은 물은 얼마인가요?","options":[{"t":"600 mL","correct":true},{"t":"1 L 400 mL","mis":"M3-2-u5-X13"},{"t":"1 L 600 mL","mis":"M3-2-u5-X13"},{"t":"3 L 800 mL","mis":"M3-2-u5-X14"}],"explanation":["200 mL에서 600을 뺄 수 없어 1 L를 1000 mL로 내려요: 1200 − 600 = 600.","L끼리: 2 − 1 − 1 = 0.","2 L 200 mL − 1 L 600 mL = 600 mL."],"asset":null},{"stem":"세제 6 L 130 mL 중에서 빨래에 5 L 510 mL를 썼어요. 남은 세제는 얼마인가요?","options":[{"t":"620 mL","correct":true},{"t":"1 L 380 mL","mis":"M3-2-u5-X13"},{"t":"1 L 620 mL","mis":"M3-2-u5-X13"},{"t":"11 L 640 mL","mis":"M3-2-u5-X14"}],"explanation":["130 mL에서 510을 뺄 수 없어 1 L를 1000 mL로 내려요: 1130 − 510 = 620.","L끼리: 6 − 1 − 5 = 0.","6 L 130 mL − 5 L 510 mL = 620 mL."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L04_challenge#4','math',3,2,'u5','L04','g3_2_math_u5_L04_challenge','lesson_challenge','M3-2-u5-C4',3,'mc','auto','소율이 2 L 100 mL + 3 L 950 mL = 5 L 1050 mL라고 계산했어요. 잘못된 까닭으로 알맞은 것은 무엇인가요?',ARRAY['M3-2-u5-X14','M3-2-u5-X11','M3-2-u5-X21']::text[],true,'{"seq":4,"concept":"M3-2-u5-C4","difficulty":3,"kind":"mc","stem":"소율이 2 L 100 mL + 3 L 950 mL = 5 L 1050 mL라고 계산했어요. 잘못된 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"mL끼리의 합이 1000이 넘으면 1 L로 올려야 해요","correct":true},{"t":"mL끼리 더하지 않고 빼야 해요","mis":"M3-2-u5-X14"},{"t":"L끼리만 더하면 돼요","mis":"M3-2-u5-X11"},{"t":"바르게 계산했어요","mis":"M3-2-u5-X21"}],"explanation":["mL끼리: 100 + 950 = 1050 — 1000 mL = 1 L로 올려요.","L끼리: 1 + 2 + 3 = 6.","2 L 100 mL + 3 L 950 mL = 6 L 50 mL."],"variant_rule":{"alt":[{"stem":"준우가 3 L 710 mL + 5 L 500 mL = 8 L 1210 mL라고 계산했어요. 잘못된 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"mL끼리의 합이 1000이 넘으면 1 L로 올려야 해요","correct":true},{"t":"mL끼리 더하지 않고 빼야 해요","mis":"M3-2-u5-X14"},{"t":"L끼리만 더하면 돼요","mis":"M3-2-u5-X11"},{"t":"바르게 계산했어요","mis":"M3-2-u5-X21"}],"explanation":["mL끼리: 710 + 500 = 1210 — 1000 mL = 1 L로 올려요.","L끼리: 1 + 3 + 5 = 9.","3 L 710 mL + 5 L 500 mL = 9 L 210 mL."],"asset":null},{"stem":"도윤이 3 L 900 mL + 5 L 200 mL = 8 L 1100 mL라고 계산했어요. 잘못된 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"mL끼리의 합이 1000이 넘으면 1 L로 올려야 해요","correct":true},{"t":"mL끼리 더하지 않고 빼야 해요","mis":"M3-2-u5-X14"},{"t":"L끼리만 더하면 돼요","mis":"M3-2-u5-X11"},{"t":"바르게 계산했어요","mis":"M3-2-u5-X21"}],"explanation":["mL끼리: 900 + 200 = 1100 — 1000 mL = 1 L로 올려요.","L끼리: 1 + 3 + 5 = 9.","3 L 900 mL + 5 L 200 mL = 9 L 100 mL."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L04_challenge#5','math',3,2,'u5','L04','g3_2_math_u5_L04_challenge','lesson_challenge','M3-2-u5-C4',3,'mc','auto','채원이 3 L 620 mL − 2 L 910 mL = 1 L 290 mL라고 계산했어요. 잘못된 까닭으로 알맞은 것은 무엇인가요?',ARRAY['M3-2-u5-X13','M3-2-u5-X14','M3-2-u5-X04']::text[],true,'{"seq":5,"concept":"M3-2-u5-C4","difficulty":3,"kind":"mc","stem":"채원이 3 L 620 mL − 2 L 910 mL = 1 L 290 mL라고 계산했어요. 잘못된 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"620 mL에서 910 mL를 뺄 수 없으니 1 L를 1000 mL로 내려야 해요","correct":true},{"t":"큰 수에서 작은 수를 빼면 되니 바르게 계산했어요","mis":"M3-2-u5-X13"},{"t":"mL끼리 더해야 해요","mis":"M3-2-u5-X14"},{"t":"1 L를 100 mL로 내려야 해요","mis":"M3-2-u5-X04"}],"explanation":["620 mL에서 910을 뺄 수 없어 1 L를 1000 mL로 내려요: 1620 − 910 = 710.","L끼리: 3 − 1 − 2 = 0.","3 L 620 mL − 2 L 910 mL = 710 mL."],"variant_rule":{"alt":[{"stem":"채원이 8 L 20 mL − 2 L 780 mL = 6 L 760 mL라고 계산했어요. 잘못된 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"20 mL에서 780 mL를 뺄 수 없으니 1 L를 1000 mL로 내려야 해요","correct":true},{"t":"큰 수에서 작은 수를 빼면 되니 바르게 계산했어요","mis":"M3-2-u5-X13"},{"t":"mL끼리 더해야 해요","mis":"M3-2-u5-X14"},{"t":"1 L를 100 mL로 내려야 해요","mis":"M3-2-u5-X04"}],"explanation":["20 mL에서 780을 뺄 수 없어 1 L를 1000 mL로 내려요: 1020 − 780 = 240.","L끼리: 8 − 1 − 2 = 5.","8 L 20 mL − 2 L 780 mL = 5 L 240 mL."],"asset":null},{"stem":"준우가 7 L 370 mL − 5 L 490 mL = 2 L 120 mL라고 계산했어요. 잘못된 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"370 mL에서 490 mL를 뺄 수 없으니 1 L를 1000 mL로 내려야 해요","correct":true},{"t":"큰 수에서 작은 수를 빼면 되니 바르게 계산했어요","mis":"M3-2-u5-X13"},{"t":"mL끼리 더해야 해요","mis":"M3-2-u5-X14"},{"t":"1 L를 100 mL로 내려야 해요","mis":"M3-2-u5-X04"}],"explanation":["370 mL에서 490을 뺄 수 없어 1 L를 1000 mL로 내려요: 1370 − 490 = 880.","L끼리: 7 − 1 − 5 = 1.","7 L 370 mL − 5 L 490 mL = 1 L 880 mL."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L04_challenge#6','math',3,2,'u5','L04','g3_2_math_u5_L04_challenge','lesson_challenge','M3-2-u5-C4',3,'mc','auto','물통의 들이는 1 L 800 mL예요. 그릇의 물은 ㉮ 1 L 100 mL, ㉯ 1 L 300 mL, ㉰ 300 mL, ㉱ 1 L 200 mL예요. 두 그릇을 골라 물통에 부어 넘치지 않으면서 가장 많이 채우려면 어느 두 그릇을 골라야 하나요?',ARRAY['M3-2-u5-X18','M3-2-u5-X20']::text[],true,'{"seq":6,"concept":"M3-2-u5-C4","difficulty":3,"kind":"mc","stem":"물통의 들이는 1 L 800 mL예요. 그릇의 물은 ㉮ 1 L 100 mL, ㉯ 1 L 300 mL, ㉰ 300 mL, ㉱ 1 L 200 mL예요. 두 그릇을 골라 물통에 부어 넘치지 않으면서 가장 많이 채우려면 어느 두 그릇을 골라야 하나요?","options":[{"t":"㉯, ㉰","correct":true},{"t":"㉮, ㉯","mis":"M3-2-u5-X18"},{"t":"㉮, ㉱","mis":"M3-2-u5-X18"},{"t":"㉰, ㉱","mis":"M3-2-u5-X20"}],"explanation":["두 그릇씩 더해 1 L 800 mL와 견주어요.","㉯, ㉰: 1 L 300 mL + 300 mL = 1 L 600 mL.","넘치지 않는 합 가운데 가장 커요."],"variant_rule":{"alt":[{"stem":"물통의 들이는 1 L 800 mL예요. 그릇의 물은 ㉮ 300 mL, ㉯ 600 mL, ㉰ 1 L 300 mL, ㉱ 800 mL예요. 두 그릇을 골라 물통에 부어 넘치지 않으면서 가장 많이 채우려면 어느 두 그릇을 골라야 하나요?","options":[{"t":"㉮, ㉰","correct":true},{"t":"㉯, ㉰","mis":"M3-2-u5-X18"},{"t":"㉰, ㉱","mis":"M3-2-u5-X18"},{"t":"㉯, ㉱","mis":"M3-2-u5-X20"}],"explanation":["두 그릇씩 더해 1 L 800 mL와 견주어요.","㉮, ㉰: 300 mL + 1 L 300 mL = 1 L 600 mL.","넘치지 않는 합 가운데 가장 커요."],"asset":null},{"stem":"물통의 들이는 1 L 800 mL예요. 그릇의 물은 ㉮ 1 L 400 mL, ㉯ 500 mL, ㉰ 800 mL, ㉱ 700 mL예요. 두 그릇을 골라 물통에 부어 넘치지 않으면서 가장 많이 채우려면 어느 두 그릇을 골라야 하나요?","options":[{"t":"㉰, ㉱","correct":true},{"t":"㉮, ㉯","mis":"M3-2-u5-X18"},{"t":"㉮, ㉰","mis":"M3-2-u5-X18"},{"t":"㉯, ㉰","mis":"M3-2-u5-X20"}],"explanation":["두 그릇씩 더해 1 L 800 mL와 견주어요.","㉰, ㉱: 800 mL + 700 mL = 1 L 500 mL.","넘치지 않는 합 가운데 가장 커요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L04_challenge#7','math',3,2,'u5','L04','g3_2_math_u5_L04_challenge','lesson_challenge','M3-2-u5-C4',3,'sa','auto','들이가 3 L인 물통에 ㉮ 그릇의 물 1 L 600 mL와 ㉯ 그릇의 물 650 mL를 부었어요. 물통을 가득 채우려면 몇 mL를 더 부어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u5-C4","difficulty":3,"kind":"sa","stem":"들이가 3 L인 물통에 ㉮ 그릇의 물 1 L 600 mL와 ㉯ 그릇의 물 650 mL를 부었어요. 물통을 가득 채우려면 몇 mL를 더 부어야 하나요? 숫자로 쓰세요.","answer":["750"],"explanation":["담은 양: 1 L 600 mL + 650 mL = 2 L 250 mL.","3 L − 2 L 250 mL = 750 mL.","750 mL 더 부어야 해요."],"variant_rule":{"alt":[{"stem":"들이가 3 L 500 mL인 물통에 ㉮ 그릇의 물 2 L 500 mL와 ㉯ 그릇의 물 500 mL를 부었어요. 물통을 가득 채우려면 몇 mL를 더 부어야 하나요? 숫자로 쓰세요.","answer":["500"],"explanation":["담은 양: 2 L 500 mL + 500 mL = 3 L.","3 L 500 mL − 3 L = 500 mL.","500 mL 더 부어야 해요."],"asset":null},{"stem":"들이가 2 L인 물통에 ㉮ 그릇의 물 1 L와 ㉯ 그릇의 물 200 mL를 부었어요. 물통을 가득 채우려면 몇 mL를 더 부어야 하나요? 숫자로 쓰세요.","answer":["800"],"explanation":["담은 양: 1 L + 200 mL = 1 L 200 mL.","2 L − 1 L 200 mL = 800 mL.","800 mL 더 부어야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L04_challenge#8','math',3,2,'u5','L04','g3_2_math_u5_L04_challenge','lesson_challenge','M3-2-u5-C4',4,'essay','teacher','세제 통에 세제가 1 L 600 mL 들어 있어요. 2 L 700 mL를 더 넣었더니 가득 찼어요. 세제 통의 들이를 구하고, mL끼리의 합이 1000 mL를 넘을 때 어떻게 하는지 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u5-C4","difficulty":4,"kind":"essay","stem":"세제 통에 세제가 1 L 600 mL 들어 있어요. 2 L 700 mL를 더 넣었더니 가득 찼어요. 세제 통의 들이를 구하고, mL끼리의 합이 1000 mL를 넘을 때 어떻게 하는지 설명해 보세요.","answer_guide":{"answer":"예: mL끼리 600 + 700 = 1300 mL이다. 1300 mL는 1 L 300 mL이므로 1 L를 L 쪽으로 올린다. L끼리 1 + 1 + 2 = 4 L이다. 그래서 세제 통의 들이는 4 L 300 mL이다.","scoring_points":["mL끼리 1300 mL를 구했는가","1000 mL를 1 L로 올렸는가","4 L 300 mL라고 답했는가"]},"explanation":["600 + 700 = 1300 mL.","1300 mL = 1 L 300 mL — 1 L 올림.","1 + 1 + 2 = 4 L — 4 L 300 mL."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L04_challenge#9','math',3,2,'u5','L04','g3_2_math_u5_L04_challenge','lesson_challenge','M3-2-u5-C4',4,'essay','teacher','주전자에 물이 5 L 200 mL 있었는데 2 L 600 mL를 썼어요. 남은 물의 양을 구하고, mL끼리 뺄 수 없을 때 어떻게 하는지 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u5-C4","difficulty":4,"kind":"essay","stem":"주전자에 물이 5 L 200 mL 있었는데 2 L 600 mL를 썼어요. 남은 물의 양을 구하고, mL끼리 뺄 수 없을 때 어떻게 하는지 설명해 보세요.","answer_guide":{"answer":"예: 200 mL에서 600 mL를 뺄 수 없으므로 5 L에서 1 L를 1000 mL로 내린다. 1200 − 600 = 600 mL, L끼리 4 − 2 = 2 L이다. 남은 물은 2 L 600 mL이다.","scoring_points":["1 L를 1000 mL로 내렸는가","mL끼리 600 mL를 구했는가","2 L 600 mL라고 답했는가"]},"explanation":["200 mL − 600 mL는 뺄 수 없어요.","1 L → 1000 mL: 1200 − 600 = 600.","4 − 2 = 2 L — 2 L 600 mL."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L04_challenge#10','math',3,2,'u5','L04','g3_2_math_u5_L04_challenge','lesson_challenge','M3-2-u5-C4',4,'sa','auto','우유 3 L 70 mL 중에서 1 L 530 mL를 마셨어요. 남은 우유는 몇 mL인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-2-u5-C4","difficulty":4,"kind":"sa","stem":"우유 3 L 70 mL 중에서 1 L 530 mL를 마셨어요. 남은 우유는 몇 mL인가요? 숫자로 쓰세요.","answer":["1540"],"explanation":["70 mL에서 530을 뺄 수 없어 1 L를 1000 mL로 내려요: 1070 − 530 = 540.","L끼리: 3 − 1 − 1 = 1.","1 L 540 mL = 1540 mL예요."],"variant_rule":{"alt":[{"stem":"수조에 물이 5 L 150 mL 있어요. 2 L 750 mL를 퍼냈어요. 수조에 남은 물은 몇 mL인가요? 숫자로 쓰세요.","answer":["2400"],"explanation":["150 mL에서 750을 뺄 수 없어 1 L를 1000 mL로 내려요: 1150 − 750 = 400.","L끼리: 5 − 1 − 2 = 2.","2 L 400 mL = 2400 mL예요."],"asset":null},{"stem":"세제 4 L 60 mL 중에서 빨래에 1 L 750 mL를 썼어요. 남은 세제는 몇 mL인가요? 숫자로 쓰세요.","answer":["2310"],"explanation":["60 mL에서 750을 뺄 수 없어 1 L를 1000 mL로 내려요: 1060 − 750 = 310.","L끼리: 4 − 1 − 1 = 2.","2 L 310 mL = 2310 mL예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L05_basic#1','math',3,2,'u5','L05','g3_2_math_u5_L05_basic','lesson_basic','M3-2-u5-C5',1,'mc','auto','양팔저울에 고구마와 당근을 올렸어요. 더 가벼운 것은 무엇인가요?',ARRAY['M3-2-u5-X15','M3-2-u5-X21']::text[],true,'{"seq":1,"concept":"M3-2-u5-C5","difficulty":1,"kind":"mc","stem":"양팔저울에 고구마와 당근을 올렸어요. 더 가벼운 것은 무엇인가요?","options":[{"t":"당근","correct":true},{"t":"고구마","mis":"M3-2-u5-X15"},{"t":"두 물건의 무게가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["양팔저울은 더 무거운 쪽이 아래로 내려가요.","고구마 쪽이 내려갔어요 — 고구마가 더 무거워요.","더 가벼운 것은 당근이에요."],"asset":{"type":"balance","scales":[{"l":{"name":"고구마","icon":"🍠"},"r":{"name":"당근","icon":"🥕"},"down":"l"}]},"variant_rule":{"alt":[{"stem":"양팔저울에 사과와 배를 올렸어요. 더 가벼운 것은 무엇인가요?","options":[{"t":"사과","correct":true},{"t":"배","mis":"M3-2-u5-X15"},{"t":"두 물건의 무게가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["양팔저울은 더 무거운 쪽이 아래로 내려가요.","배 쪽이 내려갔어요 — 배가 더 무거워요.","더 가벼운 것은 사과예요."],"asset":{"type":"balance","scales":[{"l":{"name":"사과","icon":"🍎"},"r":{"name":"배","icon":"🍐"},"down":"r"}]}},{"stem":"이번에는 다른 문제예요. 양팔저울에 고구마와 당근을 올렸어요. 더 가벼운 것은 무엇인가요?","options":[{"t":"고구마","correct":true},{"t":"당근","mis":"M3-2-u5-X15"},{"t":"두 물건의 무게가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["양팔저울은 더 무거운 쪽이 아래로 내려가요.","당근 쪽이 내려갔어요 — 당근이 더 무거워요.","더 가벼운 것은 고구마예요."],"asset":{"type":"balance","scales":[{"l":{"name":"고구마","icon":"🍠"},"r":{"name":"당근","icon":"🥕"},"down":"r"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L05_basic#2','math',3,2,'u5','L05','g3_2_math_u5_L05_basic','lesson_basic','M3-2-u5-C5',1,'sa','auto','키위의 무게는 바둑돌 18개, 레몬의 무게는 바둑돌 20개와 같아요. 레몬은 키위보다 바둑돌 몇 개만큼 더 무거운가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u5-C5","difficulty":1,"kind":"sa","stem":"키위의 무게는 바둑돌 18개, 레몬의 무게는 바둑돌 20개와 같아요. 레몬은 키위보다 바둑돌 몇 개만큼 더 무거운가요? 숫자로 쓰세요.","answer":["2"],"explanation":["같은 바둑돌으로 재었으니 개수로 견줄 수 있어요.","키위 18개, 레몬 20개.","20 − 18 = 2 — 바둑돌 2개만큼 더 무거워요."],"variant_rule":{"alt":[{"stem":"사과의 무게는 공깃돌 24개, 배의 무게는 공깃돌 29개와 같아요. 배는 사과보다 공깃돌 몇 개만큼 더 무거운가요? 숫자로 쓰세요.","answer":["5"],"explanation":["같은 공깃돌으로 재었으니 개수로 견줄 수 있어요.","사과 24개, 배 29개.","29 − 24 = 5 — 공깃돌 5개만큼 더 무거워요."],"asset":null},{"stem":"우유갑의 무게는 바둑돌 30개, 페트병의 무게는 바둑돌 21개와 같아요. 우유갑은 페트병보다 바둑돌 몇 개만큼 더 무거운가요? 숫자로 쓰세요.","answer":["9"],"explanation":["같은 바둑돌으로 재었으니 개수로 견줄 수 있어요.","우유갑 30개, 페트병 21개.","30 − 21 = 9 — 바둑돌 9개만큼 더 무거워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L05_basic#3','math',3,2,'u5','L05','g3_2_math_u5_L05_basic','lesson_basic','M3-2-u5-C5',1,'mc','auto','양팔저울에서 더 무거운 쪽은 어떻게 되나요?',ARRAY['M3-2-u5-X15','M3-2-u5-X21']::text[],true,'{"seq":3,"concept":"M3-2-u5-C5","difficulty":1,"kind":"mc","stem":"양팔저울에서 더 무거운 쪽은 어떻게 되나요?","options":[{"t":"아래로 내려가요","correct":true},{"t":"위로 올라가요","mis":"M3-2-u5-X15"},{"t":"움직이지 않아요","mis":"M3-2-u5-X21"},{"t":"옆으로 돌아가요","mis":"M3-2-u5-X21"}],"explanation":["양팔저울은 무게를 견주는 도구예요.","무거운 쪽은 내려가고 가벼운 쪽은 올라가요.","수평이면 무게가 같아요."],"variant_rule":{"alt":[{"stem":"양팔저울이 기울지 않고 수평을 이루었어요. 두 물건의 무게는 어떤가요?","options":[{"t":"두 물건의 무게가 같아요","correct":true},{"t":"왼쪽이 더 무거워요","mis":"M3-2-u5-X15"},{"t":"크기가 큰 쪽이 더 무거워요","mis":"M3-2-u5-X16"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["양팔저울은 무게를 견주는 도구예요.","무거운 쪽은 내려가고 가벼운 쪽은 올라가요.","수평이면 무게가 같아요."],"asset":null},{"stem":"양팔저울에서 더 가벼운 쪽은 어떻게 되나요?","options":[{"t":"위로 올라가요","correct":true},{"t":"아래로 내려가요","mis":"M3-2-u5-X15"},{"t":"움직이지 않아요","mis":"M3-2-u5-X21"},{"t":"옆으로 돌아가요","mis":"M3-2-u5-X21"}],"explanation":["양팔저울은 무게를 견주는 도구예요.","무거운 쪽은 내려가고 가벼운 쪽은 올라가요.","수평이면 무게가 같아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L05_basic#4','math',3,2,'u5','L05','g3_2_math_u5_L05_basic','lesson_basic','M3-2-u5-C5',1,'mc','auto','양팔저울에 우유갑과 페트병을 올렸어요. 더 무거운 것은 무엇인가요?',ARRAY['M3-2-u5-X15','M3-2-u5-X21']::text[],true,'{"seq":4,"concept":"M3-2-u5-C5","difficulty":1,"kind":"mc","stem":"양팔저울에 우유갑과 페트병을 올렸어요. 더 무거운 것은 무엇인가요?","options":[{"t":"우유갑","correct":true},{"t":"페트병","mis":"M3-2-u5-X15"},{"t":"두 물건의 무게가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["양팔저울은 더 무거운 쪽이 아래로 내려가요.","우유갑 쪽이 내려갔어요 — 우유갑이 더 무거워요.","더 무거운 것은 우유갑이에요."],"asset":{"type":"balance","scales":[{"l":{"name":"우유갑","icon":"🥛"},"r":{"name":"페트병","icon":"🍶"},"down":"l"}]},"variant_rule":{"alt":[{"stem":"양팔저울에 고구마와 당근을 올렸어요. 더 무거운 것은 무엇인가요?","options":[{"t":"고구마","correct":true},{"t":"당근","mis":"M3-2-u5-X15"},{"t":"두 물건의 무게가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["양팔저울은 더 무거운 쪽이 아래로 내려가요.","고구마 쪽이 내려갔어요 — 고구마가 더 무거워요.","더 무거운 것은 고구마예요."],"asset":{"type":"balance","scales":[{"l":{"name":"고구마","icon":"🍠"},"r":{"name":"당근","icon":"🥕"},"down":"l"}]}},{"stem":"양팔저울에 감자와 양파를 올렸어요. 더 무거운 것은 무엇인가요?","options":[{"t":"양파","correct":true},{"t":"감자","mis":"M3-2-u5-X15"},{"t":"두 물건의 무게가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["양팔저울은 더 무거운 쪽이 아래로 내려가요.","양파 쪽이 내려갔어요 — 양파가 더 무거워요.","더 무거운 것은 양파예요."],"asset":{"type":"balance","scales":[{"l":{"name":"감자","icon":"🥔"},"r":{"name":"양파","icon":"🧅"},"down":"r"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L05_basic#5','math',3,2,'u5','L05','g3_2_math_u5_L05_basic','lesson_basic','M3-2-u5-C5',2,'sa','auto','키위의 무게는 쌓기나무 25개, 레몬의 무게는 쌓기나무 24개와 같아요. 레몬은 키위보다 쌓기나무 몇 개만큼 더 가벼운가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u5-C5","difficulty":2,"kind":"sa","stem":"키위의 무게는 쌓기나무 25개, 레몬의 무게는 쌓기나무 24개와 같아요. 레몬은 키위보다 쌓기나무 몇 개만큼 더 가벼운가요? 숫자로 쓰세요.","answer":["1"],"explanation":["같은 쌓기나무로 재었으니 개수로 견줄 수 있어요.","키위 25개, 레몬 24개.","25 − 24 = 1 — 쌓기나무 1개만큼 더 가벼워요."],"variant_rule":{"alt":[{"stem":"우유갑의 무게는 클립 30개, 페트병의 무게는 클립 17개와 같아요. 페트병은 우유갑보다 클립 몇 개만큼 더 가벼운가요? 숫자로 쓰세요.","answer":["13"],"explanation":["같은 클립으로 재었으니 개수로 견줄 수 있어요.","우유갑 30개, 페트병 17개.","30 − 17 = 13 — 클립 13개만큼 더 가벼워요."],"asset":null},{"stem":"키위의 무게는 공깃돌 25개, 레몬의 무게는 공깃돌 29개와 같아요. 키위는 레몬보다 공깃돌 몇 개만큼 더 가벼운가요? 숫자로 쓰세요.","answer":["4"],"explanation":["같은 공깃돌으로 재었으니 개수로 견줄 수 있어요.","키위 25개, 레몬 29개.","29 − 25 = 4 — 공깃돌 4개만큼 더 가벼워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L05_basic#6','math',3,2,'u5','L05','g3_2_math_u5_L05_basic','lesson_basic','M3-2-u5-C5',2,'mc','auto','양파는 500원짜리 동전 20개, 감자는 100원짜리 동전 20개와 무게가 같아요. 두 무게가 다른 까닭은 무엇인가요?',ARRAY['M3-2-u5-X03','M3-2-u5-X16','M3-2-u5-X21']::text[],true,'{"seq":6,"concept":"M3-2-u5-C5","difficulty":2,"kind":"mc","stem":"양파는 500원짜리 동전 20개, 감자는 100원짜리 동전 20개와 무게가 같아요. 두 무게가 다른 까닭은 무엇인가요?","options":[{"t":"500원짜리와 100원짜리 동전 한 개의 무게가 달라서","correct":true},{"t":"동전의 개수가 달라서","mis":"M3-2-u5-X03"},{"t":"양파의 크기가 더 커서","mis":"M3-2-u5-X16"},{"t":"감자가 땅속에서 자라서","mis":"M3-2-u5-X21"}],"explanation":["두 물건 모두 동전 20개예요.","동전 한 개의 무게가 서로 달라요.","그래서 무게를 정확히 나타낼 같은 단위가 필요해요."],"variant_rule":{"alt":[{"stem":"귤은 500원짜리 동전 12개, 레몬은 100원짜리 동전 12개와 무게가 같아요. 귤과 레몬의 무게는 어떤가요?","options":[{"t":"서로 달라요","correct":true},{"t":"서로 같아요","mis":"M3-2-u5-X16"},{"t":"귤의 동전 개수가 더 많아요","mis":"M3-2-u5-X03"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["동전 개수는 12개로 같아요.","그런데 500원짜리와 100원짜리 동전은 한 개의 무게가 달라요.","재는 단위 물건이 다르면 개수가 같아도 무게가 달라요."],"asset":null},{"stem":"귤은 500원짜리 동전 10개, 레몬은 100원짜리 동전 10개와 무게가 같아요. 두 무게가 다른 까닭은 무엇인가요?","options":[{"t":"500원짜리와 100원짜리 동전 한 개의 무게가 달라서","correct":true},{"t":"동전의 개수가 달라서","mis":"M3-2-u5-X03"},{"t":"귤의 크기가 더 커서","mis":"M3-2-u5-X16"},{"t":"레몬이 땅속에서 자라서","mis":"M3-2-u5-X21"}],"explanation":["두 물건 모두 동전 10개예요.","동전 한 개의 무게가 서로 달라요.","그래서 무게를 정확히 나타낼 같은 단위가 필요해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L05_basic#7','math',3,2,'u5','L05','g3_2_math_u5_L05_basic','lesson_basic','M3-2-u5-C5',2,'mc','auto','바둑돌로 무게를 재었더니 공책 11개, 색연필 10개, 자 12개였어요. 가장 무거운 것은 무엇인가요?',ARRAY['M3-2-u5-X20','M3-2-u5-X21']::text[],true,'{"seq":7,"concept":"M3-2-u5-C5","difficulty":2,"kind":"mc","stem":"바둑돌로 무게를 재었더니 공책 11개, 색연필 10개, 자 12개였어요. 가장 무거운 것은 무엇인가요?","options":[{"t":"자","correct":true},{"t":"색연필","mis":"M3-2-u5-X20"},{"t":"공책","mis":"M3-2-u5-X20"},{"t":"모두 같아요","mis":"M3-2-u5-X21"}],"explanation":["바둑돌이 많이 올라갈수록 더 무거워요.","공책 11개, 색연필 10개, 자 12개.","가장 무거운 것은 자예요."],"variant_rule":{"alt":[{"stem":"클립으로 무게를 재었더니 공책 14개, 색연필 15개, 자 7개였어요. 가장 무거운 것은 무엇인가요?","options":[{"t":"색연필","correct":true},{"t":"자","mis":"M3-2-u5-X20"},{"t":"공책","mis":"M3-2-u5-X20"},{"t":"모두 같아요","mis":"M3-2-u5-X21"}],"explanation":["클립이 많이 올라갈수록 더 무거워요.","공책 14개, 색연필 15개, 자 7개.","가장 무거운 것은 색연필이에요."],"asset":null},{"stem":"공깃돌로 무게를 재었더니 공책 10개, 색연필 8개, 자 14개였어요. 가장 무거운 것은 무엇인가요?","options":[{"t":"자","correct":true},{"t":"색연필","mis":"M3-2-u5-X20"},{"t":"공책","mis":"M3-2-u5-X20"},{"t":"모두 같아요","mis":"M3-2-u5-X21"}],"explanation":["공깃돌이 많이 올라갈수록 더 무거워요.","공책 10개, 색연필 8개, 자 14개.","가장 무거운 것은 자예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L05_basic#8','math',3,2,'u5','L05','g3_2_math_u5_L05_basic','lesson_basic','M3-2-u5-C5',2,'ox','auto','은비가 저울을 보고 「위로 올라간 감자가 더 무거워.」라고 했어요. 바르게 말했어요.',ARRAY['M3-2-u5-X15']::text[],true,'{"seq":8,"concept":"M3-2-u5-C5","difficulty":2,"kind":"ox","stem":"은비가 저울을 보고 「위로 올라간 감자가 더 무거워.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"더 무거운 쪽이 아래로 내려가서","correct":true},{"t":"위로 올라간 쪽이 무거워서","mis":"M3-2-u5-X15"}],"mis":"M3-2-u5-X15","explanation":["양팔저울은 무거운 쪽이 내려가요.","양파 쪽이 내려갔어요.","양파가 더 무거워요 ×."],"asset":{"type":"balance","scales":[{"l":{"name":"감자","icon":"🥔"},"r":{"name":"양파","icon":"🧅"},"down":"r"}]},"variant_rule":{"alt":[{"stem":"지아가 저울을 보고 「위로 올라간 지우개가 더 무거워.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"더 무거운 쪽이 아래로 내려가서","correct":true},{"t":"위로 올라간 쪽이 무거워서","mis":"M3-2-u5-X15"}],"explanation":["양팔저울은 무거운 쪽이 내려가요.","필통 쪽이 내려갔어요.","필통이 더 무거워요 ×."],"asset":{"type":"balance","scales":[{"l":{"name":"필통","icon":"✏️"},"r":{"name":"지우개","icon":"🧽"},"down":"l"}]}},{"stem":"소율이 저울을 보고 「위로 올라간 페트병이 더 무거워.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"더 무거운 쪽이 아래로 내려가서","correct":true},{"t":"위로 올라간 쪽이 무거워서","mis":"M3-2-u5-X15"}],"explanation":["양팔저울은 무거운 쪽이 내려가요.","우유갑 쪽이 내려갔어요.","우유갑이 더 무거워요 ×."],"asset":{"type":"balance","scales":[{"l":{"name":"우유갑","icon":"🥛"},"r":{"name":"페트병","icon":"🍶"},"down":"l"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L05_basic#9','math',3,2,'u5','L05','g3_2_math_u5_L05_basic','lesson_basic','M3-2-u5-C5',2,'mc','auto','같은 샴푸 통의 무게를 쌓기나무로 재면 20개, 바둑돌로 재면 35개예요. 바르게 말한 것은 무엇인가요?',ARRAY['M3-2-u5-X03','M3-2-u5-X21']::text[],true,'{"seq":9,"concept":"M3-2-u5-C5","difficulty":2,"kind":"mc","stem":"같은 샴푸 통의 무게를 쌓기나무로 재면 20개, 바둑돌로 재면 35개예요. 바르게 말한 것은 무엇인가요?","options":[{"t":"재는 물건이 달라서 개수가 달라요","correct":true},{"t":"바둑돌로 잰 쪽이 더 무거워요","mis":"M3-2-u5-X03"},{"t":"어느 한쪽을 잘못 재었어요","mis":"M3-2-u5-X21"},{"t":"샴푸 통의 무게가 바뀌었어요","mis":"M3-2-u5-X21"}],"explanation":["같은 샴푸 통이에요 — 무게는 하나예요.","쌓기나무 한 개와 바둑돌 한 개의 무게가 달라요.","그래서 누구나 같게 말할 수 있는 단위(kg·g)가 필요해요."],"variant_rule":{"alt":[{"stem":"같은 필통의 무게를 쌓기나무로 재면 20개, 바둑돌로 재면 31개예요. 바르게 말한 것은 무엇인가요?","options":[{"t":"재는 물건이 달라서 개수가 달라요","correct":true},{"t":"바둑돌로 잰 쪽이 더 무거워요","mis":"M3-2-u5-X03"},{"t":"어느 한쪽을 잘못 재었어요","mis":"M3-2-u5-X21"},{"t":"필통의 무게가 바뀌었어요","mis":"M3-2-u5-X21"}],"explanation":["같은 필통이에요 — 무게는 하나예요.","쌓기나무 한 개와 바둑돌 한 개의 무게가 달라요.","그래서 누구나 같게 말할 수 있는 단위(kg·g)가 필요해요."],"asset":null},{"stem":"같은 샴푸 통의 무게를 쌓기나무로 재면 15개, 바둑돌로 재면 29개예요. 바르게 말한 것은 무엇인가요?","options":[{"t":"재는 물건이 달라서 개수가 달라요","correct":true},{"t":"바둑돌로 잰 쪽이 더 무거워요","mis":"M3-2-u5-X03"},{"t":"어느 한쪽을 잘못 재었어요","mis":"M3-2-u5-X21"},{"t":"샴푸 통의 무게가 바뀌었어요","mis":"M3-2-u5-X21"}],"explanation":["같은 샴푸 통이에요 — 무게는 하나예요.","쌓기나무 한 개와 바둑돌 한 개의 무게가 달라요.","그래서 누구나 같게 말할 수 있는 단위(kg·g)가 필요해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L05_basic#10','math',3,2,'u5','L05','g3_2_math_u5_L05_basic','lesson_basic','M3-2-u5-C5',3,'mc','auto','양팔저울 두 개로 ㉮ 주머니, ㉯ 주머니, ㉰ 주머니의 무게를 견주었어요. 가장 무거운 것은 무엇인가요?',ARRAY['M3-2-u5-X20','M3-2-u5-X15','M3-2-u5-X21']::text[],true,'{"seq":10,"concept":"M3-2-u5-C5","difficulty":3,"kind":"mc","stem":"양팔저울 두 개로 ㉮ 주머니, ㉯ 주머니, ㉰ 주머니의 무게를 견주었어요. 가장 무거운 것은 무엇인가요?","options":[{"t":"㉰ 주머니","correct":true},{"t":"㉯ 주머니","mis":"M3-2-u5-X20"},{"t":"㉮ 주머니","mis":"M3-2-u5-X15"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["저울마다 내려간 쪽이 더 무거워요.","㉰ 주머니 > ㉮ 주머니, ㉮ 주머니 > ㉯ 주머니.","무게 순서 ㉰ 주머니 > ㉮ 주머니 > ㉯ 주머니 — 가장 무거운 것은 ㉰ 주머니예요."],"asset":{"type":"balance","scales":[{"l":{"name":"㉰ 주머니","icon":"👜"},"r":{"name":"㉮ 주머니","icon":"👜"},"down":"l"},{"l":{"name":"㉯ 주머니","icon":"👜"},"r":{"name":"㉮ 주머니","icon":"👜"},"down":"r"}]},"variant_rule":{"alt":[{"stem":"양팔저울 두 개로 고구마, 감자, 당근의 무게를 견주었어요. 가장 무거운 것은 무엇인가요?","options":[{"t":"당근","correct":true},{"t":"고구마","mis":"M3-2-u5-X20"},{"t":"감자","mis":"M3-2-u5-X15"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["저울마다 내려간 쪽이 더 무거워요.","당근 > 감자, 감자 > 고구마.","무게 순서 당근 > 감자 > 고구마 — 가장 무거운 것은 당근이에요."],"asset":{"type":"balance","scales":[{"l":{"name":"감자","icon":"🥔"},"r":{"name":"당근","icon":"🥕"},"down":"r"},{"l":{"name":"감자","icon":"🥔"},"r":{"name":"고구마","icon":"🍠"},"down":"l"}]}},{"stem":"이번에는 다른 문제예요. 양팔저울 두 개로 ㉮ 주머니, ㉯ 주머니, ㉰ 주머니의 무게를 견주었어요. 가장 무거운 것은 무엇인가요?","options":[{"t":"㉯ 주머니","correct":true},{"t":"㉮ 주머니","mis":"M3-2-u5-X20"},{"t":"㉰ 주머니","mis":"M3-2-u5-X15"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["저울마다 내려간 쪽이 더 무거워요.","㉯ 주머니 > ㉰ 주머니, ㉰ 주머니 > ㉮ 주머니.","무게 순서 ㉯ 주머니 > ㉰ 주머니 > ㉮ 주머니 — 가장 무거운 것은 ㉯ 주머니예요."],"asset":{"type":"balance","scales":[{"l":{"name":"㉯ 주머니","icon":"👜"},"r":{"name":"㉰ 주머니","icon":"👜"},"down":"l"},{"l":{"name":"㉮ 주머니","icon":"👜"},"r":{"name":"㉰ 주머니","icon":"👜"},"down":"r"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L05_challenge#1','math',3,2,'u5','L05','g3_2_math_u5_L05_challenge','lesson_challenge','M3-2-u5-C5',2,'mc','auto','클립으로 무게를 재었더니 공책 14개, 색연필 6개, 자 12개였어요. 가장 가벼운 것은 무엇인가요?',ARRAY['M3-2-u5-X20','M3-2-u5-X21']::text[],true,'{"seq":1,"concept":"M3-2-u5-C5","difficulty":2,"kind":"mc","stem":"클립으로 무게를 재었더니 공책 14개, 색연필 6개, 자 12개였어요. 가장 가벼운 것은 무엇인가요?","options":[{"t":"색연필","correct":true},{"t":"공책","mis":"M3-2-u5-X20"},{"t":"자","mis":"M3-2-u5-X20"},{"t":"모두 같아요","mis":"M3-2-u5-X21"}],"explanation":["클립이 많이 올라갈수록 더 무거워요.","공책 14개, 색연필 6개, 자 12개.","가장 가벼운 것은 색연필이에요."],"variant_rule":{"alt":[{"stem":"클립으로 무게를 재었더니 연필 5개, 자 14개, 지우개 10개였어요. 가장 가벼운 것은 무엇인가요?","options":[{"t":"연필","correct":true},{"t":"자","mis":"M3-2-u5-X20"},{"t":"지우개","mis":"M3-2-u5-X20"},{"t":"모두 같아요","mis":"M3-2-u5-X21"}],"explanation":["클립이 많이 올라갈수록 더 무거워요.","연필 5개, 자 14개, 지우개 10개.","가장 가벼운 것은 연필이에요."],"asset":null},{"stem":"공깃돌로 무게를 재었더니 가위 13개, 풀 10개, 필통 14개였어요. 가장 가벼운 것은 무엇인가요?","options":[{"t":"풀","correct":true},{"t":"필통","mis":"M3-2-u5-X20"},{"t":"가위","mis":"M3-2-u5-X20"},{"t":"모두 같아요","mis":"M3-2-u5-X21"}],"explanation":["공깃돌이 많이 올라갈수록 더 무거워요.","가위 13개, 풀 10개, 필통 14개.","가장 가벼운 것은 풀이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L05_challenge#2','math',3,2,'u5','L05','g3_2_math_u5_L05_challenge','lesson_challenge','M3-2-u5-C5',2,'mc','auto','양파는 500원짜리 동전 22개, 감자는 100원짜리 동전 22개와 무게가 같아요. 두 무게가 다른 까닭은 무엇인가요?',ARRAY['M3-2-u5-X03','M3-2-u5-X16','M3-2-u5-X21']::text[],true,'{"seq":2,"concept":"M3-2-u5-C5","difficulty":2,"kind":"mc","stem":"양파는 500원짜리 동전 22개, 감자는 100원짜리 동전 22개와 무게가 같아요. 두 무게가 다른 까닭은 무엇인가요?","options":[{"t":"500원짜리와 100원짜리 동전 한 개의 무게가 달라서","correct":true},{"t":"동전의 개수가 달라서","mis":"M3-2-u5-X03"},{"t":"양파의 크기가 더 커서","mis":"M3-2-u5-X16"},{"t":"감자가 땅속에서 자라서","mis":"M3-2-u5-X21"}],"explanation":["두 물건 모두 동전 22개예요.","동전 한 개의 무게가 서로 달라요.","그래서 무게를 정확히 나타낼 같은 단위가 필요해요."],"variant_rule":{"alt":[{"stem":"필통은 500원짜리 동전 12개, 공책은 100원짜리 동전 12개와 무게가 같아요. 필통과 공책의 무게는 어떤가요?","options":[{"t":"서로 달라요","correct":true},{"t":"서로 같아요","mis":"M3-2-u5-X16"},{"t":"필통의 동전 개수가 더 많아요","mis":"M3-2-u5-X03"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["동전 개수는 12개로 같아요.","그런데 500원짜리와 100원짜리 동전은 한 개의 무게가 달라요.","재는 단위 물건이 다르면 개수가 같아도 무게가 달라요."],"asset":null},{"stem":"지우개는 500원짜리 동전 23개, 풀은 100원짜리 동전 23개와 무게가 같아요. 두 무게가 다른 까닭은 무엇인가요?","options":[{"t":"500원짜리와 100원짜리 동전 한 개의 무게가 달라서","correct":true},{"t":"동전의 개수가 달라서","mis":"M3-2-u5-X03"},{"t":"지우개의 크기가 더 커서","mis":"M3-2-u5-X16"},{"t":"풀이 땅속에서 자라서","mis":"M3-2-u5-X21"}],"explanation":["두 물건 모두 동전 23개예요.","동전 한 개의 무게가 서로 달라요.","그래서 무게를 정확히 나타낼 같은 단위가 필요해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L05_challenge#3','math',3,2,'u5','L05','g3_2_math_u5_L05_challenge','lesson_challenge','M3-2-u5-C5',3,'mc','auto','양팔저울 두 개로 빨간 상자, 파란 상자, 노란 상자의 무게를 견주었어요. 가장 무거운 것은 무엇인가요?',ARRAY['M3-2-u5-X20','M3-2-u5-X15','M3-2-u5-X21']::text[],true,'{"seq":3,"concept":"M3-2-u5-C5","difficulty":3,"kind":"mc","stem":"양팔저울 두 개로 빨간 상자, 파란 상자, 노란 상자의 무게를 견주었어요. 가장 무거운 것은 무엇인가요?","options":[{"t":"빨간 상자","correct":true},{"t":"파란 상자","mis":"M3-2-u5-X20"},{"t":"노란 상자","mis":"M3-2-u5-X15"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["저울마다 내려간 쪽이 더 무거워요.","빨간 상자 > 노란 상자, 노란 상자 > 파란 상자.","무게 순서 빨간 상자 > 노란 상자 > 파란 상자 — 가장 무거운 것은 빨간 상자예요."],"asset":{"type":"balance","scales":[{"l":{"name":"노란 상자","icon":"📦"},"r":{"name":"빨간 상자","icon":"📦"},"down":"r"},{"l":{"name":"노란 상자","icon":"📦"},"r":{"name":"파란 상자","icon":"📦"},"down":"l"}]},"variant_rule":{"alt":[{"stem":"양팔저울 두 개로 키위, 레몬, 감의 무게를 견주었어요. 가장 무거운 것은 무엇인가요?","options":[{"t":"레몬","correct":true},{"t":"키위","mis":"M3-2-u5-X20"},{"t":"감","mis":"M3-2-u5-X15"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["저울마다 내려간 쪽이 더 무거워요.","레몬 > 감, 감 > 키위.","무게 순서 레몬 > 감 > 키위 — 가장 무거운 것은 레몬이에요."],"asset":{"type":"balance","scales":[{"l":{"name":"레몬","icon":"🍋"},"r":{"name":"감","icon":"🟠"},"down":"l"},{"l":{"name":"키위","icon":"🥝"},"r":{"name":"감","icon":"🟠"},"down":"r"}]}},{"stem":"양팔저울 두 개로 고구마, 감자, 당근의 무게를 견주었어요. 가장 무거운 것은 무엇인가요?","options":[{"t":"감자","correct":true},{"t":"고구마","mis":"M3-2-u5-X20"},{"t":"당근","mis":"M3-2-u5-X15"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["저울마다 내려간 쪽이 더 무거워요.","감자 > 당근, 당근 > 고구마.","무게 순서 감자 > 당근 > 고구마 — 가장 무거운 것은 감자예요."],"asset":{"type":"balance","scales":[{"l":{"name":"당근","icon":"🥕"},"r":{"name":"감자","icon":"🥔"},"down":"r"},{"l":{"name":"당근","icon":"🥕"},"r":{"name":"고구마","icon":"🍠"},"down":"l"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L05_challenge#4','math',3,2,'u5','L05','g3_2_math_u5_L05_challenge','lesson_challenge','M3-2-u5-C5',3,'mc','auto','양팔저울 두 개로 키위, 레몬, 감의 무게를 견주었어요. 가장 가벼운 것은 무엇인가요?',ARRAY['M3-2-u5-X20','M3-2-u5-X15','M3-2-u5-X21']::text[],true,'{"seq":4,"concept":"M3-2-u5-C5","difficulty":3,"kind":"mc","stem":"양팔저울 두 개로 키위, 레몬, 감의 무게를 견주었어요. 가장 가벼운 것은 무엇인가요?","options":[{"t":"레몬","correct":true},{"t":"키위","mis":"M3-2-u5-X20"},{"t":"감","mis":"M3-2-u5-X15"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["저울마다 내려간 쪽이 더 무거워요.","키위 > 감, 감 > 레몬.","무게 순서 키위 > 감 > 레몬 — 가장 가벼운 것은 레몬이에요."],"asset":{"type":"balance","scales":[{"l":{"name":"감","icon":"🟠"},"r":{"name":"키위","icon":"🥝"},"down":"r"},{"l":{"name":"감","icon":"🟠"},"r":{"name":"레몬","icon":"🍋"},"down":"l"}]},"variant_rule":{"alt":[{"stem":"양팔저울 두 개로 빨간 상자, 파란 상자, 노란 상자의 무게를 견주었어요. 가장 가벼운 것은 무엇인가요?","options":[{"t":"빨간 상자","correct":true},{"t":"파란 상자","mis":"M3-2-u5-X20"},{"t":"노란 상자","mis":"M3-2-u5-X15"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["저울마다 내려간 쪽이 더 무거워요.","파란 상자 > 노란 상자, 노란 상자 > 빨간 상자.","무게 순서 파란 상자 > 노란 상자 > 빨간 상자 — 가장 가벼운 것은 빨간 상자예요."],"asset":{"type":"balance","scales":[{"l":{"name":"파란 상자","icon":"📦"},"r":{"name":"노란 상자","icon":"📦"},"down":"l"},{"l":{"name":"빨간 상자","icon":"📦"},"r":{"name":"노란 상자","icon":"📦"},"down":"r"}]}},{"stem":"양팔저울 두 개로 고구마, 감자, 당근의 무게를 견주었어요. 가장 가벼운 것은 무엇인가요?","options":[{"t":"당근","correct":true},{"t":"감자","mis":"M3-2-u5-X20"},{"t":"고구마","mis":"M3-2-u5-X15"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["저울마다 내려간 쪽이 더 무거워요.","감자 > 고구마, 고구마 > 당근.","무게 순서 감자 > 고구마 > 당근 — 가장 가벼운 것은 당근이에요."],"asset":{"type":"balance","scales":[{"l":{"name":"고구마","icon":"🍠"},"r":{"name":"감자","icon":"🥔"},"down":"r"},{"l":{"name":"고구마","icon":"🍠"},"r":{"name":"당근","icon":"🥕"},"down":"l"}]}}]}}'::js