INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L05_challenge#5','math',3,2,'u5','L05','g3_2_math_u5_L05_challenge','lesson_challenge','M3-2-u5-C5',3,'ox','auto','채원이 「베개가 책보다 크니까 항상 더 무거워.」라고 했어요. 바르게 말했어요.',ARRAY['M3-2-u5-X16']::text[],true,'{"seq":5,"concept":"M3-2-u5-C5","difficulty":3,"kind":"ox","stem":"채원이 「베개가 책보다 크니까 항상 더 무거워.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"크기가 커도 더 가벼울 수 있어서","correct":true},{"t":"큰 물건은 언제나 무거워서","mis":"M3-2-u5-X16"}],"mis":"M3-2-u5-X16","explanation":["크기와 무게는 다를 수 있어요.","크기가 커도 가벼운 물건이 있어요(풍선·빈 상자).","무게는 양팔저울이나 저울로 견주어야 해요 ×."],"variant_rule":{"alt":[{"stem":"은비가 「풍선이 사과보다 크니까 항상 더 무거워.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"크기가 커도 더 가벼울 수 있어서","correct":true},{"t":"큰 물건은 언제나 무거워서","mis":"M3-2-u5-X16"}],"explanation":["크기와 무게는 다를 수 있어요.","크기가 커도 가벼운 물건이 있어요(풍선·빈 상자).","무게는 양팔저울이나 저울로 견주어야 해요 ×."],"asset":null},{"stem":"준우가 「솜인형이 벽돌보다 크니까 항상 더 무거워.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"크기가 커도 더 가벼울 수 있어서","correct":true},{"t":"큰 물건은 언제나 무거워서","mis":"M3-2-u5-X16"}],"explanation":["크기와 무게는 다를 수 있어요.","크기가 커도 가벼운 물건이 있어요(풍선·빈 상자).","무게는 양팔저울이나 저울로 견주어야 해요 ×."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L05_challenge#6','math',3,2,'u5','L05','g3_2_math_u5_L05_challenge','lesson_challenge','M3-2-u5-C5',3,'mc','auto','같은 필통의 무게를 쌓기나무로 재면 20개, 바둑돌로 재면 32개예요. 바르게 말한 것은 무엇인가요?',ARRAY['M3-2-u5-X03','M3-2-u5-X21']::text[],true,'{"seq":6,"concept":"M3-2-u5-C5","difficulty":3,"kind":"mc","stem":"같은 필통의 무게를 쌓기나무로 재면 20개, 바둑돌로 재면 32개예요. 바르게 말한 것은 무엇인가요?","options":[{"t":"재는 물건이 달라서 개수가 달라요","correct":true},{"t":"바둑돌로 잰 쪽이 더 무거워요","mis":"M3-2-u5-X03"},{"t":"어느 한쪽을 잘못 재었어요","mis":"M3-2-u5-X21"},{"t":"필통의 무게가 바뀌었어요","mis":"M3-2-u5-X21"}],"explanation":["같은 필통이에요 — 무게는 하나예요.","쌓기나무 한 개와 바둑돌 한 개의 무게가 달라요.","그래서 누구나 같게 말할 수 있는 단위(kg·g)가 필요해요."],"variant_rule":{"alt":[{"stem":"같은 필통의 무게를 쌓기나무로 재면 15개, 바둑돌로 재면 25개예요. 바르게 말한 것은 무엇인가요?","options":[{"t":"재는 물건이 달라서 개수가 달라요","correct":true},{"t":"바둑돌로 잰 쪽이 더 무거워요","mis":"M3-2-u5-X03"},{"t":"어느 한쪽을 잘못 재었어요","mis":"M3-2-u5-X21"},{"t":"필통의 무게가 바뀌었어요","mis":"M3-2-u5-X21"}],"explanation":["같은 필통이에요 — 무게는 하나예요.","쌓기나무 한 개와 바둑돌 한 개의 무게가 달라요.","그래서 누구나 같게 말할 수 있는 단위(kg·g)가 필요해요."],"asset":null},{"stem":"같은 필통의 무게를 쌓기나무로 재면 12개, 바둑돌로 재면 21개예요. 바르게 말한 것은 무엇인가요?","options":[{"t":"재는 물건이 달라서 개수가 달라요","correct":true},{"t":"바둑돌로 잰 쪽이 더 무거워요","mis":"M3-2-u5-X03"},{"t":"어느 한쪽을 잘못 재었어요","mis":"M3-2-u5-X21"},{"t":"필통의 무게가 바뀌었어요","mis":"M3-2-u5-X21"}],"explanation":["같은 필통이에요 — 무게는 하나예요.","쌓기나무 한 개와 바둑돌 한 개의 무게가 달라요.","그래서 누구나 같게 말할 수 있는 단위(kg·g)가 필요해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L05_challenge#7','math',3,2,'u5','L05','g3_2_math_u5_L05_challenge','lesson_challenge','M3-2-u5-C5',3,'sa','auto','고구마의 무게는 공깃돌 13개, 당근의 무게는 공깃돌 10개와 같아요. 당근은 고구마보다 공깃돌 몇 개만큼 더 가벼운가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u5-C5","difficulty":3,"kind":"sa","stem":"고구마의 무게는 공깃돌 13개, 당근의 무게는 공깃돌 10개와 같아요. 당근은 고구마보다 공깃돌 몇 개만큼 더 가벼운가요? 숫자로 쓰세요.","answer":["3"],"explanation":["같은 공깃돌으로 재었으니 개수로 견줄 수 있어요.","고구마 13개, 당근 10개.","13 − 10 = 3 — 공깃돌 3개만큼 더 가벼워요."],"variant_rule":{"alt":[{"stem":"우유갑의 무게는 쌓기나무 25개, 페트병의 무게는 쌓기나무 22개와 같아요. 페트병은 우유갑보다 쌓기나무 몇 개만큼 더 가벼운가요? 숫자로 쓰세요.","answer":["3"],"explanation":["같은 쌓기나무로 재었으니 개수로 견줄 수 있어요.","우유갑 25개, 페트병 22개.","25 − 22 = 3 — 쌓기나무 3개만큼 더 가벼워요."],"asset":null},{"stem":"고구마의 무게는 공깃돌 8개, 당근의 무게는 공깃돌 25개와 같아요. 고구마는 당근보다 공깃돌 몇 개만큼 더 가벼운가요? 숫자로 쓰세요.","answer":["17"],"explanation":["같은 공깃돌으로 재었으니 개수로 견줄 수 있어요.","고구마 8개, 당근 25개.","25 − 8 = 17 — 공깃돌 17개만큼 더 가벼워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L05_challenge#8','math',3,2,'u5','L05','g3_2_math_u5_L05_challenge','lesson_challenge','M3-2-u5-C5',4,'essay','teacher','빈 우유갑과 빈 페트병 중에서 더 무거운 것을 저금통으로 쓰려고 해요. 양손에 들어 보는 방법과 양팔저울에 올리는 방법을 견주어, 어느 방법이 더 좋은지 까닭과 함께 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u5-C5","difficulty":4,"kind":"essay","stem":"빈 우유갑과 빈 페트병 중에서 더 무거운 것을 저금통으로 쓰려고 해요. 양손에 들어 보는 방법과 양팔저울에 올리는 방법을 견주어, 어느 방법이 더 좋은지 까닭과 함께 설명해 보세요.","answer_guide":{"answer":"예: 양손에 들어 보는 방법은 쉽지만 두 무게가 비슷하면 어느 쪽이 무거운지 알기 어렵다. 양팔저울에 올리면 더 무거운 쪽이 아래로 내려가서 분명하게 알 수 있으므로 양팔저울이 더 좋다. 우유갑 쪽으로 기울면 우유갑이 더 무겁다.","scoring_points":["양손으로 들면 비슷한 무게를 알기 어렵다고 썼는가","양팔저울은 무거운 쪽이 내려간다고 썼는가","양팔저울이 더 분명하다고 판단했는가"]},"explanation":["양손 — 쉽지만 비슷하면 어려워요.","양팔저울 — 무거운 쪽이 내려가요.","양팔저울이 더 분명해요."],"asset":{"type":"balance","scales":[{"l":{"name":"우유갑","icon":"🥛"},"r":{"name":"페트병","icon":"🍶"},"down":"l"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L05_challenge#9','math',3,2,'u5','L05','g3_2_math_u5_L05_challenge','lesson_challenge','M3-2-u5-C5',4,'essay','teacher','같은 필통의 무게를 바둑돌로 재면 18개, 쌓기나무로 재면 12개예요. 도윤이는 「바둑돌로 잰 수가 더 크니까 바둑돌로 잴 때 더 무겁게 나와.」라고 했어요. 도윤이의 말이 맞는지 판단하고 왜 수가 달라지는지 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u5-C5","difficulty":4,"kind":"essay","stem":"같은 필통의 무게를 바둑돌로 재면 18개, 쌓기나무로 재면 12개예요. 도윤이는 「바둑돌로 잰 수가 더 크니까 바둑돌로 잴 때 더 무겁게 나와.」라고 했어요. 도윤이의 말이 맞는지 판단하고 왜 수가 달라지는지 설명해 보세요.","answer_guide":{"answer":"예: 틀렸다. 같은 필통이라 무게는 하나이다. 바둑돌 한 개가 쌓기나무 한 개보다 가벼워서 더 많이 필요한 것이다. 재는 물건이 다르면 수가 달라지므로 누구나 같게 말할 수 있는 단위(kg·g)가 필요하다.","scoring_points":["틀렸다고 판단했는가","단위 물건 한 개의 무게가 달라서라고 설명했는가","같은 단위가 필요하다고 썼는가"]},"explanation":["같은 필통 — 무게는 하나.","바둑돌 한 개가 더 가벼워 더 많이 필요해요.","같은 단위(kg·g)가 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L05_challenge#10','math',3,2,'u5','L05','g3_2_math_u5_L05_challenge','lesson_challenge','M3-2-u5-C5',4,'mc','auto','바둑돌로 무게를 재었더니 공책 13개, 색연필 14개, 자 5개였어요. 가장 무거운 것은 무엇인가요?',ARRAY['M3-2-u5-X20','M3-2-u5-X21']::text[],true,'{"seq":10,"concept":"M3-2-u5-C5","difficulty":4,"kind":"mc","stem":"바둑돌로 무게를 재었더니 공책 13개, 색연필 14개, 자 5개였어요. 가장 무거운 것은 무엇인가요?","options":[{"t":"색연필","correct":true},{"t":"자","mis":"M3-2-u5-X20"},{"t":"공책","mis":"M3-2-u5-X20"},{"t":"모두 같아요","mis":"M3-2-u5-X21"}],"explanation":["바둑돌이 많이 올라갈수록 더 무거워요.","공책 13개, 색연필 14개, 자 5개.","가장 무거운 것은 색연필이에요."],"variant_rule":{"alt":[{"stem":"공깃돌로 무게를 재었더니 가위 10개, 풀 9개, 필통 8개였어요. 가장 무거운 것은 무엇인가요?","options":[{"t":"가위","correct":true},{"t":"필통","mis":"M3-2-u5-X20"},{"t":"풀","mis":"M3-2-u5-X20"},{"t":"모두 같아요","mis":"M3-2-u5-X21"}],"explanation":["공깃돌이 많이 올라갈수록 더 무거워요.","가위 10개, 풀 9개, 필통 8개.","가장 무거운 것은 가위예요."],"asset":null},{"stem":"공깃돌로 무게를 재었더니 연필 6개, 자 8개, 지우개 13개였어요. 가장 무거운 것은 무엇인가요?","options":[{"t":"지우개","correct":true},{"t":"연필","mis":"M3-2-u5-X20"},{"t":"자","mis":"M3-2-u5-X20"},{"t":"모두 같아요","mis":"M3-2-u5-X21"}],"explanation":["공깃돌이 많이 올라갈수록 더 무거워요.","연필 6개, 자 8개, 지우개 13개.","가장 무거운 것은 지우개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L06_basic#1','math',3,2,'u5','L06','g3_2_math_u5_L06_basic','lesson_basic','M3-2-u5-C6',1,'sa','auto','3 kg 600 g은 몇 g인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u5-C6","difficulty":1,"kind":"sa","stem":"3 kg 600 g은 몇 g인가요? 숫자로 쓰세요.","answer":["3600"],"explanation":["1 kg = 1000 g — 3 kg = 3000 g.","3000 g + 600 g = 3600 g.","3 kg 600 g = 3600 g."],"variant_rule":{"alt":[{"stem":"8 kg 700 g은 몇 g인가요? 숫자로 쓰세요.","answer":["8700"],"explanation":["1 kg = 1000 g — 8 kg = 8000 g.","8000 g + 700 g = 8700 g.","8 kg 700 g = 8700 g."],"asset":null},{"stem":"8 kg 300 g은 몇 g인가요? 숫자로 쓰세요.","answer":["8300"],"explanation":["1 kg = 1000 g — 8 kg = 8000 g.","8000 g + 300 g = 8300 g.","8 kg 300 g = 8300 g."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L06_basic#2','math',3,2,'u5','L06','g3_2_math_u5_L06_basic','lesson_basic','M3-2-u5-C6',1,'sa','auto','4900 g은 몇 kg 몇 g인가요? kg 앞에 올 수를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u5-C6","difficulty":1,"kind":"sa","stem":"4900 g은 몇 kg 몇 g인가요? kg 앞에 올 수를 쓰세요.","answer":["4"],"explanation":["1000 g = 1 kg이에요.","4900 = 4000 + 900.","4900 g = 4 kg 900 g — kg 앞은 4."],"variant_rule":{"alt":[{"stem":"9200 g은 몇 kg 몇 g인가요? kg 앞에 올 수를 쓰세요.","answer":["9"],"explanation":["1000 g = 1 kg이에요.","9200 = 9000 + 200.","9200 g = 9 kg 200 g — kg 앞은 9."],"asset":null},{"stem":"6800 g은 몇 kg 몇 g인가요? kg 앞에 올 수를 쓰세요.","answer":["6"],"explanation":["1000 g = 1 kg이에요.","6800 = 6000 + 800.","6800 g = 6 kg 800 g — kg 앞은 6."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L06_basic#3','math',3,2,'u5','L06','g3_2_math_u5_L06_basic','lesson_basic','M3-2-u5-C7',1,'sa','auto','4 t은 몇 kg인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u5-C7","difficulty":1,"kind":"sa","stem":"4 t은 몇 kg인가요? 숫자로 쓰세요.","answer":["4000"],"explanation":["1 t = 1000 kg이에요.","4 t = 1000 kg이 4번.","4 t = 4000 kg."],"variant_rule":{"alt":[{"stem":"5 t은 몇 kg인가요? 숫자로 쓰세요.","answer":["5000"],"explanation":["1 t = 1000 kg이에요.","5 t = 1000 kg이 5번.","5 t = 5000 kg."],"asset":null},{"stem":"2 t은 몇 kg인가요? 숫자로 쓰세요.","answer":["2000"],"explanation":["1 t = 1000 kg이에요.","2 t = 1000 kg이 2번.","2 t = 2000 kg."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L06_basic#4','math',3,2,'u5','L06','g3_2_math_u5_L06_basic','lesson_basic','M3-2-u5-C6',1,'mc','auto','1 kg 500 g은 몇 g인가요?',ARRAY['M3-2-u5-X05','M3-2-u5-X04','M3-2-u5-X11']::text[],true,'{"seq":4,"concept":"M3-2-u5-C6","difficulty":1,"kind":"mc","stem":"1 kg 500 g은 몇 g인가요?","options":[{"t":"1500 g","correct":true},{"t":"10500 g","mis":"M3-2-u5-X05"},{"t":"600 g","mis":"M3-2-u5-X04"},{"t":"501 g","mis":"M3-2-u5-X11"}],"explanation":["1 kg = 1000 g — 1 kg = 1000 g.","1000 g + 500 g = 1500 g.","1 kg 500 g = 1500 g."],"variant_rule":{"alt":[{"stem":"9 kg 600 g은 몇 g인가요?","options":[{"t":"9600 g","correct":true},{"t":"90600 g","mis":"M3-2-u5-X05"},{"t":"1500 g","mis":"M3-2-u5-X04"},{"t":"609 g","mis":"M3-2-u5-X11"}],"explanation":["1 kg = 1000 g — 9 kg = 9000 g.","9000 g + 600 g = 9600 g.","9 kg 600 g = 9600 g."],"asset":null},{"stem":"3 kg 200 g은 몇 g인가요?","options":[{"t":"3200 g","correct":true},{"t":"30200 g","mis":"M3-2-u5-X05"},{"t":"500 g","mis":"M3-2-u5-X04"},{"t":"203 g","mis":"M3-2-u5-X11"}],"explanation":["1 kg = 1000 g — 3 kg = 3000 g.","3000 g + 200 g = 3200 g.","3 kg 200 g = 3200 g."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L06_basic#5','math',3,2,'u5','L06','g3_2_math_u5_L06_basic','lesson_basic','M3-2-u5-C6',2,'mc','auto','1 kg 300 g을 바르게 읽은 것은 무엇인가요?',ARRAY['M3-2-u5-X06','M3-2-u5-X05']::text[],true,'{"seq":5,"concept":"M3-2-u5-C6","difficulty":2,"kind":"mc","stem":"1 kg 300 g을 바르게 읽은 것은 무엇인가요?","options":[{"t":"1 킬로그램 300 그램","correct":true},{"t":"1 그램 300 킬로그램","mis":"M3-2-u5-X06"},{"t":"1300 킬로그램","mis":"M3-2-u5-X05"},{"t":"1 킬로그램 300 킬로그램","mis":"M3-2-u5-X06"}],"explanation":["1 kg은 1 킬로그램이라고 읽어요.","1 kg 300 g의 앞은 킬로그램, 뒤는 그램.","1 kg 300 g — 1 킬로그램 300 그램."],"variant_rule":{"alt":[{"stem":"9 kg 800 g을 바르게 읽은 것은 무엇인가요?","options":[{"t":"9 킬로그램 800 그램","correct":true},{"t":"9 그램 800 킬로그램","mis":"M3-2-u5-X06"},{"t":"9800 킬로그램","mis":"M3-2-u5-X05"},{"t":"9 킬로그램 800 킬로그램","mis":"M3-2-u5-X06"}],"explanation":["1 kg은 1 킬로그램이라고 읽어요.","9 kg 800 g의 앞은 킬로그램, 뒤는 그램.","9 kg 800 g — 9 킬로그램 800 그램."],"asset":null},{"stem":"3 kg 20 g을 바르게 읽은 것은 무엇인가요?","options":[{"t":"3 킬로그램 20 그램","correct":true},{"t":"3 그램 20 킬로그램","mis":"M3-2-u5-X06"},{"t":"320 킬로그램","mis":"M3-2-u5-X05"},{"t":"3 킬로그램 20 킬로그램","mis":"M3-2-u5-X06"}],"explanation":["1 kg은 1 킬로그램이라고 읽어요.","3 kg 20 g의 앞은 킬로그램, 뒤는 그램.","3 kg 20 g — 3 킬로그램 20 그램."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L06_basic#6','math',3,2,'u5','L06','g3_2_math_u5_L06_basic','lesson_basic','M3-2-u5-C6',2,'mc','auto','지아가 모은 재활용품은 3 kg 40 g, 은비가 모은 재활용품은 3400 g이에요. 누가 더 무겁게 모았나요?',ARRAY['M3-2-u5-X05','M3-2-u5-X21']::text[],true,'{"seq":6,"concept":"M3-2-u5-C6","difficulty":2,"kind":"mc","stem":"지아가 모은 재활용품은 3 kg 40 g, 은비가 모은 재활용품은 3400 g이에요. 누가 더 무겁게 모았나요?","options":[{"t":"은비","correct":true},{"t":"지아","mis":"M3-2-u5-X05"},{"t":"두 사람이 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["한 가지 단위로 바꾸어 견주어요.","3 kg 40 g = 3040 g.","3040 g < 3400 g — 은비가 더 무겁게 모았어요."],"variant_rule":{"alt":[{"stem":"지아가 모은 재활용품은 4 kg 30 g, 은비가 모은 재활용품은 4300 g이에요. 누가 더 무겁게 모았나요?","options":[{"t":"은비","correct":true},{"t":"지아","mis":"M3-2-u5-X05"},{"t":"두 사람이 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["한 가지 단위로 바꾸어 견주어요.","4 kg 30 g = 4030 g.","4030 g < 4300 g — 은비가 더 무겁게 모았어요."],"asset":null},{"stem":"서준이 모은 재활용품은 4 kg 60 g, 민아가 모은 재활용품은 4600 g이에요. 누가 더 무겁게 모았나요?","options":[{"t":"민아","correct":true},{"t":"서준","mis":"M3-2-u5-X05"},{"t":"두 사람이 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["한 가지 단위로 바꾸어 견주어요.","4 kg 60 g = 4060 g.","4060 g < 4600 g — 민아가 더 무겁게 모았어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L06_basic#7','math',3,2,'u5','L06','g3_2_math_u5_L06_basic','lesson_basic','M3-2-u5-C6',2,'sa','auto','저울의 큰 눈금 0과 1 kg 사이가 똑같이 5칸으로 나뉘어 있어요. 현미를 재었더니 바늘이 0에서부터 17칸째 눈금을 가리켜요. 몇 g인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u5-C6","difficulty":2,"kind":"sa","stem":"저울의 큰 눈금 0과 1 kg 사이가 똑같이 5칸으로 나뉘어 있어요. 현미를 재었더니 바늘이 0에서부터 17칸째 눈금을 가리켜요. 몇 g인가요? 숫자로 쓰세요.","answer":["3400"],"explanation":["한 칸의 크기부터: 1 kg = 1000 g, 1000 ÷ 5 = 200 g.","17칸 → 200 × 17 = 3400.","3400 g이에요."],"variant_rule":{"alt":[{"stem":"저울의 큰 눈금 0과 1 kg 사이가 똑같이 10칸으로 나뉘어 있어요. 현미를 재었더니 바늘이 0에서부터 28칸째 눈금을 가리켜요. 몇 g인가요? 숫자로 쓰세요.","answer":["2800"],"explanation":["한 칸의 크기부터: 1 kg = 1000 g, 1000 ÷ 10 = 100 g.","28칸 → 100 × 28 = 2800.","2800 g이에요."],"asset":null},{"stem":"저울의 큰 눈금 0과 1 kg 사이가 똑같이 2칸으로 나뉘어 있어요. 현미를 재었더니 바늘이 0에서부터 7칸째 눈금을 가리켜요. 몇 g인가요? 숫자로 쓰세요.","answer":["3500"],"explanation":["한 칸의 크기부터: 1 kg = 1000 g, 1000 ÷ 2 = 500 g.","7칸 → 500 × 7 = 3500.","3500 g이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L06_basic#8','math',3,2,'u5','L06','g3_2_math_u5_L06_basic','lesson_basic','M3-2-u5-C7',2,'mc','auto','잘못 나타낸 것은 무엇인가요?',ARRAY['M3-2-u5-X21']::text[],true,'{"seq":8,"concept":"M3-2-u5-C7","difficulty":2,"kind":"mc","stem":"잘못 나타낸 것은 무엇인가요?","options":[{"t":"6 t은 600 kg이에요","correct":true},{"t":"5 t은 5000 kg이에요","mis":"M3-2-u5-X21"},{"t":"5850 g은 5 kg 850 g이에요","mis":"M3-2-u5-X21"},{"t":"1 t은 1000 kg이에요","mis":"M3-2-u5-X21"}],"explanation":["1 t = 1000 kg, 1 kg = 1000 g.","6 t = 6000 kg이에요.","「6 t은 600 kg이에요」 — 1 t을 100 kg으로 본 잘못이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 잘못 나타낸 것은 무엇인가요?","options":[{"t":"6 t은 600 kg이에요","correct":true},{"t":"8 t은 8000 kg이에요","mis":"M3-2-u5-X21"},{"t":"5840 g은 5 kg 840 g이에요","mis":"M3-2-u5-X21"},{"t":"1 t은 1000 kg이에요","mis":"M3-2-u5-X21"}],"explanation":["1 t = 1000 kg, 1 kg = 1000 g.","6 t = 6000 kg이에요.","「6 t은 600 kg이에요」 — 1 t을 100 kg으로 본 잘못이에요."],"asset":null},{"stem":"이번에는 다른 문제예요. 잘못 나타낸 것은 무엇인가요?","options":[{"t":"9 t은 900 kg이에요","correct":true},{"t":"4 t은 4000 kg이에요","mis":"M3-2-u5-X21"},{"t":"3430 g은 3 kg 430 g이에요","mis":"M3-2-u5-X21"},{"t":"1 t은 1000 kg이에요","mis":"M3-2-u5-X21"}],"explanation":["1 t = 1000 kg, 1 kg = 1000 g.","9 t = 9000 kg이에요.","「9 t은 900 kg이에요」 — 1 t을 100 kg으로 본 잘못이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L06_basic#9','math',3,2,'u5','L06','g3_2_math_u5_L06_basic','lesson_basic','M3-2-u5-C7',2,'sa','auto','트럭에 짐을 5000 kg 실었어요. 실은 짐은 몇 t인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u5-C7","difficulty":2,"kind":"sa","stem":"트럭에 짐을 5000 kg 실었어요. 실은 짐은 몇 t인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["1000 kg = 1 t이에요.","5000 kg = 1000 kg이 5번.","5 t이에요."],"variant_rule":{"alt":[{"stem":"트럭에 짐을 3000 kg 실었어요. 실은 짐은 몇 t인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["1000 kg = 1 t이에요.","3000 kg = 1000 kg이 3번.","3 t이에요."],"asset":null},{"stem":"트럭에 짐을 6000 kg 실었어요. 실은 짐은 몇 t인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["1000 kg = 1 t이에요.","6000 kg = 1000 kg이 6번.","6 t이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L06_basic#10','math',3,2,'u5','L06','g3_2_math_u5_L06_basic','lesson_basic','M3-2-u5-C7',3,'sa','auto','쌀 1 t을 10 kg 포대에 똑같이 나누어 담으면 모두 몇 포대가 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-2-u5-C7","difficulty":3,"kind":"sa","stem":"쌀 1 t을 10 kg 포대에 똑같이 나누어 담으면 모두 몇 포대가 되나요? 숫자로 쓰세요.","answer":["100"],"explanation":["1 t = 1000 kg이에요.","1000 ÷ 10 = 100.","100포대가 돼요."],"variant_rule":{"alt":[{"stem":"쌀 2 t을 20 kg 포대에 똑같이 나누어 담으면 모두 몇 포대가 되나요? 숫자로 쓰세요.","answer":["100"],"explanation":["2 t = 2000 kg이에요.","2000 ÷ 20 = 100.","100포대가 돼요."],"asset":null},{"stem":"쌀 1 t을 25 kg 포대에 똑같이 나누어 담으면 모두 몇 포대가 되나요? 숫자로 쓰세요.","answer":["40"],"explanation":["1 t = 1000 kg이에요.","1000 ÷ 25 = 40.","40포대가 돼요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L06_challenge#1','math',3,2,'u5','L06','g3_2_math_u5_L06_challenge','lesson_challenge','M3-2-u5-C7',2,'mc','auto','6 t은 몇 kg인가요?',ARRAY['M3-2-u5-X17']::text[],true,'{"seq":1,"concept":"M3-2-u5-C7","difficulty":2,"kind":"mc","stem":"6 t은 몇 kg인가요?","options":[{"t":"6000 kg","correct":true},{"t":"600 kg","mis":"M3-2-u5-X17"},{"t":"60000 kg","mis":"M3-2-u5-X17"},{"t":"60 kg","mis":"M3-2-u5-X17"}],"explanation":["1 t = 1000 kg이에요.","6 t = 1000 kg이 6번.","6 t = 6000 kg."],"variant_rule":{"alt":[{"stem":"3 t은 몇 kg인가요?","options":[{"t":"3000 kg","correct":true},{"t":"300 kg","mis":"M3-2-u5-X17"},{"t":"30000 kg","mis":"M3-2-u5-X17"},{"t":"30 kg","mis":"M3-2-u5-X17"}],"explanation":["1 t = 1000 kg이에요.","3 t = 1000 kg이 3번.","3 t = 3000 kg."],"asset":null},{"stem":"5 t은 몇 kg인가요?","options":[{"t":"5000 kg","correct":true},{"t":"500 kg","mis":"M3-2-u5-X17"},{"t":"50000 kg","mis":"M3-2-u5-X17"},{"t":"50 kg","mis":"M3-2-u5-X17"}],"explanation":["1 t = 1000 kg이에요.","5 t = 1000 kg이 5번.","5 t = 5000 kg."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L06_challenge#2','math',3,2,'u5','L06','g3_2_math_u5_L06_challenge','lesson_challenge','M3-2-u5-C6',2,'sa','auto','7070 g은 몇 kg 몇 g인가요? kg 앞에 올 수를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u5-C6","difficulty":2,"kind":"sa","stem":"7070 g은 몇 kg 몇 g인가요? kg 앞에 올 수를 쓰세요.","answer":["7"],"explanation":["1000 g = 1 kg이에요.","7070 = 7000 + 70.","7070 g = 7 kg 70 g — kg 앞은 7."],"variant_rule":{"alt":[{"stem":"4060 g은 몇 kg 몇 g인가요? g 앞에 올 수를 쓰세요.","answer":["60"],"explanation":["1000 g을 1 kg으로 묶어요.","4060 = 4000 + 60.","4060 g = 4 kg 60 g — g 앞은 60."],"asset":null},{"stem":"5050 g은 몇 kg 몇 g인가요? kg 앞에 올 수를 쓰세요.","answer":["5"],"explanation":["1000 g = 1 kg이에요.","5050 = 5000 + 50.","5050 g = 5 kg 50 g — kg 앞은 5."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L06_challenge#3','math',3,2,'u5','L06','g3_2_math_u5_L06_challenge','lesson_challenge','M3-2-u5-C6',3,'mc','auto','㉮는 3 kg 10 g, ㉯는 3100 g이에요. 무게가 더 무거운 것은 무엇인가요?',ARRAY['M3-2-u5-X20','M3-2-u5-X21']::text[],true,'{"seq":3,"concept":"M3-2-u5-C6","difficulty":3,"kind":"mc","stem":"㉮는 3 kg 10 g, ㉯는 3100 g이에요. 무게가 더 무거운 것은 무엇인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M3-2-u5-X20"},{"t":"두 무게가 같아요","mis":"M3-2-u5-X21"},{"t":"단위가 달라서 견줄 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["한 가지 단위로 바꾸어 견주어요.","3 kg 10 g = 3010 g.","3010 g < 3100 g — 무게가 더 무거운 것은 ㉯예요."],"variant_rule":{"alt":[{"stem":"㉮는 2 kg 30 g, ㉯는 2300 g이에요. 무게가 더 무거운 것은 무엇인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M3-2-u5-X20"},{"t":"두 무게가 같아요","mis":"M3-2-u5-X21"},{"t":"단위가 달라서 견줄 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["한 가지 단위로 바꾸어 견주어요.","2 kg 30 g = 2030 g.","2030 g < 2300 g — 무게가 더 무거운 것은 ㉯예요."],"asset":null},{"stem":"㉮는 4 kg 50 g, ㉯는 4505 g이에요. 무게가 더 무거운 것은 무엇인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M3-2-u5-X20"},{"t":"두 무게가 같아요","mis":"M3-2-u5-X21"},{"t":"단위가 달라서 견줄 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["한 가지 단위로 바꾸어 견주어요.","4 kg 50 g = 4050 g.","4050 g < 4505 g — 무게가 더 무거운 것은 ㉯예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L06_challenge#4','math',3,2,'u5','L06','g3_2_math_u5_L06_challenge','lesson_challenge','M3-2-u5-C6',3,'error','auto','무게의 단위를 바꾸며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u5-X04','M3-2-u5-X21']::text[],true,'{"seq":4,"concept":"M3-2-u5-C6","difficulty":3,"kind":"error","stem":"무게의 단위를 바꾸며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"소율 — 「2 kg 70 g = 270 g」","correct":true,"mis_target":"M3-2-u5-X04"},{"t":"도윤 — 「1 kg = 1000 g」","mis":"M3-2-u5-X21"},{"t":"지아 — 「3 kg = 3000 g」","mis":"M3-2-u5-X21"},{"t":"민아 — 「3070 g = 3 kg 70 g」","mis":"M3-2-u5-X21"}],"explanation":["1 kg = 1000 g이에요.","2 kg 70 g = 2070 g.","소율의 말이 틀렸어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 무게의 단위를 바꾸며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하윤 — 「2 kg 690 g = 890 g」","correct":true,"mis_target":"M3-2-u5-X04"},{"t":"은비 — 「1 kg = 1000 g」","mis":"M3-2-u5-X21"},{"t":"지아 — 「3 kg = 3000 g」","mis":"M3-2-u5-X21"},{"t":"민아 — 「3690 g = 3 kg 690 g」","mis":"M3-2-u5-X21"}],"explanation":["1 kg = 1000 g이에요.","2 kg 690 g = 2690 g.","하윤의 말이 틀렸어요."],"asset":null},{"stem":"이번에는 다른 문제예요. 무게의 단위를 바꾸며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"소율 — 「1090 g = 1 kg 900 g」","correct":true,"mis_target":"M3-2-u5-X05"},{"t":"채원 — 「1 kg = 1000 g」","mis":"M3-2-u5-X21"},{"t":"서준 — 「2 kg = 2000 g」","mis":"M3-2-u5-X21"},{"t":"지아 — 「2090 g = 2 kg 90 g」","mis":"M3-2-u5-X21"}],"explanation":["1 kg = 1000 g이에요.","1 kg 90 g = 1090 g.","소율의 말이 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L06_challenge#5','math',3,2,'u5','L06','g3_2_math_u5_L06_challenge','lesson_challenge','M3-2-u5-C6',3,'mc','auto','1 kg 70 g, 1200 g, 1002 g 중에서 무게가 가장 무거운 것은 무엇인가요?',ARRAY['M3-2-u5-X20','M3-2-u5-X05','M3-2-u5-X21']::text[],true,'{"seq":5,"concept":"M3-2-u5-C6","difficulty":3,"kind":"mc","stem":"1 kg 70 g, 1200 g, 1002 g 중에서 무게가 가장 무거운 것은 무엇인가요?","options":[{"t":"1200 g","correct":true},{"t":"1002 g","mis":"M3-2-u5-X20"},{"t":"1 kg 70 g","mis":"M3-2-u5-X05"},{"t":"모두 같아요","mis":"M3-2-u5-X21"}],"explanation":["모두 g으로 바꾸어요.","1070 g, 1200 g, 1002 g.","가장 무거운 것은 1200 g이에요."],"variant_rule":{"alt":[{"stem":"3 kg 5 g, 3 kg 700 g, 3 kg 80 g 중에서 무게가 가장 무거운 것은 무엇인가요?","options":[{"t":"3 kg 700 g","correct":true},{"t":"3 kg 5 g","mis":"M3-2-u5-X20"},{"t":"3 kg 80 g","mis":"M3-2-u5-X05"},{"t":"모두 같아요","mis":"M3-2-u5-X21"}],"explanation":["모두 g으로 바꾸어요.","3005 g, 3700 g, 3080 g.","가장 무거운 것은 3 kg 700 g이에요."],"asset":null},{"stem":"1 kg 2 g, 1010 g, 1200 g 중에서 무게가 가장 무거운 것은 무엇인가요?","options":[{"t":"1200 g","correct":true},{"t":"1 kg 2 g","mis":"M3-2-u5-X20"},{"t":"1010 g","mis":"M3-2-u5-X05"},{"t":"모두 같아요","mis":"M3-2-u5-X21"}],"explanation":["모두 g으로 바꾸어요.","1002 g, 1010 g, 1200 g.","가장 무거운 것은 1200 g이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L06_challenge#6','math',3,2,'u5','L06','g3_2_math_u5_L06_challenge','lesson_challenge','M3-2-u5-C7',3,'sa','auto','쌀 2 t을 20 kg 포대에 똑같이 나누어 담으면 모두 몇 포대가 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u5-C7","difficulty":3,"kind":"sa","stem":"쌀 2 t을 20 kg 포대에 똑같이 나누어 담으면 모두 몇 포대가 되나요? 숫자로 쓰세요.","answer":["100"],"explanation":["2 t = 2000 kg이에요.","2000 ÷ 20 = 100.","100포대가 돼요."],"variant_rule":{"alt":[{"stem":"쌀 2 t을 50 kg 포대에 똑같이 나누어 담으면 모두 몇 포대가 되나요? 숫자로 쓰세요.","answer":["40"],"explanation":["2 t = 2000 kg이에요.","2000 ÷ 50 = 40.","40포대가 돼요."],"asset":null},{"stem":"쌀 1 t을 100 kg 포대에 똑같이 나누어 담으면 모두 몇 포대가 되나요? 숫자로 쓰세요.","answer":["10"],"explanation":["1 t = 1000 kg이에요.","1000 ÷ 100 = 10.","10포대가 돼요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L06_challenge#7','math',3,2,'u5','L06','g3_2_math_u5_L06_challenge','lesson_challenge','M3-2-u5-C6',3,'sa','auto','저울에 상자를 올리니 1 kg 추 3개와 100 g 추 9개와 무게가 같았어요. 상자는 모두 몇 g인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u5-C6","difficulty":3,"kind":"sa","stem":"저울에 상자를 올리니 1 kg 추 3개와 100 g 추 9개와 무게가 같았어요. 상자는 모두 몇 g인가요? 숫자로 쓰세요.","answer":["3900"],"explanation":["1 kg 추 3개 → 3000 g.","나머지 900 g.","3000 + 900 = 3900 — 3900 g이에요."],"variant_rule":{"alt":[{"stem":"저울에 상자를 올리니 1 kg 추 4개와 100 g 추 5개와 무게가 같았어요. 상자는 모두 몇 g인가요? 숫자로 쓰세요.","answer":["4500"],"explanation":["1 kg 추 4개 → 4000 g.","나머지 500 g.","4000 + 500 = 4500 — 4500 g이에요."],"asset":null},{"stem":"저울에 상자를 올리니 1 kg 추 6개와 100 g 추 8개와 무게가 같았어요. 상자는 모두 몇 g인가요? 숫자로 쓰세요.","answer":["6800"],"explanation":["1 kg 추 6개 → 6000 g.","나머지 800 g.","6000 + 800 = 6800 — 6800 g이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L06_challenge#8','math',3,2,'u5','L06','g3_2_math_u5_L06_challenge','lesson_challenge','M3-2-u5-C6',4,'essay','teacher','정후가 모은 재활용품은 3 kg 40 g, 지아가 모은 재활용품은 3400 g이에요. 정후는 「40이 400보다 작지만 kg이 붙어 있으니까 내가 더 무거워.」라고 했어요. 누가 더 무겁게 모았는지 쓰고, 단위를 바꾸어 견주는 방법으로 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u5-C6","difficulty":4,"kind":"essay","stem":"정후가 모은 재활용품은 3 kg 40 g, 지아가 모은 재활용품은 3400 g이에요. 정후는 「40이 400보다 작지만 kg이 붙어 있으니까 내가 더 무거워.」라고 했어요. 누가 더 무겁게 모았는지 쓰고, 단위를 바꾸어 견주는 방법으로 설명해 보세요.","answer_guide":{"answer":"예: 지아가 더 무겁게 모았다. 1 kg = 1000 g이므로 3 kg 40 g = 3040 g이다. 3040 g과 3400 g을 견주면 3400 g이 더 크다. 또는 3400 g = 3 kg 400 g으로 바꾸면 kg이 같고 400 g > 40 g이다.","scoring_points":["지아라고 답했는가","한 가지 단위로 바꾸었는가(3040 g 또는 3 kg 400 g)","바꾼 수로 바르게 견주었는가"]},"explanation":["3 kg 40 g = 3040 g.","3040 g < 3400 g.","지아가 더 무겁게 모았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L06_challenge#9','math',3,2,'u5','L06','g3_2_math_u5_L06_challenge','lesson_challenge','M3-2-u5-C7',4,'essay','teacher','트럭에 1 t까지 짐을 실을 수 있어요. 10 kg짜리 쌀 포대를 몇 포대까지 실을 수 있는지 구하고, 1 t과 kg의 관계를 이용해 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u5-C7","difficulty":4,"kind":"essay","stem":"트럭에 1 t까지 짐을 실을 수 있어요. 10 kg짜리 쌀 포대를 몇 포대까지 실을 수 있는지 구하고, 1 t과 kg의 관계를 이용해 설명해 보세요.","answer_guide":{"answer":"예: 1 t = 1000 kg이다. 1000 kg을 10 kg씩 나누면 1000 ÷ 10 = 100이므로 100포대까지 실을 수 있다.","scoring_points":["1 t = 1000 kg이라고 썼는가","1000 ÷ 10을 계산했는가","100포대라고 답했는가"]},"explanation":["1 t = 1000 kg.","1000 ÷ 10 = 100.","100포대."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L06_challenge#10','math',3,2,'u5','L06','g3_2_math_u5_L06_challenge','lesson_challenge','M3-2-u5-C6',4,'sa','auto','저울의 큰 눈금 0과 1 kg 사이가 똑같이 2칸으로 나뉘어 있어요. 쌀 포대를 재었더니 바늘이 0에서부터 7칸째 눈금을 가리켜요. 몇 g인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-2-u5-C6","difficulty":4,"kind":"sa","stem":"저울의 큰 눈금 0과 1 kg 사이가 똑같이 2칸으로 나뉘어 있어요. 쌀 포대를 재었더니 바늘이 0에서부터 7칸째 눈금을 가리켜요. 몇 g인가요? 숫자로 쓰세요.","answer":["3500"],"explanation":["한 칸의 크기부터: 1 kg = 1000 g, 1000 ÷ 2 = 500 g.","7칸 → 500 × 7 = 3500.","3500 g이에요."],"variant_rule":{"alt":[{"stem":"저울의 큰 눈금 0과 1 kg 사이가 똑같이 10칸으로 나뉘어 있어요. 쌀 포대를 재었더니 바늘이 0에서부터 24칸째 눈금을 가리켜요. 몇 g인가요? 숫자로 쓰세요.","answer":["2400"],"explanation":["한 칸의 크기부터: 1 kg = 1000 g, 1000 ÷ 10 = 100 g.","24칸 → 100 × 24 = 2400.","2400 g이에요."],"asset":null},{"stem":"저울의 큰 눈금 0과 1 kg 사이가 똑같이 5칸으로 나뉘어 있어요. 쌀 포대를 재었더니 바늘이 0에서부터 19칸째 눈금을 가리켜요. 몇 g인가요? 숫자로 쓰세요.","answer":["3800"],"explanation":["한 칸의 크기부터: 1 kg = 1000 g, 1000 ÷ 5 = 200 g.","19칸 → 200 × 19 = 3800.","3800 g이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L07_basic#1','math',3,2,'u5','L07','g3_2_math_u5_L07_basic','lesson_basic','M3-2-u5-C8',1,'sa','auto','저울의 큰 눈금 0과 1 kg 사이가 똑같이 5칸으로 나뉘어 있어요. 사과를 재었더니 바늘이 0에서부터 2칸째 눈금을 가리켜요. 몇 g인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u5-C8","difficulty":1,"kind":"sa","stem":"저울의 큰 눈금 0과 1 kg 사이가 똑같이 5칸으로 나뉘어 있어요. 사과를 재었더니 바늘이 0에서부터 2칸째 눈금을 가리켜요. 몇 g인가요? 숫자로 쓰세요.","answer":["400"],"explanation":["한 칸의 크기부터: 1 kg = 1000 g, 1000 ÷ 5 = 200 g.","2칸 → 200 × 2 = 400.","400 g이에요."],"variant_rule":{"alt":[{"stem":"저울의 큰 눈금 0과 500 g 사이가 똑같이 10칸으로 나뉘어 있어요. 사과를 재었더니 바늘이 0에서부터 8칸째 눈금을 가리켜요. 몇 g인가요? 숫자로 쓰세요.","answer":["400"],"explanation":["한 칸의 크기부터: 500 ÷ 10 = 50 g.","8칸 → 50 × 8 = 400.","400 g이에요."],"asset":null},{"stem":"저울의 큰 눈금 0과 1 kg 사이가 똑같이 4칸으로 나뉘어 있어요. 사과를 재었더니 바늘이 0에서부터 3칸째 눈금을 가리켜요. 몇 g인가요? 숫자로 쓰세요.","answer":["750"],"explanation":["한 칸의 크기부터: 1 kg = 1000 g, 1000 ÷ 4 = 250 g.","3칸 → 250 × 3 = 750.","750 g이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L07_basic#2','math',3,2,'u5','L07','g3_2_math_u5_L07_basic','lesson_basic','M3-2-u5-C8',1,'mc','auto','코끼리의 무게는 약 3 ○예요. ○에 알맞은 단위는 무엇인가요?',ARRAY['M3-2-u5-X09','M3-2-u5-X10']::text[],true,'{"seq":2,"concept":"M3-2-u5-C8","difficulty":1,"kind":"mc","stem":"코끼리의 무게는 약 3 ○예요. ○에 알맞은 단위는 무엇인가요?","options":[{"t":"t","correct":true},{"t":"g","mis":"M3-2-u5-X09"},{"t":"kg","mis":"M3-2-u5-X09"},{"t":"mL","mis":"M3-2-u5-X10"}],"explanation":["코끼리를 아는 무게와 견주어 봐요.","무게에 쓰는 단위는 g·kg·t.","코끼리의 무게는 약 3 t이에요."],"variant_rule":{"alt":[{"stem":"공책 1권의 무게는 약 50 ○예요. ○에 알맞은 단위는 무엇인가요?","options":[{"t":"g","correct":true},{"t":"kg","mis":"M3-2-u5-X09"},{"t":"t","mis":"M3-2-u5-X09"},{"t":"mL","mis":"M3-2-u5-X10"}],"explanation":["공책 1권을 아는 무게와 견주어 봐요.","무게에 쓰는 단위는 g·kg·t.","공책 1권의 무게는 약 50 g이에요."],"asset":null},{"stem":"고래의 무게는 약 30 ○예요. ○에 알맞은 단위는 무엇인가요?","options":[{"t":"t","correct":true},{"t":"g","mis":"M3-2-u5-X09"},{"t":"kg","mis":"M3-2-u5-X09"},{"t":"mL","mis":"M3-2-u5-X10"}],"explanation":["고래를 아는 무게와 견주어 봐요.","무게에 쓰는 단위는 g·kg·t.","고래의 무게는 약 30 t이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L07_basic#3','math',3,2,'u5','L07','g3_2_math_u5_L07_basic','lesson_basic','M3-2-u5-C8',1,'mc','auto','1 t보다 무거운 것끼리 짝 지은 것은 무엇인가요?',ARRAY['M3-2-u5-X09']::text[],true,'{"seq":3,"concept":"M3-2-u5-C8","difficulty":1,"kind":"mc","stem":"1 t보다 무거운 것끼리 짝 지은 것은 무엇인가요?","options":[{"t":"버스, 배","correct":true},{"t":"자전거, 유모차","mis":"M3-2-u5-X09"},{"t":"버스, 자전거","mis":"M3-2-u5-X09"},{"t":"유모차, 배","mis":"M3-2-u5-X09"}],"explanation":["1 t = 1000 kg — 아주 무거운 무게예요.","「버스, 배」는 1 t보다 무거워요.","나머지 짝에는 1 t보다 가벼운 것이 있어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 1 t보다 무거운 것끼리 짝 지은 것은 무엇인가요?","options":[{"t":"트럭, 코끼리","correct":true},{"t":"강아지, 의자","mis":"M3-2-u5-X09"},{"t":"트럭, 의자","mis":"M3-2-u5-X09"},{"t":"강아지, 코끼리","mis":"M3-2-u5-X09"}],"explanation":["1 t = 1000 kg — 아주 무거운 무게예요.","「트럭, 코끼리」는 1 t보다 무거워요.","나머지 짝에는 1 t보다 가벼운 것이 있어요."],"asset":null},{"stem":"이번에는 다른 문제예요. 1 t보다 무거운 것끼리 짝 지은 것은 무엇인가요?","options":[{"t":"비행기, 기차","correct":true},{"t":"책상, 냉장고","mis":"M3-2-u5-X09"},{"t":"비행기, 책상","mis":"M3-2-u5-X09"},{"t":"냉장고, 기차","mis":"M3-2-u5-X09"}],"explanation":["1 t = 1000 kg — 아주 무거운 무게예요.","「비행기, 기차」는 1 t보다 무거워요.","나머지 짝에는 1 t보다 가벼운 것이 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L07_basic#4','math',3,2,'u5','L07','g3_2_math_u5_L07_basic','lesson_basic','M3-2-u5-C8',1,'sa','auto','저울의 큰 눈금 0과 1 kg 사이가 똑같이 10칸으로 나뉘어 있어요. 눈금 한 칸은 몇 g인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u5-C8","difficulty":1,"kind":"sa","stem":"저울의 큰 눈금 0과 1 kg 사이가 똑같이 10칸으로 나뉘어 있어요. 눈금 한 칸은 몇 g인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["0부터 1000 g까지를 10칸으로 똑같이 나누었어요.","1000 ÷ 10 = 100.","한 칸은 100 g이에요."],"variant_rule":{"alt":[{"stem":"저울의 큰 눈금 0과 1 kg 사이가 똑같이 2칸으로 나뉘어 있어요. 눈금 한 칸은 몇 g인가요? 숫자로 쓰세요.","answer":["500"],"explanation":["0부터 1000 g까지를 2칸으로 똑같이 나누었어요.","1000 ÷ 2 = 500.","한 칸은 500 g이에요."],"asset":null},{"stem":"저울의 큰 눈금 0과 500 g 사이가 똑같이 5칸으로 나뉘어 있어요. 눈금 한 칸은 몇 g인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["0부터 500 g까지를 5칸으로 똑같이 나누었어요.","500 ÷ 5 = 100.","한 칸은 100 g이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L07_basic#5','math',3,2,'u5','L07','g3_2_math_u5_L07_basic','lesson_basic','M3-2-u5-C8',2,'mc','auto','채원이 필통의 무게를 400 g쯤 될 것 같다고 어림했어요. 어림한 무게를 바르게 나타낸 것은 무엇인가요?',ARRAY['M3-2-u5-X08','M3-2-u5-X09']::text[],true,'{"seq":5,"concept":"M3-2-u5-C8","difficulty":2,"kind":"mc","stem":"채원이 필통의 무게를 400 g쯤 될 것 같다고 어림했어요. 어림한 무게를 바르게 나타낸 것은 무엇인가요?","options":[{"t":"약 400 g","correct":true},{"t":"400 g 약","mis":"M3-2-u5-X08"},{"t":"딱 400 g","mis":"M3-2-u5-X08"},{"t":"약 400 kg","mis":"M3-2-u5-X09"}],"explanation":["어림한 값은 앞에 「약」을 붙여요.","400 g쯤 → 약 400 g.","단위도 그대로 — 약 400 g."],"variant_rule":{"alt":[{"stem":"서준이 빨랫비누 1개의 무게를 600 g쯤 될 것 같다고 어림했어요. 어림한 무게를 바르게 나타낸 것은 무엇인가요?","options":[{"t":"약 600 g","correct":true},{"t":"600 g 약","mis":"M3-2-u5-X08"},{"t":"딱 600 g","mis":"M3-2-u5-X08"},{"t":"약 600 kg","mis":"M3-2-u5-X09"}],"explanation":["어림한 값은 앞에 「약」을 붙여요.","600 g쯤 → 약 600 g.","단위도 그대로 — 약 600 g."],"asset":null},{"stem":"지아가 위인전의 무게를 450 g쯤 될 것 같다고 어림했어요. 어림한 무게를 바르게 나타낸 것은 무엇인가요?","options":[{"t":"약 450 g","correct":true},{"t":"450 g 약","mis":"M3-2-u5-X08"},{"t":"딱 450 g","mis":"M3-2-u5-X08"},{"t":"약 450 kg","mis":"M3-2-u5-X09"}],"explanation":["어림한 값은 앞에 「약」을 붙여요.","450 g쯤 → 약 450 g.","단위도 그대로 — 약 450 g."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L07_basic#6','math',3,2,'u5','L07','g3_2_math_u5_L07_basic','lesson_basic','M3-2-u5-C8',2,'mc','auto','수박의 무게를 어림했어요 — 은비 약 1 kg 650 g, 도윤 약 1 kg 200 g, 하윤 약 1 kg. 재어 보니 1 kg 500 g이었어요. 가장 가깝게 어림한 친구는 누구인가요?',ARRAY['M3-2-u5-X08','M3-2-u5-X21']::text[],true,'{"seq":6,"concept":"M3-2-u5-C8","difficulty":2,"kind":"mc","stem":"수박의 무게를 어림했어요 — 은비 약 1 kg 650 g, 도윤 약 1 kg 200 g, 하윤 약 1 kg. 재어 보니 1 kg 500 g이었어요. 가장 가깝게 어림한 친구는 누구인가요?","options":[{"t":"은비","correct":true},{"t":"도윤","mis":"M3-2-u5-X08"},{"t":"하윤","mis":"M3-2-u5-X08"},{"t":"모두 똑같이 알맞아요","mis":"M3-2-u5-X21"}],"explanation":["잰 값 1 kg 500 g과 어림한 값의 차를 견주어요.","은비 150 g, 도윤 300 g, 하윤 500 g 차이.","차가 가장 작은 은비가 가장 가깝게 어림했어요."],"variant_rule":{"alt":[{"stem":"수박의 무게를 어림했어요 — 서준 약 1 kg 150 g, 소율 약 1 kg 350 g, 정후 약 1 kg 500 g. 재어 보니 1 kg 200 g이었어요. 가장 가깝게 어림한 친구는 누구인가요?","options":[{"t":"서준","correct":true},{"t":"소율","mis":"M3-2-u5-X08"},{"t":"정후","mis":"M3-2-u5-X08"},{"t":"모두 똑같이 알맞아요","mis":"M3-2-u5-X21"}],"explanation":["잰 값 1 kg 200 g과 어림한 값의 차를 견주어요.","서준 50 g, 소율 150 g, 정후 300 g 차이.","차가 가장 작은 서준이 가장 가깝게 어림했어요."],"asset":null},{"stem":"가방의 무게를 어림했어요 — 하윤 약 700 g, 서준 약 1 kg 150 g, 은비 약 1 kg 500 g. 재어 보니 1 kg 200 g이었어요. 가장 가깝게 어림한 친구는 누구인가요?","options":[{"t":"서준","correct":true},{"t":"하윤","mis":"M3-2-u5-X08"},{"t":"은비","mis":"M3-2-u5-X08"},{"t":"모두 똑같이 알맞아요","mis":"M3-2-u5-X21"}],"explanation":["잰 값 1 kg 200 g과 어림한 값의 차를 견주어요.","하윤 500 g, 서준 50 g, 은비 300 g 차이.","차가 가장 작은 서준이 가장 가깝게 어림했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L07_basic#7','math',3,2,'u5','L07','g3_2_math_u5_L07_basic','lesson_basic','M3-2-u5-C8',2,'sa','auto','공책 묶음의 무게가 50 g인 물건 10개와 비슷할 것 같아요. 공책 묶음의 무게는 약 몇 g으로 어림할 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u5-C8","difficulty":2,"kind":"sa","stem":"공책 묶음의 무게가 50 g인 물건 10개와 비슷할 것 같아요. 공책 묶음의 무게는 약 몇 g으로 어림할 수 있나요? 숫자로 쓰세요.","answer":["500"],"explanation":["아는 무게 50 g이 몇 번인지 헤아려요.","50 × 10 = 500.","약 500 g이에요."],"variant_rule":{"alt":[{"stem":"필통의 무게가 200 g인 물건 4개와 비슷할 것 같아요. 필통의 무게는 약 몇 g으로 어림할 수 있나요? 숫자로 쓰세요.","answer":["800"],"explanation":["아는 무게 200 g이 몇 번인지 헤아려요.","200 × 4 = 800.","약 800 g이에요."],"asset":null},{"stem":"공책 묶음의 무게가 50 g인 물건 3개와 비슷할 것 같아요. 공책 묶음의 무게는 약 몇 g으로 어림할 수 있나요? 숫자로 쓰세요.","answer":["150"],"explanation":["아는 무게 50 g이 몇 번인지 헤아려요.","50 × 3 = 150.","약 150 g이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L07_basic#8','math',3,2,'u5','L07','g3_2_math_u5_L07_basic','lesson_basic','M3-2-u5-C8',2,'mc','auto','책상의 무게는 약 15 ○예요. ○에 알맞은 단위는 무엇인가요?',ARRAY['M3-2-u5-X09','M3-2-u5-X10']::text[],true,'{"seq":8,"concept":"M3-2-u5-C8","difficulty":2,"kind":"mc","stem":"책상의 무게는 약 15 ○예요. ○에 알맞은 단위는 무엇인가요?","options":[{"t":"kg","correct":true},{"t":"g","mis":"M3-2-u5-X09"},{"t":"t","mis":"M3-2-u5-X09"},{"t":"mL","mis":"M3-2-u5-X10"}],"explanation":["책상을 아는 무게와 견주어 봐요.","무게에 쓰는 단위는 g·kg·t.","책상의 무게는 약 15 kg이에요."],"variant_rule":{"alt":[{"stem":"달걀 1개의 무게는 약 60 ○예요. ○에 알맞은 단위는 무엇인가요?","options":[{"t":"g","correct":true},{"t":"kg","mis":"M3-2-u5-X09"},{"t":"t","mis":"M3-2-u5-X09"},{"t":"mL","mis":"M3-2-u5-X10"}],"explanation":["달걀 1개를 아는 무게와 견주어 봐요.","무게에 쓰는 단위는 g·kg·t.","달걀 1개의 무게는 약 60 g이에요."],"asset":null},{"stem":"쌀 한 포대의 무게는 약 20 ○예요. ○에 알맞은 단위는 무엇인가요?","options":[{"t":"kg","correct":true},{"t":"g","mis":"M3-2-u5-X09"},{"t":"t","mis":"M3-2-u5-X09"},{"t":"mL","mis":"M3-2-u5-X10"}],"explanation":["쌀 한 포대를 아는 무게와 견주어 봐요.","무게에 쓰는 단위는 g·kg·t.","쌀 한 포대의 무게는 약 20 kg이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L07_basic#9','math',3,2,'u5','L07','g3_2_math_u5_L07_basic','lesson_basic','M3-2-u5-C8',2,'ox','auto','소율은 필통의 무게를 약 400 g으로 어림하고 재어 보니 360 g이었어요. 「어림한 값과 잰 값이 다르니 어림을 잘못한 거야.」',ARRAY['M3-2-u5-X08']::text[],true,'{"seq":9,"concept":"M3-2-u5-C8","difficulty":2,"kind":"ox","stem":"소율은 필통의 무게를 약 400 g으로 어림하고 재어 보니 360 g이었어요. 「어림한 값과 잰 값이 다르니 어림을 잘못한 거야.」","answer":"X","reason_options":[{"t":"어림은 아는 양과 견주어 얼마쯤인지 나타낸 것이라서","correct":true},{"t":"어림한 값은 잰 값과 꼭 같아야 해서","mis":"M3-2-u5-X08"}],"mis":"M3-2-u5-X08","explanation":["어림은 재기 전에 얼마쯤인지 생각해 보는 거예요.","약 400 g과 360 g — 차이 40 g.","달라도 괜찮아요 — 무엇과 견주어 어림했는지가 중요해요 ×."],"variant_rule":{"alt":[{"stem":"하윤은 위인전의 무게를 약 200 g으로 어림하고 재어 보니 220 g이었어요. 「어림한 값과 잰 값이 다르니 어림을 잘못한 거야.」","answer":"X","reason_options":[{"t":"어림은 아는 양과 견주어 얼마쯤인지 나타낸 것이라서","correct":true},{"t":"어림한 값은 잰 값과 꼭 같아야 해서","mis":"M3-2-u5-X08"}],"explanation":["어림은 재기 전에 얼마쯤인지 생각해 보는 거예요.","약 200 g과 220 g — 차이 20 g.","달라도 괜찮아요 — 무엇과 견주어 어림했는지가 중요해요 ×."],"asset":null},{"stem":"준우는 가방의 무게를 약 400 g으로 어림하고 재어 보니 370 g이었어요. 「어림한 값과 잰 값이 다르니 어림을 잘못한 거야.」","answer":"X","reason_options":[{"t":"어림은 아는 양과 견주어 얼마쯤인지 나타낸 것이라서","correct":true},{"t":"어림한 값은 잰 값과 꼭 같아야 해서","mis":"M3-2-u5-X08"}],"explanation":["어림은 재기 전에 얼마쯤인지 생각해 보는 거예요.","약 400 g과 370 g — 차이 30 g.","달라도 괜찮아요 — 무엇과 견주어 어림했는지가 중요해요 ×."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L07_basic#10','math',3,2,'u5','L07','g3_2_math_u5_L07_basic','lesson_basic','M3-2-u5-C8',3,'mc','auto','저울의 큰 눈금 0과 1 kg 사이가 똑같이 4칸으로 나뉘어 있어요. 빨랫비누 상자를 재었더니 바늘이 0에서부터 3칸째 눈금을 가리켜요. 몇 g인가요?',ARRAY['M3-2-u5-X07']::text[],true,'{"seq":10,"concept":"M3-2-u5-C8","difficulty":3,"kind":"mc","stem":"저울의 큰 눈금 0과 1 kg 사이가 똑같이 4칸으로 나뉘어 있어요. 빨랫비누 상자를 재었더니 바늘이 0에서부터 3칸째 눈금을 가리켜요. 몇 g인가요?","options":[{"t":"750 g","correct":true},{"t":"3 g","mis":"M3-2-u5-X07"},{"t":"300 g","mis":"M3-2-u5-X07"},{"t":"1000 g","mis":"M3-2-u5-X07"}],"explanation":["한 칸의 크기부터: 1 kg = 1000 g, 1000 ÷ 4 = 250 g.","3칸 → 250 × 3 = 750.","750 g이에요."],"variant_rule":{"alt":[{"stem":"저울의 큰 눈금 0과 1 kg 사이가 똑같이 5칸으로 나뉘어 있어요. 사과를 재었더니 바늘이 0에서부터 3칸째 눈금을 가리켜요. 몇 g인가요?","options":[{"t":"600 g","correct":true},{"t":"3 g","mis":"M3-2-u5-X07"},{"t":"300 g","mis":"M3-2-u5-X07"},{"t":"800 g","mis":"M3-2-u5-X07"}],"explanation":["한 칸의 크기부터: 1 kg = 1000 g, 1000 ÷ 5 = 200 g.","3칸 → 200 × 3 = 600.","600 g이에요."],"asset":null},{"stem":"저울의 큰 눈금 0과 1 kg 사이가 똑같이 5칸으로 나뉘어 있어요. 현미를 재었더니 바늘이 0에서부터 4칸째 눈금을 가리켜요. 몇 g인가요?","options":[{"t":"800 g","correct":true},{"t":"4 g","mis":"M3-2-u5-X07"},{"t":"400 g","mis":"M3-2-u5-X07"},{"t":"1000 g","mis":"M3-2-u5-X07"}],"explanation":["한 칸의 크기부터: 1 kg = 1000 g, 1000 ÷ 5 = 200 g.","4칸 → 200 × 4 = 800.","800 g이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L07_challenge#1','math',3,2,'u5','L07','g3_2_math_u5_L07_challenge','lesson_challenge','M3-2-u5-C8',2,'mc','auto','무게를 알맞게 어림한 것은 무엇인가요?',ARRAY['M3-2-u5-X09','M3-2-u5-X10']::text[],true,'{"seq":1,"concept":"M3-2-u5-C8","difficulty":2,"kind":"mc","stem":"무게를 알맞게 어림한 것은 무엇인가요?","options":[{"t":"클립 1개의 무게는 약 1 g이에요","correct":true},{"t":"클립 1개의 무게는 약 1 kg이에요","mis":"M3-2-u5-X09"},{"t":"강아지의 무게는 약 10 g이에요","mis":"M3-2-u5-X09"},{"t":"클립 1개의 들이는 약 1 g이에요","mis":"M3-2-u5-X10"}],"explanation":["물건과 단위의 크기를 견주어 봐요.","무게의 단위는 g·kg·t.","알맞은 것은 「클립 1개의 무게는 약 1 g이에요」."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 무게를 알맞게 어림한 것은 무엇인가요?","options":[{"t":"수박 1통의 무게는 약 5 kg이에요","correct":true},{"t":"수박 1통의 무게는 약 5 t이에요","mis":"M3-2-u5-X09"},{"t":"코끼리의 무게는 약 3 kg이에요","mis":"M3-2-u5-X09"},{"t":"수박 1통의 무게는 약 5 mL예요","mis":"M3-2-u5-X10"}],"explanation":["물건과 단위의 크기를 견주어 봐요.","무게의 단위는 g·kg·t.","알맞은 것은 「수박 1통의 무게는 약 5 kg이에요」."],"asset":null},{"stem":"이번에는 다른 문제예요. 무게를 알맞게 어림한 것은 무엇인가요?","options":[{"t":"자동차의 무게는 약 1 t이에요","correct":true},{"t":"자동차의 무게는 약 1 kg이에요","mis":"M3-2-u5-X09"},{"t":"사과 1개의 무게는 약 300 kg이에요","mis":"M3-2-u5-X09"},{"t":"자동차의 무게는 약 1 L예요","mis":"M3-2-u5-X10"}],"explanation":["물건과 단위의 크기를 견주어 봐요.","무게의 단위는 g·kg·t.","알맞은 것은 「자동차의 무게는 약 1 t이에요」."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L07_challenge#2','math',3,2,'u5','L07','g3_2_math_u5_L07_challenge','lesson_challenge','M3-2-u5-C8',2,'mc','auto','사과 1개의 무게는 약 300 ○예요. ○에 알맞은 단위는 무엇인가요?',ARRAY['M3-2-u5-X09','M3-2-u5-X10']::text[],true,'{"seq":2,"concept":"M3-2-u5-C8","difficulty":2,"kind":"mc","stem":"사과 1개의 무게는 약 300 ○예요. ○에 알맞은 단위는 무엇인가요?","options":[{"t":"g","correct":true},{"t":"kg","mis":"M3-2-u5-X09"},{"t":"t","mis":"M3-2-u5-X09"},{"t":"mL","mis":"M3-2-u5-X10"}],"explanation":["사과 1개를 아는 무게와 견주어 봐요.","무게에 쓰는 단위는 g·kg·t.","사과 1개의 무게는 약 300 g이에요."],"variant_rule":{"alt":[{"stem":"수박 1통의 무게는 약 5 ○예요. ○에 알맞은 단위는 무엇인가요?","options":[{"t":"kg","correct":true},{"t":"g","mis":"M3-2-u5-X09"},{"t":"t","mis":"M3-2-u5-X09"},{"t":"mL","mis":"M3-2-u5-X10"}],"explanation":["수박 1통을 아는 무게와 견주어 봐요.","무게에 쓰는 단위는 g·kg·t.","수박 1통의 무게는 약 5 kg이에요."],"asset":null},{"stem":"강아지의 무게는 약 10 ○예요. ○에 알맞은 단위는 무엇인가요?","options":[{"t":"kg","correct":true},{"t":"g","mis":"M3-2-u5-X09"},{"t":"t","mis":"M3-2-u5-X09"},{"t":"mL","mis":"M3-2-u5-X10"}],"explanation":["강아지를 아는 무게와 견주어 봐요.","무게에 쓰는 단위는 g·kg·t.","강아지의 무게는 약 10 kg이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L07_challenge#3','math',3,2,'u5','L07','g3_2_math_u5_L07_challenge','lesson_challenge','M3-2-u5-C8',3,'mc','auto','저울의 큰 눈금 0과 1 kg 사이가 똑같이 10칸으로 나뉘어 있어요. 현미를 재었더니 바늘이 0에서부터 24칸째 눈금을 가리켜요. 몇 g인가요?',ARRAY['M3-2-u5-X07']::text[],true,'{"seq":3,"concept":"M3-2-u5-C8","difficulty":3,"kind":"mc","stem":"저울의 큰 눈금 0과 1 kg 사이가 똑같이 10칸으로 나뉘어 있어요. 현미를 재었더니 바늘이 0에서부터 24칸째 눈금을 가리켜요. 몇 g인가요?","options":[{"t":"2400 g","correct":true},{"t":"24 g","mis":"M3-2-u5-X07"},{"t":"240 g","mis":"M3-2-u5-X07"},{"t":"2500 g","mis":"M3-2-u5-X07"}],"explanation":["한 칸의 크기부터: 1 kg = 1000 g, 1000 ÷ 10 = 100 g.","24칸 → 100 × 24 = 2400.","2400 g이에요."],"variant_rule":{"alt":[{"stem":"저울의 큰 눈금 0과 1 kg 사이가 똑같이 4칸으로 나뉘어 있어요. 책가방을 재었더니 바늘이 0에서부터 15칸째 눈금을 가리켜요. 몇 g인가요?","options":[{"t":"3750 g","correct":true},{"t":"15 g","mis":"M3-2-u5-X07"},{"t":"1500 g","mis":"M3-2-u5-X07"},{"t":"4000 g","mis":"M3-2-u5-X07"}],"explanation":["한 칸의 크기부터: 1 kg = 1000 g, 1000 ÷ 4 = 250 g.","15칸 → 250 × 15 = 3750.","3750 g이에요."],"asset":null},{"stem":"저울의 큰 눈금 0과 1 kg 사이가 똑같이 5칸으로 나뉘어 있어요. 빨랫비누 상자를 재었더니 바늘이 0에서부터 7칸째 눈금을 가리켜요. 몇 g인가요?","options":[{"t":"1400 g","correct":true},{"t":"7 g","mis":"M3-2-u5-X07"},{"t":"700 g","mis":"M3-2-u5-X07"},{"t":"1600 g","mis":"M3-2-u5-X07"}],"explanation":["한 칸의 크기부터: 1 kg = 1000 g, 1000 ÷ 5 = 200 g.","7칸 → 200 × 7 = 1400.","1400 g이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L07_challenge#4','math',3,2,'u5','L07','g3_2_math_u5_L07_challenge','lesson_challenge','M3-2-u5-C8',3,'mc','auto','위인전의 무게를 어림했어요 — 서준 약 1 kg, 채원 약 450 g, 도윤 약 1 kg 250 g. 재어 보니 950 g이었어요. 가장 가깝게 어림한 친구는 누구인가요?',ARRAY['M3-2-u5-X08','M3-2-u5-X21']::text[],true,'{"seq":4,"concept":"M3-2-u5-C8","difficulty":3,"kind":"mc","stem":"위인전의 무게를 어림했어요 — 서준 약 1 kg, 채원 약 450 g, 도윤 약 1 kg 250 g. 재어 보니 950 g이었어요. 가장 가깝게 어림한 친구는 누구인가요?","options":[{"t":"서준","correct":true},{"t":"채원","mis":"M3-2-u5-X08"},{"t":"도윤","mis":"M3-2-u5-X08"},{"t":"모두 똑같이 알맞아요","mis":"M3-2-u5-X21"}],"explanation":["잰 값 950 g과 어림한 값의 차를 견주어요.","서준 50 g, 채원 500 g, 도윤 300 g 차이.","차가 가장 작은 서준이 가장 가깝게 어림했어요."],"variant_rule":{"alt":[{"stem":"가방의 무게를 어림했어요 — 지아 약 1 kg 700 g, 도윤 약 1 kg 350 g, 하윤 약 900 g. 재어 보니 1 kg 200 g이었어요. 가장 가깝게 어림한 친구는 누구인가요?","options":[{"t":"도윤","correct":true},{"t":"지아","mis":"M3-2-u5-X08"},{"t":"하윤","mis":"M3-2-u5-X08"},{"t":"모두 똑같이 알맞아요","mis":"M3-2-u5-X21"}],"explanation":["잰 값 1 kg 200 g과 어림한 값의 차를 견주어요.","지아 500 g, 도윤 150 g, 하윤 300 g 차이.","차가 가장 작은 도윤이 가장 가깝게 어림했어요."],"asset":null},{"stem":"수박의 무게를 어림했어요 — 정후 약 2 kg 100 g, 지아 약 1 kg 950 g, 채원 약 1 kg 750 g. 재어 보니 1 kg 800 g이었어요. 가장 가깝게 어림한 친구는 누구인가요?","options":[{"t":"채원","correct":true},{"t":"정후","mis":"M3-2-u5-X08"},{"t":"지아","mis":"M3-2-u5-X08"},{"t":"모두 똑같이 알맞아요","mis":"M3-2-u5-X21"}],"explanation":["잰 값 1 kg 800 g과 어림한 값의 차를 견주어요.","정후 300 g, 지아 150 g, 채원 50 g 차이.","차가 가장 작은 채원이 가장 가깝게 어림했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L07_challenge#5','math',3,2,'u5','L07','g3_2_math_u5_L07_challenge','lesson_challenge','M3-2-u5-C8',3,'sa','auto','동화책 꾸러미의 무게가 250 g인 물건 5개와 비슷할 것 같아요. 동화책 꾸러미의 무게는 약 몇 g으로 어림할 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u5-C8","difficulty":3,"kind":"sa","stem":"동화책 꾸러미의 무게가 250 g인 물건 5개와 비슷할 것 같아요. 동화책 꾸러미의 무게는 약 몇 g으로 어림할 수 있나요? 숫자로 쓰세요.","answer":["1250"],"explanation":["아는 무게 250 g이 몇 번인지 헤아려요.","250 × 5 = 1250.","약 1250 g이에요."],"variant_rule":{"alt":[{"stem":"빨랫비누 상자의 무게가 100 g인 물건 6개와 비슷할 것 같아요. 빨랫비누 상자의 무게는 약 몇 g으로 어림할 수 있나요? 숫자로 쓰세요.","answer":["600"],"explanation":["아는 무게 100 g이 몇 번인지 헤아려요.","100 × 6 = 600.","약 600 g이에요."],"asset":null},{"stem":"공책 묶음의 무게가 50 g인 물건 3개와 비슷할 것 같아요. 공책 묶음의 무게는 약 몇 g으로 어림할 수 있나요? 숫자로 쓰세요.","answer":["150"],"explanation":["아는 무게 50 g이 몇 번인지 헤아려요.","50 × 3 = 150.","약 150 g이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L07_challenge#6','math',3,2,'u5','L07','g3_2_math_u5_L07_challenge','lesson_challenge','M3-2-u5-C8',3,'sa','auto','저울의 큰 눈금 0과 1 kg 사이가 똑같이 4칸으로 나뉘어 있어요. 사과를 재었더니 바늘이 0에서부터 5칸째 눈금을 가리켜요. 몇 g인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u5-C8","difficulty":3,"kind":"sa","stem":"저울의 큰 눈금 0과 1 kg 사이가 똑같이 4칸으로 나뉘어 있어요. 사과를 재었더니 바늘이 0에서부터 5칸째 눈금을 가리켜요. 몇 g인가요? 숫자로 쓰세요.","answer":["1250"],"explanation":["한 칸의 크기부터: 1 kg = 1000 g, 1000 ÷ 4 = 250 g.","5칸 → 250 × 5 = 1250.","1250 g이에요."],"variant_rule":{"alt":[{"stem":"저울의 큰 눈금 0과 1 kg 사이가 똑같이 2칸으로 나뉘어 있어요. 현미를 재었더니 바늘이 0에서부터 6칸째 눈금을 가리켜요. 몇 g인가요? 숫자로 쓰세요.","answer":["3000"],"explanation":["한 칸의 크기부터: 1 kg = 1000 g, 1000 ÷ 2 = 500 g.","6칸 → 500 × 6 = 3000.","3000 g이에요."],"asset":null},{"stem":"저울의 큰 눈금 0과 1 kg 사이가 똑같이 10칸으로 나뉘어 있어요. 책가방을 재었더니 바늘이 0에서부터 25칸째 눈금을 가리켜요. 몇 g인가요? 숫자로 쓰세요.","answer":["2500"],"explanation":["한 칸의 크기부터: 1 kg = 1000 g, 1000 ÷ 10 = 100 g.","25칸 → 100 × 25 = 2500.","2500 g이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L07_challenge#7','math',3,2,'u5','L07','g3_2_math_u5_L07_challenge','lesson_challenge','M3-2-u5-C8',3,'mc','auto','1 t보다 무거운 것끼리 짝 지은 것은 무엇인가요?',ARRAY['M3-2-u5-X09']::text[],true,'{"seq":7,"concept":"M3-2-u5-C8","difficulty":3,"kind":"mc","stem":"1 t보다 무거운 것끼리 짝 지은 것은 무엇인가요?","options":[{"t":"트럭, 코끼리","correct":true},{"t":"강아지, 의자","mis":"M3-2-u5-X09"},{"t":"트럭, 의자","mis":"M3-2-u5-X09"},{"t":"강아지, 코끼리","mis":"M3-2-u5-X09"}],"explanation":["1 t = 1000 kg — 아주 무거운 무게예요.","「트럭, 코끼리」는 1 t보다 무거워요.","나머지 짝에는 1 t보다 가벼운 것이 있어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 1 t보다 무거운 것끼리 짝 지은 것은 무엇인가요?","options":[{"t":"버스, 배","correct":true},{"t":"자전거, 유모차","mis":"M3-2-u5-X09"},{"t":"버스, 자전거","mis":"M3-2-u5-X09"},{"t":"유모차, 배","mis":"M3-2-u5-X09"}],"explanation":["1 t = 1000 kg — 아주 무거운 무게예요.","「버스, 배」는 1 t보다 무거워요.","나머지 짝에는 1 t보다 가벼운 것이 있어요."],"asset":null},{"stem":"이번에는 다른 문제예요. 1 t보다 무거운 것끼리 짝 지은 것은 무엇인가요?","options":[{"t":"비행기, 기차","correct":true},{"t":"책상, 냉장고","mis":"M3-2-u5-X09"},{"t":"비행기, 책상","mis":"M3-2-u5-X09"},{"t":"냉장고, 기차","mis":"M3-2-u5-X09"}],"explanation":["1 t = 1000 kg — 아주 무거운 무게예요.","「비행기, 기차」는 1 t보다 무거워요.","나머지 짝에는 1 t보다 가벼운 것이 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L07_challenge#8','math',3,2,'u5','L07','g3_2_math_u5_L07_challenge','lesson_challenge','M3-2-u5-C8',4,'essay','teacher','은비네 반이 만든 빨랫비누 한 상자에는 100 g짜리 비누가 10개 들어 있어요. 상자의 무게를 어림하는 방법을 쓰고, 어림한 무게를 「약」을 붙여 나타내 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u5-C8","difficulty":4,"kind":"essay","stem":"은비네 반이 만든 빨랫비누 한 상자에는 100 g짜리 비누가 10개 들어 있어요. 상자의 무게를 어림하는 방법을 쓰고, 어림한 무게를 「약」을 붙여 나타내 보세요.","answer_guide":{"answer":"예: 비누 한 개가 100 g이고 10개가 들어 있으니 100 g이 10번이라 1000 g, 곧 약 1 kg으로 어림한다. 상자의 무게가 조금 더해지므로 「약 1 kg」 또는 「약 1 kg 100 g」처럼 나타낸다. 밀가루 1 kg 봉지의 무게와 견주어 비슷한지 들어 볼 수도 있다.","scoring_points":["100 g이 10번이라고 헤아렸는가","약 1 kg(약 1000 g)으로 나타냈는가","「약」을 붙였는가"]},"explanation":["100 g × 10개 = 1000 g.","1000 g = 1 kg.","약 1 kg."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L07_challenge#9','math',3,2,'u5','L07','g3_2_math_u5_L07_challenge','lesson_challenge','M3-2-u5-C8',4,'essay','teacher','저울의 큰 눈금 0과 1 kg 사이가 똑같이 10칸으로 나뉘어 있어요. 바늘이 0에서부터 14칸째 눈금을 가리켜요. 물건의 무게를 「몇 kg 몇 g」으로 나타내고 그렇게 읽은 방법을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u5-C8","difficulty":4,"kind":"essay","stem":"저울의 큰 눈금 0과 1 kg 사이가 똑같이 10칸으로 나뉘어 있어요. 바늘이 0에서부터 14칸째 눈금을 가리켜요. 물건의 무게를 「몇 kg 몇 g」으로 나타내고 그렇게 읽은 방법을 설명해 보세요.","answer_guide":{"answer":"예: 1 kg = 1000 g을 10칸으로 나누었으므로 한 칸은 100 g이다. 14칸은 100 × 14 = 1400 g이고, 1400 g = 1 kg 400 g이다.","scoring_points":["한 칸이 100 g임을 구했는가","1400 g을 구했는가","1 kg 400 g으로 나타냈는가"]},"explanation":["1000 ÷ 10 = 100 g — 한 칸.","14칸 = 1400 g.","1400 g = 1 kg 400 g."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L07_challenge#10','math',3,2,'u5','L07','g3_2_math_u5_L07_challenge','lesson_challenge','M3-2-u5-C8',4,'mc','auto','저울의 큰 눈금 0과 1 kg 사이가 똑같이 2칸으로 나뉘어 있어요. 책가방을 재었더니 바늘이 0에서부터 5칸째 눈금을 가리켜요. 몇 g인가요?',ARRAY['M3-2-u5-X07']::text[],true,'{"seq":10,"concept":"M3-2-u5-C8","difficulty":4,"kind":"mc","stem":"저울의 큰 눈금 0과 1 kg 사이가 똑같이 2칸으로 나뉘어 있어요. 책가방을 재었더니 바늘이 0에서부터 5칸째 눈금을 가리켜요. 몇 g인가요?","options":[{"t":"2500 g","correct":true},{"t":"5 g","mis":"M3-2-u5-X07"},{"t":"500 g","mis":"M3-2-u5-X07"},{"t":"3000 g","mis":"M3-2-u5-X07"}],"explanation":["한 칸의 크기부터: 1 kg = 1000 g, 1000 ÷ 2 = 500 g.","5칸 → 500 × 5 = 2500.","2500 g이에요."],"variant_rule":{"alt":[{"stem":"저울의 큰 눈금 0과 1 kg 사이가 똑같이 5칸으로 나뉘어 있어요. 빨랫비누 상자를 재었더니 바늘이 0에서부터 10칸째 눈금을 가리켜요. 몇 g인가요?","options":[{"t":"2000 g","correct":true},{"t":"10 g","mis":"M3-2-u5-X07"},{"t":"1000 g","mis":"M3-2-u5-X07"},{"t":"2200 g","mis":"M3-2-u5-X07"}],"explanation":["한 칸의 크기부터: 1 kg = 1000 g, 1000 ÷ 5 = 200 g.","10칸 → 200 × 10 = 2000.","2000 g이에요."],"asset":null},{"stem":"저울의 큰 눈금 0과 1 kg 사이가 똑같이 2칸으로 나뉘어 있어요. 사과를 재었더니 바늘이 0에서부터 3칸째 눈금을 가리켜요. 몇 g인가요?","options":[{"t":"1500 g","correct":true},{"t":"3 g","mis":"M3-2-u5-X07"},{"t":"300 g","mis":"M3-2-u5-X07"},{"t":"2000 g","mis":"M3-2-u5-X07"}],"explanation":["한 칸의 크기부터: 1 kg = 1000 g, 1000 ÷ 2 = 500 g.","3칸 → 500 × 3 = 1500.","1500 g이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L08_basic#1','math',3,2,'u5','L08','g3_2_math_u5_L08_basic','lesson_basic','M3-2-u5-C9',1,'sa','auto','2 kg 500 g + 1 kg 200 g = 3 kg □ g에서 □ 안에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u5-C9","difficulty":1,"kind":"sa","stem":"2 kg 500 g + 1 kg 200 g = 3 kg □ g에서 □ 안에 알맞은 수를 쓰세요.","answer":["700"],"explanation":["g끼리: 500 + 200 = 700.","kg끼리: 2 + 1 = 3.","2 kg 500 g + 1 kg 200 g = 3 kg 700 g."],"variant_rule":{"alt":[{"stem":"4 kg 100 g + 5 kg 750 g = 9 kg □ g에서 □ 안에 알맞은 수를 쓰세요.","answer":["850"],"explanation":["g끼리: 100 + 750 = 850.","kg끼리: 4 + 5 = 9.","4 kg 100 g + 5 kg 750 g = 9 kg 850 g."],"asset":null},{"stem":"4 kg 300 g + 1 kg 200 g = 5 kg □ g에서 □ 안에 알맞은 수를 쓰세요.","answer":["500"],"explanation":["g끼리: 300 + 200 = 500.","kg끼리: 4 + 1 = 5.","4 kg 300 g + 1 kg 200 g = 5 kg 500 g."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L08_basic#2','math',3,2,'u5','L08','g3_2_math_u5_L08_basic','lesson_basic','M3-2-u5-C9',1,'sa','auto','4 kg 700 g − 3 kg 600 g = □ kg 100 g에서 □ 안에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u5-C9","difficulty":1,"kind":"sa","stem":"4 kg 700 g − 3 kg 600 g = □ kg 100 g에서 □ 안에 알맞은 수를 쓰세요.","answer":["1"],"explanation":["g끼리: 700 − 600 = 100.","kg끼리: 4 − 3 = 1.","4 kg 700 g − 3 kg 600 g = 1 kg 100 g."],"variant_rule":{"alt":[{"stem":"3 kg 970 g − 1 kg 640 g = □ kg 330 g에서 □ 안에 알맞은 수를 쓰세요.","answer":["2"],"explanation":["g끼리: 970 − 640 = 330.","kg끼리: 3 − 1 = 2.","3 kg 970 g − 1 kg 640 g = 2 kg 330 g."],"asset":null},{"stem":"9 kg 250 g − 5 kg 200 g = □ kg 50 g에서 □ 안에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["g끼리: 250 − 200 = 50.","kg끼리: 9 − 5 = 4.","9 kg 250 g − 5 kg 200 g = 4 kg 50 g."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L08_basic#3','math',3,2,'u5','L08','g3_2_math_u5_L08_basic','lesson_basic','M3-2-u5-C9',1,'mc','auto','상자에 사과 5 kg 450 g과 배 4 kg 200 g을 담았어요. 과일은 모두 얼마인가요?',ARRAY['M3-2-u5-X12','M3-2-u5-X14']::text[],true,'{"seq":3,"concept":"M3-2-u5-C9","difficulty":1,"kind":"mc","stem":"상자에 사과 5 kg 450 g과 배 4 kg 200 g을 담았어요. 과일은 모두 얼마인가요?","options":[{"t":"9 kg 650 g","correct":true},{"t":"10 kg 650 g","mis":"M3-2-u5-X12"},{"t":"1 kg 250 g","mis":"M3-2-u5-X14"},{"t":"8 kg 650 g","mis":"M3-2-u5-X12"}],"explanation":["g끼리: 450 + 200 = 650.","kg끼리: 5 + 4 = 9.","5 kg 450 g + 4 kg 200 g = 9 kg 650 g."],"variant_rule":{"alt":[{"stem":"채원이는 2 kg 330 g, 도윤이는 1 kg 150 g의 옷을 모아 기부했어요. 두 사람이 모은 옷은 모두 얼마인가요?","options":[{"t":"3 kg 480 g","correct":true},{"t":"4 kg 480 g","mis":"M3-2-u5-X12"},{"t":"1 kg 180 g","mis":"M3-2-u5-X14"},{"t":"2 kg 480 g","mis":"M3-2-u5-X12"}],"explanation":["g끼리: 330 + 150 = 480.","kg끼리: 2 + 1 = 3.","2 kg 330 g + 1 kg 150 g = 3 kg 480 g."],"asset":null},{"stem":"여행 가방이 3 kg 510 g이에요. 5 kg 130 g의 짐을 더 넣으면 모두 얼마인가요?","options":[{"t":"8 kg 640 g","correct":true},{"t":"9 kg 640 g","mis":"M3-2-u5-X12"},{"t":"1 kg 620 g","mis":"M3-2-u5-X14"},{"t":"7 kg 640 g","mis":"M3-2-u5-X12"}],"explanation":["g끼리: 510 + 130 = 640.","kg끼리: 3 + 5 = 8.","3 kg 510 g + 5 kg 130 g = 8 kg 640 g."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L08_basic#4','math',3,2,'u5','L08','g3_2_math_u5_L08_basic','lesson_basic','M3-2-u5-C9',1,'sa','auto','쌀 8 kg 650 g 중에서 4 kg 300 g으로 떡을 만들었어요. 남은 쌀은 몇 g인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u5-C9","difficulty":1,"kind":"sa","stem":"쌀 8 kg 650 g 중에서 4 kg 300 g으로 떡을 만들었어요. 남은 쌀은 몇 g인가요? 숫자로 쓰세요.","answer":["4350"],"explanation":["g끼리: 650 − 300 = 350.","kg끼리: 8 − 4 = 4.","4 kg 350 g = 4350 g이에요."],"variant_rule":{"alt":[{"stem":"흙 4 kg 350 g 중에서 3 kg 300 g을 화분에 담았어요. 남은 흙은 몇 g인가요? 숫자로 쓰세요.","answer":["1050"],"explanation":["g끼리: 350 − 300 = 50.","kg끼리: 4 − 3 = 1.","1 kg 50 g = 1050 g이에요."],"asset":null},{"stem":"밀가루 4 kg 740 g 중에서 1 kg 480 g을 빵 만들기에 썼어요. 남은 밀가루는 몇 g인가요? 숫자로 쓰세요.","answer":["3260"],"explanation":["g끼리: 740 − 480 = 260.","kg끼리: 4 − 1 = 3.","3 kg 260 g = 3260 g이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L08_basic#5','math',3,2,'u5','L08','g3_2_math_u5_L08_basic','lesson_basic','M3-2-u5-C9',2,'sa','auto','수박은 3 kg 900 g, 멜론은 4 kg 300 g이에요. 멜론이 몇 g 더 무거운가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u5-C9","difficulty":2,"kind":"sa","stem":"수박은 3 kg 900 g, 멜론은 4 kg 300 g이에요. 멜론이 몇 g 더 무거운가요? 숫자로 쓰세요.","answer":["400"],"explanation":["차는 큰 쪽에서 작은 쪽을 빼요.","4 kg 300 g − 3 kg 900 g = 400 g.","멜론이 400 g 더 무거워요."],"variant_rule":{"alt":[{"stem":"수박은 1 kg 800 g, 멜론은 2 kg 200 g이에요. 멜론이 몇 g 더 무거운가요? 숫자로 쓰세요.","answer":["400"],"explanation":["차는 큰 쪽에서 작은 쪽을 빼요.","2 kg 200 g − 1 kg 800 g = 400 g.","멜론이 400 g 더 무거워요."],"asset":null},{"stem":"수박은 1 kg 600 g, 멜론은 1 kg 700 g이에요. 멜론이 몇 g 더 무거운가요? 숫자로 쓰세요.","answer":["100"],"explanation":["차는 큰 쪽에서 작은 쪽을 빼요.","1 kg 700 g − 1 kg 600 g = 100 g.","멜론이 100 g 더 무거워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L08_basic#6','math',3,2,'u5','L08','g3_2_math_u5_L08_basic','lesson_basic','M3-2-u5-C9',2,'sa','auto','상자에는 9 kg 500 g까지 담을 수 있어요. 수박 3 kg 400 g과 사과 3 kg을 담았어요. 몇 g을 더 담을 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u5-C9","difficulty":2,"kind":"sa","stem":"상자에는 9 kg 500 g까지 담을 수 있어요. 수박 3 kg 400 g과 사과 3 kg을 담았어요. 몇 g을 더 담을 수 있나요? 숫자로 쓰세요.","answer":["3100"],"explanation":["담은 무게: 3 kg 400 g + 3 kg = 6 kg 400 g.","9 kg 500 g − 6 kg 400 g = 3 kg 100 g.","3100 g 더 담을 수 있어요."],"variant_rule":{"alt":[{"stem":"상자에는 3 kg 500 g까지 담을 수 있어요. 수박 500 g과 사과 1 kg 100 g을 담았어요. 몇 g을 더 담을 수 있나요? 숫자로 쓰세요.","answer":["1900"],"explanation":["담은 무게: 500 g + 1 kg 100 g = 1 kg 600 g.","3 kg 500 g − 1 kg 600 g = 1 kg 900 g.","1900 g 더 담을 수 있어요."],"asset":null},{"stem":"상자에는 4 kg까지 담을 수 있어요. 수박 3 kg과 사과 350 g을 담았어요. 몇 g을 더 담을 수 있나요? 숫자로 쓰세요.","answer":["650"],"explanation":["담은 무게: 3 kg + 350 g = 3 kg 350 g.","4 kg − 3 kg 350 g = 650 g.","650 g 더 담을 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L08_basic#7','math',3,2,'u5','L08','g3_2_math_u5_L08_basic','lesson_basic','M3-2-u5-C9',2,'mc','auto','재활용품 3 kg 800 g 중에서 1 kg 400 g을 먼저 보냈어요. 남은 재활용품은 얼마인가요?',ARRAY['M3-2-u5-X13','M3-2-u5-X14']::text[],true,'{"seq":7,"concept":"M3-2-u5-C9","difficulty":2,"kind":"mc","stem":"재활용품 3 kg 800 g 중에서 1 kg 400 g을 먼저 보냈어요. 남은 재활용품은 얼마인가요?","options":[{"t":"2 kg 400 g","correct":true},{"t":"3 kg 400 g","mis":"M3-2-u5-X13"},{"t":"1 kg 400 g","mis":"M3-2-u5-X13"},{"t":"5 kg 200 g","mis":"M3-2-u5-X14"}],"explanation":["g끼리: 800 − 400 = 400.","kg끼리: 3 − 1 = 2.","3 kg 800 g − 1 kg 400 g = 2 kg 400 g."],"variant_rule":{"alt":[{"stem":"쌀 4 kg 900 g 중에서 3 kg 800 g으로 떡을 만들었어요. 남은 쌀은 얼마인가요?","options":[{"t":"1 kg 100 g","correct":true},{"t":"2 kg 100 g","mis":"M3-2-u5-X13"},{"t":"100 g","mis":"M3-2-u5-X13"},{"t":"8 kg 700 g","mis":"M3-2-u5-X14"}],"explanation":["g끼리: 900 − 800 = 100.","kg끼리: 4 − 3 = 1.","4 kg 900 g − 3 kg 800 g = 1 kg 100 g."],"asset":null},{"stem":"흙 4 kg 80 g 중에서 3 kg 10 g을 화분에 담았어요. 남은 흙은 얼마인가요?","options":[{"t":"1 kg 70 g","correct":true},{"t":"2 kg 70 g","mis":"M3-2-u5-X13"},{"t":"70 g","mis":"M3-2-u5-X13"},{"t":"7 kg 90 g","mis":"M3-2-u5-X14"}],"explanation":["g끼리: 80 − 10 = 70.","kg끼리: 4 − 3 = 1.","4 kg 80 g − 3 kg 10 g = 1 kg 70 g."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L08_basic#8','math',3,2,'u5','L08','g3_2_math_u5_L08_basic','lesson_basic','M3-2-u5-C9',2,'sa','auto','채원이는 2 kg 600 g, 도윤이는 3 kg 200 g의 옷을 모아 기부했어요. 두 사람이 모은 옷은 모두 몇 g인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u5-C9","difficulty":2,"kind":"sa","stem":"채원이는 2 kg 600 g, 도윤이는 3 kg 200 g의 옷을 모아 기부했어요. 두 사람이 모은 옷은 모두 몇 g인가요? 숫자로 쓰세요.","answer":["5800"],"explanation":["g끼리: 600 + 200 = 800.","kg끼리: 2 + 3 = 5.","5 kg 800 g = 5800 g이에요."],"variant_rule":{"alt":[{"stem":"여행 가방이 5 kg 340 g이에요. 2 kg 470 g의 짐을 더 넣으면 모두 몇 g인가요? 숫자로 쓰세요.","answer":["7810"],"explanation":["g끼리: 340 + 470 = 810.","kg끼리: 5 + 2 = 7.","7 kg 810 g = 7810 g이에요."],"asset":null},{"stem":"준우는 3 kg 500 g, 소율이는 4 kg 380 g의 재활용품을 모았어요. 두 사람이 모은 재활용품은 모두 몇 g인가요? 숫자로 쓰세요.","answer":["7880"],"explanation":["g끼리: 500 + 380 = 880.","kg끼리: 3 + 4 = 7.","7 kg 880 g = 7880 g이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L08_basic#9','math',3,2,'u5','L08','g3_2_math_u5_L08_basic','lesson_basic','M3-2-u5-C9',2,'sa','auto','3 kg 500 g + 5 kg 600 g = □ kg 100 g에서 □ 안에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u5-C9","difficulty":2,"kind":"sa","stem":"3 kg 500 g + 5 kg 600 g = □ kg 100 g에서 □ 안에 알맞은 수를 쓰세요.","answer":["9"],"explanation":["g끼리: 500 + 600 = 1100 — 1000 g = 1 kg으로 올려요.","kg끼리: 1 + 3 + 5 = 9.","3 kg 500 g + 5 kg 600 g = 9 kg 100 g."],"variant_rule":{"alt":[{"stem":"2 kg 480 g + 4 kg 540 g = 7 kg □ g에서 □ 안에 알맞은 수를 쓰세요.","answer":["20"],"explanation":["g끼리: 480 + 540 = 1020 — 1000 g = 1 kg으로 올려요.","kg끼리: 1 + 2 + 4 = 7.","2 kg 480 g + 4 kg 540 g = 7 kg 20 g."],"asset":null},{"stem":"2 kg 600 g + 2 kg 600 g = □ kg 200 g에서 □ 안에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["g끼리: 600 + 600 = 1200 — 1000 g = 1 kg으로 올려요.","kg끼리: 1 + 2 + 2 = 5.","2 kg 600 g + 2 kg 600 g = 5 kg 200 g."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L08_basic#10','math',3,2,'u5','L08','g3_2_math_u5_L08_basic','lesson_basic','M3-2-u5-C9',3,'mc','auto','하윤이 4 kg 550 g + 4 kg 700 g = 8 kg 1250 g이라고 계산했어요. 잘못된 까닭으로 알맞은 것은 무엇인가요?',ARRAY['M3-2-u5-X14','M3-2-u5-X11','M3-2-u5-X21']::text[],true,'{"seq":10,"concept":"M3-2-u5-C9","difficulty":3,"kind":"mc","stem":"하윤이 4 kg 550 g + 4 kg 700 g = 8 kg 1250 g이라고 계산했어요. 잘못된 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"g끼리의 합이 1000이 넘으면 1 kg으로 올려야 해요","correct":true},{"t":"g끼리 더하지 않고 빼야 해요","mis":"M3-2-u5-X14"},{"t":"kg끼리만 더하면 돼요","mis":"M3-2-u5-X11"},{"t":"바르게 계산했어요","mis":"M3-2-u5-X21"}],"explanation":["g끼리: 550 + 700 = 1250 — 1000 g = 1 kg으로 올려요.","kg끼리: 1 + 4 + 4 = 9.","4 kg 550 g + 4 kg 700 g = 9 kg 250 g."],"variant_rule":{"alt":[{"stem":"소율이 4 kg 400 g + 2 kg 900 g = 6 kg 1300 g이라고 계산했어요. 잘못된 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"g끼리의 합이 1000이 넘으면 1 kg으로 올려야 해요","correct":true},{"t":"g끼리 더하지 않고 빼야 해요","mis":"M3-2-u5-X14"},{"t":"kg끼리만 더하면 돼요","mis":"M3-2-u5-X11"},{"t":"바르게 계산했어요","mis":"M3-2-u5-X21"}],"explanation":["g끼리: 400 + 900 = 1300 — 1000 g = 1 kg으로 올려요.","kg끼리: 1 + 4 + 2 = 7.","4 kg 400 g + 2 kg 900 g = 7 kg 300 g."],"asset":null},{"stem":"지아가 1 kg 600 g + 1 kg 800 g = 2 kg 1400 g이라고 계산했어요. 잘못된 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"g끼리의 합이 1000이 넘으면 1 kg으로 올려야 해요","correct":true},{"t":"g끼리 더하지 않고 빼야 해요","mis":"M3-2-u5-X14"},{"t":"kg끼리만 더하면 돼요","mis":"M3-2-u5-X11"},{"t":"바르게 계산했어요","mis":"M3-2-u5-X21"}],"explanation":["g끼리: 600 + 800 = 1400 — 1000 g = 1 kg으로 올려요.","kg끼리: 1 + 1 + 1 = 3.","1 kg 600 g + 1 kg 800 g = 3 kg 400 g."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L08_challenge#1','math',3,2,'u5','L08','g3_2_math_u5_L08_challenge','lesson_challenge','M3-2-u5-C9',2,'mc','auto','준우는 1 kg 500 g, 소율이는 3 kg 780 g의 재활용품을 모았어요. 두 사람이 모은 재활용품은 모두 얼마인가요?',ARRAY['M3-2-u5-X12','M3-2-u5-X14']::text[],true,'{"seq":1,"concept":"M3-2-u5-C9","difficulty":2,"kind":"mc","stem":"준우는 1 kg 500 g, 소율이는 3 kg 780 g의 재활용품을 모았어요. 두 사람이 모은 재활용품은 모두 얼마인가요?","options":[{"t":"5 kg 280 g","correct":true},{"t":"4 kg 1280 g","mis":"M3-2-u5-X12"},{"t":"4 kg 280 g","mis":"M3-2-u5-X12"},{"t":"2 kg 280 g","mis":"M3-2-u5-X14"}],"explanation":["g끼리: 500 + 780 = 1280 — 1000 g = 1 kg으로 올려요.","kg끼리: 1 + 1 + 3 = 5.","1 kg 500 g + 3 kg 780 g = 5 kg 280 g."],"variant_rule":{"alt":[{"stem":"상자에 사과 5 kg 300 g과 배 4 kg 800 g을 담았어요. 과일은 모두 얼마인가요?","options":[{"t":"10 kg 100 g","correct":true},{"t":"9 kg 1100 g","mis":"M3-2-u5-X12"},{"t":"9 kg 100 g","mis":"M3-2-u5-X12"},{"t":"500 g","mis":"M3-2-u5-X14"}],"explanation":["g끼리: 300 + 800 = 1100 — 1000 g = 1 kg으로 올려요.","kg끼리: 1 + 5 + 4 = 10.","5 kg 300 g + 4 kg 800 g = 10 kg 100 g."],"asset":null},{"stem":"채원이는 3 kg 600 g, 도윤이는 2 kg 900 g의 옷을 모아 기부했어요. 두 사람이 모은 옷은 모두 얼마인가요?","options":[{"t":"6 kg 500 g","correct":true},{"t":"5 kg 1500 g","mis":"M3-2-u5-X12"},{"t":"5 kg 500 g","mis":"M3-2-u5-X12"},{"t":"700 g","mis":"M3-2-u5-X14"}],"explanation":["g끼리: 600 + 900 = 1500 — 1000 g = 1 kg으로 올려요.","kg끼리: 1 + 3 + 2 = 6.","3 kg 600 g + 2 kg 900 g = 6 kg 500 g."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L08_challenge#2','math',3,2,'u5','L08','g3_2_math_u5_L08_challenge','lesson_challenge','M3-2-u5-C9',2,'sa','auto','6 kg 800 g − 1 kg 900 g = □ kg 900 g에서 □ 안에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u5-C9","difficulty":2,"kind":"sa","stem":"6 kg 800 g − 1 kg 900 g = □ kg 900 g에서 □ 안에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["800 g에서 900을 뺄 수 없어 1 kg을 1000 g으로 내려요: 1800 − 900 = 900.","kg끼리: 6 − 1 − 1 = 4.","6 kg 800 g − 1 kg 900 g = 4 kg 900 g."],"variant_rule":{"alt":[{"stem":"4 kg 500 g − 3 kg 800 g = □ g에서 □ 안에 알맞은 수를 쓰세요.","answer":["700"],"explanation":["500 g에서 800을 뺄 수 없어 1 kg을 1000 g으로 내려요: 1500 − 800 = 700.","kg끼리: 4 − 1 − 3 = 0.","4 kg 500 g − 3 kg 800 g = 700 g."],"asset":null},{"stem":"7 kg 680 g − 5 kg 860 g = □ kg 820 g에서 □ 안에 알맞은 수를 쓰세요.","answer":["1"],"explanation":["680 g에서 860을 뺄 수 없어 1 kg을 1000 g으로 내려요: 1680 − 860 = 820.","kg끼리: 7 − 1 − 5 = 1.","7 kg 680 g − 5 kg 860 g = 1 kg 820 g."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L08_challenge#3','math',3,2,'u5','L08','g3_2_math_u5_L08_challenge','lesson_challenge','M3-2-u5-C9',3,'mc','auto','쌀 9 kg 840 g 중에서 4 kg 860 g으로 떡을 만들었어요. 남은 쌀은 얼마인가요?',ARRAY['M3-2-u5-X13']::text[],true,'{"seq":3,"concept":"M3-2-u5-C9","difficulty":3,"kind":"mc","stem":"쌀 9 kg 840 g 중에서 4 kg 860 g으로 떡을 만들었어요. 남은 쌀은 얼마인가요?","options":[{"t":"4 kg 980 g","correct":true},{"t":"5 kg 20 g","mis":"M3-2-u5-X13"},{"t":"4 kg 80 g","mis":"M3-2-u5-X13"},{"t":"5 kg 980 g","mis":"M3-2-u5-X13"}],"explanation":["840 g에서 860을 뺄 수 없어 1 kg을 1000 g으로 내려요: 1840 − 860 = 980.","kg끼리: 9 − 1 − 4 = 4.","9 kg 840 g − 4 kg 860 g = 4 kg 980 g."],"variant_rule":{"alt":[{"stem":"흙 6 kg 200 g 중에서 5 kg 500 g을 화분에 담았어요. 남은 흙은 얼마인가요?","options":[{"t":"700 g","correct":true},{"t":"1 kg 300 g","mis":"M3-2-u5-X13"},{"t":"1 kg 700 g","mis":"M3-2-u5-X13"},{"t":"11 kg 700 g","mis":"M3-2-u5-X14"}],"explanation":["200 g에서 500을 뺄 수 없어 1 kg을 1000 g으로 내려요: 1200 − 500 = 700.","kg끼리: 6 − 1 − 5 = 0.","6 kg 200 g − 5 kg 500 g = 700 g."],"asset":null},{"stem":"밀가루 4 kg 230 g 중에서 1 kg 810 g을 빵 만들기에 썼어요. 남은 밀가루는 얼마인가요?","options":[{"t":"2 kg 420 g","correct":true},{"t":"3 kg 580 g","mis":"M3-2-u5-X13"},{"t":"3 kg 420 g","mis":"M3-2-u5-X13"},{"t":"6 kg 40 g","mis":"M3-2-u5-X14"}],"explanation":["230 g에서 810을 뺄 수 없어 1 kg을 1000 g으로 내려요: 1230 − 810 = 420.","kg끼리: 4 − 1 − 1 = 2.","4 kg 230 g − 1 kg 810 g = 2 kg 420 g."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L08_challenge#4','math',3,2,'u5','L08','g3_2_math_u5_L08_challenge','lesson_challenge','M3-2-u5-C9',3,'mc','auto','하윤이 5 kg 590 g − 3 kg 690 g = 2 kg 100 g이라고 계산했어요. 잘못된 까닭으로 알맞은 것은 무엇인가요?',ARRAY['M3-2-u5-X13','M3-2-u5-X14','M3-2-u5-X04']::text[],true,'{"seq":4,"concept":"M3-2-u5-C9","difficulty":3,"kind":"mc","stem":"하윤이 5 kg 590 g − 3 kg 690 g = 2 kg 100 g이라고 계산했어요. 잘못된 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"590 g에서 690 g을 뺄 수 없으니 1 kg을 1000 g으로 내려야 해요","correct":true},{"t":"큰 수에서 작은 수를 빼면 되니 바르게 계산했어요","mis":"M3-2-u5-X13"},{"t":"g끼리 더해야 해요","mis":"M3-2-u5-X14"},{"t":"1 kg을 100 g으로 내려야 해요","mis":"M3-2-u5-X04"}],"explanation":["590 g에서 690을 뺄 수 없어 1 kg을 1000 g으로 내려요: 1590 − 690 = 900.","kg끼리: 5 − 1 − 3 = 1.","5 kg 590 g − 3 kg 690 g = 1 kg 900 g."],"variant_rule":{"alt":[{"stem":"채원이 2 kg 750 g − 1 kg 950 g = 1 kg 200 g이라고 계산했어요. 잘못된 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"750 g에서 950 g을 뺄 수 없으니 1 kg을 1000 g으로 내려야 해요","correct":true},{"t":"큰 수에서 작은 수를 빼면 되니 바르게 계산했어요","mis":"M3-2-u5-X13"},{"t":"g끼리 더해야 해요","mis":"M3-2-u5-X14"},{"t":"1 kg을 100 g으로 내려야 해요","mis":"M3-2-u5-X04"}],"explanation":["750 g에서 950을 뺄 수 없어 1 kg을 1000 g으로 내려요: 1750 − 950 = 800.","kg끼리: 2 − 1 − 1 = 0.","2 kg 750 g − 1 kg 950 g = 800 g."],"asset":null},{"stem":"서준이 9 kg 700 g − 7 kg 710 g = 2 kg 10 g이라고 계산했어요. 잘못된 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"700 g에서 710 g을 뺄 수 없으니 1 kg을 1000 g으로 내려야 해요","correct":true},{"t":"큰 수에서 작은 수를 빼면 되니 바르게 계산했어요","mis":"M3-2-u5-X13"},{"t":"g끼리 더해야 해요","mis":"M3-2-u5-X14"},{"t":"1 kg을 100 g으로 내려야 해요","mis":"M3-2-u5-X04"}],"explanation":["700 g에서 710을 뺄 수 없어 1 kg을 1000 g으로 내려요: 1700 − 710 = 990.","kg끼리: 9 − 1 − 7 = 1.","9 kg 700 g − 7 kg 710 g = 1 kg 990 g."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L08_challenge#5','math',3,2,'u5','L08','g3_2_math_u5_L08_challenge','lesson_challenge','M3-2-u5-C9',3,'sa','auto','상자에는 5 kg까지 담을 수 있어요. 수박 2 kg 400 g과 사과 1 kg을 담았어요. 몇 g을 더 담을 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u5-C9","difficulty":3,"kind":"sa","stem":"상자에는 5 kg까지 담을 수 있어요. 수박 2 kg 400 g과 사과 1 kg을 담았어요. 몇 g을 더 담을 수 있나요? 숫자로 쓰세요.","answer":["1600"],"explanation":["담은 무게: 2 kg 400 g + 1 kg = 3 kg 400 g.","5 kg − 3 kg 400 g = 1 kg 600 g.","1600 g 더 담을 수 있어요."],"variant_rule":{"alt":[{"stem":"상자에는 5 kg까지 담을 수 있어요. 수박 2 kg 400 g과 사과 2 kg 50 g을 담았어요. 몇 g을 더 담을 수 있나요? 숫자로 쓰세요.","answer":["550"],"explanation":["담은 무게: 2 kg 400 g + 2 kg 50 g = 4 kg 450 g.","5 kg − 4 kg 450 g = 550 g.","550 g 더 담을 수 있어요."],"asset":null},{"stem":"상자에는 2 kg 500 g까지 담을 수 있어요. 수박 1 kg 500 g과 사과 900 g을 담았어요. 몇 g을 더 담을 수 있나요? 숫자로 쓰세요.","answer":["100"],"explanation":["담은 무게: 1 kg 500 g + 900 g = 2 kg 400 g.","2 kg 500 g − 2 kg 400 g = 100 g.","100 g 더 담을 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L08_challenge#6','math',3,2,'u5','L08','g3_2_math_u5_L08_challenge','lesson_challenge','M3-2-u5-C9',3,'sa','auto','상자에 사과 1 kg 650 g과 배 3 kg 850 g을 담았어요. 과일은 모두 몇 g인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u5-C9","difficulty":3,"kind":"sa","stem":"상자에 사과 1 kg 650 g과 배 3 kg 850 g을 담았어요. 과일은 모두 몇 g인가요? 숫자로 쓰세요.","answer":["5500"],"explanation":["g끼리: 650 + 850 = 1500 — 1000 g = 1 kg으로 올려요.","kg끼리: 1 + 1 + 3 = 5.","5 kg 500 g = 5500 g이에요."],"variant_rule":{"alt":[{"stem":"채원이는 4 kg 900 g, 도윤이는 1 kg 600 g의 옷을 모아 기부했어요. 두 사람이 모은 옷은 모두 몇 g인가요? 숫자로 쓰세요.","answer":["6500"],"explanation":["g끼리: 900 + 600 = 1500 — 1000 g = 1 kg으로 올려요.","kg끼리: 1 + 4 + 1 = 6.","6 kg 500 g = 6500 g이에요."],"asset":null},{"stem":"여행 가방이 3 kg 610 g이에요. 3 kg 970 g의 짐을 더 넣으면 모두 몇 g인가요? 숫자로 쓰세요.","answer":["7580"],"explanation":["g끼리: 610 + 970 = 1580 — 1000 g = 1 kg으로 올려요.","kg끼리: 1 + 3 + 3 = 7.","7 kg 580 g = 7580 g이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L08_challenge#7','math',3,2,'u5','L08','g3_2_math_u5_L08_challenge','lesson_challenge','M3-2-u5-C9',3,'sa','auto','쌀 3 kg 200 g 중에서 1 kg 700 g으로 떡을 만들었어요. 남은 쌀은 몇 g인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u5-C9","difficulty":3,"kind":"sa","stem":"쌀 3 kg 200 g 중에서 1 kg 700 g으로 떡을 만들었어요. 남은 쌀은 몇 g인가요? 숫자로 쓰세요.","answer":["1500"],"explanation":["200 g에서 700을 뺄 수 없어 1 kg을 1000 g으로 내려요: 1200 − 700 = 500.","kg끼리: 3 − 1 − 1 = 1.","1 kg 500 g = 1500 g이에요."],"variant_rule":{"alt":[{"stem":"흙 5 kg 300 g 중에서 4 kg 900 g을 화분에 담았어요. 남은 흙은 몇 g인가요? 숫자로 쓰세요.","answer":["400"],"explanation":["300 g에서 900을 뺄 수 없어 1 kg을 1000 g으로 내려요: 1300 − 900 = 400.","kg끼리: 5 − 1 − 4 = 0.","400 g = 400 g이에요."],"asset":null},{"stem":"밀가루 4 kg 300 g 중에서 2 kg 700 g을 빵 만들기에 썼어요. 남은 밀가루는 몇 g인가요? 숫자로 쓰세요.","answer":["1600"],"explanation":["300 g에서 700을 뺄 수 없어 1 kg을 1000 g으로 내려요: 1300 − 700 = 600.","kg끼리: 4 − 1 − 2 = 1.","1 kg 600 g = 1600 g이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L08_challenge#8','math',3,2,'u5','L08','g3_2_math_u5_L08_challenge','lesson_challenge','M3-2-u5-C9',4,'essay','teacher','친구가 1 kg 200 g과 1050 g을 더하면서 1050 g을 1 kg 500 g으로 바꾸어 「2 kg 700 g」이라고 했어요. 잘못된 점을 찾고 바르게 더한 무게를 구해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u5-C9","difficulty":4,"kind":"essay","stem":"친구가 1 kg 200 g과 1050 g을 더하면서 1050 g을 1 kg 500 g으로 바꾸어 「2 kg 700 g」이라고 했어요. 잘못된 점을 찾고 바르게 더한 무게를 구해 보세요.","answer_guide":{"answer":"예: 1050 g은 1000 g + 50 g이므로 1 kg 50 g이다. 친구는 50 g을 500 g으로 바꾸었다. 바르게 더하면 1 kg 200 g + 1 kg 50 g = 2 kg 250 g이다.","scoring_points":["1050 g = 1 kg 50 g이라고 썼는가","50 g을 500 g으로 바꾼 잘못을 짚었는가","2 kg 250 g이라고 답했는가"]},"explanation":["1050 g = 1 kg 50 g.","50 g ≠ 500 g.","1 kg 200 g + 1 kg 50 g = 2 kg 250 g."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L08_challenge#9','math',3,2,'u5','L08','g3_2_math_u5_L08_challenge','lesson_challenge','M3-2-u5-C9',4,'essay','teacher','빈 가방의 무게는 1500 g이에요. 짐 19 kg 200 g을 넣으면 가방의 무게는 모두 얼마인지 구하고, 단위를 어떻게 맞추어 더하면 편리한지 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u5-C9","difficulty":4,"kind":"essay","stem":"빈 가방의 무게는 1500 g이에요. 짐 19 kg 200 g을 넣으면 가방의 무게는 모두 얼마인지 구하고, 단위를 어떻게 맞추어 더하면 편리한지 설명해 보세요.","answer_guide":{"answer":"예: 1500 g을 1 kg 500 g으로 바꾸어 같은 단위끼리 더하면 편리하다. g끼리 500 + 200 = 700 g, kg끼리 1 + 19 = 20 kg이므로 모두 20 kg 700 g이다.","scoring_points":["1500 g = 1 kg 500 g으로 바꾸었는가","같은 단위끼리 더했는가","20 kg 700 g이라고 답했는가"]},"explanation":["1500 g = 1 kg 500 g.","g끼리 700, kg끼리 20.","20 kg 700 g."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L08_challenge#10','math',3,2,'u5','L08','g3_2_math_u5_L08_challenge','lesson_challenge','M3-2-u5-C9',4,'mc','auto','정후가 5 kg 600 g + 2 kg 500 g = 7 kg 1100 g이라고 계산했어요. 잘못된 까닭으로 알맞은 것은 무엇인가요?',ARRAY['M3-2-u5-X14','M3-2-u5-X11','M3-2-u5-X21']::text[],true,'{"seq":10,"concept":"M3-2-u5-C9","difficulty":4,"kind":"mc","stem":"정후가 5 kg 600 g + 2 kg 500 g = 7 kg 1100 g이라고 계산했어요. 잘못된 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"g끼리의 합이 1000이 넘으면 1 kg으로 올려야 해요","correct":true},{"t":"g끼리 더하지 않고 빼야 해요","mis":"M3-2-u5-X14"},{"t":"kg끼리만 더하면 돼요","mis":"M3-2-u5-X11"},{"t":"바르게 계산했어요","mis":"M3-2-u5-X21"}],"explanation":["g끼리: 600 + 500 = 1100 — 1000 g = 1 kg으로 올려요.","kg끼리: 1 + 5 + 2 = 8.","5 kg 600 g + 2 kg 500 g = 8 kg 100 g."],"variant_rule":{"alt":[{"stem":"민아가 2 kg 600 g + 4 kg 900 g = 6 kg 1500 g이라고 계산했어요. 잘못된 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"g끼리의 합이 1000이 넘으면 1 kg으로 올려야 해요","correct":true},{"t":"g끼리 더하지 않고 빼야 해요","mis":"M3-2-u5-X14"},{"t":"kg끼리만 더하면 돼요","mis":"M3-2-u5-X11"},{"t":"바르게 계산했어요","mis":"M3-2-u5-X21"}],"explanation":["g끼리: 600 + 900 = 1500 — 1000 g = 1 kg으로 올려요.","kg끼리: 1 + 2 + 4 = 7.","2 kg 600 g + 4 kg 900 g = 7 kg 500 g."],"asset":null},{"stem":"하윤이 4 kg 730 g + 3 kg 920 g = 7 kg 1650 g이라고 계산했어요. 잘못된 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"g끼리의 합이 1000이 넘으면 1 kg으로 올려야 해요","correct":true},{"t":"g끼리 더하지 않고 빼야 해요","mis":"M3-2-u5-X14"},{"t":"kg끼리만 더하면 돼요","mis":"M3-2-u5-X11"},{"t":"바르게 계산했어요","mis":"M3-2-u5-X21"}],"explanation":["g끼리: 730 + 920 = 1650 — 1000 g = 1 kg으로 올려요.","kg끼리: 1 + 4 + 3 = 8.","4 kg 730 g + 3 kg 920 g = 8 kg 650 g."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L09_basic#1','math',3,2,'u5','L09','g3_2_math_u5_L09_basic','lesson_basic','M3-2-u5-C10',1,'sa','auto','우유를 10 L 통 7개에 남김없이 나누어 담았어요. 우유는 모두 몇 L인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u5-C10","difficulty":1,"kind":"sa","stem":"우유를 10 L 통 7개에 남김없이 나누어 담았어요. 우유는 모두 몇 L인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["통마다 담은 양: 10 × 7 = 70.","모두 더해요.","70 L예요."],"variant_rule":{"alt":[{"stem":"우유를 10 L 통 4개에 남김없이 나누어 담았어요. 우유는 모두 몇 L인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["통마다 담은 양: 10 × 4 = 40.","모두 더해요.","40 L예요."],"asset":null},{"stem":"우유를 10 L 통 3개에 남김없이 나누어 담았어요. 우유는 모두 몇 L인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["통마다 담은 양: 10 × 3 = 30.","모두 더해요.","30 L예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L09_basic#2','math',3,2,'u5','L09','g3_2_math_u5_L09_basic','lesson_basic','M3-2-u5-C10',1,'sa','auto','우유 90 L를 남김없이 나누어 담아요. 10 L 통 7개를 썼어요. 5 L 통은 몇 개 써야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u5-C10","difficulty":1,"kind":"sa","stem":"우유 90 L를 남김없이 나누어 담아요. 10 L 통 7개를 썼어요. 5 L 통은 몇 개 써야 하나요? 숫자로 쓰세요.","answer":["4"],"explanation":["지금까지 담은 양: 70 L.","남은 양: 90 − 70 = 20 L.","20 ÷ 5 = 4 — 5 L 통 4개."],"variant_rule":{"alt":[{"stem":"사료 50 kg을 남김없이 나누어 담아요. 4 kg 봉지 6개, 2 kg 봉지 3개를 썼어요. 5 kg 봉지는 몇 개 써야 하나요? 숫자로 쓰세요.","answer":["4"],"explanation":["지금까지 담은 양: 30 kg.","남은 양: 50 − 30 = 20 kg.","20 ÷ 5 = 4 — 5 kg 봉지 4개."],"asset":null},{"stem":"우유 90 L를 남김없이 나누어 담아요. 6 L 통 5개, 5 L 통 6개를 썼어요. 10 L 통은 몇 개 써야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["지금까지 담은 양: 60 L.","남은 양: 90 − 60 = 30 L.","30 ÷ 10 = 3 — 10 L 통 3개."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L09_basic#3','math',3,2,'u5','L09','g3_2_math_u5_L09_basic','lesson_basic','M3-2-u5-C10',1,'sa','auto','우유를 10 L 통 2개, 5 L 통 4개에 남김없이 나누어 담았어요. 우유는 모두 몇 L인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u5-C10","difficulty":1,"kind":"sa","stem":"우유를 10 L 통 2개, 5 L 통 4개에 남김없이 나누어 담았어요. 우유는 모두 몇 L인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["통마다 담은 양: 10 × 2 = 20, 5 × 4 = 20.","모두 더해요.","40 L예요."],"variant_rule":{"alt":[{"stem":"우유를 10 L 통 4개, 6 L 통 5개, 5 L 통 2개에 남김없이 나누어 담았어요. 우유는 모두 몇 L인가요? 숫자로 쓰세요.","answer":["80"],"explanation":["통마다 담은 양: 10 × 4 = 40, 6 × 5 = 30, 5 × 2 = 10.","모두 더해요.","80 L예요."],"asset":null},{"stem":"우유를 6 L 통 1개, 5 L 통 1개에 남김없이 나누어 담았어요. 우유는 모두 몇 L인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["통마다 담은 양: 6 × 1 = 6, 5 × 1 = 5.","모두 더해요.","11 L예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L09_basic#4','math',3,2,'u5','L09','g3_2_math_u5_L09_basic','lesson_basic','M3-2-u5-C10',1,'sa','auto','우유 90 L를 남김없이 나누어 담아요. 10 L 통 5개, 6 L 통 5개를 썼어요. 5 L 통은 몇 개 써야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u5-C10","difficulty":1,"kind":"sa","stem":"우유 90 L를 남김없이 나누어 담아요. 10 L 통 5개, 6 L 통 5개를 썼어요. 5 L 통은 몇 개 써야 하나요? 숫자로 쓰세요.","answer":["2"],"explanation":["지금까지 담은 양: 80 L.","남은 양: 90 − 80 = 10 L.","10 ÷ 5 = 2 — 5 L 통 2개."],"variant_rule":{"alt":[{"stem":"우유 90 L를 남김없이 나누어 담아요. 10 L 통 6개를 썼어요. 5 L 통은 몇 개 써야 하나요? 숫자로 쓰세요.","answer":["6"],"explanation":["지금까지 담은 양: 60 L.","남은 양: 90 − 60 = 30 L.","30 ÷ 5 = 6 — 5 L 통 6개."],"asset":null},{"stem":"우유 90 L를 남김없이 나누어 담아요. 10 L 통 6개를 썼어요. 6 L 통은 몇 개 써야 하나요? 숫자로 쓰세요.","answer":["5"],"explanation":["지금까지 담은 양: 60 L.","남은 양: 90 − 60 = 30 L.","30 ÷ 6 = 5 — 6 L 통 5개."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L09_basic#5','math',3,2,'u5','L09','g3_2_math_u5_L09_basic','lesson_basic','M3-2-u5-C10',2,'mc','auto','우유 90 L를 10 L, 6 L, 5 L 통(각각 7개)에 남김없이 담으려고 해요. 6 L 통은 몇 개 써야 하나요?',ARRAY['M3-2-u5-X18','M3-2-u5-X19']::text[],true,'{"seq":5,"concept":"M3-2-u5-C10","difficulty":2,"kind":"mc","stem":"우유 90 L를 10 L, 6 L, 5 L 통(각각 7개)에 남김없이 담으려고 해요. 6 L 통은 몇 개 써야 하나요?","options":[{"t":"쓰지 않거나 5개","correct":true},{"t":"1개나 2개","mis":"M3-2-u5-X18"},{"t":"3개나 4개","mis":"M3-2-u5-X18"},{"t":"7개 모두","mis":"M3-2-u5-X19"}],"explanation":["10 L 통과 5 L 통으로 담은 양은 끝자리가 0이나 5예요.","6 L 통 1개·2개·3개·4개 → 6, 12, 18, 24 L — 끝자리가 맞지 않아요.","6 L 통은 쓰지 않거나 5개 써야 해요."],"variant_rule":{"alt":[{"stem":"우유 70 L를 10 L, 8 L, 5 L 통(각각 6개)에 남김없이 담으려고 해요. 8 L 통은 몇 개 써야 하나요?","options":[{"t":"쓰지 않거나 5개","correct":true},{"t":"1개나 2개","mis":"M3-2-u5-X18"},{"t":"3개나 4개","mis":"M3-2-u5-X18"},{"t":"6개 모두","mis":"M3-2-u5-X19"}],"explanation":["10 L 통과 5 L 통으로 담은 양은 끝자리가 0이나 5예요.","8 L 통 1개·2개·3개·4개 → 8, 16, 24, 32 L — 끝자리가 맞지 않아요.","8 L 통은 쓰지 않거나 5개 써야 해요."],"asset":null},{"stem":"우유 90 L를 10 L, 8 L, 5 L 통(각각 7개)에 남김없이 담으려고 해요. 8 L 통은 몇 개 써야 하나요?","options":[{"t":"쓰지 않거나 5개","correct":true},{"t":"1개나 2개","mis":"M3-2-u5-X18"},{"t":"3개나 4개","mis":"M3-2-u5-X18"},{"t":"7개 모두","mis":"M3-2-u5-X19"}],"explanation":["10 L 통과 5 L 통으로 담은 양은 끝자리가 0이나 5예요.","8 L 통 1개·2개·3개·4개 → 8, 16, 24, 32 L — 끝자리가 맞지 않아요.","8 L 통은 쓰지 않거나 5개 써야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L09_basic#6','math',3,2,'u5','L09','g3_2_math_u5_L09_basic','lesson_basic','M3-2-u5-C10',2,'mc','auto','우유 90 L를 10 L, 6 L, 5 L 통(각각 7개)에 남김없이 나누어 담는 방법은 무엇인가요?',ARRAY['M3-2-u5-X18']::text[],true,'{"seq":6,"concept":"M3-2-u5-C10","difficulty":2,"kind":"mc","stem":"우유 90 L를 10 L, 6 L, 5 L 통(각각 7개)에 남김없이 나누어 담는 방법은 무엇인가요?","options":[{"t":"10 L 통 6개, 5 L 통 6개","correct":true},{"t":"10 L 통 5개, 5 L 통 5개","mis":"M3-2-u5-X18"},{"t":"10 L 통 7개, 5 L 통 5개","mis":"M3-2-u5-X18"},{"t":"10 L 통 5개, 5 L 통 7개","mis":"M3-2-u5-X18"}],"explanation":["보기마다 담은 양을 모두 더해 90 L와 견주어요.","10 L 통 6개, 5 L 통 6개 → 60 + 30 = 90 L.","남김없이 꼭 맞는 것은 이것뿐이에요."],"variant_rule":{"alt":[{"stem":"사료 50 kg을 5 kg, 4 kg, 2 kg 봉지(각각 6개)에 남김없이 나누어 담는 방법은 무엇인가요?","options":[{"t":"5 kg 봉지 6개, 4 kg 봉지 5개","correct":true},{"t":"5 kg 봉지 8개, 4 kg 봉지 5개, 2 kg 봉지 1개","mis":"M3-2-u5-X18"},{"t":"5 kg 봉지 7개, 4 kg 봉지 4개","mis":"M3-2-u5-X18"},{"t":"5 kg 봉지 8개, 4 kg 봉지 4개, 2 kg 봉지 2개","mis":"M3-2-u5-X18"}],"explanation":["보기마다 담은 양을 모두 더해 50 kg과 견주어요.","5 kg 봉지 6개, 4 kg 봉지 5개 → 30 + 20 = 50 kg.","남김없이 꼭 맞는 것은 이것뿐이에요."],"asset":null},{"stem":"우유 40 L를 10 L, 5 L, 2 L 통(각각 4개)에 남김없이 나누어 담는 방법은 무엇인가요?","options":[{"t":"10 L 통 3개, 5 L 통 2개","correct":true},{"t":"10 L 통 5개, 5 L 통 1개, 2 L 통 2개","mis":"M3-2-u5-X18"},{"t":"10 L 통 5개, 5 L 통 2개, 2 L 통 2개","mis":"M3-2-u5-X18"},{"t":"10 L 통 4개, 5 L 통 2개, 2 L 통 2개","mis":"M3-2-u5-X18"}],"explanation":["보기마다 담은 양을 모두 더해 40 L와 견주어요.","10 L 통 3개, 5 L 통 2개 → 30 + 10 = 40 L.","남김없이 꼭 맞는 것은 이것뿐이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L09_basic#7','math',3,2,'u5','L09','g3_2_math_u5_L09_basic','lesson_basic','M3-2-u5-C10',2,'sa','auto','우유 90 L를 남김없이 나누어 담아요. 10 L 통 4개, 6 L 통 5개를 썼어요. 5 L 통은 몇 개 써야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u5-C10","difficulty":2,"kind":"sa","stem":"우유 90 L를 남김없이 나누어 담아요. 10 L 통 4개, 6 L 통 5개를 썼어요. 5 L 통은 몇 개 써야 하나요? 숫자로 쓰세요.","answer":["4"],"explanation":["지금까지 담은 양: 70 L.","남은 양: 90 − 70 = 20 L.","20 ÷ 5 = 4 — 5 L 통 4개."],"variant_rule":{"alt":[{"stem":"우유 90 L를 남김없이 나누어 담아요. 6 L 통 5개를 썼어요. 10 L 통은 몇 개 써야 하나요? 숫자로 쓰세요.","answer":["6"],"explanation":["지금까지 담은 양: 30 L.","남은 양: 90 − 30 = 60 L.","60 ÷ 10 = 6 — 10 L 통 6개."],"asset":null},{"stem":"우유 90 L를 남김없이 나누어 담아요. 10 L 통 4개, 5 L 통 4개를 썼어요. 6 L 통은 몇 개 써야 하나요? 숫자로 쓰세요.","answer":["5"],"explanation":["지금까지 담은 양: 60 L.","남은 양: 90 − 60 = 30 L.","30 ÷ 6 = 5 — 6 L 통 5개."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L09_basic#8','math',3,2,'u5','L09','g3_2_math_u5_L09_basic','lesson_basic','M3-2-u5-C10',2,'sa','auto','사료를 5 kg 봉지 2개, 4 kg 봉지 4개, 2 kg 봉지 2개에 남김없이 나누어 담았어요. 사료는 모두 몇 kg인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u5-C10","difficulty":2,"kind":"sa","stem":"사료를 5 kg 봉지 2개, 4 kg 봉지 4개, 2 kg 봉지 2개에 남김없이 나누어 담았어요. 사료는 모두 몇 kg인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["통마다 담은 양: 5 × 2 = 10, 4 × 4 = 16, 2 × 2 = 4.","모두 더해요.","30 kg이에요."],"variant_rule":{"alt":[{"stem":"우유를 10 L 통 5개, 6 L 통 1개에 남김없이 나누어 담았어요. 우유는 모두 몇 L인가요? 숫자로 쓰세요.","answer":["56"],"explanation":["통마다 담은 양: 10 × 5 = 50, 6 × 1 = 6.","모두 더해요.","56 L예요."],"asset":null},{"stem":"사료를 4 kg 봉지 1개, 2 kg 봉지 2개에 남김없이 나누어 담았어요. 사료는 모두 몇 kg인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["통마다 담은 양: 4 × 1 = 4, 2 × 2 = 4.","모두 더해요.","8 kg이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L09_basic#9','math',3,2,'u5','L09','g3_2_math_u5_L09_basic','lesson_basic','M3-2-u5-C10',2,'mc','auto','우유 90 L를 10 L, 6 L, 5 L 통(각각 7개)에 남김없이 나누어 담는 방법은 무엇인가요?',ARRAY['M3-2-u5-X18']::text[],true,'{"seq":9,"concept":"M3-2-u5-C10","difficulty":2,"kind":"mc","stem":"우유 90 L를 10 L, 6 L, 5 L 통(각각 7개)에 남김없이 나누어 담는 방법은 무엇인가요?","options":[{"t":"10 L 통 6개, 5 L 통 6개","correct":true},{"t":"10 L 통 6개, 5 L 통 8개","mis":"M3-2-u5-X18"},{"t":"10 L 통 8개, 5 L 통 6개","mis":"M3-2-u5-X18"},{"t":"10 L 통 8개, 6 L 통 1개, 5 L 통 8개","mis":"M3-2-u5-X18"}],"explanation":["보기마다 담은 양을 모두 더해 90 L와 견주어요.","10 L 통 6개, 5 L 통 6개 → 60 + 30 = 90 L.","남김없이 꼭 맞는 것은 이것뿐이에요."],"variant_rule":{"alt":[{"stem":"사료 30 kg을 5 kg, 4 kg, 2 kg 봉지(각각 5개)에 남김없이 나누어 담는 방법은 무엇인가요?","options":[{"t":"5 kg 봉지 4개, 2 kg 봉지 5개","correct":true},{"t":"5 kg 봉지 3개, 4 kg 봉지 1개, 2 kg 봉지 4개","mis":"M3-2-u5-X18"},{"t":"5 kg 봉지 5개, 2 kg 봉지 5개","mis":"M3-2-u5-X18"},{"t":"5 kg 봉지 3개, 2 kg 봉지 4개","mis":"M3-2-u5-X18"}],"explanation":["보기마다 담은 양을 모두 더해 30 kg과 견주어요.","5 kg 봉지 4개, 2 kg 봉지 5개 → 20 + 10 = 30 kg.","남김없이 꼭 맞는 것은 이것뿐이에요."],"asset":null},{"stem":"우유 40 L를 10 L, 5 L, 2 L 통(각각 4개)에 남김없이 나누어 담는 방법은 무엇인가요?","options":[{"t":"10 L 통 3개, 5 L 통 2개","correct":true},{"t":"10 L 통 4개, 5 L 통 4개, 2 L 통 1개","mis":"M3-2-u5-X18"},{"t":"10 L 통 3개, 5 L 통 3개, 2 L 통 1개","mis":"M3-2-u5-X18"},{"t":"10 L 통 4개, 5 L 통 3개, 2 L 통 2개","mis":"M3-2-u5-X18"}],"explanation":["보기마다 담은 양을 모두 더해 40 L와 견주어요.","10 L 통 3개, 5 L 통 2개 → 30 + 10 = 40 L.","남김없이 꼭 맞는 것은 이것뿐이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.pa