INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L09_basic#10','math',3,2,'u5','L09','g3_2_math_u5_L09_basic','lesson_basic','M3-2-u5-C10',3,'sa','auto','20 kg을 5 kg 봉지 4개, 2 kg 봉지 10개에 남김없이 나누어 담는 방법은 모두 몇 가지인가요? 쓰지 않는 봉지가 있어도 돼요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-2-u5-C10","difficulty":3,"kind":"sa","stem":"20 kg을 5 kg 봉지 4개, 2 kg 봉지 10개에 남김없이 나누어 담는 방법은 모두 몇 가지인가요? 쓰지 않는 봉지가 있어도 돼요. 숫자로 쓰세요.","answer":["3"],"explanation":["표로 큰 봉지부터 개수를 하나씩 바꾸어 봐요.","합이 20 kg인 것만 세어요.","모두 3가지예요."],"variant_rule":{"alt":[{"stem":"30 L를 10 L 통 3개, 5 L 통 6개에 남김없이 나누어 담는 방법은 모두 몇 가지인가요? 쓰지 않는 통이 있어도 돼요. 숫자로 쓰세요.","answer":["4"],"explanation":["표로 큰 통부터 개수를 하나씩 바꾸어 봐요.","합이 30 L인 것만 세어요.","모두 4가지예요."],"asset":null},{"stem":"24 kg을 6 kg 봉지 4개, 4 kg 봉지 6개에 남김없이 나누어 담는 방법은 모두 몇 가지인가요? 쓰지 않는 봉지가 있어도 돼요. 숫자로 쓰세요.","answer":["3"],"explanation":["표로 큰 봉지부터 개수를 하나씩 바꾸어 봐요.","합이 24 kg인 것만 세어요.","모두 3가지예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L09_challenge#1','math',3,2,'u5','L09','g3_2_math_u5_L09_challenge','lesson_challenge','M3-2-u5-C10',2,'sa','auto','사료 50 kg을 남김없이 나누어 담아요. 5 kg 봉지 4개, 2 kg 봉지 5개를 썼어요. 4 kg 봉지는 몇 개 써야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u5-C10","difficulty":2,"kind":"sa","stem":"사료 50 kg을 남김없이 나누어 담아요. 5 kg 봉지 4개, 2 kg 봉지 5개를 썼어요. 4 kg 봉지는 몇 개 써야 하나요? 숫자로 쓰세요.","answer":["5"],"explanation":["지금까지 담은 양: 30 kg.","남은 양: 50 − 30 = 20 kg.","20 ÷ 4 = 5 — 4 kg 봉지 5개."],"variant_rule":{"alt":[{"stem":"사료 50 kg을 남김없이 나누어 담아요. 5 kg 봉지 4개, 2 kg 봉지 3개를 썼어요. 4 kg 봉지는 몇 개 써야 하나요? 숫자로 쓰세요.","answer":["6"],"explanation":["지금까지 담은 양: 26 kg.","남은 양: 50 − 26 = 24 kg.","24 ÷ 4 = 6 — 4 kg 봉지 6개."],"asset":null},{"stem":"우유 90 L를 남김없이 나누어 담아요. 6 L 통 5개, 5 L 통 2개를 썼어요. 10 L 통은 몇 개 써야 하나요? 숫자로 쓰세요.","answer":["5"],"explanation":["지금까지 담은 양: 40 L.","남은 양: 90 − 40 = 50 L.","50 ÷ 10 = 5 — 10 L 통 5개."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L09_challenge#2','math',3,2,'u5','L09','g3_2_math_u5_L09_challenge','lesson_challenge','M3-2-u5-C10',2,'mc','auto','사료 50 kg을 5 kg, 4 kg, 2 kg 봉지(각각 6개)에 남김없이 나누어 담는 방법은 무엇인가요?',ARRAY['M3-2-u5-X18']::text[],true,'{"seq":2,"concept":"M3-2-u5-C10","difficulty":2,"kind":"mc","stem":"사료 50 kg을 5 kg, 4 kg, 2 kg 봉지(각각 6개)에 남김없이 나누어 담는 방법은 무엇인가요?","options":[{"t":"5 kg 봉지 6개, 4 kg 봉지 5개","correct":true},{"t":"5 kg 봉지 6개, 4 kg 봉지 7개","mis":"M3-2-u5-X18"},{"t":"5 kg 봉지 7개, 4 kg 봉지 4개, 2 kg 봉지 2개","mis":"M3-2-u5-X18"},{"t":"5 kg 봉지 5개, 4 kg 봉지 6개, 2 kg 봉지 2개","mis":"M3-2-u5-X18"}],"explanation":["보기마다 담은 양을 모두 더해 50 kg과 견주어요.","5 kg 봉지 6개, 4 kg 봉지 5개 → 30 + 20 = 50 kg.","남김없이 꼭 맞는 것은 이것뿐이에요."],"variant_rule":{"alt":[{"stem":"우유 60 L를 10 L, 6 L, 5 L 통(각각 5개)에 남김없이 나누어 담는 방법은 무엇인가요?","options":[{"t":"10 L 통 5개, 5 L 통 2개","correct":true},{"t":"10 L 통 5개, 6 L 통 2개, 5 L 통 4개","mis":"M3-2-u5-X18"},{"t":"10 L 통 6개, 6 L 통 2개, 5 L 통 1개","mis":"M3-2-u5-X18"},{"t":"10 L 통 4개, 5 L 통 1개","mis":"M3-2-u5-X18"}],"explanation":["보기마다 담은 양을 모두 더해 60 L와 견주어요.","10 L 통 5개, 5 L 통 2개 → 50 + 10 = 60 L.","남김없이 꼭 맞는 것은 이것뿐이에요."],"asset":null},{"stem":"우유 40 L를 10 L, 5 L, 2 L 통(각각 4개)에 남김없이 나누어 담는 방법은 무엇인가요?","options":[{"t":"10 L 통 4개","correct":true},{"t":"10 L 통 3개, 5 L 통 2개, 2 L 통 2개","mis":"M3-2-u5-X18"},{"t":"10 L 통 3개, 2 L 통 1개","mis":"M3-2-u5-X18"},{"t":"10 L 통 5개, 5 L 통 1개","mis":"M3-2-u5-X18"}],"explanation":["보기마다 담은 양을 모두 더해 40 L와 견주어요.","10 L 통 4개 → 40 = 40 L.","남김없이 꼭 맞는 것은 이것뿐이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L09_challenge#3','math',3,2,'u5','L09','g3_2_math_u5_L09_challenge','lesson_challenge','M3-2-u5-C10',3,'mc','auto','우유 60 L를 10 L, 6 L, 5 L 통(각각 6개)에 남김없이 담으려고 해요. 6 L 통은 몇 개 써야 하나요?',ARRAY['M3-2-u5-X18','M3-2-u5-X19']::text[],true,'{"seq":3,"concept":"M3-2-u5-C10","difficulty":3,"kind":"mc","stem":"우유 60 L를 10 L, 6 L, 5 L 통(각각 6개)에 남김없이 담으려고 해요. 6 L 통은 몇 개 써야 하나요?","options":[{"t":"쓰지 않거나 5개","correct":true},{"t":"1개나 2개","mis":"M3-2-u5-X18"},{"t":"3개나 4개","mis":"M3-2-u5-X18"},{"t":"6개 모두","mis":"M3-2-u5-X19"}],"explanation":["10 L 통과 5 L 통으로 담은 양은 끝자리가 0이나 5예요.","6 L 통 1개·2개·3개·4개 → 6, 12, 18, 24 L — 끝자리가 맞지 않아요.","6 L 통은 쓰지 않거나 5개 써야 해요."],"variant_rule":{"alt":[{"stem":"우유 90 L를 10 L, 8 L, 5 L 통(각각 7개)에 남김없이 담으려고 해요. 8 L 통은 몇 개 써야 하나요?","options":[{"t":"쓰지 않거나 5개","correct":true},{"t":"1개나 2개","mis":"M3-2-u5-X18"},{"t":"3개나 4개","mis":"M3-2-u5-X18"},{"t":"7개 모두","mis":"M3-2-u5-X19"}],"explanation":["10 L 통과 5 L 통으로 담은 양은 끝자리가 0이나 5예요.","8 L 통 1개·2개·3개·4개 → 8, 16, 24, 32 L — 끝자리가 맞지 않아요.","8 L 통은 쓰지 않거나 5개 써야 해요."],"asset":null},{"stem":"우유 70 L를 10 L, 8 L, 5 L 통(각각 6개)에 남김없이 담으려고 해요. 8 L 통은 몇 개 써야 하나요?","options":[{"t":"쓰지 않거나 5개","correct":true},{"t":"1개나 2개","mis":"M3-2-u5-X18"},{"t":"3개나 4개","mis":"M3-2-u5-X18"},{"t":"6개 모두","mis":"M3-2-u5-X19"}],"explanation":["10 L 통과 5 L 통으로 담은 양은 끝자리가 0이나 5예요.","8 L 통 1개·2개·3개·4개 → 8, 16, 24, 32 L — 끝자리가 맞지 않아요.","8 L 통은 쓰지 않거나 5개 써야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
