INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L09_challenge#5','math',3,2,'u5','L09','g3_2_math_u5_L09_challenge','lesson_challenge','M3-2-u5-C10',3,'mc','auto','사료 30 kg을 5 kg, 4 kg, 2 kg 봉지(각각 5개)에 남김없이 나누어 담는 방법은 무엇인가요?',ARRAY['M3-2-u5-X18']::text[],true,'{"seq":5,"concept":"M3-2-u5-C10","difficulty":3,"kind":"mc","stem":"사료 30 kg을 5 kg, 4 kg, 2 kg 봉지(각각 5개)에 남김없이 나누어 담는 방법은 무엇인가요?","options":[{"t":"5 kg 봉지 2개, 4 kg 봉지 5개","correct":true},{"t":"5 kg 봉지 4개, 4 kg 봉지 4개","mis":"M3-2-u5-X18"},{"t":"5 kg 봉지 4개, 4 kg 봉지 6개, 2 kg 봉지 2개","mis":"M3-2-u5-X18"},{"t":"5 kg 봉지 1개, 4 kg 봉지 6개, 2 kg 봉지 2개","mis":"M3-2-u5-X18"}],"explanation":["보기마다 담은 양을 모두 더해 30 kg과 견주어요.","5 kg 봉지 2개, 4 kg 봉지 5개 → 10 + 20 = 30 kg.","남김없이 꼭 맞는 것은 이것뿐이에요."],"variant_rule":{"alt":[{"stem":"우유 40 L를 10 L, 5 L, 2 L 통(각각 4개)에 남김없이 나누어 담는 방법은 무엇인가요?","options":[{"t":"10 L 통 2개, 5 L 통 4개","correct":true},{"t":"10 L 통 2개, 5 L 통 5개","mis":"M3-2-u5-X18"},{"t":"10 L 통 4개, 5 L 통 5개, 2 L 통 1개","mis":"M3-2-u5-X18"},{"t":"10 L 통 2개, 5 L 통 3개","mis":"M3-2-u5-X18"}],"explanation":["보기마다 담은 양을 모두 더해 40 L와 견주어요.","10 L 통 2개, 5 L 통 4개 → 20 + 20 = 40 L.","남김없이 꼭 맞는 것은 이것뿐이에요."],"asset":null},{"stem":"사료 50 kg을 5 kg, 4 kg, 2 kg 봉지(각각 6개)에 남김없이 나누어 담는 방법은 무엇인가요?","options":[{"t":"5 kg 봉지 4개, 4 kg 봉지 5개, 2 kg 봉지 5개","correct":true},{"t":"5 kg 봉지 5개, 4 kg 봉지 6개, 2 kg 봉지 6개","mis":"M3-2-u5-X18"},{"t":"5 kg 봉지 6개, 4 kg 봉지 4개, 2 kg 봉지 4개","mis":"M3-2-u5-X18"},{"t":"5 kg 봉지 3개, 4 kg 봉지 7개, 2 kg 봉지 7개","mis":"M3-2-u5-X18"}],"explanation":["보기마다 담은 양을 모두 더해 50 kg과 견주어요.","5 kg 봉지 4개, 4 kg 봉지 5개, 2 kg 봉지 5개 → 20 + 20 + 10 = 50 kg.","남김없이 꼭 맞는 것은 이것뿐이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes