INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L09_challenge#6','math',3,2,'u5','L09','g3_2_math_u5_L09_challenge','lesson_challenge','M3-2-u5-C10',3,'sa','auto','우유 90 L를 남김없이 나누어 담아요. 6 L 통 5개, 5 L 통 6개를 썼어요. 10 L 통은 몇 개 써야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u5-C10","difficulty":3,"kind":"sa","stem":"우유 90 L를 남김없이 나누어 담아요. 6 L 통 5개, 5 L 통 6개를 썼어요. 10 L 통은 몇 개 써야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["지금까지 담은 양: 60 L.","남은 양: 90 − 60 = 30 L.","30 ÷ 10 = 3 — 10 L 통 3개."],"variant_rule":{"alt":[{"stem":"우유 90 L를 남김없이 나누어 담아요. 10 L 통 5개, 5 L 통 2개를 썼어요. 6 L 통은 몇 개 써야 하나요? 숫자로 쓰세요.","answer":["5"],"explanation":["지금까지 담은 양: 60 L.","남은 양: 90 − 60 = 30 L.","30 ÷ 6 = 5 — 6 L 통 5개."],"asset":null},{"stem":"우유 90 L를 남김없이 나누어 담아요. 6 L 통 5개를 썼어요. 10 L 통은 몇 개 써야 하나요? 숫자로 쓰세요.","answer":["6"],"explanation":["지금까지 담은 양: 30 L.","남은 양: 90 − 30 = 60 L.","60 ÷ 10 = 6 — 10 L 통 6개."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L09_challenge#7','math',3,2,'u5','L09','g3_2_math_u5_L09_challenge','lesson_challenge','M3-2-u5-C10',3,'sa','auto','30 kg을 5 kg 봉지 6개, 3 kg 봉지 10개에 남김없이 나누어 담는 방법은 모두 몇 가지인가요? 쓰지 않는 봉지가 있어도 돼요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u5-C10","difficulty":3,"kind":"sa","stem":"30 kg을 5 kg 봉지 6개, 3 kg 봉지 10개에 남김없이 나누어 담는 방법은 모두 몇 가지인가요? 쓰지 않는 봉지가 있어도 돼요. 숫자로 쓰세요.","answer":["3"],"explanation":["표로 큰 봉지부터 개수를 하나씩 바꾸어 봐요.","합이 30 kg인 것만 세어요.","모두 3가지예요."],"variant_rule":{"alt":[{"stem":"30 L를 10 L 통 3개, 5 L 통 6개에 남김없이 나누어 담는 방법은 모두 몇 가지인가요? 쓰지 않는 통이 있어도 돼요. 숫자로 쓰세요.","answer":["4"],"explanation":["표로 큰 통부터 개수를 하나씩 바꾸어 봐요.","합이 30 L인 것만 세어요.","모두 4가지예요."],"asset":null},{"stem":"24 kg을 6 kg 봉지 4개, 4 kg 봉지 6개에 남김없이 나누어 담는 방법은 모두 몇 가지인가요? 쓰지 않는 봉지가 있어도 돼요. 숫자로 쓰세요.","answer":["3"],"explanation":["표로 큰 봉지부터 개수를 하나씩 바꾸어 봐요.","합이 24 kg인 것만 세어요.","모두 3가지예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L09_challenge#8','math',3,2,'u5','L09','g3_2_math_u5_L09_challenge','lesson_challenge','M3-2-u5-C10',4,'essay','teacher','초록 목장에서 우유 90 L를 짰어요. 10 L, 6 L, 5 L 통이 각각 7개씩 있어요. 6 L 통을 꼭 써서 우유를 남김없이 담는 방법을 한 가지 쓰고, 6 L 통을 몇 개 써야 하는지 일의 자리를 이용해 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u5-C10","difficulty":4,"kind":"essay","stem":"초록 목장에서 우유 90 L를 짰어요. 10 L, 6 L, 5 L 통이 각각 7개씩 있어요. 6 L 통을 꼭 써서 우유를 남김없이 담는 방법을 한 가지 쓰고, 6 L 통을 몇 개 써야 하는지 일의 자리를 이용해 설명해 보세요.","answer_guide":{"answer":"예: 10 L 통과 5 L 통으로 담은 양은 끝자리가 0이나 5이다. 90의 끝자리는 0이므로 6 L 통으로 담은 양의 끝자리도 0이나 5여야 한다. 6, 12, 18, 24는 맞지 않고 6 × 5 = 30이 맞으므로 6 L 통은 5개 쓴다. 예를 들어 10 L 통 6개(60 L)와 6 L 통 5개(30 L)로 60 + 30 = 90 L를 담는다.","scoring_points":["6 L 통 5개를 찾았는가","일의 자리(끝자리)로 까닭을 설명했는가","모두 더해 90 L가 되는 방법을 썼는가"]},"explanation":["10 L·5 L 통 → 끝자리 0이나 5.","6 × 5 = 30 L.","60 + 30 = 90 L."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L09_challenge#9','math',3,2,'u5','L09','g3_2_math_u5_L09_challenge','lesson_challenge','M3-2-u5-C10',4,'essay','teacher','강아지 사료 50 kg을 5 kg, 4 kg, 2 kg 봉지(각각 6개)에 남김없이 나누어 담으려고 해요. 서로 다른 방법을 두 가지 찾고, 맞는지 확인하는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u5-C10","difficulty":4,"kind":"essay","stem":"강아지 사료 50 kg을 5 kg, 4 kg, 2 kg 봉지(각각 6개)에 남김없이 나누어 담으려고 해요. 서로 다른 방법을 두 가지 찾고, 맞는지 확인하는 방법을 설명해 보세요.","answer_guide":{"answer":"예: ① 5 kg 봉지 4개, 4 kg 봉지 5개, 2 kg 봉지 5개 → 20 + 20 + 10 = 50 kg. ② 5 kg 봉지 6개, 4 kg 봉지 5개 → 30 + 20 = 50 kg. 봉지마다 담은 양을 곱해 모두 더한 값이 50 kg인지, 쓴 봉지가 6개를 넘지 않는지 확인한다.","scoring_points":["합이 50 kg인 방법을 하나 찾았는가","서로 다른 방법을 하나 더 찾았는가","모두 더해 확인하고 봉지 수(6개 이하)를 살폈는가"]},"explanation":["봉지 수 × 봉지 하나의 양.","모두 더해 50 kg인지 확인.","봉지는 6개를 넘지 않게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_L09_challenge#10','math',3,2,'u5','L09','g3_2_math_u5_L09_challenge','lesson_challenge','M3-2-u5-C10',4,'sa','auto','50 L를 10 L 통 5개, 5 L 통 10개에 남김없이 나누어 담는 방법은 모두 몇 가지인가요? 쓰지 않는 통이 있어도 돼요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-2-u5-C10","difficulty":4,"kind":"sa","stem":"50 L를 10 L 통 5개, 5 L 통 10개에 남김없이 나누어 담는 방법은 모두 몇 가지인가요? 쓰지 않는 통이 있어도 돼요. 숫자로 쓰세요.","answer":["6"],"explanation":["표로 큰 통부터 개수를 하나씩 바꾸어 봐요.","합이 50 L인 것만 세어요.","모두 6가지예요."],"variant_rule":{"alt":[{"stem":"20 kg을 5 kg 봉지 4개, 2 kg 봉지 10개에 남김없이 나누어 담는 방법은 모두 몇 가지인가요? 쓰지 않는 봉지가 있어도 돼요. 숫자로 쓰세요.","answer":["3"],"explanation":["표로 큰 봉지부터 개수를 하나씩 바꾸어 봐요.","합이 20 kg인 것만 세어요.","모두 3가지예요."],"asset":null},{"stem":"40 L를 10 L 통 4개, 5 L 통 8개에 남김없이 나누어 담는 방법은 모두 몇 가지인가요? 쓰지 않는 통이 있어도 돼요. 숫자로 쓰세요.","answer":["5"],"explanation":["표로 큰 통부터 개수를 하나씩 바꾸어 봐요.","합이 40 L인 것만 세어요.","모두 5가지예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_a#1','math',3,2,'u5','','g3_2_math_u5_review_a','unit_review','M3-2-u5-C1',1,'mc','auto','㉯ 컵에 물을 가득 채워 ㉮ 컵에 옮겨 담았더니 가득 차지 않았어요. 들이가 더 많은 것은 무엇인가요?',ARRAY['M3-2-u5-X02','M3-2-u5-X21']::text[],true,'{"seq":1,"concept":"M3-2-u5-C1","difficulty":1,"kind":"mc","stem":"㉯ 컵에 물을 가득 채워 ㉮ 컵에 옮겨 담았더니 가득 차지 않았어요. 들이가 더 많은 것은 무엇인가요?","options":[{"t":"㉮ 컵","correct":true},{"t":"㉯ 컵","mis":"M3-2-u5-X02"},{"t":"두 그릇의 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["㉯ 컵에 가득 담은 물을 ㉮ 컵에 부었어요.","가득 차지 않았어요 — ㉮ 컵에 빈 곳이 남았으니 ㉮ 컵의 들이가 더 많아요.","들이가 더 많은 것은 ㉮ 컵이에요."],"asset":{"type":"cups","items":[{"label":"㉮ 컵","w":2,"h":5},{"label":"㉯ 컵","w":2,"h":4}],"pour":{"from":1,"to":0}},"variant_rule":{"alt":[{"stem":"유리컵에 물을 가득 채워 머그잔에 옮겨 담았더니 가득 차지 않았어요. 들이가 더 적은 것은 무엇인가요?","options":[{"t":"유리컵","correct":true},{"t":"머그잔","mis":"M3-2-u5-X20"},{"t":"두 그릇의 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["유리컵에 가득 담은 물을 머그잔에 부었어요.","가득 차지 않았어요 — 머그잔에 빈 곳이 남았으니 머그잔의 들이가 더 많아요.","들이가 더 적은 것은 유리컵이에요."],"asset":{"type":"cups","items":[{"label":"머그잔","w":4,"h":4},{"label":"유리컵","w":3,"h":3}],"pour":{"from":1,"to":0}}},{"stem":"우유갑에 물을 가득 채워 주스병에 옮겨 담았더니 가득 차지 않았어요. 들이가 더 많은 것은 무엇인가요?","options":[{"t":"주스병","correct":true},{"t":"우유갑","mis":"M3-2-u5-X02"},{"t":"두 그릇의 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["우유갑에 가득 담은 물을 주스병에 부었어요.","가득 차지 않았어요 — 주스병에 빈 곳이 남았으니 주스병의 들이가 더 많아요.","들이가 더 많은 것은 주스병이에요."],"asset":{"type":"cups","items":[{"label":"우유갑","w":3,"h":5},{"label":"주스병","w":4,"h":6}],"pour":{"from":0,"to":1}}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_a#2','math',3,2,'u5','','g3_2_math_u5_review_a','unit_review','M3-2-u5-C2',1,'sa','auto','8 L 20 mL는 몇 mL인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u5-C2","difficulty":1,"kind":"sa","stem":"8 L 20 mL는 몇 mL인가요? 숫자로 쓰세요.","answer":["8020"],"explanation":["1 L = 1000 mL — 8 L = 8000 mL.","8000 mL + 20 mL = 8020 mL.","8 L 20 mL = 8020 mL."],"variant_rule":{"alt":[{"stem":"8 L 40 mL는 몇 mL인가요? 숫자로 쓰세요.","answer":["8040"],"explanation":["1 L = 1000 mL — 8 L = 8000 mL.","8000 mL + 40 mL = 8040 mL.","8 L 40 mL = 8040 mL."],"asset":null},{"stem":"7 L 450 mL는 몇 mL인가요? 숫자로 쓰세요.","answer":["7450"],"explanation":["1 L = 1000 mL — 7 L = 7000 mL.","7000 mL + 450 mL = 7450 mL.","7 L 450 mL = 7450 mL."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_a#3','math',3,2,'u5','','g3_2_math_u5_review_a','unit_review','M3-2-u5-C3',1,'sa','auto','비커의 큰 눈금 0과 500 mL 사이가 똑같이 10칸으로 나뉘어 있어요. 양치 컵의 물을 재었더니 물이 0에서부터 9칸째 눈금까지 올라와 있어요. 몇 mL인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u5-C3","difficulty":1,"kind":"sa","stem":"비커의 큰 눈금 0과 500 mL 사이가 똑같이 10칸으로 나뉘어 있어요. 양치 컵의 물을 재었더니 물이 0에서부터 9칸째 눈금까지 올라와 있어요. 몇 mL인가요? 숫자로 쓰세요.","answer":["450"],"explanation":["한 칸의 크기부터: 500 ÷ 10 = 50 mL.","9칸 → 50 × 9 = 450.","450 mL예요."],"variant_rule":{"alt":[{"stem":"비커의 큰 눈금 0과 1000 mL 사이가 똑같이 4칸으로 나뉘어 있어요. 다회용 컵의 물을 재었더니 물이 0에서부터 2칸째 눈금까지 올라와 있어요. 몇 mL인가요? 숫자로 쓰세요.","answer":["500"],"explanation":["한 칸의 크기부터: 1000 ÷ 4 = 250 mL.","2칸 → 250 × 2 = 500.","500 mL예요."],"asset":null},{"stem":"비커의 큰 눈금 0과 1000 mL 사이가 똑같이 5칸으로 나뉘어 있어요. 세제를 재었더니 물이 0에서부터 4칸째 눈금까지 올라와 있어요. 몇 mL인가요? 숫자로 쓰세요.","answer":["800"],"explanation":["한 칸의 크기부터: 1000 ÷ 5 = 200 mL.","4칸 → 200 × 4 = 800.","800 mL예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_a#4','math',3,2,'u5','','g3_2_math_u5_review_a','unit_review','M3-2-u5-C4',1,'sa','auto','2 L 600 mL + 2 L 200 mL = □ L 800 mL에서 □ 안에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u5-C4","difficulty":1,"kind":"sa","stem":"2 L 600 mL + 2 L 200 mL = □ L 800 mL에서 □ 안에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["mL끼리: 600 + 200 = 800.","L끼리: 2 + 2 = 4.","2 L 600 mL + 2 L 200 mL = 4 L 800 mL."],"variant_rule":{"alt":[{"stem":"2 L 460 mL + 4 L 440 mL = 6 L □ mL에서 □ 안에 알맞은 수를 쓰세요.","answer":["900"],"explanation":["mL끼리: 460 + 440 = 900.","L끼리: 2 + 4 = 6.","2 L 460 mL + 4 L 440 mL = 6 L 900 mL."],"asset":null},{"stem":"5 L 200 mL + 2 L 550 mL = □ L 750 mL에서 □ 안에 알맞은 수를 쓰세요.","answer":["7"],"explanation":["mL끼리: 200 + 550 = 750.","L끼리: 5 + 2 = 7.","5 L 200 mL + 2 L 550 mL = 7 L 750 mL."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_a#5','math',3,2,'u5','','g3_2_math_u5_review_a','unit_review','M3-2-u5-C5',1,'mc','auto','양팔저울에 귤과 사과를 올렸어요. 더 무거운 것은 무엇인가요?',ARRAY['M3-2-u5-X15','M3-2-u5-X21']::text[],true,'{"seq":5,"concept":"M3-2-u5-C5","difficulty":1,"kind":"mc","stem":"양팔저울에 귤과 사과를 올렸어요. 더 무거운 것은 무엇인가요?","options":[{"t":"사과","correct":true},{"t":"귤","mis":"M3-2-u5-X15"},{"t":"두 물건의 무게가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["양팔저울은 더 무거운 쪽이 아래로 내려가요.","사과 쪽이 내려갔어요 — 사과가 더 무거워요.","더 무거운 것은 사과예요."],"asset":{"type":"balance","scales":[{"l":{"name":"귤","icon":"🍊"},"r":{"name":"사과","icon":"🍎"},"down":"r"}]},"variant_rule":{"alt":[{"stem":"양팔저울에 필통과 지우개를 올렸어요. 더 무거운 것은 무엇인가요?","options":[{"t":"필통","correct":true},{"t":"지우개","mis":"M3-2-u5-X15"},{"t":"두 물건의 무게가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["양팔저울은 더 무거운 쪽이 아래로 내려가요.","필통 쪽이 내려갔어요 — 필통이 더 무거워요.","더 무거운 것은 필통이에요."],"asset":{"type":"balance","scales":[{"l":{"name":"필통","icon":"✏️"},"r":{"name":"지우개","icon":"🧽"},"down":"l"}]}},{"stem":"양팔저울에 고구마와 당근을 올렸어요. 더 무거운 것은 무엇인가요?","options":[{"t":"고구마","correct":true},{"t":"당근","mis":"M3-2-u5-X15"},{"t":"두 물건의 무게가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["양팔저울은 더 무거운 쪽이 아래로 내려가요.","고구마 쪽이 내려갔어요 — 고구마가 더 무거워요.","더 무거운 것은 고구마예요."],"asset":{"type":"balance","scales":[{"l":{"name":"고구마","icon":"🍠"},"r":{"name":"당근","icon":"🥕"},"down":"l"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_a#6','math',3,2,'u5','','g3_2_math_u5_review_a','unit_review','M3-2-u5-C6',1,'sa','auto','8 kg 700 g은 몇 g인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u5-C6","difficulty":1,"kind":"sa","stem":"8 kg 700 g은 몇 g인가요? 숫자로 쓰세요.","answer":["8700"],"explanation":["1 kg = 1000 g — 8 kg = 8000 g.","8000 g + 700 g = 8700 g.","8 kg 700 g = 8700 g."],"variant_rule":{"alt":[{"stem":"6 kg 600 g은 몇 g인가요? 숫자로 쓰세요.","answer":["6600"],"explanation":["1 kg = 1000 g — 6 kg = 6000 g.","6000 g + 600 g = 6600 g.","6 kg 600 g = 6600 g."],"asset":null},{"stem":"5 kg 80 g은 몇 g인가요? 숫자로 쓰세요.","answer":["5080"],"explanation":["1 kg = 1000 g — 5 kg = 5000 g.","5000 g + 80 g = 5080 g.","5 kg 80 g = 5080 g."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_a#7','math',3,2,'u5','','g3_2_math_u5_review_a','unit_review','M3-2-u5-C7',1,'sa','auto','4 t은 몇 kg인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u5-C7","difficulty":1,"kind":"sa","stem":"4 t은 몇 kg인가요? 숫자로 쓰세요.","answer":["4000"],"explanation":["1 t = 1000 kg이에요.","4 t = 1000 kg이 4번.","4 t = 4000 kg."],"variant_rule":{"alt":[{"stem":"3 t은 몇 kg인가요? 숫자로 쓰세요.","answer":["3000"],"explanation":["1 t = 1000 kg이에요.","3 t = 1000 kg이 3번.","3 t = 3000 kg."],"asset":null},{"stem":"8 t은 몇 kg인가요? 숫자로 쓰세요.","answer":["8000"],"explanation":["1 t = 1000 kg이에요.","8 t = 1000 kg이 8번.","8 t = 8000 kg."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_a#8','math',3,2,'u5','','g3_2_math_u5_review_a','unit_review','M3-2-u5-C8',1,'mc','auto','판다의 무게는 약 130 ○예요. ○에 알맞은 단위는 무엇인가요?',ARRAY['M3-2-u5-X09','M3-2-u5-X10']::text[],true,'{"seq":8,"concept":"M3-2-u5-C8","difficulty":1,"kind":"mc","stem":"판다의 무게는 약 130 ○예요. ○에 알맞은 단위는 무엇인가요?","options":[{"t":"kg","correct":true},{"t":"g","mis":"M3-2-u5-X09"},{"t":"t","mis":"M3-2-u5-X09"},{"t":"mL","mis":"M3-2-u5-X10"}],"explanation":["판다를 아는 무게와 견주어 봐요.","무게에 쓰는 단위는 g·kg·t.","판다의 무게는 약 130 kg이에요."],"variant_rule":{"alt":[{"stem":"김치 반 포기의 무게는 약 500 ○예요. ○에 알맞은 단위는 무엇인가요?","options":[{"t":"g","correct":true},{"t":"kg","mis":"M3-2-u5-X09"},{"t":"t","mis":"M3-2-u5-X09"},{"t":"mL","mis":"M3-2-u5-X10"}],"explanation":["김치 반 포기를 아는 무게와 견주어 봐요.","무게에 쓰는 단위는 g·kg·t.","김치 반 포기의 무게는 약 500 g이에요."],"asset":null},{"stem":"수박 1통의 무게는 약 5 ○예요. ○에 알맞은 단위는 무엇인가요?","options":[{"t":"kg","correct":true},{"t":"g","mis":"M3-2-u5-X09"},{"t":"t","mis":"M3-2-u5-X09"},{"t":"mL","mis":"M3-2-u5-X10"}],"explanation":["수박 1통을 아는 무게와 견주어 봐요.","무게에 쓰는 단위는 g·kg·t.","수박 1통의 무게는 약 5 kg이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_a#9','math',3,2,'u5','','g3_2_math_u5_review_a','unit_review','M3-2-u5-C2',2,'mc','auto','㉮는 2 L 250 mL, ㉯는 2850 mL예요. 들이가 더 많은 것은 무엇인가요?',ARRAY['M3-2-u5-X20','M3-2-u5-X21']::text[],true,'{"seq":9,"concept":"M3-2-u5-C2","difficulty":2,"kind":"mc","stem":"㉮는 2 L 250 mL, ㉯는 2850 mL예요. 들이가 더 많은 것은 무엇인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M3-2-u5-X20"},{"t":"두 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"단위가 달라서 견줄 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["한 가지 단위로 바꾸어 견주어요.","2 L 250 mL = 2250 mL.","2250 mL < 2850 mL — 들이가 더 많은 것은 ㉯예요."],"variant_rule":{"alt":[{"stem":"㉮는 5 L 50 mL, ㉯는 5140 mL예요. 들이가 더 많은 것은 무엇인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M3-2-u5-X20"},{"t":"두 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"단위가 달라서 견줄 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["한 가지 단위로 바꾸어 견주어요.","5 L 50 mL = 5050 mL.","5050 mL < 5140 mL — 들이가 더 많은 것은 ㉯예요."],"asset":null},{"stem":"㉮는 6 L 650 mL, ㉯는 6690 mL예요. 들이가 더 많은 것은 무엇인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M3-2-u5-X20"},{"t":"두 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"단위가 달라서 견줄 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["한 가지 단위로 바꾸어 견주어요.","6 L 650 mL = 6650 mL.","6650 mL < 6690 mL — 들이가 더 많은 것은 ㉯예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_a#10','math',3,2,'u5','','g3_2_math_u5_review_a','unit_review','M3-2-u5-C3',2,'mc','auto','주스병의 들이를 어림했어요 — 지아 약 700 mL, 준우 약 800 mL, 은비 약 550 mL. 재어 보니 850 mL였어요. 가장 가깝게 어림한 친구는 누구인가요?',ARRAY['M3-2-u5-X08','M3-2-u5-X21']::text[],true,'{"seq":10,"concept":"M3-2-u5-C3","difficulty":2,"kind":"mc","stem":"주스병의 들이를 어림했어요 — 지아 약 700 mL, 준우 약 800 mL, 은비 약 550 mL. 재어 보니 850 mL였어요. 가장 가깝게 어림한 친구는 누구인가요?","options":[{"t":"준우","correct":true},{"t":"지아","mis":"M3-2-u5-X08"},{"t":"은비","mis":"M3-2-u5-X08"},{"t":"모두 똑같이 알맞아요","mis":"M3-2-u5-X21"}],"explanation":["잰 값 850 mL와 어림한 값의 차를 견주어요.","지아 150 mL, 준우 50 mL, 은비 300 mL 차이.","차가 가장 작은 준우가 가장 가깝게 어림했어요."],"variant_rule":{"alt":[{"stem":"주스병의 들이를 어림했어요 — 준우 약 800 mL, 은비 약 450 mL, 도윤 약 1 L 250 mL. 재어 보니 950 mL였어요. 가장 가깝게 어림한 친구는 누구인가요?","options":[{"t":"준우","correct":true},{"t":"은비","mis":"M3-2-u5-X08"},{"t":"도윤","mis":"M3-2-u5-X08"},{"t":"모두 똑같이 알맞아요","mis":"M3-2-u5-X21"}],"explanation":["잰 값 950 mL와 어림한 값의 차를 견주어요.","준우 150 mL, 은비 500 mL, 도윤 300 mL 차이.","차가 가장 작은 준우가 가장 가깝게 어림했어요."],"asset":null},{"stem":"세제 통의 들이를 어림했어요 — 정후 약 2 L, 지아 약 1 L 800 mL, 은비 약 1 L 550 mL. 재어 보니 1 L 500 mL였어요. 가장 가깝게 어림한 친구는 누구인가요?","options":[{"t":"은비","correct":true},{"t":"정후","mis":"M3-2-u5-X08"},{"t":"지아","mis":"M3-2-u5-X08"},{"t":"모두 똑같이 알맞아요","mis":"M3-2-u5-X21"}],"explanation":["잰 값 1 L 500 mL와 어림한 값의 차를 견주어요.","정후 500 mL, 지아 300 mL, 은비 50 mL 차이.","차가 가장 작은 은비가 가장 가깝게 어림했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_a#11','math',3,2,'u5','','g3_2_math_u5_review_a','unit_review','M3-2-u5-C4',2,'mc','auto','세제 8 L 970 mL 중에서 빨래에 2 L 70 mL를 썼어요. 남은 세제는 얼마인가요?',ARRAY['M3-2-u5-X13','M3-2-u5-X14']::text[],true,'{"seq":11,"concept":"M3-2-u5-C4","difficulty":2,"kind":"mc","stem":"세제 8 L 970 mL 중에서 빨래에 2 L 70 mL를 썼어요. 남은 세제는 얼마인가요?","options":[{"t":"6 L 900 mL","correct":true},{"t":"7 L 900 mL","mis":"M3-2-u5-X13"},{"t":"5 L 900 mL","mis":"M3-2-u5-X13"},{"t":"11 L 40 mL","mis":"M3-2-u5-X14"}],"explanation":["mL끼리: 970 − 70 = 900.","L끼리: 8 − 2 = 6.","8 L 970 mL − 2 L 70 mL = 6 L 900 mL."],"variant_rule":{"alt":[{"stem":"주전자에 물이 4 L 500 mL 있었는데 1 L 200 mL를 썼어요. 남은 물은 얼마인가요?","options":[{"t":"3 L 300 mL","correct":true},{"t":"4 L 300 mL","mis":"M3-2-u5-X13"},{"t":"2 L 300 mL","mis":"M3-2-u5-X13"},{"t":"5 L 700 mL","mis":"M3-2-u5-X14"}],"explanation":["mL끼리: 500 − 200 = 300.","L끼리: 4 − 1 = 3.","4 L 500 mL − 1 L 200 mL = 3 L 300 mL."],"asset":null},{"stem":"우유 4 L 710 mL 중에서 2 L 20 mL를 마셨어요. 남은 우유는 얼마인가요?","options":[{"t":"2 L 690 mL","correct":true},{"t":"3 L 690 mL","mis":"M3-2-u5-X13"},{"t":"1 L 690 mL","mis":"M3-2-u5-X13"},{"t":"6 L 730 mL","mis":"M3-2-u5-X14"}],"explanation":["mL끼리: 710 − 20 = 690.","L끼리: 4 − 2 = 2.","4 L 710 mL − 2 L 20 mL = 2 L 690 mL."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_a#12','math',3,2,'u5','','g3_2_math_u5_review_a','unit_review','M3-2-u5-C5',2,'sa','auto','우유갑의 무게는 클립 20개, 페트병의 무게는 클립 10개와 같아요. 우유갑은 페트병보다 클립 몇 개만큼 더 무거운가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M3-2-u5-C5","difficulty":2,"kind":"sa","stem":"우유갑의 무게는 클립 20개, 페트병의 무게는 클립 10개와 같아요. 우유갑은 페트병보다 클립 몇 개만큼 더 무거운가요? 숫자로 쓰세요.","answer":["10"],"explanation":["같은 클립으로 재었으니 개수로 견줄 수 있어요.","우유갑 20개, 페트병 10개.","20 − 10 = 10 — 클립 10개만큼 더 무거워요."],"variant_rule":{"alt":[{"stem":"우유갑의 무게는 쌓기나무 20개, 페트병의 무게는 쌓기나무 8개와 같아요. 우유갑은 페트병보다 쌓기나무 몇 개만큼 더 무거운가요? 숫자로 쓰세요.","answer":["12"],"explanation":["같은 쌓기나무로 재었으니 개수로 견줄 수 있어요.","우유갑 20개, 페트병 8개.","20 − 8 = 12 — 쌓기나무 12개만큼 더 무거워요."],"asset":null},{"stem":"사과의 무게는 공깃돌 8개, 배의 무게는 공깃돌 29개와 같아요. 배는 사과보다 공깃돌 몇 개만큼 더 무거운가요? 숫자로 쓰세요.","answer":["21"],"explanation":["같은 공깃돌으로 재었으니 개수로 견줄 수 있어요.","사과 8개, 배 29개.","29 − 8 = 21 — 공깃돌 21개만큼 더 무거워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_a#13','math',3,2,'u5','','g3_2_math_u5_review_a','unit_review','M3-2-u5-C6',2,'mc','auto','하윤이 모은 재활용품은 4 kg 60 g, 정후가 모은 재활용품은 4600 g이에요. 누가 더 무겁게 모았나요?',ARRAY['M3-2-u5-X05','M3-2-u5-X21']::text[],true,'{"seq":13,"concept":"M3-2-u5-C6","difficulty":2,"kind":"mc","stem":"하윤이 모은 재활용품은 4 kg 60 g, 정후가 모은 재활용품은 4600 g이에요. 누가 더 무겁게 모았나요?","options":[{"t":"정후","correct":true},{"t":"하윤","mis":"M3-2-u5-X05"},{"t":"두 사람이 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["한 가지 단위로 바꾸어 견주어요.","4 kg 60 g = 4060 g.","4060 g < 4600 g — 정후가 더 무겁게 모았어요."],"variant_rule":{"alt":[{"stem":"소율이 모은 재활용품은 3 kg 60 g, 하윤이 모은 재활용품은 3600 g이에요. 누가 더 무겁게 모았나요?","options":[{"t":"하윤","correct":true},{"t":"소율","mis":"M3-2-u5-X05"},{"t":"두 사람이 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["한 가지 단위로 바꾸어 견주어요.","3 kg 60 g = 3060 g.","3060 g < 3600 g — 하윤이 더 무겁게 모았어요."],"asset":null},{"stem":"준우가 모은 재활용품은 3 kg 70 g, 지아가 모은 재활용품은 3700 g이에요. 누가 더 무겁게 모았나요?","options":[{"t":"지아","correct":true},{"t":"준우","mis":"M3-2-u5-X05"},{"t":"두 사람이 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["한 가지 단위로 바꾸어 견주어요.","3 kg 70 g = 3070 g.","3070 g < 3700 g — 지아가 더 무겁게 모았어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_a#14','math',3,2,'u5','','g3_2_math_u5_review_a','unit_review','M3-2-u5-C7',2,'mc','auto','잘못 나타낸 것은 무엇인가요?',ARRAY['M3-2-u5-X21']::text[],true,'{"seq":14,"concept":"M3-2-u5-C7","difficulty":2,"kind":"mc","stem":"잘못 나타낸 것은 무엇인가요?","options":[{"t":"9 t은 900 kg이에요","correct":true},{"t":"6 t은 6000 kg이에요","mis":"M3-2-u5-X21"},{"t":"9940 g은 9 kg 940 g이에요","mis":"M3-2-u5-X21"},{"t":"1 t은 1000 kg이에요","mis":"M3-2-u5-X21"}],"explanation":["1 t = 1000 kg, 1 kg = 1000 g.","9 t = 9000 kg이에요.","「9 t은 900 kg이에요」 — 1 t을 100 kg으로 본 잘못이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 잘못 나타낸 것은 무엇인가요?","options":[{"t":"9 t은 900 kg이에요","correct":true},{"t":"5 t은 5000 kg이에요","mis":"M3-2-u5-X21"},{"t":"5230 g은 5 kg 230 g이에요","mis":"M3-2-u5-X21"},{"t":"1 t은 1000 kg이에요","mis":"M3-2-u5-X21"}],"explanation":["1 t = 1000 kg, 1 kg = 1000 g.","9 t = 9000 kg이에요.","「9 t은 900 kg이에요」 — 1 t을 100 kg으로 본 잘못이에요."],"asset":null},{"stem":"이번에는 다른 문제예요. 잘못 나타낸 것은 무엇인가요?","options":[{"t":"3 t은 300 kg이에요","correct":true},{"t":"4 t은 4000 kg이에요","mis":"M3-2-u5-X21"},{"t":"4140 g은 4 kg 140 g이에요","mis":"M3-2-u5-X21"},{"t":"1 t은 1000 kg이에요","mis":"M3-2-u5-X21"}],"explanation":["1 t = 1000 kg, 1 kg = 1000 g.","3 t = 3000 kg이에요.","「3 t은 300 kg이에요」 — 1 t을 100 kg으로 본 잘못이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_a#15','math',3,2,'u5','','g3_2_math_u5_review_a','unit_review','M3-2-u5-C9',2,'mc','auto','여행 가방이 5 kg 100 g이에요. 4 kg 700 g의 짐을 더 넣으면 모두 얼마인가요?',ARRAY['M3-2-u5-X12','M3-2-u5-X14']::text[],true,'{"seq":15,"concept":"M3-2-u5-C9","difficulty":2,"kind":"mc","stem":"여행 가방이 5 kg 100 g이에요. 4 kg 700 g의 짐을 더 넣으면 모두 얼마인가요?","options":[{"t":"9 kg 800 g","correct":true},{"t":"10 kg 800 g","mis":"M3-2-u5-X12"},{"t":"400 g","mis":"M3-2-u5-X14"},{"t":"8 kg 800 g","mis":"M3-2-u5-X12"}],"explanation":["g끼리: 100 + 700 = 800.","kg끼리: 5 + 4 = 9.","5 kg 100 g + 4 kg 700 g = 9 kg 800 g."],"variant_rule":{"alt":[{"stem":"준우는 4 kg 130 g, 소율이는 4 kg 800 g의 재활용품을 모았어요. 두 사람이 모은 재활용품은 모두 얼마인가요?","options":[{"t":"8 kg 930 g","correct":true},{"t":"9 kg 930 g","mis":"M3-2-u5-X12"},{"t":"670 g","mis":"M3-2-u5-X14"},{"t":"7 kg 930 g","mis":"M3-2-u5-X12"}],"explanation":["g끼리: 130 + 800 = 930.","kg끼리: 4 + 4 = 8.","4 kg 130 g + 4 kg 800 g = 8 kg 930 g."],"asset":null},{"stem":"상자에 사과 3 kg 400 g과 배 2 kg 500 g을 담았어요. 과일은 모두 얼마인가요?","options":[{"t":"5 kg 900 g","correct":true},{"t":"6 kg 900 g","mis":"M3-2-u5-X12"},{"t":"900 g","mis":"M3-2-u5-X14"},{"t":"4 kg 900 g","mis":"M3-2-u5-X12"}],"explanation":["g끼리: 400 + 500 = 900.","kg끼리: 3 + 2 = 5.","3 kg 400 g + 2 kg 500 g = 5 kg 900 g."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_a#16','math',3,2,'u5','','g3_2_math_u5_review_a','unit_review','M3-2-u5-C10',2,'sa','auto','우유 90 L를 남김없이 나누어 담아요. 5 L 통 4개를 썼어요. 10 L 통은 몇 개 써야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M3-2-u5-C10","difficulty":2,"kind":"sa","stem":"우유 90 L를 남김없이 나누어 담아요. 5 L 통 4개를 썼어요. 10 L 통은 몇 개 써야 하나요? 숫자로 쓰세요.","answer":["7"],"explanation":["지금까지 담은 양: 20 L.","남은 양: 90 − 20 = 70 L.","70 ÷ 10 = 7 — 10 L 통 7개."],"variant_rule":{"alt":[{"stem":"사료 50 kg을 남김없이 나누어 담아요. 5 kg 봉지 4개, 2 kg 봉지 3개를 썼어요. 4 kg 봉지는 몇 개 써야 하나요? 숫자로 쓰세요.","answer":["6"],"explanation":["지금까지 담은 양: 26 kg.","남은 양: 50 − 26 = 24 kg.","24 ÷ 4 = 6 — 4 kg 봉지 6개."],"asset":null},{"stem":"사료 50 kg을 남김없이 나누어 담아요. 5 kg 봉지 6개를 썼어요. 4 kg 봉지는 몇 개 써야 하나요? 숫자로 쓰세요.","answer":["5"],"explanation":["지금까지 담은 양: 30 kg.","남은 양: 50 − 30 = 20 kg.","20 ÷ 4 = 5 — 4 kg 봉지 5개."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_a#17','math',3,2,'u5','','g3_2_math_u5_review_a','unit_review','M3-2-u5-C1',3,'mc','auto','㉮ 물통은 큰 컵으로 6번, ㉯ 물통은 작은 컵으로 7번 부어 가득 채웠어요. 이것만 보고 들이를 바르게 말한 것은 무엇인가요?',ARRAY['M3-2-u5-X03','M3-2-u5-X21']::text[],true,'{"seq":17,"concept":"M3-2-u5-C1","difficulty":3,"kind":"mc","stem":"㉮ 물통은 큰 컵으로 6번, ㉯ 물통은 작은 컵으로 7번 부어 가득 채웠어요. 이것만 보고 들이를 바르게 말한 것은 무엇인가요?","options":[{"t":"재는 컵이 달라서 알 수 없어요","correct":true},{"t":"㉯ 물통의 들이가 더 많아요","mis":"M3-2-u5-X03"},{"t":"㉮ 물통의 들이가 더 많아요","mis":"M3-2-u5-X03"},{"t":"두 물통의 들이가 같아요","mis":"M3-2-u5-X21"}],"explanation":["㉮는 큰 컵, ㉯는 작은 컵 — 재는 그릇이 달라요.","횟수만으로는 들이를 견줄 수 없어요.","같은 컵(같은 단위)으로 재야 견줄 수 있어요."],"variant_rule":{"alt":[{"stem":"㉮ 물통은 큰 컵으로 3번, ㉯ 물통은 작은 컵으로 4번 부어 가득 채웠어요. 이것만 보고 들이를 바르게 말한 것은 무엇인가요?","options":[{"t":"재는 컵이 달라서 알 수 없어요","correct":true},{"t":"㉯ 물통의 들이가 더 많아요","mis":"M3-2-u5-X03"},{"t":"㉮ 물통의 들이가 더 많아요","mis":"M3-2-u5-X03"},{"t":"두 물통의 들이가 같아요","mis":"M3-2-u5-X21"}],"explanation":["㉮는 큰 컵, ㉯는 작은 컵 — 재는 그릇이 달라요.","횟수만으로는 들이를 견줄 수 없어요.","같은 컵(같은 단위)으로 재야 견줄 수 있어요."],"asset":null},{"stem":"㉮ 물통은 큰 컵으로 4번, ㉯ 물통은 작은 컵으로 8번 부어 가득 채웠어요. 이것만 보고 들이를 바르게 말한 것은 무엇인가요?","options":[{"t":"재는 컵이 달라서 알 수 없어요","correct":true},{"t":"㉯ 물통의 들이가 더 많아요","mis":"M3-2-u5-X03"},{"t":"㉮ 물통의 들이가 더 많아요","mis":"M3-2-u5-X03"},{"t":"두 물통의 들이가 같아요","mis":"M3-2-u5-X21"}],"explanation":["㉮는 큰 컵, ㉯는 작은 컵 — 재는 그릇이 달라요.","횟수만으로는 들이를 견줄 수 없어요.","같은 컵(같은 단위)으로 재야 견줄 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_a#18','math',3,2,'u5','','g3_2_math_u5_review_a','unit_review','M3-2-u5-C4',3,'mc','auto','간장병에는 3 L 700 mL, 주스병에는 4 L 900 mL 들어 있어요. 두 병에 든 양은 모두 얼마인가요?',ARRAY['M3-2-u5-X12','M3-2-u5-X14']::text[],true,'{"seq":18,"concept":"M3-2-u5-C4","difficulty":3,"kind":"mc","stem":"간장병에는 3 L 700 mL, 주스병에는 4 L 900 mL 들어 있어요. 두 병에 든 양은 모두 얼마인가요?","options":[{"t":"8 L 600 mL","correct":true},{"t":"7 L 1600 mL","mis":"M3-2-u5-X12"},{"t":"7 L 600 mL","mis":"M3-2-u5-X12"},{"t":"1 L 200 mL","mis":"M3-2-u5-X14"}],"explanation":["mL끼리: 700 + 900 = 1600 — 1000 mL = 1 L로 올려요.","L끼리: 1 + 3 + 4 = 8.","3 L 700 mL + 4 L 900 mL = 8 L 600 mL."],"variant_rule":{"alt":[{"stem":"물통에 물이 1 L 900 mL 있었는데 5 L 300 mL를 더 부었어요. 물통의 물은 모두 얼마인가요?","options":[{"t":"7 L 200 mL","correct":true},{"t":"6 L 1200 mL","mis":"M3-2-u5-X12"},{"t":"6 L 200 mL","mis":"M3-2-u5-X12"},{"t":"3 L 400 mL","mis":"M3-2-u5-X14"}],"explanation":["mL끼리: 900 + 300 = 1200 — 1000 mL = 1 L로 올려요.","L끼리: 1 + 1 + 5 = 7.","1 L 900 mL + 5 L 300 mL = 7 L 200 mL."],"asset":null},{"stem":"세제 통에 세제가 2 L 830 mL 들어 있어요. 1 L 530 mL를 더 넣었어요. 세제는 모두 얼마인가요?","options":[{"t":"4 L 360 mL","correct":true},{"t":"3 L 1360 mL","mis":"M3-2-u5-X12"},{"t":"3 L 360 mL","mis":"M3-2-u5-X12"},{"t":"1 L 300 mL","mis":"M3-2-u5-X14"}],"explanation":["mL끼리: 830 + 530 = 1360 — 1000 mL = 1 L로 올려요.","L끼리: 1 + 2 + 1 = 4.","2 L 830 mL + 1 L 530 mL = 4 L 360 mL."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_a#19','math',3,2,'u5','','g3_2_math_u5_review_a','unit_review','M3-2-u5-C5',3,'mc','auto','양팔저울 두 개로 고구마, 감자, 당근의 무게를 견주었어요. 가장 무거운 것은 무엇인가요?',ARRAY['M3-2-u5-X20','M3-2-u5-X15','M3-2-u5-X21']::text[],true,'{"seq":19,"concept":"M3-2-u5-C5","difficulty":3,"kind":"mc","stem":"양팔저울 두 개로 고구마, 감자, 당근의 무게를 견주었어요. 가장 무거운 것은 무엇인가요?","options":[{"t":"감자","correct":true},{"t":"고구마","mis":"M3-2-u5-X20"},{"t":"당근","mis":"M3-2-u5-X15"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["저울마다 내려간 쪽이 더 무거워요.","감자 > 당근, 당근 > 고구마.","무게 순서 감자 > 당근 > 고구마 — 가장 무거운 것은 감자예요."],"asset":{"type":"balance","scales":[{"l":{"name":"감자","icon":"🥔"},"r":{"name":"당근","icon":"🥕"},"down":"l"},{"l":{"name":"고구마","icon":"🍠"},"r":{"name":"당근","icon":"🥕"},"down":"r"}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 양팔저울 두 개로 고구마, 감자, 당근의 무게를 견주었어요. 가장 무거운 것은 무엇인가요?","options":[{"t":"감자","correct":true},{"t":"당근","mis":"M3-2-u5-X20"},{"t":"고구마","mis":"M3-2-u5-X15"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["저울마다 내려간 쪽이 더 무거워요.","감자 > 고구마, 고구마 > 당근.","무게 순서 감자 > 고구마 > 당근 — 가장 무거운 것은 감자예요."],"asset":{"type":"balance","scales":[{"l":{"name":"고구마","icon":"🍠"},"r":{"name":"감자","icon":"🥔"},"down":"r"},{"l":{"name":"고구마","icon":"🍠"},"r":{"name":"당근","icon":"🥕"},"down":"l"}]}},{"stem":"양팔저울 두 개로 빨간 상자, 파란 상자, 노란 상자의 무게를 견주었어요. 가장 무거운 것은 무엇인가요?","options":[{"t":"빨간 상자","correct":true},{"t":"노란 상자","mis":"M3-2-u5-X20"},{"t":"파란 상자","mis":"M3-2-u5-X15"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["저울마다 내려간 쪽이 더 무거워요.","빨간 상자 > 파란 상자, 파란 상자 > 노란 상자.","무게 순서 빨간 상자 > 파란 상자 > 노란 상자 — 가장 무거운 것은 빨간 상자예요."],"asset":{"type":"balance","scales":[{"l":{"name":"빨간 상자","icon":"📦"},"r":{"name":"파란 상자","icon":"📦"},"down":"l"},{"l":{"name":"노란 상자","icon":"📦"},"r":{"name":"파란 상자","icon":"📦"},"down":"r"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_a#20','math',3,2,'u5','','g3_2_math_u5_review_a','unit_review','M3-2-u5-C8',3,'mc','auto','저울의 큰 눈금 0과 1 kg 사이가 똑같이 2칸으로 나뉘어 있어요. 현미를 재었더니 바늘이 0에서부터 7칸째 눈금을 가리켜요. 몇 g인가요?',ARRAY['M3-2-u5-X07']::text[],true,'{"seq":20,"concept":"M3-2-u5-C8","difficulty":3,"kind":"mc","stem":"저울의 큰 눈금 0과 1 kg 사이가 똑같이 2칸으로 나뉘어 있어요. 현미를 재었더니 바늘이 0에서부터 7칸째 눈금을 가리켜요. 몇 g인가요?","options":[{"t":"3500 g","correct":true},{"t":"7 g","mis":"M3-2-u5-X07"},{"t":"700 g","mis":"M3-2-u5-X07"},{"t":"4000 g","mis":"M3-2-u5-X07"}],"explanation":["한 칸의 크기부터: 1 kg = 1000 g, 1000 ÷ 2 = 500 g.","7칸 → 500 × 7 = 3500.","3500 g이에요."],"variant_rule":{"alt":[{"stem":"저울의 큰 눈금 0과 1 kg 사이가 똑같이 5칸으로 나뉘어 있어요. 책가방을 재었더니 바늘이 0에서부터 12칸째 눈금을 가리켜요. 몇 g인가요?","options":[{"t":"2400 g","correct":true},{"t":"12 g","mis":"M3-2-u5-X07"},{"t":"1200 g","mis":"M3-2-u5-X07"},{"t":"2600 g","mis":"M3-2-u5-X07"}],"explanation":["한 칸의 크기부터: 1 kg = 1000 g, 1000 ÷ 5 = 200 g.","12칸 → 200 × 12 = 2400.","2400 g이에요."],"asset":null},{"stem":"저울의 큰 눈금 0과 1 kg 사이가 똑같이 4칸으로 나뉘어 있어요. 빨랫비누 상자를 재었더니 바늘이 0에서부터 14칸째 눈금을 가리켜요. 몇 g인가요?","options":[{"t":"3500 g","correct":true},{"t":"14 g","mis":"M3-2-u5-X07"},{"t":"1400 g","mis":"M3-2-u5-X07"},{"t":"3750 g","mis":"M3-2-u5-X07"}],"explanation":["한 칸의 크기부터: 1 kg = 1000 g, 1000 ÷ 4 = 250 g.","14칸 → 250 × 14 = 3500.","3500 g이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_a#21','math',3,2,'u5','','g3_2_math_u5_review_a','unit_review','M3-2-u5-C9',3,'mc','auto','밀가루 7 kg 700 g 중에서 5 kg 800 g을 빵 만들기에 썼어요. 남은 밀가루는 얼마인가요?',ARRAY['M3-2-u5-X13','M3-2-u5-X14']::text[],true,'{"seq":21,"concept":"M3-2-u5-C9","difficulty":3,"kind":"mc","stem":"밀가루 7 kg 700 g 중에서 5 kg 800 g을 빵 만들기에 썼어요. 남은 밀가루는 얼마인가요?","options":[{"t":"1 kg 900 g","correct":true},{"t":"2 kg 100 g","mis":"M3-2-u5-X13"},{"t":"2 kg 900 g","mis":"M3-2-u5-X13"},{"t":"13 kg 500 g","mis":"M3-2-u5-X14"}],"explanation":["700 g에서 800을 뺄 수 없어 1 kg을 1000 g으로 내려요: 1700 − 800 = 900.","kg끼리: 7 − 1 − 5 = 1.","7 kg 700 g − 5 kg 800 g = 1 kg 900 g."],"variant_rule":{"alt":[{"stem":"재활용품 7 kg 260 g 중에서 2 kg 670 g을 먼저 보냈어요. 남은 재활용품은 얼마인가요?","options":[{"t":"4 kg 590 g","correct":true},{"t":"5 kg 410 g","mis":"M3-2-u5-X13"},{"t":"5 kg 590 g","mis":"M3-2-u5-X13"},{"t":"9 kg 930 g","mis":"M3-2-u5-X14"}],"explanation":["260 g에서 670을 뺄 수 없어 1 kg을 1000 g으로 내려요: 1260 − 670 = 590.","kg끼리: 7 − 1 − 2 = 4.","7 kg 260 g − 2 kg 670 g = 4 kg 590 g."],"asset":null},{"stem":"쌀 4 kg 300 g 중에서 3 kg 700 g으로 떡을 만들었어요. 남은 쌀은 얼마인가요?","options":[{"t":"600 g","correct":true},{"t":"1 kg 400 g","mis":"M3-2-u5-X13"},{"t":"1 kg 600 g","mis":"M3-2-u5-X13"},{"t":"8 kg","mis":"M3-2-u5-X14"}],"explanation":["300 g에서 700을 뺄 수 없어 1 kg을 1000 g으로 내려요: 1300 − 700 = 600.","kg끼리: 4 − 1 − 3 = 0.","4 kg 300 g − 3 kg 700 g = 600 g."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_a#22','math',3,2,'u5','','g3_2_math_u5_review_a','unit_review','M3-2-u5-C10',3,'mc','auto','우유 40 L를 10 L, 5 L, 2 L 통(각각 4개)에 남김없이 나누어 담는 방법은 무엇인가요?',ARRAY['M3-2-u5-X18','M3-2-u5-X19']::text[],true,'{"seq":22,"concept":"M3-2-u5-C10","difficulty":3,"kind":"mc","stem":"우유 40 L를 10 L, 5 L, 2 L 통(각각 4개)에 남김없이 나누어 담는 방법은 무엇인가요?","options":[{"t":"10 L 통 2개, 5 L 통 4개","correct":true},{"t":"10 L 통 3개, 5 L 통 6개","mis":"M3-2-u5-X18"},{"t":"10 L 통 1개, 5 L 통 6개","mis":"M3-2-u5-X19"},{"t":"10 L 통 4개, 5 L 통 4개, 2 L 통 1개","mis":"M3-2-u5-X18"}],"explanation":["보기마다 담은 양을 모두 더해 40 L와 견주어요.","10 L 통 2개, 5 L 통 4개 → 20 + 20 = 40 L.","남김없이 꼭 맞는 것은 이것뿐이에요."],"variant_rule":{"alt":[{"stem":"우유 90 L를 10 L, 6 L, 5 L 통(각각 7개)에 남김없이 나누어 담는 방법은 무엇인가요?","options":[{"t":"10 L 통 6개, 5 L 통 6개","correct":true},{"t":"10 L 통 7개, 5 L 통 7개","mis":"M3-2-u5-X18"},{"t":"10 L 통 8개, 5 L 통 6개","mis":"M3-2-u5-X18"},{"t":"10 L 통 7개, 6 L 통 2개, 5 L 통 5개","mis":"M3-2-u5-X18"}],"explanation":["보기마다 담은 양을 모두 더해 90 L와 견주어요.","10 L 통 6개, 5 L 통 6개 → 60 + 30 = 90 L.","남김없이 꼭 맞는 것은 이것뿐이에요."],"asset":null},{"stem":"우유 60 L를 10 L, 6 L, 5 L 통(각각 5개)에 남김없이 나누어 담는 방법은 무엇인가요?","options":[{"t":"10 L 통 2개, 6 L 통 5개, 5 L 통 2개","correct":true},{"t":"10 L 통 2개, 6 L 통 5개, 5 L 통 4개","mis":"M3-2-u5-X18"},{"t":"10 L 통 4개, 6 L 통 5개, 5 L 통 1개","mis":"M3-2-u5-X18"},{"t":"10 L 통 4개, 6 L 통 6개, 5 L 통 1개","mis":"M3-2-u5-X18"}],"explanation":["보기마다 담은 양을 모두 더해 60 L와 견주어요.","10 L 통 2개, 6 L 통 5개, 5 L 통 2개 → 20 + 30 + 10 = 60 L.","남김없이 꼭 맞는 것은 이것뿐이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_a#23','math',3,2,'u5','','g3_2_math_u5_review_a','unit_review','M3-2-u5-C4',4,'mc','auto','물통의 들이는 2 L예요. 그릇의 물은 ㉮ 1 L 100 mL, ㉯ 1 L 200 mL, ㉰ 300 mL, ㉱ 1 L예요. 두 그릇을 골라 물통에 부어 넘치지 않으면서 가장 많이 채우려면 어느 두 그릇을 골라야 하나요?',ARRAY['M3-2-u5-X18','M3-2-u5-X20']::text[],true,'{"seq":23,"concept":"M3-2-u5-C4","difficulty":4,"kind":"mc","stem":"물통의 들이는 2 L예요. 그릇의 물은 ㉮ 1 L 100 mL, ㉯ 1 L 200 mL, ㉰ 300 mL, ㉱ 1 L예요. 두 그릇을 골라 물통에 부어 넘치지 않으면서 가장 많이 채우려면 어느 두 그릇을 골라야 하나요?","options":[{"t":"㉯, ㉰","correct":true},{"t":"㉮, ㉯","mis":"M3-2-u5-X18"},{"t":"㉮, ㉱","mis":"M3-2-u5-X18"},{"t":"㉮, ㉰","mis":"M3-2-u5-X20"}],"explanation":["두 그릇씩 더해 2 L와 견주어요.","㉯, ㉰: 1 L 200 mL + 300 mL = 1 L 500 mL.","넘치지 않는 합 가운데 가장 커요."],"variant_rule":{"alt":[{"stem":"물통의 들이는 1 L 500 mL예요. 그릇의 물은 ㉮ 400 mL, ㉯ 1 L, ㉰ 300 mL, ㉱ 1 L 400 mL예요. 두 그릇을 골라 물통에 부어 넘치지 않으면서 가장 많이 채우려면 어느 두 그릇을 골라야 하나요?","options":[{"t":"㉮, ㉯","correct":true},{"t":"㉮, ㉱","mis":"M3-2-u5-X18"},{"t":"㉯, ㉱","mis":"M3-2-u5-X18"},{"t":"㉯, ㉰","mis":"M3-2-u5-X20"}],"explanation":["두 그릇씩 더해 1 L 500 mL와 견주어요.","㉮, ㉯: 400 mL + 1 L = 1 L 400 mL.","넘치지 않는 합 가운데 가장 커요."],"asset":null},{"stem":"물통의 들이는 1 L 500 mL예요. 그릇의 물은 ㉮ 700 mL, ㉯ 600 mL, ㉰ 300 mL, ㉱ 1 L 300 mL예요. 두 그릇을 골라 물통에 부어 넘치지 않으면서 가장 많이 채우려면 어느 두 그릇을 골라야 하나요?","options":[{"t":"㉮, ㉯","correct":true},{"t":"㉮, ㉱","mis":"M3-2-u5-X18"},{"t":"㉯, ㉱","mis":"M3-2-u5-X18"},{"t":"㉮, ㉰","mis":"M3-2-u5-X20"}],"explanation":["두 그릇씩 더해 1 L 500 mL와 견주어요.","㉮, ㉯: 700 mL + 600 mL = 1 L 300 mL.","넘치지 않는 합 가운데 가장 커요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_a#24','math',3,2,'u5','','g3_2_math_u5_review_a','unit_review','M3-2-u5-C10',4,'sa','auto','50 L를 10 L 통 5개, 5 L 통 10개에 남김없이 나누어 담는 방법은 모두 몇 가지인가요? 쓰지 않는 통이 있어도 돼요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M3-2-u5-C10","difficulty":4,"kind":"sa","stem":"50 L를 10 L 통 5개, 5 L 통 10개에 남김없이 나누어 담는 방법은 모두 몇 가지인가요? 쓰지 않는 통이 있어도 돼요. 숫자로 쓰세요.","answer":["6"],"explanation":["표로 큰 통부터 개수를 하나씩 바꾸어 봐요.","합이 50 L인 것만 세어요.","모두 6가지예요."],"variant_rule":{"alt":[{"stem":"30 L를 10 L 통 3개, 5 L 통 6개에 남김없이 나누어 담는 방법은 모두 몇 가지인가요? 쓰지 않는 통이 있어도 돼요. 숫자로 쓰세요.","answer":["4"],"explanation":["표로 큰 통부터 개수를 하나씩 바꾸어 봐요.","합이 30 L인 것만 세어요.","모두 4가지예요."],"asset":null},{"stem":"40 L를 10 L 통 4개, 5 L 통 8개에 남김없이 나누어 담는 방법은 모두 몇 가지인가요? 쓰지 않는 통이 있어도 돼요. 숫자로 쓰세요.","answer":["5"],"explanation":["표로 큰 통부터 개수를 하나씩 바꾸어 봐요.","합이 40 L인 것만 세어요.","모두 5가지예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_a#25','math',3,2,'u5','','g3_2_math_u5_review_a','unit_review','M3-2-u5-C2',4,'essay','teacher','500 mL 우유 두 병과 1 L 우유 한 병이 있어요. 승우는 「두 병이니까 500 mL 두 병이 더 많아.」라고 했어요. 승우의 말이 맞는지 판단하고 단위를 이용해 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u5-C2","difficulty":4,"kind":"essay","stem":"500 mL 우유 두 병과 1 L 우유 한 병이 있어요. 승우는 「두 병이니까 500 mL 두 병이 더 많아.」라고 했어요. 승우의 말이 맞는지 판단하고 단위를 이용해 설명해 보세요.","answer_guide":{"answer":"예: 틀렸다. 500 mL 두 병은 500 + 500 = 1000 mL이고, 1 L = 1000 mL이므로 1 L 한 병과 양이 같다. 병의 수가 아니라 들이를 같은 단위로 바꾸어 견주어야 한다.","scoring_points":["틀렸다고 판단했는가","500 mL 두 병 = 1000 mL를 구했는가","1 L = 1000 mL로 같다고 설명했는가"]},"explanation":["500 + 500 = 1000 mL.","1 L = 1000 mL.","두 양은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_b#1','math',3,2,'u5','','g3_2_math_u5_review_b','unit_review','M3-2-u5-C1',1,'mc','auto','빨간색 컵에 물을 가득 채워 초록색 컵에 옮겨 담았더니 가득 차지 않았어요. 들이가 더 많은 것은 무엇인가요?',ARRAY['M3-2-u5-X02','M3-2-u5-X21']::text[],true,'{"seq":1,"concept":"M3-2-u5-C1","difficulty":1,"kind":"mc","stem":"빨간색 컵에 물을 가득 채워 초록색 컵에 옮겨 담았더니 가득 차지 않았어요. 들이가 더 많은 것은 무엇인가요?","options":[{"t":"초록색 컵","correct":true},{"t":"빨간색 컵","mis":"M3-2-u5-X02"},{"t":"두 그릇의 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["빨간색 컵에 가득 담은 물을 초록색 컵에 부었어요.","가득 차지 않았어요 — 초록색 컵에 빈 곳이 남았으니 초록색 컵의 들이가 더 많아요.","들이가 더 많은 것은 초록색 컵이에요."],"asset":{"type":"cups","items":[{"label":"초록색 컵","w":4,"h":3},{"label":"빨간색 컵","w":2,"h":4}],"pour":{"from":1,"to":0}},"variant_rule":{"alt":[{"stem":"물병에 물을 가득 채워 보온병에 옮겨 담았더니 넘쳤어요. 들이가 더 많은 것은 무엇인가요?","options":[{"t":"물병","correct":true},{"t":"보온병","mis":"M3-2-u5-X02"},{"t":"두 그릇의 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["물병에 가득 담은 물을 보온병에 부었어요.","넘쳤어요 — 물병의 들이가 더 많아서 다 담기지 못했어요.","들이가 더 많은 것은 물병이에요."],"asset":{"type":"cups","items":[{"label":"물병","w":4,"h":4},{"label":"보온병","w":2,"h":3}],"pour":{"from":0,"to":1}}},{"stem":"㉮ 컵에 물을 가득 채워 ㉯ 컵에 옮겨 담았더니 넘쳤어요. 들이가 더 많은 것은 무엇인가요?","options":[{"t":"㉮ 컵","correct":true},{"t":"㉯ 컵","mis":"M3-2-u5-X02"},{"t":"두 그릇의 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["㉮ 컵에 가득 담은 물을 ㉯ 컵에 부었어요.","넘쳤어요 — ㉮ 컵의 들이가 더 많아서 다 담기지 못했어요.","들이가 더 많은 것은 ㉮ 컵이에요."],"asset":{"type":"cups","items":[{"label":"㉮ 컵","w":2,"h":5},{"label":"㉯ 컵","w":3,"h":3}],"pour":{"from":0,"to":1}}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_b#2','math',3,2,'u5','','g3_2_math_u5_review_b','unit_review','M3-2-u5-C2',1,'sa','auto','1 L 600 mL는 몇 mL인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u5-C2","difficulty":1,"kind":"sa","stem":"1 L 600 mL는 몇 mL인가요? 숫자로 쓰세요.","answer":["1600"],"explanation":["1 L = 1000 mL — 1 L = 1000 mL.","1000 mL + 600 mL = 1600 mL.","1 L 600 mL = 1600 mL."],"variant_rule":{"alt":[{"stem":"2 L 350 mL는 몇 mL인가요? 숫자로 쓰세요.","answer":["2350"],"explanation":["1 L = 1000 mL — 2 L = 2000 mL.","2000 mL + 350 mL = 2350 mL.","2 L 350 mL = 2350 mL."],"asset":null},{"stem":"7 L 500 mL는 몇 mL인가요? 숫자로 쓰세요.","answer":["7500"],"explanation":["1 L = 1000 mL — 7 L = 7000 mL.","7000 mL + 500 mL = 7500 mL.","7 L 500 mL = 7500 mL."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_b#3','math',3,2,'u5','','g3_2_math_u5_review_b','unit_review','M3-2-u5-C3',1,'sa','auto','비커의 큰 눈금 0과 1000 mL 사이가 똑같이 4칸으로 나뉘어 있어요. 다회용 컵의 물을 재었더니 물이 0에서부터 3칸째 눈금까지 올라와 있어요. 몇 mL인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u5-C3","difficulty":1,"kind":"sa","stem":"비커의 큰 눈금 0과 1000 mL 사이가 똑같이 4칸으로 나뉘어 있어요. 다회용 컵의 물을 재었더니 물이 0에서부터 3칸째 눈금까지 올라와 있어요. 몇 mL인가요? 숫자로 쓰세요.","answer":["750"],"explanation":["한 칸의 크기부터: 1000 ÷ 4 = 250 mL.","3칸 → 250 × 3 = 750.","750 mL예요."],"variant_rule":{"alt":[{"stem":"비커의 큰 눈금 0과 1000 mL 사이가 똑같이 5칸으로 나뉘어 있어요. 세제를 재었더니 물이 0에서부터 4칸째 눈금까지 올라와 있어요. 몇 mL인가요? 숫자로 쓰세요.","answer":["800"],"explanation":["한 칸의 크기부터: 1000 ÷ 5 = 200 mL.","4칸 → 200 × 4 = 800.","800 mL예요."],"asset":null},{"stem":"비커의 큰 눈금 0과 1000 mL 사이가 똑같이 4칸으로 나뉘어 있어요. 우유를 재었더니 물이 0에서부터 2칸째 눈금까지 올라와 있어요. 몇 mL인가요? 숫자로 쓰세요.","answer":["500"],"explanation":["한 칸의 크기부터: 1000 ÷ 4 = 250 mL.","2칸 → 250 × 2 = 500.","500 mL예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_b#4','math',3,2,'u5','','g3_2_math_u5_review_b','unit_review','M3-2-u5-C4',1,'sa','auto','1 L 240 mL + 4 L 70 mL = 5 L □ mL에서 □ 안에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u5-C4","difficulty":1,"kind":"sa","stem":"1 L 240 mL + 4 L 70 mL = 5 L □ mL에서 □ 안에 알맞은 수를 쓰세요.","answer":["310"],"explanation":["mL끼리: 240 + 70 = 310.","L끼리: 1 + 4 = 5.","1 L 240 mL + 4 L 70 mL = 5 L 310 mL."],"variant_rule":{"alt":[{"stem":"2 L 200 mL + 4 L 100 mL = □ L 300 mL에서 □ 안에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["mL끼리: 200 + 100 = 300.","L끼리: 2 + 4 = 6.","2 L 200 mL + 4 L 100 mL = 6 L 300 mL."],"asset":null},{"stem":"4 L 100 mL + 1 L 30 mL = 5 L □ mL에서 □ 안에 알맞은 수를 쓰세요.","answer":["130"],"explanation":["mL끼리: 100 + 30 = 130.","L끼리: 4 + 1 = 5.","4 L 100 mL + 1 L 30 mL = 5 L 130 mL."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_b#5','math',3,2,'u5','','g3_2_math_u5_review_b','unit_review','M3-2-u5-C5',1,'mc','auto','양팔저울에 귤과 사과를 올렸어요. 더 무거운 것은 무엇인가요?',ARRAY['M3-2-u5-X15','M3-2-u5-X21']::text[],true,'{"seq":5,"concept":"M3-2-u5-C5","difficulty":1,"kind":"mc","stem":"양팔저울에 귤과 사과를 올렸어요. 더 무거운 것은 무엇인가요?","options":[{"t":"사과","correct":true},{"t":"귤","mis":"M3-2-u5-X15"},{"t":"두 물건의 무게가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["양팔저울은 더 무거운 쪽이 아래로 내려가요.","사과 쪽이 내려갔어요 — 사과가 더 무거워요.","더 무거운 것은 사과예요."],"asset":{"type":"balance","scales":[{"l":{"name":"귤","icon":"🍊"},"r":{"name":"사과","icon":"🍎"},"down":"r"}]},"variant_rule":{"alt":[{"stem":"양팔저울에 우유갑과 페트병을 올렸어요. 더 무거운 것은 무엇인가요?","options":[{"t":"페트병","correct":true},{"t":"우유갑","mis":"M3-2-u5-X15"},{"t":"두 물건의 무게가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["양팔저울은 더 무거운 쪽이 아래로 내려가요.","페트병 쪽이 내려갔어요 — 페트병이 더 무거워요.","더 무거운 것은 페트병이에요."],"asset":{"type":"balance","scales":[{"l":{"name":"우유갑","icon":"🥛"},"r":{"name":"페트병","icon":"🍶"},"down":"r"}]}},{"stem":"양팔저울에 필통과 지우개를 올렸어요. 더 무거운 것은 무엇인가요?","options":[{"t":"필통","correct":true},{"t":"지우개","mis":"M3-2-u5-X15"},{"t":"두 물건의 무게가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["양팔저울은 더 무거운 쪽이 아래로 내려가요.","필통 쪽이 내려갔어요 — 필통이 더 무거워요.","더 무거운 것은 필통이에요."],"asset":{"type":"balance","scales":[{"l":{"name":"필통","icon":"✏️"},"r":{"name":"지우개","icon":"🧽"},"down":"l"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_b#6','math',3,2,'u5','','g3_2_math_u5_review_b','unit_review','M3-2-u5-C6',1,'sa','auto','4 kg 200 g은 몇 g인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u5-C6","difficulty":1,"kind":"sa","stem":"4 kg 200 g은 몇 g인가요? 숫자로 쓰세요.","answer":["4200"],"explanation":["1 kg = 1000 g — 4 kg = 4000 g.","4000 g + 200 g = 4200 g.","4 kg 200 g = 4200 g."],"variant_rule":{"alt":[{"stem":"3 kg 300 g은 몇 g인가요? 숫자로 쓰세요.","answer":["3300"],"explanation":["1 kg = 1000 g — 3 kg = 3000 g.","3000 g + 300 g = 3300 g.","3 kg 300 g = 3300 g."],"asset":null},{"stem":"5 kg 80 g은 몇 g인가요? 숫자로 쓰세요.","answer":["5080"],"explanation":["1 kg = 1000 g — 5 kg = 5000 g.","5000 g + 80 g = 5080 g.","5 kg 80 g = 5080 g."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_b#7','math',3,2,'u5','','g3_2_math_u5_review_b','unit_review','M3-2-u5-C7',1,'sa','auto','8 t은 몇 kg인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u5-C7","difficulty":1,"kind":"sa","stem":"8 t은 몇 kg인가요? 숫자로 쓰세요.","answer":["8000"],"explanation":["1 t = 1000 kg이에요.","8 t = 1000 kg이 8번.","8 t = 8000 kg."],"variant_rule":{"alt":[{"stem":"3 t은 몇 kg인가요? 숫자로 쓰세요.","answer":["3000"],"explanation":["1 t = 1000 kg이에요.","3 t = 1000 kg이 3번.","3 t = 3000 kg."],"asset":null},{"stem":"9 t은 몇 kg인가요? 숫자로 쓰세요.","answer":["9000"],"explanation":["1 t = 1000 kg이에요.","9 t = 1000 kg이 9번.","9 t = 9000 kg."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_b#8','math',3,2,'u5','','g3_2_math_u5_review_b','unit_review','M3-2-u5-C8',1,'mc','auto','공책 1권의 무게는 약 50 ○예요. ○에 알맞은 단위는 무엇인가요?',ARRAY['M3-2-u5-X09','M3-2-u5-X10']::text[],true,'{"seq":8,"concept":"M3-2-u5-C8","difficulty":1,"kind":"mc","stem":"공책 1권의 무게는 약 50 ○예요. ○에 알맞은 단위는 무엇인가요?","options":[{"t":"g","correct":true},{"t":"kg","mis":"M3-2-u5-X09"},{"t":"t","mis":"M3-2-u5-X09"},{"t":"mL","mis":"M3-2-u5-X10"}],"explanation":["공책 1권을 아는 무게와 견주어 봐요.","무게에 쓰는 단위는 g·kg·t.","공책 1권의 무게는 약 50 g이에요."],"variant_rule":{"alt":[{"stem":"판다의 무게는 약 130 ○예요. ○에 알맞은 단위는 무엇인가요?","options":[{"t":"kg","correct":true},{"t":"g","mis":"M3-2-u5-X09"},{"t":"t","mis":"M3-2-u5-X09"},{"t":"mL","mis":"M3-2-u5-X10"}],"explanation":["판다를 아는 무게와 견주어 봐요.","무게에 쓰는 단위는 g·kg·t.","판다의 무게는 약 130 kg이에요."],"asset":null},{"stem":"강아지의 무게는 약 10 ○예요. ○에 알맞은 단위는 무엇인가요?","options":[{"t":"kg","correct":true},{"t":"g","mis":"M3-2-u5-X09"},{"t":"t","mis":"M3-2-u5-X09"},{"t":"mL","mis":"M3-2-u5-X10"}],"explanation":["강아지를 아는 무게와 견주어 봐요.","무게에 쓰는 단위는 g·kg·t.","강아지의 무게는 약 10 kg이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_b#9','math',3,2,'u5','','g3_2_math_u5_review_b','unit_review','M3-2-u5-C2',2,'mc','auto','㉮는 1 L 10 mL, ㉯는 560 mL예요. 들이가 더 많은 것은 무엇인가요?',ARRAY['M3-2-u5-X04','M3-2-u5-X21']::text[],true,'{"seq":9,"concept":"M3-2-u5-C2","difficulty":2,"kind":"mc","stem":"㉮는 1 L 10 mL, ㉯는 560 mL예요. 들이가 더 많은 것은 무엇인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M3-2-u5-X04"},{"t":"두 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"단위가 달라서 견줄 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["한 가지 단위로 바꾸어 견주어요.","1 L 10 mL = 1010 mL.","1010 mL > 560 mL — 들이가 더 많은 것은 ㉮예요."],"variant_rule":{"alt":[{"stem":"㉮는 3 L 150 mL, ㉯는 2950 mL예요. 들이가 더 많은 것은 무엇인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M3-2-u5-X04"},{"t":"두 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"단위가 달라서 견줄 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["한 가지 단위로 바꾸어 견주어요.","3 L 150 mL = 3150 mL.","3150 mL > 2950 mL — 들이가 더 많은 것은 ㉮예요."],"asset":null},{"stem":"㉮는 1 L 700 mL, ㉯는 1500 mL예요. 들이가 더 많은 것은 무엇인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M3-2-u5-X04"},{"t":"두 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"단위가 달라서 견줄 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["한 가지 단위로 바꾸어 견주어요.","1 L 700 mL = 1700 mL.","1700 mL > 1500 mL — 들이가 더 많은 것은 ㉮예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_b#10','math',3,2,'u5','','g3_2_math_u5_review_b','unit_review','M3-2-u5-C3',2,'mc','auto','세제 통의 들이를 어림했어요 — 채원 약 1 L 650 mL, 준우 약 1 L 200 mL, 정후 약 2 L. 재어 보니 1 L 500 mL였어요. 가장 가깝게 어림한 친구는 누구인가요?',ARRAY['M3-2-u5-X08','M3-2-u5-X21']::text[],true,'{"seq":10,"concept":"M3-2-u5-C3","difficulty":2,"kind":"mc","stem":"세제 통의 들이를 어림했어요 — 채원 약 1 L 650 mL, 준우 약 1 L 200 mL, 정후 약 2 L. 재어 보니 1 L 500 mL였어요. 가장 가깝게 어림한 친구는 누구인가요?","options":[{"t":"채원","correct":true},{"t":"준우","mis":"M3-2-u5-X08"},{"t":"정후","mis":"M3-2-u5-X08"},{"t":"모두 똑같이 알맞아요","mis":"M3-2-u5-X21"}],"explanation":["잰 값 1 L 500 mL와 어림한 값의 차를 견주어요.","채원 150 mL, 준우 300 mL, 정후 500 mL 차이.","차가 가장 작은 채원이 가장 가깝게 어림했어요."],"variant_rule":{"alt":[{"stem":"세제 통의 들이를 어림했어요 — 지아 약 1 L 50 mL, 정후 약 1 L 250 mL, 채원 약 1 L 500 mL. 재어 보니 1 L 200 mL였어요. 가장 가깝게 어림한 친구는 누구인가요?","options":[{"t":"정후","correct":true},{"t":"지아","mis":"M3-2-u5-X08"},{"t":"채원","mis":"M3-2-u5-X08"},{"t":"모두 똑같이 알맞아요","mis":"M3-2-u5-X21"}],"explanation":["잰 값 1 L 200 mL와 어림한 값의 차를 견주어요.","지아 150 mL, 정후 50 mL, 채원 300 mL 차이.","차가 가장 작은 정후가 가장 가깝게 어림했어요."],"asset":null},{"stem":"세제 통의 들이를 어림했어요 — 채원 약 1 L 650 mL, 준우 약 1 L 750 mL, 은비 약 2 L 300 mL. 재어 보니 1 L 800 mL였어요. 가장 가깝게 어림한 친구는 누구인가요?","options":[{"t":"준우","correct":true},{"t":"채원","mis":"M3-2-u5-X08"},{"t":"은비","mis":"M3-2-u5-X08"},{"t":"모두 똑같이 알맞아요","mis":"M3-2-u5-X21"}],"explanation":["잰 값 1 L 800 mL와 어림한 값의 차를 견주어요.","채원 150 mL, 준우 50 mL, 은비 500 mL 차이.","차가 가장 작은 준우가 가장 가깝게 어림했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_b#11','math',3,2,'u5','','g3_2_math_u5_review_b','unit_review','M3-2-u5-C4',2,'mc','auto','주전자에 물이 3 L 900 mL 있었는데 1 L 50 mL를 썼어요. 남은 물은 얼마인가요?',ARRAY['M3-2-u5-X13','M3-2-u5-X14']::text[],true,'{"seq":11,"concept":"M3-2-u5-C4","difficulty":2,"kind":"mc","stem":"주전자에 물이 3 L 900 mL 있었는데 1 L 50 mL를 썼어요. 남은 물은 얼마인가요?","options":[{"t":"2 L 850 mL","correct":true},{"t":"3 L 850 mL","mis":"M3-2-u5-X13"},{"t":"1 L 850 mL","mis":"M3-2-u5-X13"},{"t":"4 L 950 mL","mis":"M3-2-u5-X14"}],"explanation":["mL끼리: 900 − 50 = 850.","L끼리: 3 − 1 = 2.","3 L 900 mL − 1 L 50 mL = 2 L 850 mL."],"variant_rule":{"alt":[{"stem":"우유 6 L 670 mL 중에서 1 L 600 mL를 마셨어요. 남은 우유는 얼마인가요?","options":[{"t":"5 L 70 mL","correct":true},{"t":"6 L 70 mL","mis":"M3-2-u5-X13"},{"t":"4 L 70 mL","mis":"M3-2-u5-X13"},{"t":"8 L 270 mL","mis":"M3-2-u5-X14"}],"explanation":["mL끼리: 670 − 600 = 70.","L끼리: 6 − 1 = 5.","6 L 670 mL − 1 L 600 mL = 5 L 70 mL."],"asset":null},{"stem":"수조에 물이 3 L 920 mL 있어요. 2 L 690 mL를 퍼냈어요. 수조에 남은 물은 얼마인가요?","options":[{"t":"1 L 230 mL","correct":true},{"t":"2 L 230 mL","mis":"M3-2-u5-X13"},{"t":"230 mL","mis":"M3-2-u5-X13"},{"t":"6 L 610 mL","mis":"M3-2-u5-X14"}],"explanation":["mL끼리: 920 − 690 = 230.","L끼리: 3 − 2 = 1.","3 L 920 mL − 2 L 690 mL = 1 L 230 mL."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_b#12','math',3,2,'u5','','g3_2_math_u5_review_b','unit_review','M3-2-u5-C5',2,'sa','auto','고구마의 무게는 쌓기나무 25개, 당근의 무게는 쌓기나무 26개와 같아요. 당근은 고구마보다 쌓기나무 몇 개만큼 더 무거운가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M3-2-u5-C5","difficulty":2,"kind":"sa","stem":"고구마의 무게는 쌓기나무 25개, 당근의 무게는 쌓기나무 26개와 같아요. 당근은 고구마보다 쌓기나무 몇 개만큼 더 무거운가요? 숫자로 쓰세요.","answer":["1"],"explanation":["같은 쌓기나무로 재었으니 개수로 견줄 수 있어요.","고구마 25개, 당근 26개.","26 − 25 = 1 — 쌓기나무 1개만큼 더 무거워요."],"variant_rule":{"alt":[{"stem":"키위의 무게는 공깃돌 23개, 레몬의 무게는 공깃돌 18개와 같아요. 키위는 레몬보다 공깃돌 몇 개만큼 더 무거운가요? 숫자로 쓰세요.","answer":["5"],"explanation":["같은 공깃돌으로 재었으니 개수로 견줄 수 있어요.","키위 23개, 레몬 18개.","23 − 18 = 5 — 공깃돌 5개만큼 더 무거워요."],"asset":null},{"stem":"감자의 무게는 공깃돌 11개, 양파의 무게는 공깃돌 14개와 같아요. 양파는 감자보다 공깃돌 몇 개만큼 더 무거운가요? 숫자로 쓰세요.","answer":["3"],"explanation":["같은 공깃돌으로 재었으니 개수로 견줄 수 있어요.","감자 11개, 양파 14개.","14 − 11 = 3 — 공깃돌 3개만큼 더 무거워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_b#13','math',3,2,'u5','','g3_2_math_u5_review_b','unit_review','M3-2-u5-C6',2,'mc','auto','하윤이 모은 재활용품은 6 kg 30 g, 정후가 모은 재활용품은 6300 g이에요. 누가 더 무겁게 모았나요?',ARRAY['M3-2-u5-X05','M3-2-u5-X21']::text[],true,'{"seq":13,"concept":"M3-2-u5-C6","difficulty":2,"kind":"mc","stem":"하윤이 모은 재활용품은 6 kg 30 g, 정후가 모은 재활용품은 6300 g이에요. 누가 더 무겁게 모았나요?","options":[{"t":"정후","correct":true},{"t":"하윤","mis":"M3-2-u5-X05"},{"t":"두 사람이 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["한 가지 단위로 바꾸어 견주어요.","6 kg 30 g = 6030 g.","6030 g < 6300 g — 정후가 더 무겁게 모았어요."],"variant_rule":{"alt":[{"stem":"하윤이 모은 재활용품은 3 kg 40 g, 민아가 모은 재활용품은 3400 g이에요. 누가 더 무겁게 모았나요?","options":[{"t":"민아","correct":true},{"t":"하윤","mis":"M3-2-u5-X05"},{"t":"두 사람이 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["한 가지 단위로 바꾸어 견주어요.","3 kg 40 g = 3040 g.","3040 g < 3400 g — 민아가 더 무겁게 모았어요."],"asset":null},{"stem":"준우가 모은 재활용품은 4 kg 80 g, 정후가 모은 재활용품은 4800 g이에요. 누가 더 무겁게 모았나요?","options":[{"t":"정후","correct":true},{"t":"준우","mis":"M3-2-u5-X05"},{"t":"두 사람이 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["한 가지 단위로 바꾸어 견주어요.","4 kg 80 g = 4080 g.","4080 g < 4800 g — 정후가 더 무겁게 모았어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_b#14','math',3,2,'u5','','g3_2_math_u5_review_b','unit_review','M3-2-u5-C7',2,'mc','auto','잘못 나타낸 것은 무엇인가요?',ARRAY['M3-2-u5-X21']::text[],true,'{"seq":14,"concept":"M3-2-u5-C7","difficulty":2,"kind":"mc","stem":"잘못 나타낸 것은 무엇인가요?","options":[{"t":"3 t은 300 kg이에요","correct":true},{"t":"9 t은 9000 kg이에요","mis":"M3-2-u5-X21"},{"t":"3780 g은 3 kg 780 g이에요","mis":"M3-2-u5-X21"},{"t":"1 t은 1000 kg이에요","mis":"M3-2-u5-X21"}],"explanation":["1 t = 1000 kg, 1 kg = 1000 g.","3 t = 3000 kg이에요.","「3 t은 300 kg이에요」 — 1 t을 100 kg으로 본 잘못이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 잘못 나타낸 것은 무엇인가요?","options":[{"t":"7 t은 700 kg이에요","correct":true},{"t":"2 t은 2000 kg이에요","mis":"M3-2-u5-X21"},{"t":"9970 g은 9 kg 970 g이에요","mis":"M3-2-u5-X21"},{"t":"1 t은 1000 kg이에요","mis":"M3-2-u5-X21"}],"explanation":["1 t = 1000 kg, 1 kg = 1000 g.","7 t = 7000 kg이에요.","「7 t은 700 kg이에요」 — 1 t을 100 kg으로 본 잘못이에요."],"asset":null},{"stem":"이번에는 다른 문제예요. 잘못 나타낸 것은 무엇인가요?","options":[{"t":"2 t은 200 kg이에요","correct":true},{"t":"8 t은 8000 kg이에요","mis":"M3-2-u5-X21"},{"t":"3450 g은 3 kg 450 g이에요","mis":"M3-2-u5-X21"},{"t":"1 t은 1000 kg이에요","mis":"M3-2-u5-X21"}],"explanation":["1 t = 1000 kg, 1 kg = 1000 g.","2 t = 2000 kg이에요.","「2 t은 200 kg이에요」 — 1 t을 100 kg으로 본 잘못이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_b#15','math',3,2,'u5','','g3_2_math_u5_review_b','unit_review','M3-2-u5-C9',2,'mc','auto','준우는 1 kg 100 g, 소율이는 1 kg 100 g의 재활용품을 모았어요. 두 사람이 모은 재활용품은 모두 얼마인가요?',ARRAY['M3-2-u5-X12']::text[],true,'{"seq":15,"concept":"M3-2-u5-C9","difficulty":2,"kind":"mc","stem":"준우는 1 kg 100 g, 소율이는 1 kg 100 g의 재활용품을 모았어요. 두 사람이 모은 재활용품은 모두 얼마인가요?","options":[{"t":"2 kg 200 g","correct":true},{"t":"3 kg 200 g","mis":"M3-2-u5-X12"},{"t":"1 kg 200 g","mis":"M3-2-u5-X12"},{"t":"2 kg 300 g","mis":"M3-2-u5-X12"}],"explanation":["g끼리: 100 + 100 = 200.","kg끼리: 1 + 1 = 2.","1 kg 100 g + 1 kg 100 g = 2 kg 200 g."],"variant_rule":{"alt":[{"stem":"상자에 사과 5 kg 570 g과 배 1 kg 300 g을 담았어요. 과일은 모두 얼마인가요?","options":[{"t":"6 kg 870 g","correct":true},{"t":"7 kg 870 g","mis":"M3-2-u5-X12"},{"t":"4 kg 270 g","mis":"M3-2-u5-X14"},{"t":"5 kg 870 g","mis":"M3-2-u5-X12"}],"explanation":["g끼리: 570 + 300 = 870.","kg끼리: 5 + 1 = 6.","5 kg 570 g + 1 kg 300 g = 6 kg 870 g."],"asset":null},{"stem":"채원이는 3 kg 250 g, 도윤이는 4 kg 600 g의 옷을 모아 기부했어요. 두 사람이 모은 옷은 모두 얼마인가요?","options":[{"t":"7 kg 850 g","correct":true},{"t":"8 kg 850 g","mis":"M3-2-u5-X12"},{"t":"1 kg 350 g","mis":"M3-2-u5-X14"},{"t":"6 kg 850 g","mis":"M3-2-u5-X12"}],"explanation":["g끼리: 250 + 600 = 850.","kg끼리: 3 + 4 = 7.","3 kg 250 g + 4 kg 600 g = 7 kg 850 g."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_b#16','math',3,2,'u5','','g3_2_math_u5_review_b','unit_review','M3-2-u5-C10',2,'sa','auto','우유 90 L를 남김없이 나누어 담아요. 10 L 통 3개, 5 L 통 6개를 썼어요. 6 L 통은 몇 개 써야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M3-2-u5-C10","difficulty":2,"kind":"sa","stem":"우유 90 L를 남김없이 나누어 담아요. 10 L 통 3개, 5 L 통 6개를 썼어요. 6 L 통은 몇 개 써야 하나요? 숫자로 쓰세요.","answer":["5"],"explanation":["지금까지 담은 양: 60 L.","남은 양: 90 − 60 = 30 L.","30 ÷ 6 = 5 — 6 L 통 5개."],"variant_rule":{"alt":[{"stem":"우유 90 L를 남김없이 나누어 담아요. 6 L 통 5개를 썼어요. 10 L 통은 몇 개 써야 하나요? 숫자로 쓰세요.","answer":["6"],"explanation":["지금까지 담은 양: 30 L.","남은 양: 90 − 30 = 60 L.","60 ÷ 10 = 6 — 10 L 통 6개."],"asset":null},{"stem":"우유 90 L를 남김없이 나누어 담아요. 10 L 통 4개, 6 L 통 5개를 썼어요. 5 L 통은 몇 개 써야 하나요? 숫자로 쓰세요.","answer":["4"],"explanation":["지금까지 담은 양: 70 L.","남은 양: 90 − 70 = 20 L.","20 ÷ 5 = 4 — 5 L 통 4개."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_b#17','math',3,2,'u5','','g3_2_math_u5_review_b','unit_review','M3-2-u5-C1',3,'mc','auto','㉮ 물통은 큰 컵으로 5번, ㉯ 물통은 작은 컵으로 8번 부어 가득 채웠어요. 이것만 보고 들이를 바르게 말한 것은 무엇인가요?',ARRAY['M3-2-u5-X03','M3-2-u5-X21']::text[],true,'{"seq":17,"concept":"M3-2-u5-C1","difficulty":3,"kind":"mc","stem":"㉮ 물통은 큰 컵으로 5번, ㉯ 물통은 작은 컵으로 8번 부어 가득 채웠어요. 이것만 보고 들이를 바르게 말한 것은 무엇인가요?","options":[{"t":"재는 컵이 달라서 알 수 없어요","correct":true},{"t":"㉯ 물통의 들이가 더 많아요","mis":"M3-2-u5-X03"},{"t":"㉮ 물통의 들이가 더 많아요","mis":"M3-2-u5-X03"},{"t":"두 물통의 들이가 같아요","mis":"M3-2-u5-X21"}],"explanation":["㉮는 큰 컵, ㉯는 작은 컵 — 재는 그릇이 달라요.","횟수만으로는 들이를 견줄 수 없어요.","같은 컵(같은 단위)으로 재야 견줄 수 있어요."],"variant_rule":{"alt":[{"stem":"㉮ 물통은 큰 컵으로 3번, ㉯ 물통은 작은 컵으로 6번 부어 가득 채웠어요. 이것만 보고 들이를 바르게 말한 것은 무엇인가요?","options":[{"t":"재는 컵이 달라서 알 수 없어요","correct":true},{"t":"㉯ 물통의 들이가 더 많아요","mis":"M3-2-u5-X03"},{"t":"㉮ 물통의 들이가 더 많아요","mis":"M3-2-u5-X03"},{"t":"두 물통의 들이가 같아요","mis":"M3-2-u5-X21"}],"explanation":["㉮는 큰 컵, ㉯는 작은 컵 — 재는 그릇이 달라요.","횟수만으로는 들이를 견줄 수 없어요.","같은 컵(같은 단위)으로 재야 견줄 수 있어요."],"asset":null},{"stem":"㉮ 물통은 큰 컵으로 6번, ㉯ 물통은 작은 컵으로 7번 부어 가득 채웠어요. 이것만 보고 들이를 바르게 말한 것은 무엇인가요?","options":[{"t":"재는 컵이 달라서 알 수 없어요","correct":true},{"t":"㉯ 물통의 들이가 더 많아요","mis":"M3-2-u5-X03"},{"t":"㉮ 물통의 들이가 더 많아요","mis":"M3-2-u5-X03"},{"t":"두 물통의 들이가 같아요","mis":"M3-2-u5-X21"}],"explanation":["㉮는 큰 컵, ㉯는 작은 컵 — 재는 그릇이 달라요.","횟수만으로는 들이를 견줄 수 없어요.","같은 컵(같은 단위)으로 재야 견줄 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_b#18','math',3,2,'u5','','g3_2_math_u5_review_b','unit_review','M3-2-u5-C4',3,'mc','auto','물통에 물이 3 L 450 mL 있었는데 3 L 700 mL를 더 부었어요. 물통의 물은 모두 얼마인가요?',ARRAY['M3-2-u5-X12','M3-2-u5-X14']::text[],true,'{"seq":18,"concept":"M3-2-u5-C4","difficulty":3,"kind":"mc","stem":"물통에 물이 3 L 450 mL 있었는데 3 L 700 mL를 더 부었어요. 물통의 물은 모두 얼마인가요?","options":[{"t":"7 L 150 mL","correct":true},{"t":"6 L 1150 mL","mis":"M3-2-u5-X12"},{"t":"6 L 150 mL","mis":"M3-2-u5-X12"},{"t":"250 mL","mis":"M3-2-u5-X14"}],"explanation":["mL끼리: 450 + 700 = 1150 — 1000 mL = 1 L로 올려요.","L끼리: 1 + 3 + 3 = 7.","3 L 450 mL + 3 L 700 mL = 7 L 150 mL."],"variant_rule":{"alt":[{"stem":"세제 통에 세제가 4 L 550 mL 들어 있어요. 5 L 800 mL를 더 넣었어요. 세제는 모두 얼마인가요?","options":[{"t":"10 L 350 mL","correct":true},{"t":"9 L 1350 mL","mis":"M3-2-u5-X12"},{"t":"9 L 350 mL","mis":"M3-2-u5-X12"},{"t":"1 L 250 mL","mis":"M3-2-u5-X14"}],"explanation":["mL끼리: 550 + 800 = 1350 — 1000 mL = 1 L로 올려요.","L끼리: 1 + 4 + 5 = 10.","4 L 550 mL + 5 L 800 mL = 10 L 350 mL."],"asset":null},{"stem":"식혜가 한 병에 3 L 300 mL, 다른 병에 2 L 800 mL 있어요. 식혜는 모두 얼마인가요?","options":[{"t":"6 L 100 mL","correct":true},{"t":"5 L 1100 mL","mis":"M3-2-u5-X12"},{"t":"5 L 100 mL","mis":"M3-2-u5-X12"},{"t":"500 mL","mis":"M3-2-u5-X14"}],"explanation":["mL끼리: 300 + 800 = 1100 — 1000 mL = 1 L로 올려요.","L끼리: 1 + 3 + 2 = 6.","3 L 300 mL + 2 L 800 mL = 6 L 100 mL."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_b#19','math',3,2,'u5','','g3_2_math_u5_review_b','unit_review','M3-2-u5-C5',3,'mc','auto','양팔저울 두 개로 ㉮ 주머니, ㉯ 주머니, ㉰ 주머니의 무게를 견주었어요. 가장 무거운 것은 무엇인가요?',ARRAY['M3-2-u5-X20','M3-2-u5-X15','M3-2-u5-X21']::text[],true,'{"seq":19,"concept":"M3-2-u5-C5","difficulty":3,"kind":"mc","stem":"양팔저울 두 개로 ㉮ 주머니, ㉯ 주머니, ㉰ 주머니의 무게를 견주었어요. 가장 무거운 것은 무엇인가요?","options":[{"t":"㉰ 주머니","correct":true},{"t":"㉮ 주머니","mis":"M3-2-u5-X20"},{"t":"㉯ 주머니","mis":"M3-2-u5-X15"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["저울마다 내려간 쪽이 더 무거워요.","㉰ 주머니 > ㉯ 주머니, ㉯ 주머니 > ㉮ 주머니.","무게 순서 ㉰ 주머니 > ㉯ 주머니 > ㉮ 주머니 — 가장 무거운 것은 ㉰ 주머니예요."],"asset":{"type":"balance","scales":[{"l":{"name":"㉯ 주머니","icon":"👜"},"r":{"name":"㉰ 주머니","icon":"👜"},"down":"r"},{"l":{"name":"㉯ 주머니","icon":"👜"},"r":{"name":"㉮ 주머니","icon":"👜"},"down":"l"}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 양팔저울 두 개로 ㉮ 주머니, ㉯ 주머니, ㉰ 주머니의 무게를 견주었어요. 가장 무거운 것은 무엇인가요?","options":[{"t":"㉯ 주머니","correct":true},{"t":"㉮ 주머니","mis":"M3-2-u5-X20"},{"t":"㉰ 주머니","mis":"M3-2-u5-X15"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["저울마다 내려간 쪽이 더 무거워요.","㉯ 주머니 > ㉰ 주머니, ㉰ 주머니 > ㉮ 주머니.","무게 순서 ㉯ 주머니 > ㉰ 주머니 > ㉮ 주머니 — 가장 무거운 것은 ㉯ 주머니예요."],"asset":{"type":"balance","scales":[{"l":{"name":"㉯ 주머니","icon":"👜"},"r":{"name":"㉰ 주머니","icon":"👜"},"down":"l"},{"l":{"name":"㉮ 주머니","icon":"👜"},"r":{"name":"㉰ 주머니","icon":"👜"},"down":"r"}]}},{"stem":"양팔저울 두 개로 빨간 상자, 파란 상자, 노란 상자의 무게를 견주었어요. 가장 무거운 것은 무엇인가요?","options":[{"t":"파란 상자","correct":true},{"t":"빨간 상자","mis":"M3-2-u5-X20"},{"t":"노란 상자","mis":"M3-2-u5-X15"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["저울마다 내려간 쪽이 더 무거워요.","파란 상자 > 노란 상자, 노란 상자 > 빨간 상자.","무게 순서 파란 상자 > 노란 상자 > 빨간 상자 — 가장 무거운 것은 파란 상자예요."],"asset":{"type":"balance","scales":[{"l":{"name":"노란 상자","icon":"📦"},"r":{"name":"파란 상자","icon":"📦"},"down":"r"},{"l":{"name":"노란 상자","icon":"📦"},"r":{"name":"빨간 상자","icon":"📦"},"down":"l"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_b#20','math',3,2,'u5','','g3_2_math_u5_review_b','unit_review','M3-2-u5-C8',3,'mc','auto','저울의 큰 눈금 0과 1 kg 사이가 똑같이 4칸으로 나뉘어 있어요. 책가방을 재었더니 바늘이 0에서부터 9칸째 눈금을 가리켜요. 몇 g인가요?',ARRAY['M3-2-u5-X07']::text[],true,'{"seq":20,"concept":"M3-2-u5-C8","difficulty":3,"kind":"mc","stem":"저울의 큰 눈금 0과 1 kg 사이가 똑같이 4칸으로 나뉘어 있어요. 책가방을 재었더니 바늘이 0에서부터 9칸째 눈금을 가리켜요. 몇 g인가요?","options":[{"t":"2250 g","correct":true},{"t":"9 g","mis":"M3-2-u5-X07"},{"t":"900 g","mis":"M3-2-u5-X07"},{"t":"2500 g","mis":"M3-2-u5-X07"}],"explanation":["한 칸의 크기부터: 1 kg = 1000 g, 1000 ÷ 4 = 250 g.","9칸 → 250 × 9 = 2250.","2250 g이에요."],"variant_rule":{"alt":[{"stem":"저울의 큰 눈금 0과 1 kg 사이가 똑같이 4칸으로 나뉘어 있어요. 빨랫비누 상자를 재었더니 바늘이 0에서부터 14칸째 눈금을 가리켜요. 몇 g인가요?","options":[{"t":"3500 g","correct":true},{"t":"14 g","mis":"M3-2-u5-X07"},{"t":"1400 g","mis":"M3-2-u5-X07"},{"t":"3750 g","mis":"M3-2-u5-X07"}],"explanation":["한 칸의 크기부터: 1 kg = 1000 g, 1000 ÷ 4 = 250 g.","14칸 → 250 × 14 = 3500.","3500 g이에요."],"asset":null},{"stem":"저울의 큰 눈금 0과 1 kg 사이가 똑같이 4칸으로 나뉘어 있어요. 사과를 재었더니 바늘이 0에서부터 11칸째 눈금을 가리켜요. 몇 g인가요?","options":[{"t":"2750 g","correct":true},{"t":"11 g","mis":"M3-2-u5-X07"},{"t":"1100 g","mis":"M3-2-u5-X07"},{"t":"3000 g","mis":"M3-2-u5-X07"}],"explanation":["한 칸의 크기부터: 1 kg = 1000 g, 1000 ÷ 4 = 250 g.","11칸 → 250 × 11 = 2750.","2750 g이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_b#21','math',3,2,'u5','','g3_2_math_u5_review_b','unit_review','M3-2-u5-C9',3,'mc','auto','재활용품 9 kg 300 g 중에서 2 kg 550 g을 먼저 보냈어요. 남은 재활용품은 얼마인가요?',ARRAY['M3-2-u5-X13','M3-2-u5-X14']::text[],true,'{"seq":21,"concept":"M3-2-u5-C9","difficulty":3,"kind":"mc","stem":"재활용품 9 kg 300 g 중에서 2 kg 550 g을 먼저 보냈어요. 남은 재활용품은 얼마인가요?","options":[{"t":"6 kg 750 g","correct":true},{"t":"7 kg 250 g","mis":"M3-2-u5-X13"},{"t":"7 kg 750 g","mis":"M3-2-u5-X13"},{"t":"11 kg 850 g","mis":"M3-2-u5-X14"}],"explanation":["300 g에서 550을 뺄 수 없어 1 kg을 1000 g으로 내려요: 1300 − 550 = 750.","kg끼리: 9 − 1 − 2 = 6.","9 kg 300 g − 2 kg 550 g = 6 kg 750 g."],"variant_rule":{"alt":[{"stem":"쌀 7 kg 300 g 중에서 3 kg 850 g으로 떡을 만들었어요. 남은 쌀은 얼마인가요?","options":[{"t":"3 kg 450 g","correct":true},{"t":"4 kg 550 g","mis":"M3-2-u5-X13"},{"t":"4 kg 450 g","mis":"M3-2-u5-X13"},{"t":"11 kg 150 g","mis":"M3-2-u5-X14"}],"explanation":["300 g에서 850을 뺄 수 없어 1 kg을 1000 g으로 내려요: 1300 − 850 = 450.","kg끼리: 7 − 1 − 3 = 3.","7 kg 300 g − 3 kg 850 g = 3 kg 450 g."],"asset":null},{"stem":"흙 5 kg 590 g 중에서 2 kg 920 g을 화분에 담았어요. 남은 흙은 얼마인가요?","options":[{"t":"2 kg 670 g","correct":true},{"t":"3 kg 330 g","mis":"M3-2-u5-X13"},{"t":"3 kg 670 g","mis":"M3-2-u5-X13"},{"t":"8 kg 510 g","mis":"M3-2-u5-X14"}],"explanation":["590 g에서 920을 뺄 수 없어 1 kg을 1000 g으로 내려요: 1590 − 920 = 670.","kg끼리: 5 − 1 − 2 = 2.","5 kg 590 g − 2 kg 920 g = 2 kg 670 g."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_b#22','math',3,2,'u5','','g3_2_math_u5_review_b','unit_review','M3-2-u5-C10',3,'mc','auto','우유 40 L를 10 L, 5 L, 2 L 통(각각 4개)에 남김없이 나누어 담는 방법은 무엇인가요?',ARRAY['M3-2-u5-X18']::text[],true,'{"seq":22,"concept":"M3-2-u5-C10","difficulty":3,"kind":"mc","stem":"우유 40 L를 10 L, 5 L, 2 L 통(각각 4개)에 남김없이 나누어 담는 방법은 무엇인가요?","options":[{"t":"10 L 통 4개","correct":true},{"t":"10 L 통 6개","mis":"M3-2-u5-X18"},{"t":"10 L 통 3개, 5 L 통 1개, 2 L 통 1개","mis":"M3-2-u5-X18"},{"t":"10 L 통 4개, 5 L 통 2개, 2 L 통 1개","mis":"M3-2-u5-X18"}],"explanation":["보기마다 담은 양을 모두 더해 40 L와 견주어요.","10 L 통 4개 → 40 = 40 L.","남김없이 꼭 맞는 것은 이것뿐이에요."],"variant_rule":{"alt":[{"stem":"우유 70 L를 10 L, 6 L, 5 L 통(각각 6개)에 남김없이 나누어 담는 방법은 무엇인가요?","options":[{"t":"10 L 통 1개, 6 L 통 5개, 5 L 통 6개","correct":true},{"t":"10 L 통 3개, 6 L 통 5개, 5 L 통 6개","mis":"M3-2-u5-X18"},{"t":"10 L 통 2개, 6 L 통 5개, 5 L 통 5개","mis":"M3-2-u5-X18"},{"t":"10 L 통 2개, 6 L 통 7개, 5 L 통 5개","mis":"M3-2-u5-X18"}],"explanation":["보기마다 담은 양을 모두 더해 70 L와 견주어요.","10 L 통 1개, 6 L 통 5개, 5 L 통 6개 → 10 + 30 + 30 = 70 L.","남김없이 꼭 맞는 것은 이것뿐이에요."],"asset":null},{"stem":"우유 60 L를 10 L, 6 L, 5 L 통(각각 5개)에 남김없이 나누어 담는 방법은 무엇인가요?","options":[{"t":"10 L 통 5개, 5 L 통 2개","correct":true},{"t":"10 L 통 7개, 5 L 통 3개","mis":"M3-2-u5-X18"},{"t":"10 L 통 4개, 5 L 통 1개","mis":"M3-2-u5-X18"},{"t":"10 L 통 4개, 5 L 통 2개","mis":"M3-2-u5-X18"}],"explanation":["보기마다 담은 양을 모두 더해 60 L와 견주어요.","10 L 통 5개, 5 L 통 2개 → 50 + 10 = 60 L.","남김없이 꼭 맞는 것은 이것뿐이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_b#23','math',3,2,'u5','','g3_2_math_u5_review_b','unit_review','M3-2-u5-C4',4,'mc','auto','물통의 들이는 1 L 800 mL예요. 그릇의 물은 ㉮ 700 mL, ㉯ 600 mL, ㉰ 1 L 300 mL, ㉱ 900 mL예요. 두 그릇을 골라 물통에 부어 넘치지 않으면서 가장 많이 채우려면 어느 두 그릇을 골라야 하나요?',ARRAY['M3-2-u5-X18','M3-2-u5-X20']::text[],true,'{"seq":23,"concept":"M3-2-u5-C4","difficulty":4,"kind":"mc","stem":"물통의 들이는 1 L 800 mL예요. 그릇의 물은 ㉮ 700 mL, ㉯ 600 mL, ㉰ 1 L 300 mL, ㉱ 900 mL예요. 두 그릇을 골라 물통에 부어 넘치지 않으면서 가장 많이 채우려면 어느 두 그릇을 골라야 하나요?","options":[{"t":"㉮, ㉱","correct":true},{"t":"㉮, ㉰","mis":"M3-2-u5-X18"},{"t":"㉯, ㉰","mis":"M3-2-u5-X18"},{"t":"㉯, ㉱","mis":"M3-2-u5-X20"}],"explanation":["두 그릇씩 더해 1 L 800 mL와 견주어요.","㉮, ㉱: 700 mL + 900 mL = 1 L 600 mL.","넘치지 않는 합 가운데 가장 커요."],"variant_rule":{"alt":[{"stem":"물통의 들이는 1 L 900 mL예요. 그릇의 물은 ㉮ 700 mL, ㉯ 1 L, ㉰ 600 mL, ㉱ 1 L 400 mL예요. 두 그릇을 골라 물통에 부어 넘치지 않으면서 가장 많이 채우려면 어느 두 그릇을 골라야 하나요?","options":[{"t":"㉮, ㉯","correct":true},{"t":"㉮, ㉱","mis":"M3-2-u5-X18"},{"t":"㉯, ㉱","mis":"M3-2-u5-X18"},{"t":"㉯, ㉰","mis":"M3-2-u5-X20"}],"explanation":["두 그릇씩 더해 1 L 900 mL와 견주어요.","㉮, ㉯: 700 mL + 1 L = 1 L 700 mL.","넘치지 않는 합 가운데 가장 커요."],"asset":null},{"stem":"물통의 들이는 1 L 500 mL예요. 그릇의 물은 ㉮ 600 mL, ㉯ 500 mL, ㉰ 400 mL, ㉱ 1 L 400 mL예요. 두 그릇을 골라 물통에 부어 넘치지 않으면서 가장 많이 채우려면 어느 두 그릇을 골라야 하나요?","options":[{"t":"㉮, ㉯","correct":true},{"t":"㉮, ㉱","mis":"M3-2-u5-X18"},{"t":"㉯, ㉱","mis":"M3-2-u5-X18"},{"t":"㉮, ㉰","mis":"M3-2-u5-X20"}],"explanation":["두 그릇씩 더해 1 L 500 mL와 견주어요.","㉮, ㉯: 600 mL + 500 mL = 1 L 100 mL.","넘치지 않는 합 가운데 가장 커요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_b#24','math',3,2,'u5','','g3_2_math_u5_review_b','unit_review','M3-2-u5-C10',4,'sa','auto','20 kg을 5 kg 봉지 4개, 2 kg 봉지 10개에 남김없이 나누어 담는 방법은 모두 몇 가지인가요? 쓰지 않는 봉지가 있어도 돼요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M3-2-u5-C10","difficulty":4,"kind":"sa","stem":"20 kg을 5 kg 봉지 4개, 2 kg 봉지 10개에 남김없이 나누어 담는 방법은 모두 몇 가지인가요? 쓰지 않는 봉지가 있어도 돼요. 숫자로 쓰세요.","answer":["3"],"explanation":["표로 큰 봉지부터 개수를 하나씩 바꾸어 봐요.","합이 20 kg인 것만 세어요.","모두 3가지예요."],"variant_rule":{"alt":[{"stem":"40 L를 10 L 통 4개, 5 L 통 8개에 남김없이 나누어 담는 방법은 모두 몇 가지인가요? 쓰지 않는 통이 있어도 돼요. 숫자로 쓰세요.","answer":["5"],"explanation":["표로 큰 통부터 개수를 하나씩 바꾸어 봐요.","합이 40 L인 것만 세어요.","모두 5가지예요."],"asset":null},{"stem":"24 kg을 6 kg 봉지 4개, 4 kg 봉지 6개에 남김없이 나누어 담는 방법은 모두 몇 가지인가요? 쓰지 않는 봉지가 있어도 돼요. 숫자로 쓰세요.","answer":["3"],"explanation":["표로 큰 봉지부터 개수를 하나씩 바꾸어 봐요.","합이 24 kg인 것만 세어요.","모두 3가지예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_b#25','math',3,2,'u5','','g3_2_math_u5_review_b','unit_review','M3-2-u5-C4',4,'essay','teacher','사과주스는 1 L 300 mL에 650 mL를 더 부었고, 당근주스는 1 L 150 mL에 700 mL를 더 부었어요. 어느 주스가 몇 mL 더 많은지 구하고 그 방법을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u5-C4","difficulty":4,"kind":"essay","stem":"사과주스는 1 L 300 mL에 650 mL를 더 부었고, 당근주스는 1 L 150 mL에 700 mL를 더 부었어요. 어느 주스가 몇 mL 더 많은지 구하고 그 방법을 설명해 보세요.","answer_guide":{"answer":"예: 사과주스는 1 L 300 mL + 650 mL = 1 L 950 mL, 당근주스는 1 L 150 mL + 700 mL = 1 L 850 mL이다. L가 같으므로 mL끼리 견주면 950 − 850 = 100이라 사과주스가 100 mL 더 많다.","scoring_points":["사과주스 1 L 950 mL를 구했는가","당근주스 1 L 850 mL를 구했는가","사과주스가 100 mL 더 많다고 답했는가"]},"explanation":["1 L 300 mL + 650 mL = 1 L 950 mL.","1 L 150 mL + 700 mL = 1 L 850 mL.","사과주스가 100 mL 더 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_c#1','math',3,2,'u5','','g3_2_math_u5_review_c','unit_review','M3-2-u5-C1',1,'mc','auto','머그잔에 물을 가득 채워 유리컵에 옮겨 담았더니 가득 차지 않았어요. 들이가 더 많은 것은 무엇인가요?',ARRAY['M3-2-u5-X02','M3-2-u5-X21']::text[],true,'{"seq":1,"concept":"M3-2-u5-C1","difficulty":1,"kind":"mc","stem":"머그잔에 물을 가득 채워 유리컵에 옮겨 담았더니 가득 차지 않았어요. 들이가 더 많은 것은 무엇인가요?","options":[{"t":"유리컵","correct":true},{"t":"머그잔","mis":"M3-2-u5-X02"},{"t":"두 그릇의 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["머그잔에 가득 담은 물을 유리컵에 부었어요.","가득 차지 않았어요 — 유리컵에 빈 곳이 남았으니 유리컵의 들이가 더 많아요.","들이가 더 많은 것은 유리컵이에요."],"asset":{"type":"cups","items":[{"label":"머그잔","w":2,"h":3},{"label":"유리컵","w":4,"h":5}],"pour":{"from":0,"to":1}},"variant_rule":{"alt":[{"stem":"우유갑에 물을 가득 채워 주스병에 옮겨 담았더니 넘쳤어요. 들이가 더 적은 것은 무엇인가요?","options":[{"t":"주스병","correct":true},{"t":"우유갑","mis":"M3-2-u5-X20"},{"t":"두 그릇의 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["우유갑에 가득 담은 물을 주스병에 부었어요.","넘쳤어요 — 우유갑의 들이가 더 많아서 다 담기지 못했어요.","들이가 더 적은 것은 주스병이에요."],"asset":{"type":"cups","items":[{"label":"우유갑","w":4,"h":4},{"label":"주스병","w":2,"h":3}],"pour":{"from":0,"to":1}}},{"stem":"초록색 컵에 물을 가득 채워 빨간색 컵에 옮겨 담았더니 가득 차지 않았어요. 들이가 더 많은 것은 무엇인가요?","options":[{"t":"빨간색 컵","correct":true},{"t":"초록색 컵","mis":"M3-2-u5-X02"},{"t":"두 그릇의 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["초록색 컵에 가득 담은 물을 빨간색 컵에 부었어요.","가득 차지 않았어요 — 빨간색 컵에 빈 곳이 남았으니 빨간색 컵의 들이가 더 많아요.","들이가 더 많은 것은 빨간색 컵이에요."],"asset":{"type":"cups","items":[{"label":"초록색 컵","w":4,"h":4},{"label":"빨간색 컵","w":3,"h":6}],"pour":{"from":0,"to":1}}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_c#2','math',3,2,'u5','','g3_2_math_u5_review_c','unit_review','M3-2-u5-C2',1,'sa','auto','3 L 500 mL는 몇 mL인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u5-C2","difficulty":1,"kind":"sa","stem":"3 L 500 mL는 몇 mL인가요? 숫자로 쓰세요.","answer":["3500"],"explanation":["1 L = 1000 mL — 3 L = 3000 mL.","3000 mL + 500 mL = 3500 mL.","3 L 500 mL = 3500 mL."],"variant_rule":{"alt":[{"stem":"8 L 50 mL는 몇 mL인가요? 숫자로 쓰세요.","answer":["8050"],"explanation":["1 L = 1000 mL — 8 L = 8000 mL.","8000 mL + 50 mL = 8050 mL.","8 L 50 mL = 8050 mL."],"asset":null},{"stem":"6 L 70 mL는 몇 mL인가요? 숫자로 쓰세요.","answer":["6070"],"explanation":["1 L = 1000 mL — 6 L = 6000 mL.","6000 mL + 70 mL = 6070 mL.","6 L 70 mL = 6070 mL."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_c#3','math',3,2,'u5','','g3_2_math_u5_review_c','unit_review','M3-2-u5-C3',1,'sa','auto','비커의 큰 눈금 0과 1000 mL 사이가 똑같이 4칸으로 나뉘어 있어요. 세제를 재었더니 물이 0에서부터 2칸째 눈금까지 올라와 있어요. 몇 mL인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u5-C3","difficulty":1,"kind":"sa","stem":"비커의 큰 눈금 0과 1000 mL 사이가 똑같이 4칸으로 나뉘어 있어요. 세제를 재었더니 물이 0에서부터 2칸째 눈금까지 올라와 있어요. 몇 mL인가요? 숫자로 쓰세요.","answer":["500"],"explanation":["한 칸의 크기부터: 1000 ÷ 4 = 250 mL.","2칸 → 250 × 2 = 500.","500 mL예요."],"variant_rule":{"alt":[{"stem":"비커의 큰 눈금 0과 1000 mL 사이가 똑같이 5칸으로 나뉘어 있어요. 우유를 재었더니 물이 0에서부터 3칸째 눈금까지 올라와 있어요. 몇 mL인가요? 숫자로 쓰세요.","answer":["600"],"explanation":["한 칸의 크기부터: 1000 ÷ 5 = 200 mL.","3칸 → 200 × 3 = 600.","600 mL예요."],"asset":null},{"stem":"비커의 큰 눈금 0과 500 mL 사이가 똑같이 10칸으로 나뉘어 있어요. 양치 컵의 물을 재었더니 물이 0에서부터 3칸째 눈금까지 올라와 있어요. 몇 mL인가요? 숫자로 쓰세요.","answer":["150"],"explanation":["한 칸의 크기부터: 500 ÷ 10 = 50 mL.","3칸 → 50 × 3 = 150.","150 mL예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_c#4','math',3,2,'u5','','g3_2_math_u5_review_c','unit_review','M3-2-u5-C4',1,'sa','auto','3 L 400 mL + 3 L 500 mL = □ L 900 mL에서 □ 안에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u5-C4","difficulty":1,"kind":"sa","stem":"3 L 400 mL + 3 L 500 mL = □ L 900 mL에서 □ 안에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["mL끼리: 400 + 500 = 900.","L끼리: 3 + 3 = 6.","3 L 400 mL + 3 L 500 mL = 6 L 900 mL."],"variant_rule":{"alt":[{"stem":"5 L 440 mL + 4 L 490 mL = 9 L □ mL에서 □ 안에 알맞은 수를 쓰세요.","answer":["930"],"explanation":["mL끼리: 440 + 490 = 930.","L끼리: 5 + 4 = 9.","5 L 440 mL + 4 L 490 mL = 9 L 930 mL."],"asset":null},{"stem":"2 L 500 mL + 2 L 100 mL = □ L 600 mL에서 □ 안에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["mL끼리: 500 + 100 = 600.","L끼리: 2 + 2 = 4.","2 L 500 mL + 2 L 100 mL = 4 L 600 mL."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_c#5','math',3,2,'u5','','g3_2_math_u5_review_c','unit_review','M3-2-u5-C5',1,'mc','auto','양팔저울에 감자와 양파를 올렸어요. 더 무거운 것은 무엇인가요?',ARRAY['M3-2-u5-X15','M3-2-u5-X21']::text[],true,'{"seq":5,"concept":"M3-2-u5-C5","difficulty":1,"kind":"mc","stem":"양팔저울에 감자와 양파를 올렸어요. 더 무거운 것은 무엇인가요?","options":[{"t":"감자","correct":true},{"t":"양파","mis":"M3-2-u5-X15"},{"t":"두 물건의 무게가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["양팔저울은 더 무거운 쪽이 아래로 내려가요.","감자 쪽이 내려갔어요 — 감자가 더 무거워요.","더 무거운 것은 감자예요."],"asset":{"type":"balance","scales":[{"l":{"name":"감자","icon":"🥔"},"r":{"name":"양파","icon":"🧅"},"down":"l"}]},"variant_rule":{"alt":[{"stem":"양팔저울에 귤과 사과를 올렸어요. 더 무거운 것은 무엇인가요?","options":[{"t":"사과","correct":true},{"t":"귤","mis":"M3-2-u5-X15"},{"t":"두 물건의 무게가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["양팔저울은 더 무거운 쪽이 아래로 내려가요.","사과 쪽이 내려갔어요 — 사과가 더 무거워요.","더 무거운 것은 사과예요."],"asset":{"type":"balance","scales":[{"l":{"name":"귤","icon":"🍊"},"r":{"name":"사과","icon":"🍎"},"down":"r"}]}},{"stem":"양팔저울에 우유갑과 페트병을 올렸어요. 더 무거운 것은 무엇인가요?","options":[{"t":"우유갑","correct":true},{"t":"페트병","mis":"M3-2-u5-X15"},{"t":"두 물건의 무게가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["양팔저울은 더 무거운 쪽이 아래로 내려가요.","우유갑 쪽이 내려갔어요 — 우유갑이 더 무거워요.","더 무거운 것은 우유갑이에요."],"asset":{"type":"balance","scales":[{"l":{"name":"우유갑","icon":"🥛"},"r":{"name":"페트병","icon":"🍶"},"down":"l"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_c#6','math',3,2,'u5','','g3_2_math_u5_review_c','unit_review','M3-2-u5-C6',1,'sa','auto','2 kg 30 g은 몇 g인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u5-C6","difficulty":1,"kind":"sa","stem":"2 kg 30 g은 몇 g인가요? 숫자로 쓰세요.","answer":["2030"],"explanation":["1 kg = 1000 g — 2 kg = 2000 g.","2000 g + 30 g = 2030 g.","2 kg 30 g = 2030 g."],"variant_rule":{"alt":[{"stem":"1 kg 800 g은 몇 g인가요? 숫자로 쓰세요.","answer":["1800"],"explanation":["1 kg = 1000 g — 1 kg = 1000 g.","1000 g + 800 g = 1800 g.","1 kg 800 g = 1800 g."],"asset":null},{"stem":"3 kg 40 g은 몇 g인가요? 숫자로 쓰세요.","answer":["3040"],"explanation":["1 kg = 1000 g — 3 kg = 3000 g.","3000 g + 40 g = 3040 g.","3 kg 40 g = 3040 g."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_c#7','math',3,2,'u5','','g3_2_math_u5_review_c','unit_review','M3-2-u5-C7',1,'sa','auto','4 t은 몇 kg인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u5-C7","difficulty":1,"kind":"sa","stem":"4 t은 몇 kg인가요? 숫자로 쓰세요.","answer":["4000"],"explanation":["1 t = 1000 kg이에요.","4 t = 1000 kg이 4번.","4 t = 4000 kg."],"variant_rule":{"alt":[{"stem":"9 t은 몇 kg인가요? 숫자로 쓰세요.","answer":["9000"],"explanation":["1 t = 1000 kg이에요.","9 t = 1000 kg이 9번.","9 t = 9000 kg."],"asset":null},{"stem":"5 t은 몇 kg인가요? 숫자로 쓰세요.","answer":["5000"],"explanation":["1 t = 1000 kg이에요.","5 t = 1000 kg이 5번.","5 t = 5000 kg."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_c#8','math',3,2,'u5','','g3_2_math_u5_review_c','unit_review','M3-2-u5-C8',1,'mc','auto','공책 1권의 무게는 약 50 ○예요. ○에 알맞은 단위는 무엇인가요?',ARRAY['M3-2-u5-X09','M3-2-u5-X10']::text[],true,'{"seq":8,"concept":"M3-2-u5-C8","difficulty":1,"kind":"mc","stem":"공책 1권의 무게는 약 50 ○예요. ○에 알맞은 단위는 무엇인가요?","options":[{"t":"g","correct":true},{"t":"kg","mis":"M3-2-u5-X09"},{"t":"t","mis":"M3-2-u5-X09"},{"t":"mL","mis":"M3-2-u5-X10"}],"explanation":["공책 1권을 아는 무게와 견주어 봐요.","무게에 쓰는 단위는 g·kg·t.","공책 1권의 무게는 약 50 g이에요."],"variant_rule":{"alt":[{"stem":"클립 1개의 무게는 약 1 ○예요. ○에 알맞은 단위는 무엇인가요?","options":[{"t":"g","correct":true},{"t":"kg","mis":"M3-2-u5-X09"},{"t":"t","mis":"M3-2-u5-X09"},{"t":"mL","mis":"M3-2-u5-X10"}],"explanation":["클립 1개를 아는 무게와 견주어 봐요.","무게에 쓰는 단위는 g·kg·t.","클립 1개의 무게는 약 1 g이에요."],"asset":null},{"stem":"달걀 1개의 무게는 약 60 ○예요. ○에 알맞은 단위는 무엇인가요?","options":[{"t":"g","correct":true},{"t":"kg","mis":"M3-2-u5-X09"},{"t":"t","mis":"M3-2-u5-X09"},{"t":"mL","mis":"M3-2-u5-X10"}],"explanation":["달걀 1개를 아는 무게와 견주어 봐요.","무게에 쓰는 단위는 g·kg·t.","달걀 1개의 무게는 약 60 g이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_c#9','math',3,2,'u5','','g3_2_math_u5_review_c','unit_review','M3-2-u5-C2',2,'mc','auto','㉮는 2 L 900 mL, ㉯는 2810 mL예요. 들이가 더 많은 것은 무엇인가요?',ARRAY['M3-2-u5-X04','M3-2-u5-X21']::text[],true,'{"seq":9,"concept":"M3-2-u5-C2","difficulty":2,"kind":"mc","stem":"㉮는 2 L 900 mL, ㉯는 2810 mL예요. 들이가 더 많은 것은 무엇인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M3-2-u5-X04"},{"t":"두 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"단위가 달라서 견줄 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["한 가지 단위로 바꾸어 견주어요.","2 L 900 mL = 2900 mL.","2900 mL > 2810 mL — 들이가 더 많은 것은 ㉮예요."],"variant_rule":{"alt":[{"stem":"㉮는 5 L 400 mL, ㉯는 4800 mL예요. 들이가 더 많은 것은 무엇인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M3-2-u5-X04"},{"t":"두 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"단위가 달라서 견줄 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["한 가지 단위로 바꾸어 견주어요.","5 L 400 mL = 5400 mL.","5400 mL > 4800 mL — 들이가 더 많은 것은 ㉮예요."],"asset":null},{"stem":"㉮는 1 L 80 mL, ㉯는 1680 mL예요. 들이가 더 많은 것은 무엇인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M3-2-u5-X20"},{"t":"두 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"단위가 달라서 견줄 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["한 가지 단위로 바꾸어 견주어요.","1 L 80 mL = 1080 mL.","1080 mL < 1680 mL — 들이가 더 많은 것은 ㉯예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_c#10','math',3,2,'u5','','g3_2_math_u5_review_c','unit_review','M3-2-u5-C3',2,'mc','auto','세제 통의 들이를 어림했어요 — 은비 약 1 L 450 mL, 지아 약 800 mL, 소율 약 900 mL. 재어 보니 950 mL였어요. 가장 가깝게 어림한 친구는 누구인가요?',ARRAY['M3-2-u5-X08','M3-2-u5-X21']::text[],true,'{"seq":10,"concept":"M3-2-u5-C3","difficulty":2,"kind":"mc","stem":"세제 통의 들이를 어림했어요 — 은비 약 1 L 450 mL, 지아 약 800 mL, 소율 약 900 mL. 재어 보니 950 mL였어요. 가장 가깝게 어림한 친구는 누구인가요?","options":[{"t":"소율","correct":true},{"t":"은비","mis":"M3-2-u5-X08"},{"t":"지아","mis":"M3-2-u5-X08"},{"t":"모두 똑같이 알맞아요","mis":"M3-2-u5-X21"}],"explanation":["잰 값 950 mL와 어림한 값의 차를 견주어요.","은비 500 mL, 지아 150 mL, 소율 50 mL 차이.","차가 가장 작은 소율이 가장 가깝게 어림했어요."],"variant_rule":{"alt":[{"stem":"주스병의 들이를 어림했어요 — 은비 약 2 L 350 mL, 민아 약 2 L, 소율 약 2 L 450 mL. 재어 보니 2 L 300 mL였어요. 가장 가깝게 어림한 친구는 누구인가요?","options":[{"t":"은비","correct":true},{"t":"민아","mis":"M3-2-u5-X08"},{"t":"소율","mis":"M3-2-u5-X08"},{"t":"모두 똑같이 알맞아요","mis":"M3-2-u5-X21"}],"explanation":["잰 값 2 L 300 mL와 어림한 값의 차를 견주어요.","은비 50 mL, 민아 300 mL, 소율 150 mL 차이.","차가 가장 작은 은비가 가장 가깝게 어림했어요."],"asset":null},{"stem":"물통의 들이를 어림했어요 — 도윤 약 1 L 850 mL, 민아 약 1 L 300 mL, 정후 약 1 L 650 mL. 재어 보니 1 L 800 mL였어요. 가장 가깝게 어림한 친구는 누구인가요?","options":[{"t":"도윤","correct":true},{"t":"민아","mis":"M3-2-u5-X08"},{"t":"정후","mis":"M3-2-u5-X08"},{"t":"모두 똑같이 알맞아요","mis":"M3-2-u5-X21"}],"explanation":["잰 값 1 L 800 mL와 어림한 값의 차를 견주어요.","도윤 50 mL, 민아 500 mL, 정후 150 mL 차이.","차가 가장 작은 도윤이 가장 가깝게 어림했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_c#11','math',3,2,'u5','','g3_2_math_u5_review_c','unit_review','M3-2-u5-C4',2,'mc','auto','우유 8 L 250 mL 중에서 5 L 200 mL를 마셨어요. 남은 우유는 얼마인가요?',ARRAY['M3-2-u5-X13','M3-2-u5-X14']::text[],true,'{"seq":11,"concept":"M3-2-u5-C4","difficulty":2,"kind":"mc","stem":"우유 8 L 250 mL 중에서 5 L 200 mL를 마셨어요. 남은 우유는 얼마인가요?","options":[{"t":"3 L 50 mL","correct":true},{"t":"4 L 50 mL","mis":"M3-2-u5-X13"},{"t":"2 L 50 mL","mis":"M3-2-u5-X13"},{"t":"13 L 450 mL","mis":"M3-2-u5-X14"}],"explanation":["mL끼리: 250 − 200 = 50.","L끼리: 8 − 5 = 3.","8 L 250 mL − 5 L 200 mL = 3 L 50 mL."],"variant_rule":{"alt":[{"stem":"수조에 물이 2 L 950 mL 있어요. 1 L 640 mL를 퍼냈어요. 수조에 남은 물은 얼마인가요?","options":[{"t":"1 L 310 mL","correct":true},{"t":"2 L 310 mL","mis":"M3-2-u5-X13"},{"t":"310 mL","mis":"M3-2-u5-X13"},{"t":"4 L 590 mL","mis":"M3-2-u5-X14"}],"explanation":["mL끼리: 950 − 640 = 310.","L끼리: 2 − 1 = 1.","2 L 950 mL − 1 L 640 mL = 1 L 310 mL."],"asset":null},{"stem":"세제 9 L 400 mL 중에서 빨래에 1 L 300 mL를 썼어요. 남은 세제는 얼마인가요?","options":[{"t":"8 L 100 mL","correct":true},{"t":"9 L 100 mL","mis":"M3-2-u5-X13"},{"t":"7 L 100 mL","mis":"M3-2-u5-X13"},{"t":"10 L 700 mL","mis":"M3-2-u5-X14"}],"explanation":["mL끼리: 400 − 300 = 100.","L끼리: 9 − 1 = 8.","9 L 400 mL − 1 L 300 mL = 8 L 100 mL."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_c#12','math',3,2,'u5','','g3_2_math_u5_review_c','unit_review','M3-2-u5-C5',2,'sa','auto','감자의 무게는 공깃돌 11개, 양파의 무게는 공깃돌 18개와 같아요. 양파는 감자보다 공깃돌 몇 개만큼 더 무거운가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M3-2-u5-C5","difficulty":2,"kind":"sa","stem":"감자의 무게는 공깃돌 11개, 양파의 무게는 공깃돌 18개와 같아요. 양파는 감자보다 공깃돌 몇 개만큼 더 무거운가요? 숫자로 쓰세요.","answer":["7"],"explanation":["같은 공깃돌으로 재었으니 개수로 견줄 수 있어요.","감자 11개, 양파 18개.","18 − 11 = 7 — 공깃돌 7개만큼 더 무거워요."],"variant_rule":{"alt":[{"stem":"우유갑의 무게는 바둑돌 24개, 페트병의 무게는 바둑돌 30개와 같아요. 페트병은 우유갑보다 바둑돌 몇 개만큼 더 무거운가요? 숫자로 쓰세요.","answer":["6"],"explanation":["같은 바둑돌으로 재었으니 개수로 견줄 수 있어요.","우유갑 24개, 페트병 30개.","30 − 24 = 6 — 바둑돌 6개만큼 더 무거워요."],"asset":null},{"stem":"키위의 무게는 쌓기나무 27개, 레몬의 무게는 쌓기나무 19개와 같아요. 키위는 레몬보다 쌓기나무 몇 개만큼 더 무거운가요? 숫자로 쓰세요.","answer":["8"],"explanation":["같은 쌓기나무로 재었으니 개수로 견줄 수 있어요.","키위 27개, 레몬 19개.","27 − 19 = 8 — 쌓기나무 8개만큼 더 무거워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_c#13','math',3,2,'u5','','g3_2_math_u5_review_c','unit_review','M3-2-u5-C6',2,'mc','auto','은비가 모은 재활용품은 3 kg 50 g, 도윤이 모은 재활용품은 3500 g이에요. 누가 더 무겁게 모았나요?',ARRAY['M3-2-u5-X05','M3-2-u5-X21']::text[],true,'{"seq":13,"concept":"M3-2-u5-C6","difficulty":2,"kind":"mc","stem":"은비가 모은 재활용품은 3 kg 50 g, 도윤이 모은 재활용품은 3500 g이에요. 누가 더 무겁게 모았나요?","options":[{"t":"도윤","correct":true},{"t":"은비","mis":"M3-2-u5-X05"},{"t":"두 사람이 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["한 가지 단위로 바꾸어 견주어요.","3 kg 50 g = 3050 g.","3050 g < 3500 g — 도윤이 더 무겁게 모았어요."],"variant_rule":{"alt":[{"stem":"하윤이 모은 재활용품은 5 kg 40 g, 은비가 모은 재활용품은 5400 g이에요. 누가 더 무겁게 모았나요?","options":[{"t":"은비","correct":true},{"t":"하윤","mis":"M3-2-u5-X05"},{"t":"두 사람이 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["한 가지 단위로 바꾸어 견주어요.","5 kg 40 g = 5040 g.","5040 g < 5400 g — 은비가 더 무겁게 모았어요."],"asset":null},{"stem":"정후가 모은 재활용품은 5 kg 10 g, 지아가 모은 재활용품은 5100 g이에요. 누가 더 무겁게 모았나요?","options":[{"t":"지아","correct":true},{"t":"정후","mis":"M3-2-u5-X05"},{"t":"두 사람이 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["한 가지 단위로 바꾸어 견주어요.","5 kg 10 g = 5010 g.","5010 g < 5100 g — 지아가 더 무겁게 모았어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_c#14','math',3,2,'u5','','g3_2_math_u5_review_c','unit_review','M3-2-u5-C7',2,'mc','auto','잘못 나타낸 것은 무엇인가요?',ARRAY['M3-2-u5-X21']::text[],true,'{"seq":14,"concept":"M3-2-u5-C7","difficulty":2,"kind":"mc","stem":"잘못 나타낸 것은 무엇인가요?","options":[{"t":"4 t은 400 kg이에요","correct":true},{"t":"3 t은 3000 kg이에요","mis":"M3-2-u5-X21"},{"t":"9730 g은 9 kg 730 g이에요","mis":"M3-2-u5-X21"},{"t":"1 t은 1000 kg이에요","mis":"M3-2-u5-X21"}],"explanation":["1 t = 1000 kg, 1 kg = 1000 g.","4 t = 4000 kg이에요.","「4 t은 400 kg이에요」 — 1 t을 100 kg으로 본 잘못이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 잘못 나타낸 것은 무엇인가요?","options":[{"t":"5 t은 500 kg이에요","correct":true},{"t":"7 t은 7000 kg이에요","mis":"M3-2-u5-X21"},{"t":"9790 g은 9 kg 790 g이에요","mis":"M3-2-u5-X21"},{"t":"1 t은 1000 kg이에요","mis":"M3-2-u5-X21"}],"explanation":["1 t = 1000 kg, 1 kg = 1000 g.","5 t = 5000 kg이에요.","「5 t은 500 kg이에요」 — 1 t을 100 kg으로 본 잘못이에요."],"asset":null},{"stem":"이번에는 다른 문제예요. 잘못 나타낸 것은 무엇인가요?","options":[{"t":"2 t은 200 kg이에요","correct":true},{"t":"9 t은 9000 kg이에요","mis":"M3-2-u5-X21"},{"t":"8320 g은 8 kg 320 g이에요","mis":"M3-2-u5-X21"},{"t":"1 t은 1000 kg이에요","mis":"M3-2-u5-X21"}],"explanation":["1 t = 1000 kg, 1 kg = 1000 g.","2 t = 2000 kg이에요.","「2 t은 200 kg이에요」 — 1 t을 100 kg으로 본 잘못이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_c#15','math',3,2,'u5','','g3_2_math_u5_review_c','unit_review','M3-2-u5-C9',2,'mc','auto','상자에 사과 5 kg 200 g과 배 4 kg 400 g을 담았어요. 과일은 모두 얼마인가요?',ARRAY['M3-2-u5-X12','M3-2-u5-X14']::text[],true,'{"seq":15,"concept":"M3-2-u5-C9","difficulty":2,"kind":"mc","stem":"상자에 사과 5 kg 200 g과 배 4 kg 400 g을 담았어요. 과일은 모두 얼마인가요?","options":[{"t":"9 kg 600 g","correct":true},{"t":"10 kg 600 g","mis":"M3-2-u5-X12"},{"t":"800 g","mis":"M3-2-u5-X14"},{"t":"8 kg 600 g","mis":"M3-2-u5-X12"}],"explanation":["g끼리: 200 + 400 = 600.","kg끼리: 5 + 4 = 9.","5 kg 200 g + 4 kg 400 g = 9 kg 600 g."],"variant_rule":{"alt":[{"stem":"채원이는 3 kg 300 g, 도윤이는 5 kg 500 g의 옷을 모아 기부했어요. 두 사람이 모은 옷은 모두 얼마인가요?","options":[{"t":"8 kg 800 g","correct":true},{"t":"9 kg 800 g","mis":"M3-2-u5-X12"},{"t":"2 kg 200 g","mis":"M3-2-u5-X14"},{"t":"7 kg 800 g","mis":"M3-2-u5-X12"}],"explanation":["g끼리: 300 + 500 = 800.","kg끼리: 3 + 5 = 8.","3 kg 300 g + 5 kg 500 g = 8 kg 800 g."],"asset":null},{"stem":"여행 가방이 3 kg 290 g이에요. 1 kg 610 g의 짐을 더 넣으면 모두 얼마인가요?","options":[{"t":"4 kg 900 g","correct":true},{"t":"5 kg 900 g","mis":"M3-2-u5-X12"},{"t":"1 kg 680 g","mis":"M3-2-u5-X14"},{"t":"3 kg 900 g","mis":"M3-2-u5-X12"}],"explanation":["g끼리: 290 + 610 = 900.","kg끼리: 3 + 1 = 4.","3 kg 290 g + 1 kg 610 g = 4 kg 900 g."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_c#16','math',3,2,'u5','','g3_2_math_u5_review_c','unit_review','M3-2-u5-C10',2,'sa','auto','우유 90 L를 남김없이 나누어 담아요. 6 L 통 5개를 썼어요. 10 L 통은 몇 개 써야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M3-2-u5-C10","difficulty":2,"kind":"sa","stem":"우유 90 L를 남김없이 나누어 담아요. 6 L 통 5개를 썼어요. 10 L 통은 몇 개 써야 하나요? 숫자로 쓰세요.","answer":["6"],"explanation":["지금까지 담은 양: 30 L.","남은 양: 90 − 30 = 60 L.","60 ÷ 10 = 6 — 10 L 통 6개."],"variant_rule":{"alt":[{"stem":"우유 90 L를 남김없이 나누어 담아요. 10 L 통 6개를 썼어요. 5 L 통은 몇 개 써야 하나요? 숫자로 쓰세요.","answer":["6"],"explanation":["지금까지 담은 양: 60 L.","남은 양: 90 − 60 = 30 L.","30 ÷ 5 = 6 — 5 L 통 6개."],"asset":null},{"stem":"사료 50 kg을 남김없이 나누어 담아요. 5 kg 봉지 6개, 2 kg 봉지 6개를 썼어요. 4 kg 봉지는 몇 개 써야 하나요? 숫자로 쓰세요.","answer":["2"],"explanation":["지금까지 담은 양: 42 kg.","남은 양: 50 − 42 = 8 kg.","8 ÷ 4 = 2 — 4 kg 봉지 2개."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_c#17','math',3,2,'u5','','g3_2_math_u5_review_c','unit_review','M3-2-u5-C1',3,'mc','auto','㉮ 물통은 큰 컵으로 5번, ㉯ 물통은 작은 컵으로 6번 부어 가득 채웠어요. 이것만 보고 들이를 바르게 말한 것은 무엇인가요?',ARRAY['M3-2-u5-X03','M3-2-u5-X21']::text[],true,'{"seq":17,"concept":"M3-2-u5-C1","difficulty":3,"kind":"mc","stem":"㉮ 물통은 큰 컵으로 5번, ㉯ 물통은 작은 컵으로 6번 부어 가득 채웠어요. 이것만 보고 들이를 바르게 말한 것은 무엇인가요?","options":[{"t":"재는 컵이 달라서 알 수 없어요","correct":true},{"t":"㉯ 물통의 들이가 더 많아요","mis":"M3-2-u5-X03"},{"t":"㉮ 물통의 들이가 더 많아요","mis":"M3-2-u5-X03"},{"t":"두 물통의 들이가 같아요","mis":"M3-2-u5-X21"}],"explanation":["㉮는 큰 컵, ㉯는 작은 컵 — 재는 그릇이 달라요.","횟수만으로는 들이를 견줄 수 없어요.","같은 컵(같은 단위)으로 재야 견줄 수 있어요."],"variant_rule":{"alt":[{"stem":"㉮ 물통은 큰 컵으로 7번, ㉯ 물통은 작은 컵으로 8번 부어 가득 채웠어요. 이것만 보고 들이를 바르게 말한 것은 무엇인가요?","options":[{"t":"재는 컵이 달라서 알 수 없어요","correct":true},{"t":"㉯ 물통의 들이가 더 많아요","mis":"M3-2-u5-X03"},{"t":"㉮ 물통의 들이가 더 많아요","mis":"M3-2-u5-X03"},{"t":"두 물통의 들이가 같아요","mis":"M3-2-u5-X21"}],"explanation":["㉮는 큰 컵, ㉯는 작은 컵 — 재는 그릇이 달라요.","횟수만으로는 들이를 견줄 수 없어요.","같은 컵(같은 단위)으로 재야 견줄 수 있어요."],"asset":null},{"stem":"㉮ 물통은 큰 컵으로 3번, ㉯ 물통은 작은 컵으로 7번 부어 가득 채웠어요. 이것만 보고 들이를 바르게 말한 것은 무엇인가요?","options":[{"t":"재는 컵이 달라서 알 수 없어요","correct":true},{"t":"㉯ 물통의 들이가 더 많아요","mis":"M3-2-u5-X03"},{"t":"㉮ 물통의 들이가 더 많아요","mis":"M3-2-u5-X03"},{"t":"두 물통의 들이가 같아요","mis":"M3-2-u5-X21"}],"explanation":["㉮는 큰 컵, ㉯는 작은 컵 — 재는 그릇이 달라요.","횟수만으로는 들이를 견줄 수 없어요.","같은 컵(같은 단위)으로 재야 견줄 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_c#18','math',3,2,'u5','','g3_2_math_u5_review_c','unit_review','M3-2-u5-C4',3,'mc','auto','세제 통에 세제가 2 L 700 mL 들어 있어요. 3 L 650 mL를 더 넣었어요. 세제는 모두 얼마인가요?',ARRAY['M3-2-u5-X12','M3-2-u5-X14']::text[],true,'{"seq":18,"concept":"M3-2-u5-C4","difficulty":3,"kind":"mc","stem":"세제 통에 세제가 2 L 700 mL 들어 있어요. 3 L 650 mL를 더 넣었어요. 세제는 모두 얼마인가요?","options":[{"t":"6 L 350 mL","correct":true},{"t":"5 L 1350 mL","mis":"M3-2-u5-X12"},{"t":"5 L 350 mL","mis":"M3-2-u5-X12"},{"t":"950 mL","mis":"M3-2-u5-X14"}],"explanation":["mL끼리: 700 + 650 = 1350 — 1000 mL = 1 L로 올려요.","L끼리: 1 + 2 + 3 = 6.","2 L 700 mL + 3 L 650 mL = 6 L 350 mL."],"variant_rule":{"alt":[{"stem":"식혜가 한 병에 4 L 300 mL, 다른 병에 4 L 800 mL 있어요. 식혜는 모두 얼마인가요?","options":[{"t":"9 L 100 mL","correct":true},{"t":"8 L 1100 mL","mis":"M3-2-u5-X12"},{"t":"8 L 100 mL","mis":"M3-2-u5-X12"},{"t":"500 mL","mis":"M3-2-u5-X14"}],"explanation":["mL끼리: 300 + 800 = 1100 — 1000 mL = 1 L로 올려요.","L끼리: 1 + 4 + 4 = 9.","4 L 300 mL + 4 L 800 mL = 9 L 100 mL."],"asset":null},{"stem":"간장병에는 1 L 800 mL, 주스병에는 1 L 250 mL 들어 있어요. 두 병에 든 양은 모두 얼마인가요?","options":[{"t":"3 L 50 mL","correct":true},{"t":"2 L 1050 mL","mis":"M3-2-u5-X12"},{"t":"2 L 50 mL","mis":"M3-2-u5-X12"},{"t":"550 mL","mis":"M3-2-u5-X14"}],"explanation":["mL끼리: 800 + 250 = 1050 — 1000 mL = 1 L로 올려요.","L끼리: 1 + 1 + 1 = 3.","1 L 800 mL + 1 L 250 mL = 3 L 50 mL."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_c#19','math',3,2,'u5','','g3_2_math_u5_review_c','unit_review','M3-2-u5-C5',3,'mc','auto','양팔저울 두 개로 키위, 레몬, 감의 무게를 견주었어요. 가장 무거운 것은 무엇인가요?',ARRAY['M3-2-u5-X20','M3-2-u5-X15','M3-2-u5-X21']::text[],true,'{"seq":19,"concept":"M3-2-u5-C5","difficulty":3,"kind":"mc","stem":"양팔저울 두 개로 키위, 레몬, 감의 무게를 견주었어요. 가장 무거운 것은 무엇인가요?","options":[{"t":"레몬","correct":true},{"t":"키위","mis":"M3-2-u5-X20"},{"t":"감","mis":"M3-2-u5-X15"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["저울마다 내려간 쪽이 더 무거워요.","레몬 > 감, 감 > 키위.","무게 순서 레몬 > 감 > 키위 — 가장 무거운 것은 레몬이에요."],"asset":{"type":"balance","scales":[{"l":{"name":"레몬","icon":"🍋"},"r":{"name":"감","icon":"🟠"},"down":"l"},{"l":{"name":"키위","icon":"🥝"},"r":{"name":"감","icon":"🟠"},"down":"r"}]},"variant_rule":{"alt":[{"stem":"양팔저울 두 개로 빨간 상자, 파란 상자, 노란 상자의 무게를 견주었어요. 가장 무거운 것은 무엇인가요?","options":[{"t":"노란 상자","correct":true},{"t":"파란 상자","mis":"M3-2-u5-X20"},{"t":"빨간 상자","mis":"M3-2-u5-X15"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["저울마다 내려간 쪽이 더 무거워요.","노란 상자 > 빨간 상자, 빨간 상자 > 파란 상자.","무게 순서 노란 상자 > 빨간 상자 > 파란 상자 — 가장 무거운 것은 노란 상자예요."],"asset":{"type":"balance","scales":[{"l":{"name":"빨간 상자","icon":"📦"},"r":{"name":"노란 상자","icon":"📦"},"down":"r"},{"l":{"name":"빨간 상자","icon":"📦"},"r":{"name":"파란 상자","icon":"📦"},"down":"l"}]}},{"stem":"양팔저울 두 개로 ㉮ 주머니, ㉯ 주머니, ㉰ 주머니의 무게를 견주었어요. 가장 무거운 것은 무엇인가요?","options":[{"t":"㉯ 주머니","correct":true},{"t":"㉰ 주머니","mis":"M3-2-u5-X20"},{"t":"㉮ 주머니","mis":"M3-2-u5-X15"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["저울마다 내려간 쪽이 더 무거워요.","㉯ 주머니 > ㉮ 주머니, ㉮ 주머니 > ㉰ 주머니.","무게 순서 ㉯ 주머니 > ㉮ 주머니 > ㉰ 주머니 — 가장 무거운 것은 ㉯ 주머니예요."],"asset":{"type":"balance","scales":[{"l":{"name":"㉯ 주머니","icon":"👜"},"r":{"name":"㉮ 주머니","icon":"👜"},"down":"l"},{"l":{"name":"㉰ 주머니","icon":"👜"},"r":{"name":"㉮ 주머니","icon":"👜"},"down":"r"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_c#20','math',3,2,'u5','','g3_2_math_u5_review_c','unit_review','M3-2-u5-C8',3,'mc','auto','저울의 큰 눈금 0과 1 kg 사이가 똑같이 5칸으로 나뉘어 있어요. 빨랫비누 상자를 재었더니 바늘이 0에서부터 11칸째 눈금을 가리켜요. 몇 g인가요?',ARRAY['M3-2-u5-X07']::text[],true,'{"seq":20,"concept":"M3-2-u5-C8","difficulty":3,"kind":"mc","stem":"저울의 큰 눈금 0과 1 kg 사이가 똑같이 5칸으로 나뉘어 있어요. 빨랫비누 상자를 재었더니 바늘이 0에서부터 11칸째 눈금을 가리켜요. 몇 g인가요?","options":[{"t":"2200 g","correct":true},{"t":"11 g","mis":"M3-2-u5-X07"},{"t":"1100 g","mis":"M3-2-u5-X07"},{"t":"2400 g","mis":"M3-2-u5-X07"}],"explanation":["한 칸의 크기부터: 1 kg = 1000 g, 1000 ÷ 5 = 200 g.","11칸 → 200 × 11 = 2200.","2200 g이에요."],"variant_rule":{"alt":[{"stem":"저울의 큰 눈금 0과 1 kg 사이가 똑같이 5칸으로 나뉘어 있어요. 사과를 재었더니 바늘이 0에서부터 16칸째 눈금을 가리켜요. 몇 g인가요?","options":[{"t":"3200 g","correct":true},{"t":"16 g","mis":"M3-2-u5-X07"},{"t":"1600 g","mis":"M3-2-u5-X07"},{"t":"3400 g","mis":"M3-2-u5-X07"}],"explanation":["한 칸의 크기부터: 1 kg = 1000 g, 1000 ÷ 5 = 200 g.","16칸 → 200 × 16 = 3200.","3200 g이에요."],"asset":null},{"stem":"저울의 큰 눈금 0과 1 kg 사이가 똑같이 10칸으로 나뉘어 있어요. 현미를 재었더니 바늘이 0에서부터 14칸째 눈금을 가리켜요. 몇 g인가요?","options":[{"t":"1400 g","correct":true},{"t":"14 g","mis":"M3-2-u5-X07"},{"t":"140 g","mis":"M3-2-u5-X07"},{"t":"1500 g","mis":"M3-2-u5-X07"}],"explanation":["한 칸의 크기부터: 1 kg = 1000 g, 1000 ÷ 10 = 100 g.","14칸 → 100 × 14 = 1400.","1400 g이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_c#21','math',3,2,'u5','','g3_2_math_u5_review_c','unit_review','M3-2-u5-C9',3,'mc','auto','쌀 6 kg 240 g 중에서 4 kg 700 g으로 떡을 만들었어요. 남은 쌀은 얼마인가요?',ARRAY['M3-2-u5-X13','M3-2-u5-X14']::text[],true,'{"seq":21,"concept":"M3-2-u5-C9","difficulty":3,"kind":"mc","stem":"쌀 6 kg 240 g 중에서 4 kg 700 g으로 떡을 만들었어요. 남은 쌀은 얼마인가요?","options":[{"t":"1 kg 540 g","correct":true},{"t":"2 kg 460 g","mis":"M3-2-u5-X13"},{"t":"2 kg 540 g","mis":"M3-2-u5-X13"},{"t":"10 kg 940 g","mis":"M3-2-u5-X14"}],"explanation":["240 g에서 700을 뺄 수 없어 1 kg을 1000 g으로 내려요: 1240 − 700 = 540.","kg끼리: 6 − 1 − 4 = 1.","6 kg 240 g − 4 kg 700 g = 1 kg 540 g."],"variant_rule":{"alt":[{"stem":"흙 2 kg 50 g 중에서 1 kg 800 g을 화분에 담았어요. 남은 흙은 얼마인가요?","options":[{"t":"250 g","correct":true},{"t":"1 kg 750 g","mis":"M3-2-u5-X13"},{"t":"1 kg 250 g","mis":"M3-2-u5-X13"},{"t":"3 kg 850 g","mis":"M3-2-u5-X14"}],"explanation":["50 g에서 800을 뺄 수 없어 1 kg을 1000 g으로 내려요: 1050 − 800 = 250.","kg끼리: 2 − 1 − 1 = 0.","2 kg 50 g − 1 kg 800 g = 250 g."],"asset":null},{"stem":"밀가루 6 kg 800 g 중에서 3 kg 990 g을 빵 만들기에 썼어요. 남은 밀가루는 얼마인가요?","options":[{"t":"2 kg 810 g","correct":true},{"t":"3 kg 190 g","mis":"M3-2-u5-X13"},{"t":"3 kg 810 g","mis":"M3-2-u5-X13"},{"t":"10 kg 790 g","mis":"M3-2-u5-X14"}],"explanation":["800 g에서 990을 뺄 수 없어 1 kg을 1000 g으로 내려요: 1800 − 990 = 810.","kg끼리: 6 − 1 − 3 = 2.","6 kg 800 g − 3 kg 990 g = 2 kg 810 g."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_c#22','math',3,2,'u5','','g3_2_math_u5_review_c','unit_review','M3-2-u5-C10',3,'mc','auto','우유 40 L를 10 L, 5 L, 2 L 통(각각 4개)에 남김없이 나누어 담는 방법은 무엇인가요?',ARRAY['M3-2-u5-X18']::text[],true,'{"seq":22,"concept":"M3-2-u5-C10","difficulty":3,"kind":"mc","stem":"우유 40 L를 10 L, 5 L, 2 L 통(각각 4개)에 남김없이 나누어 담는 방법은 무엇인가요?","options":[{"t":"10 L 통 4개","correct":true},{"t":"10 L 통 3개, 2 L 통 2개","mis":"M3-2-u5-X18"},{"t":"10 L 통 6개","mis":"M3-2-u5-X18"},{"t":"10 L 통 4개, 5 L 통 2개","mis":"M3-2-u5-X18"}],"explanation":["보기마다 담은 양을 모두 더해 40 L와 견주어요.","10 L 통 4개 → 40 = 40 L.","남김없이 꼭 맞는 것은 이것뿐이에요."],"variant_rule":{"alt":[{"stem":"우유 90 L를 10 L, 6 L, 5 L 통(각각 7개)에 남김없이 나누어 담는 방법은 무엇인가요?","options":[{"t":"10 L 통 6개, 5 L 통 6개","correct":true},{"t":"10 L 통 6개, 6 L 통 2개, 5 L 통 7개","mis":"M3-2-u5-X18"},{"t":"10 L 통 6개, 5 L 통 7개","mis":"M3-2-u5-X18"},{"t":"10 L 통 7개, 5 L 통 7개","mis":"M3-2-u5-X18"}],"explanation":["보기마다 담은 양을 모두 더해 90 L와 견주어요.","10 L 통 6개, 5 L 통 6개 → 60 + 30 = 90 L.","남김없이 꼭 맞는 것은 이것뿐이에요."],"asset":null},{"stem":"사료 50 kg을 5 kg, 4 kg, 2 kg 봉지(각각 6개)에 남김없이 나누어 담는 방법은 무엇인가요?","options":[{"t":"5 kg 봉지 4개, 4 kg 봉지 6개, 2 kg 봉지 3개","correct":true},{"t":"5 kg 봉지 6개, 4 kg 봉지 8개, 2 kg 봉지 5개","mis":"M3-2-u5-X18"},{"t":"5 kg 봉지 6개, 4 kg 봉지 7개, 2 kg 봉지 5개","mis":"M3-2-u5-X18"},{"t":"5 kg 봉지 3개, 4 kg 봉지 6개, 2 kg 봉지 5개","mis":"M3-2-u5-X18"}],"explanation":["보기마다 담은 양을 모두 더해 50 kg과 견주어요.","5 kg 봉지 4개, 4 kg 봉지 6개, 2 kg 봉지 3개 → 20 + 24 + 6 = 50 kg.","남김없이 꼭 맞는 것은 이것뿐이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_c#23','math',3,2,'u5','','g3_2_math_u5_review_c','unit_review','M3-2-u5-C4',4,'mc','auto','물통의 들이는 1 L 700 mL예요. 그릇의 물은 ㉮ 900 mL, ㉯ 1 L 200 mL, ㉰ 400 mL, ㉱ 600 mL예요. 두 그릇을 골라 물통에 부어 넘치지 않으면서 가장 많이 채우려면 어느 두 그릇을 골라야 하나요?',ARRAY['M3-2-u5-X18','M3-2-u5-X20']::text[],true,'{"seq":23,"concept":"M3-2-u5-C4","difficulty":4,"kind":"mc","stem":"물통의 들이는 1 L 700 mL예요. 그릇의 물은 ㉮ 900 mL, ㉯ 1 L 200 mL, ㉰ 400 mL, ㉱ 600 mL예요. 두 그릇을 골라 물통에 부어 넘치지 않으면서 가장 많이 채우려면 어느 두 그릇을 골라야 하나요?","options":[{"t":"㉯, ㉰","correct":true},{"t":"㉮, ㉯","mis":"M3-2-u5-X18"},{"t":"㉯, ㉱","mis":"M3-2-u5-X18"},{"t":"㉮, ㉱","mis":"M3-2-u5-X20"}],"explanation":["두 그릇씩 더해 1 L 700 mL와 견주어요.","㉯, ㉰: 1 L 200 mL + 400 mL = 1 L 600 mL.","넘치지 않는 합 가운데 가장 커요."],"variant_rule":{"alt":[{"stem":"물통의 들이는 1 L 900 mL예요. 그릇의 물은 ㉮ 1 L 300 mL, ㉯ 1 L, ㉰ 700 mL, ㉱ 500 mL예요. 두 그릇을 골라 물통에 부어 넘치지 않으면서 가장 많이 채우려면 어느 두 그릇을 골라야 하나요?","options":[{"t":"㉮, ㉱","correct":true},{"t":"㉮, ㉯","mis":"M3-2-u5-X18"},{"t":"㉮, ㉰","mis":"M3-2-u5-X18"},{"t":"㉯, ㉰","mis":"M3-2-u5-X20"}],"explanation":["두 그릇씩 더해 1 L 900 mL와 견주어요.","㉮, ㉱: 1 L 300 mL + 500 mL = 1 L 800 mL.","넘치지 않는 합 가운데 가장 커요."],"asset":null},{"stem":"물통의 들이는 1 L 800 mL예요. 그릇의 물은 ㉮ 700 mL, ㉯ 1 L 400 mL, ㉰ 800 mL, ㉱ 900 mL예요. 두 그릇을 골라 물통에 부어 넘치지 않으면서 가장 많이 채우려면 어느 두 그릇을 골라야 하나요?","options":[{"t":"㉰, ㉱","correct":true},{"t":"㉮, ㉯","mis":"M3-2-u5-X18"},{"t":"㉯, ㉰","mis":"M3-2-u5-X18"},{"t":"㉮, ㉱","mis":"M3-2-u5-X20"}],"explanation":["두 그릇씩 더해 1 L 800 mL와 견주어요.","㉰, ㉱: 800 mL + 900 mL = 1 L 700 mL.","넘치지 않는 합 가운데 가장 커요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_c#24','math',3,2,'u5','','g3_2_math_u5_review_c','unit_review','M3-2-u5-C10',4,'sa','auto','30 kg을 5 kg 봉지 6개, 3 kg 봉지 10개에 남김없이 나누어 담는 방법은 모두 몇 가지인가요? 쓰지 않는 봉지가 있어도 돼요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M3-2-u5-C10","difficulty":4,"kind":"sa","stem":"30 kg을 5 kg 봉지 6개, 3 kg 봉지 10개에 남김없이 나누어 담는 방법은 모두 몇 가지인가요? 쓰지 않는 봉지가 있어도 돼요. 숫자로 쓰세요.","answer":["3"],"explanation":["표로 큰 봉지부터 개수를 하나씩 바꾸어 봐요.","합이 30 kg인 것만 세어요.","모두 3가지예요."],"variant_rule":{"alt":[{"stem":"40 L를 10 L 통 4개, 5 L 통 8개에 남김없이 나누어 담는 방법은 모두 몇 가지인가요? 쓰지 않는 통이 있어도 돼요. 숫자로 쓰세요.","answer":["5"],"explanation":["표로 큰 통부터 개수를 하나씩 바꾸어 봐요.","합이 40 L인 것만 세어요.","모두 5가지예요."],"asset":null},{"stem":"30 L를 10 L 통 3개, 5 L 통 6개에 남김없이 나누어 담는 방법은 모두 몇 가지인가요? 쓰지 않는 통이 있어도 돼요. 숫자로 쓰세요.","answer":["4"],"explanation":["표로 큰 통부터 개수를 하나씩 바꾸어 봐요.","합이 30 L인 것만 세어요.","모두 4가지예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_c#25','math',3,2,'u5','','g3_2_math_u5_review_c','unit_review','M3-2-u5-C9',4,'essay','teacher','장난감을 넣은 정리함은 3 kg 850 g이고, 빈 정리함은 1 kg 600 g이에요. 장난감의 무게를 구하고, 같은 단위끼리 계산하는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u5-C9","difficulty":4,"kind":"essay","stem":"장난감을 넣은 정리함은 3 kg 850 g이고, 빈 정리함은 1 kg 600 g이에요. 장난감의 무게를 구하고, 같은 단위끼리 계산하는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 장난감의 무게는 3 kg 850 g − 1 kg 600 g이다. g끼리 850 − 600 = 250 g, kg끼리 3 − 1 = 2 kg이므로 2 kg 250 g(= 2250 g)이다.","scoring_points":["뺄셈식을 세웠는가","g끼리, kg끼리 뺐는가","2 kg 250 g(2250 g)이라고 답했는가"]},"explanation":["3 kg 850 g − 1 kg 600 g.","g끼리 250, kg끼리 2.","2 kg 250 g."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_d#1','math',3,2,'u5','','g3_2_math_u5_review_d','unit_review','M3-2-u5-C1',1,'mc','auto','보온병에 물을 가득 채워 물병에 옮겨 담았더니 넘쳤어요. 들이가 더 적은 것은 무엇인가요?',ARRAY['M3-2-u5-X20','M3-2-u5-X21']::text[],true,'{"seq":1,"concept":"M3-2-u5-C1","difficulty":1,"kind":"mc","stem":"보온병에 물을 가득 채워 물병에 옮겨 담았더니 넘쳤어요. 들이가 더 적은 것은 무엇인가요?","options":[{"t":"물병","correct":true},{"t":"보온병","mis":"M3-2-u5-X20"},{"t":"두 그릇의 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["보온병에 가득 담은 물을 물병에 부었어요.","넘쳤어요 — 보온병의 들이가 더 많아서 다 담기지 못했어요.","들이가 더 적은 것은 물병이에요."],"asset":{"type":"cups","items":[{"label":"물병","w":3,"h":3},{"label":"보온병","w":3,"h":4}],"pour":{"from":1,"to":0}},"variant_rule":{"alt":[{"stem":"㉯ 컵에 물을 가득 채워 ㉮ 컵에 옮겨 담았더니 넘쳤어요. 들이가 더 많은 것은 무엇인가요?","options":[{"t":"㉯ 컵","correct":true},{"t":"㉮ 컵","mis":"M3-2-u5-X02"},{"t":"두 그릇의 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["㉯ 컵에 가득 담은 물을 ㉮ 컵에 부었어요.","넘쳤어요 — ㉯ 컵의 들이가 더 많아서 다 담기지 못했어요.","들이가 더 많은 것은 ㉯ 컵이에요."],"asset":{"type":"cups","items":[{"label":"㉮ 컵","w":2,"h":3},{"label":"㉯ 컵","w":3,"h":3}],"pour":{"from":1,"to":0}}},{"stem":"유리컵에 물을 가득 채워 머그잔에 옮겨 담았더니 넘쳤어요. 들이가 더 적은 것은 무엇인가요?","options":[{"t":"머그잔","correct":true},{"t":"유리컵","mis":"M3-2-u5-X20"},{"t":"두 그릇의 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["유리컵에 가득 담은 물을 머그잔에 부었어요.","넘쳤어요 — 유리컵의 들이가 더 많아서 다 담기지 못했어요.","들이가 더 적은 것은 머그잔이에요."],"asset":{"type":"cups","items":[{"label":"머그잔","w":2,"h":3},{"label":"유리컵","w":3,"h":3}],"pour":{"from":1,"to":0}}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_d#2','math',3,2,'u5','','g3_2_math_u5_review_d','unit_review','M3-2-u5-C2',1,'sa','auto','2 L 400 mL는 몇 mL인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u5-C2","difficulty":1,"kind":"sa","stem":"2 L 400 mL는 몇 mL인가요? 숫자로 쓰세요.","answer":["2400"],"explanation":["1 L = 1000 mL — 2 L = 2000 mL.","2000 mL + 400 mL = 2400 mL.","2 L 400 mL = 2400 mL."],"variant_rule":{"alt":[{"stem":"6 L 30 mL는 몇 mL인가요? 숫자로 쓰세요.","answer":["6030"],"explanation":["1 L = 1000 mL — 6 L = 6000 mL.","6000 mL + 30 mL = 6030 mL.","6 L 30 mL = 6030 mL."],"asset":null},{"stem":"9 L 900 mL는 몇 mL인가요? 숫자로 쓰세요.","answer":["9900"],"explanation":["1 L = 1000 mL — 9 L = 9000 mL.","9000 mL + 900 mL = 9900 mL.","9 L 900 mL = 9900 mL."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_d#3','math',3,2,'u5','','g3_2_math_u5_review_d','unit_review','M3-2-u5-C3',1,'sa','auto','비커의 큰 눈금 0과 1000 mL 사이가 똑같이 10칸으로 나뉘어 있어요. 우유를 재었더니 물이 0에서부터 4칸째 눈금까지 올라와 있어요. 몇 mL인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u5-C3","difficulty":1,"kind":"sa","stem":"비커의 큰 눈금 0과 1000 mL 사이가 똑같이 10칸으로 나뉘어 있어요. 우유를 재었더니 물이 0에서부터 4칸째 눈금까지 올라와 있어요. 몇 mL인가요? 숫자로 쓰세요.","answer":["400"],"explanation":["한 칸의 크기부터: 1000 ÷ 10 = 100 mL.","4칸 → 100 × 4 = 400.","400 mL예요."],"variant_rule":{"alt":[{"stem":"비커의 큰 눈금 0과 1000 mL 사이가 똑같이 10칸으로 나뉘어 있어요. 양치 컵의 물을 재었더니 물이 0에서부터 2칸째 눈금까지 올라와 있어요. 몇 mL인가요? 숫자로 쓰세요.","answer":["200"],"explanation":["한 칸의 크기부터: 1000 ÷ 10 = 100 mL.","2칸 → 100 × 2 = 200.","200 mL예요."],"asset":null},{"stem":"비커의 큰 눈금 0과 1000 mL 사이가 똑같이 10칸으로 나뉘어 있어요. 다회용 컵의 물을 재었더니 물이 0에서부터 9칸째 눈금까지 올라와 있어요. 몇 mL인가요? 숫자로 쓰세요.","answer":["900"],"explanation":["한 칸의 크기부터: 1000 ÷ 10 = 100 mL.","9칸 → 100 × 9 = 900.","900 mL예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_d#4','math',3,2,'u5','','g3_2_math_u5_review_d','unit_review','M3-2-u5-C4',1,'sa','auto','4 L 300 mL + 5 L 100 mL = 9 L □ mL에서 □ 안에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u5-C4","difficulty":1,"kind":"sa","stem":"4 L 300 mL + 5 L 100 mL = 9 L □ mL에서 □ 안에 알맞은 수를 쓰세요.","answer":["400"],"explanation":["mL끼리: 300 + 100 = 400.","L끼리: 4 + 5 = 9.","4 L 300 mL + 5 L 100 mL = 9 L 400 mL."],"variant_rule":{"alt":[{"stem":"2 L 790 mL + 5 L 20 mL = □ L 810 mL에서 □ 안에 알맞은 수를 쓰세요.","answer":["7"],"explanation":["mL끼리: 790 + 20 = 810.","L끼리: 2 + 5 = 7.","2 L 790 mL + 5 L 20 mL = 7 L 810 mL."],"asset":null},{"stem":"2 L 860 mL + 4 L 50 mL = 6 L □ mL에서 □ 안에 알맞은 수를 쓰세요.","answer":["910"],"explanation":["mL끼리: 860 + 50 = 910.","L끼리: 2 + 4 = 6.","2 L 860 mL + 4 L 50 mL = 6 L 910 mL."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_d#5','math',3,2,'u5','','g3_2_math_u5_review_d','unit_review','M3-2-u5-C5',1,'mc','auto','양팔저울에 책가방과 공책을 올렸어요. 더 무거운 것은 무엇인가요?',ARRAY['M3-2-u5-X15','M3-2-u5-X21']::text[],true,'{"seq":5,"concept":"M3-2-u5-C5","difficulty":1,"kind":"mc","stem":"양팔저울에 책가방과 공책을 올렸어요. 더 무거운 것은 무엇인가요?","options":[{"t":"책가방","correct":true},{"t":"공책","mis":"M3-2-u5-X15"},{"t":"두 물건의 무게가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["양팔저울은 더 무거운 쪽이 아래로 내려가요.","책가방 쪽이 내려갔어요 — 책가방이 더 무거워요.","더 무거운 것은 책가방이에요."],"asset":{"type":"balance","scales":[{"l":{"name":"책가방","icon":"🎒"},"r":{"name":"공책","icon":"📒"},"down":"l"}]},"variant_rule":{"alt":[{"stem":"양팔저울에 귤과 사과를 올렸어요. 더 무거운 것은 무엇인가요?","options":[{"t":"사과","correct":true},{"t":"귤","mis":"M3-2-u5-X15"},{"t":"두 물건의 무게가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["양팔저울은 더 무거운 쪽이 아래로 내려가요.","사과 쪽이 내려갔어요 — 사과가 더 무거워요.","더 무거운 것은 사과예요."],"asset":{"type":"balance","scales":[{"l":{"name":"귤","icon":"🍊"},"r":{"name":"사과","icon":"🍎"},"down":"r"}]}},{"stem":"양팔저울에 키위와 레몬을 올렸어요. 더 무거운 것은 무엇인가요?","options":[{"t":"키위","correct":true},{"t":"레몬","mis":"M3-2-u5-X15"},{"t":"두 물건의 무게가 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["양팔저울은 더 무거운 쪽이 아래로 내려가요.","키위 쪽이 내려갔어요 — 키위가 더 무거워요.","더 무거운 것은 키위예요."],"asset":{"type":"balance","scales":[{"l":{"name":"키위","icon":"🥝"},"r":{"name":"레몬","icon":"🍋"},"down":"l"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_d#6','math',3,2,'u5','','g3_2_math_u5_review_d','unit_review','M3-2-u5-C6',1,'sa','auto','7 kg 90 g은 몇 g인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u5-C6","difficulty":1,"kind":"sa","stem":"7 kg 90 g은 몇 g인가요? 숫자로 쓰세요.","answer":["7090"],"explanation":["1 kg = 1000 g — 7 kg = 7000 g.","7000 g + 90 g = 7090 g.","7 kg 90 g = 7090 g."],"variant_rule":{"alt":[{"stem":"7 kg 400 g은 몇 g인가요? 숫자로 쓰세요.","answer":["7400"],"explanation":["1 kg = 1000 g — 7 kg = 7000 g.","7000 g + 400 g = 7400 g.","7 kg 400 g = 7400 g."],"asset":null},{"stem":"2 kg 90 g은 몇 g인가요? 숫자로 쓰세요.","answer":["2090"],"explanation":["1 kg = 1000 g — 2 kg = 2000 g.","2000 g + 90 g = 2090 g.","2 kg 90 g = 2090 g."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_d#7','math',3,2,'u5','','g3_2_math_u5_review_d','unit_review','M3-2-u5-C7',1,'sa','auto','6 t은 몇 kg인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u5-C7","difficulty":1,"kind":"sa","stem":"6 t은 몇 kg인가요? 숫자로 쓰세요.","answer":["6000"],"explanation":["1 t = 1000 kg이에요.","6 t = 1000 kg이 6번.","6 t = 6000 kg."],"variant_rule":{"alt":[{"stem":"2 t은 몇 kg인가요? 숫자로 쓰세요.","answer":["2000"],"explanation":["1 t = 1000 kg이에요.","2 t = 1000 kg이 2번.","2 t = 2000 kg."],"asset":null},{"stem":"3 t은 몇 kg인가요? 숫자로 쓰세요.","answer":["3000"],"explanation":["1 t = 1000 kg이에요.","3 t = 1000 kg이 3번.","3 t = 3000 kg."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_d#8','math',3,2,'u5','','g3_2_math_u5_review_d','unit_review','M3-2-u5-C8',1,'mc','auto','책상의 무게는 약 15 ○예요. ○에 알맞은 단위는 무엇인가요?',ARRAY['M3-2-u5-X09','M3-2-u5-X10']::text[],true,'{"seq":8,"concept":"M3-2-u5-C8","difficulty":1,"kind":"mc","stem":"책상의 무게는 약 15 ○예요. ○에 알맞은 단위는 무엇인가요?","options":[{"t":"kg","correct":true},{"t":"g","mis":"M3-2-u5-X09"},{"t":"t","mis":"M3-2-u5-X09"},{"t":"mL","mis":"M3-2-u5-X10"}],"explanation":["책상을 아는 무게와 견주어 봐요.","무게에 쓰는 단위는 g·kg·t.","책상의 무게는 약 15 kg이에요."],"variant_rule":{"alt":[{"stem":"공책 1권의 무게는 약 50 ○예요. ○에 알맞은 단위는 무엇인가요?","options":[{"t":"g","correct":true},{"t":"kg","mis":"M3-2-u5-X09"},{"t":"t","mis":"M3-2-u5-X09"},{"t":"mL","mis":"M3-2-u5-X10"}],"explanation":["공책 1권을 아는 무게와 견주어 봐요.","무게에 쓰는 단위는 g·kg·t.","공책 1권의 무게는 약 50 g이에요."],"asset":null},{"stem":"트럭의 무게는 약 5 ○예요. ○에 알맞은 단위는 무엇인가요?","options":[{"t":"t","correct":true},{"t":"g","mis":"M3-2-u5-X09"},{"t":"kg","mis":"M3-2-u5-X09"},{"t":"mL","mis":"M3-2-u5-X10"}],"explanation":["트럭을 아는 무게와 견주어 봐요.","무게에 쓰는 단위는 g·kg·t.","트럭의 무게는 약 5 t이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_d#9','math',3,2,'u5','','g3_2_math_u5_review_d','unit_review','M3-2-u5-C2',2,'mc','auto','㉮는 5 L 300 mL, ㉯는 5500 mL예요. 들이가 더 많은 것은 무엇인가요?',ARRAY['M3-2-u5-X20','M3-2-u5-X21']::text[],true,'{"seq":9,"concept":"M3-2-u5-C2","difficulty":2,"kind":"mc","stem":"㉮는 5 L 300 mL, ㉯는 5500 mL예요. 들이가 더 많은 것은 무엇인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M3-2-u5-X20"},{"t":"두 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"단위가 달라서 견줄 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["한 가지 단위로 바꾸어 견주어요.","5 L 300 mL = 5300 mL.","5300 mL < 5500 mL — 들이가 더 많은 것은 ㉯예요."],"variant_rule":{"alt":[{"stem":"㉮는 3 L 100 mL, ㉯는 3700 mL예요. 들이가 더 많은 것은 무엇인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M3-2-u5-X20"},{"t":"두 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"단위가 달라서 견줄 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["한 가지 단위로 바꾸어 견주어요.","3 L 100 mL = 3100 mL.","3100 mL < 3700 mL — 들이가 더 많은 것은 ㉯예요."],"asset":null},{"stem":"㉮는 1 L 250 mL, ㉯는 1850 mL예요. 들이가 더 많은 것은 무엇인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M3-2-u5-X20"},{"t":"두 들이가 같아요","mis":"M3-2-u5-X21"},{"t":"단위가 달라서 견줄 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["한 가지 단위로 바꾸어 견주어요.","1 L 250 mL = 1250 mL.","1250 mL < 1850 mL — 들이가 더 많은 것은 ㉯예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_d#10','math',3,2,'u5','','g3_2_math_u5_review_d','unit_review','M3-2-u5-C3',2,'mc','auto','물통의 들이를 어림했어요 — 소율 약 1 L 200 mL, 준우 약 1 L 350 mL, 도윤 약 1 L 450 mL. 재어 보니 1 L 500 mL였어요. 가장 가깝게 어림한 친구는 누구인가요?',ARRAY['M3-2-u5-X08','M3-2-u5-X21']::text[],true,'{"seq":10,"concept":"M3-2-u5-C3","difficulty":2,"kind":"mc","stem":"물통의 들이를 어림했어요 — 소율 약 1 L 200 mL, 준우 약 1 L 350 mL, 도윤 약 1 L 450 mL. 재어 보니 1 L 500 mL였어요. 가장 가깝게 어림한 친구는 누구인가요?","options":[{"t":"도윤","correct":true},{"t":"소율","mis":"M3-2-u5-X08"},{"t":"준우","mis":"M3-2-u5-X08"},{"t":"모두 똑같이 알맞아요","mis":"M3-2-u5-X21"}],"explanation":["잰 값 1 L 500 mL와 어림한 값의 차를 견주어요.","소율 300 mL, 준우 150 mL, 도윤 50 mL 차이.","차가 가장 작은 도윤이 가장 가깝게 어림했어요."],"variant_rule":{"alt":[{"stem":"주스병의 들이를 어림했어요 — 채원 약 1 L 350 mL, 도윤 약 900 mL, 지아 약 1 L 700 mL. 재어 보니 1 L 200 mL였어요. 가장 가깝게 어림한 친구는 누구인가요?","options":[{"t":"채원","correct":true},{"t":"도윤","mis":"M3-2-u5-X08"},{"t":"지아","mis":"M3-2-u5-X08"},{"t":"모두 똑같이 알맞아요","mis":"M3-2-u5-X21"}],"explanation":["잰 값 1 L 200 mL와 어림한 값의 차를 견주어요.","채원 150 mL, 도윤 300 mL, 지아 500 mL 차이.","차가 가장 작은 채원이 가장 가깝게 어림했어요."],"asset":null},{"stem":"세제 통의 들이를 어림했어요 — 정후 약 2 L 100 mL, 소율 약 1 L 750 mL, 준우 약 1 L 300 mL. 재어 보니 1 L 800 mL였어요. 가장 가깝게 어림한 친구는 누구인가요?","options":[{"t":"소율","correct":true},{"t":"정후","mis":"M3-2-u5-X08"},{"t":"준우","mis":"M3-2-u5-X08"},{"t":"모두 똑같이 알맞아요","mis":"M3-2-u5-X21"}],"explanation":["잰 값 1 L 800 mL와 어림한 값의 차를 견주어요.","정후 300 mL, 소율 50 mL, 준우 500 mL 차이.","차가 가장 작은 소율이 가장 가깝게 어림했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_d#11','math',3,2,'u5','','g3_2_math_u5_review_d','unit_review','M3-2-u5-C4',2,'mc','auto','수조에 물이 4 L 800 mL 있어요. 3 L 500 mL를 퍼냈어요. 수조에 남은 물은 얼마인가요?',ARRAY['M3-2-u5-X13','M3-2-u5-X14']::text[],true,'{"seq":11,"concept":"M3-2-u5-C4","difficulty":2,"kind":"mc","stem":"수조에 물이 4 L 800 mL 있어요. 3 L 500 mL를 퍼냈어요. 수조에 남은 물은 얼마인가요?","options":[{"t":"1 L 300 mL","correct":true},{"t":"2 L 300 mL","mis":"M3-2-u5-X13"},{"t":"300 mL","mis":"M3-2-u5-X13"},{"t":"8 L 300 mL","mis":"M3-2-u5-X14"}],"explanation":["mL끼리: 800 − 500 = 300.","L끼리: 4 − 3 = 1.","4 L 800 mL − 3 L 500 mL = 1 L 300 mL."],"variant_rule":{"alt":[{"stem":"세제 5 L 350 mL 중에서 빨래에 1 L 150 mL를 썼어요. 남은 세제는 얼마인가요?","options":[{"t":"4 L 200 mL","correct":true},{"t":"5 L 200 mL","mis":"M3-2-u5-X13"},{"t":"3 L 200 mL","mis":"M3-2-u5-X13"},{"t":"6 L 500 mL","mis":"M3-2-u5-X14"}],"explanation":["mL끼리: 350 − 150 = 200.","L끼리: 5 − 1 = 4.","5 L 350 mL − 1 L 150 mL = 4 L 200 mL."],"asset":null},{"stem":"주전자에 물이 5 L 800 mL 있었는데 2 L 650 mL를 썼어요. 남은 물은 얼마인가요?","options":[{"t":"3 L 150 mL","correct":true},{"t":"4 L 150 mL","mis":"M3-2-u5-X13"},{"t":"2 L 150 mL","mis":"M3-2-u5-X13"},{"t":"8 L 450 mL","mis":"M3-2-u5-X14"}],"explanation":["mL끼리: 800 − 650 = 150.","L끼리: 5 − 2 = 3.","5 L 800 mL − 2 L 650 mL = 3 L 150 mL."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_d#12','math',3,2,'u5','','g3_2_math_u5_review_d','unit_review','M3-2-u5-C5',2,'sa','auto','감자의 무게는 쌓기나무 14개, 양파의 무게는 쌓기나무 16개와 같아요. 양파는 감자보다 쌓기나무 몇 개만큼 더 무거운가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M3-2-u5-C5","difficulty":2,"kind":"sa","stem":"감자의 무게는 쌓기나무 14개, 양파의 무게는 쌓기나무 16개와 같아요. 양파는 감자보다 쌓기나무 몇 개만큼 더 무거운가요? 숫자로 쓰세요.","answer":["2"],"explanation":["같은 쌓기나무로 재었으니 개수로 견줄 수 있어요.","감자 14개, 양파 16개.","16 − 14 = 2 — 쌓기나무 2개만큼 더 무거워요."],"variant_rule":{"alt":[{"stem":"고구마의 무게는 클립 10개, 당근의 무게는 클립 19개와 같아요. 당근은 고구마보다 클립 몇 개만큼 더 무거운가요? 숫자로 쓰세요.","answer":["9"],"explanation":["같은 클립으로 재었으니 개수로 견줄 수 있어요.","고구마 10개, 당근 19개.","19 − 10 = 9 — 클립 9개만큼 더 무거워요."],"asset":null},{"stem":"사과의 무게는 공깃돌 25개, 배의 무게는 공깃돌 8개와 같아요. 사과는 배보다 공깃돌 몇 개만큼 더 무거운가요? 숫자로 쓰세요.","answer":["17"],"explanation":["같은 공깃돌으로 재었으니 개수로 견줄 수 있어요.","사과 25개, 배 8개.","25 − 8 = 17 — 공깃돌 17개만큼 더 무거워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_d#13','math',3,2,'u5','','g3_2_math_u5_review_d','unit_review','M3-2-u5-C6',2,'mc','auto','하윤이 모은 재활용품은 2 kg 50 g, 준우가 모은 재활용품은 2500 g이에요. 누가 더 무겁게 모았나요?',ARRAY['M3-2-u5-X05','M3-2-u5-X21']::text[],true,'{"seq":13,"concept":"M3-2-u5-C6","difficulty":2,"kind":"mc","stem":"하윤이 모은 재활용품은 2 kg 50 g, 준우가 모은 재활용품은 2500 g이에요. 누가 더 무겁게 모았나요?","options":[{"t":"준우","correct":true},{"t":"하윤","mis":"M3-2-u5-X05"},{"t":"두 사람이 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["한 가지 단위로 바꾸어 견주어요.","2 kg 50 g = 2050 g.","2050 g < 2500 g — 준우가 더 무겁게 모았어요."],"variant_rule":{"alt":[{"stem":"도윤이 모은 재활용품은 4 kg 10 g, 하윤이 모은 재활용품은 4100 g이에요. 누가 더 무겁게 모았나요?","options":[{"t":"하윤","correct":true},{"t":"도윤","mis":"M3-2-u5-X05"},{"t":"두 사람이 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["한 가지 단위로 바꾸어 견주어요.","4 kg 10 g = 4010 g.","4010 g < 4100 g — 하윤이 더 무겁게 모았어요."],"asset":null},{"stem":"서준이 모은 재활용품은 4 kg 70 g, 도윤이 모은 재활용품은 4700 g이에요. 누가 더 무겁게 모았나요?","options":[{"t":"도윤","correct":true},{"t":"서준","mis":"M3-2-u5-X05"},{"t":"두 사람이 같아요","mis":"M3-2-u5-X21"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["한 가지 단위로 바꾸어 견주어요.","4 kg 70 g = 4070 g.","4070 g < 4700 g — 도윤이 더 무겁게 모았어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_d#14','math',3,2,'u5','','g3_2_math_u5_review_d','unit_review','M3-2-u5-C7',2,'mc','auto','잘못 나타낸 것은 무엇인가요?',ARRAY['M3-2-u5-X21']::text[],true,'{"seq":14,"concept":"M3-2-u5-C7","difficulty":2,"kind":"mc","stem":"잘못 나타낸 것은 무엇인가요?","options":[{"t":"7 t은 700 kg이에요","correct":true},{"t":"8 t은 8000 kg이에요","mis":"M3-2-u5-X21"},{"t":"8850 g은 8 kg 850 g이에요","mis":"M3-2-u5-X21"},{"t":"1 t은 1000 kg이에요","mis":"M3-2-u5-X21"}],"explanation":["1 t = 1000 kg, 1 kg = 1000 g.","7 t = 7000 kg이에요.","「7 t은 700 kg이에요」 — 1 t을 100 kg으로 본 잘못이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 잘못 나타낸 것은 무엇인가요?","options":[{"t":"7 t은 700 kg이에요","correct":true},{"t":"3 t은 3000 kg이에요","mis":"M3-2-u5-X21"},{"t":"2190 g은 2 kg 190 g이에요","mis":"M3-2-u5-X21"},{"t":"1 t은 1000 kg이에요","mis":"M3-2-u5-X21"}],"explanation":["1 t = 1000 kg, 1 kg = 1000 g.","7 t = 7000 kg이에요.","「7 t은 700 kg이에요」 — 1 t을 100 kg으로 본 잘못이에요."],"asset":null},{"stem":"이번에는 다른 문제예요. 잘못 나타낸 것은 무엇인가요?","options":[{"t":"9 t은 900 kg이에요","correct":true},{"t":"6 t은 6000 kg이에요","mis":"M3-2-u5-X21"},{"t":"3430 g은 3 kg 430 g이에요","mis":"M3-2-u5-X21"},{"t":"1 t은 1000 kg이에요","mis":"M3-2-u5-X21"}],"explanation":["1 t = 1000 kg, 1 kg = 1000 g.","9 t = 9000 kg이에요.","「9 t은 900 kg이에요」 — 1 t을 100 kg으로 본 잘못이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_d#15','math',3,2,'u5','','g3_2_math_u5_review_d','unit_review','M3-2-u5-C9',2,'mc','auto','채원이는 4 kg 550 g, 도윤이는 4 kg 240 g의 옷을 모아 기부했어요. 두 사람이 모은 옷은 모두 얼마인가요?',ARRAY['M3-2-u5-X12','M3-2-u5-X14']::text[],true,'{"seq":15,"concept":"M3-2-u5-C9","difficulty":2,"kind":"mc","stem":"채원이는 4 kg 550 g, 도윤이는 4 kg 240 g의 옷을 모아 기부했어요. 두 사람이 모은 옷은 모두 얼마인가요?","options":[{"t":"8 kg 790 g","correct":true},{"t":"9 kg 790 g","mis":"M3-2-u5-X12"},{"t":"310 g","mis":"M3-2-u5-X14"},{"t":"7 kg 790 g","mis":"M3-2-u5-X12"}],"explanation":["g끼리: 550 + 240 = 790.","kg끼리: 4 + 4 = 8.","4 kg 550 g + 4 kg 240 g = 8 kg 790 g."],"variant_rule":{"alt":[{"stem":"여행 가방이 5 kg 500 g이에요. 4 kg 200 g의 짐을 더 넣으면 모두 얼마인가요?","options":[{"t":"9 kg 700 g","correct":true},{"t":"10 kg 700 g","mis":"M3-2-u5-X12"},{"t":"1 kg 300 g","mis":"M3-2-u5-X14"},{"t":"8 kg 700 g","mis":"M3-2-u5-X12"}],"explanation":["g끼리: 500 + 200 = 700.","kg끼리: 5 + 4 = 9.","5 kg 500 g + 4 kg 200 g = 9 kg 700 g."],"asset":null},{"stem":"준우는 5 kg 750 g, 소율이는 2 kg 200 g의 재활용품을 모았어요. 두 사람이 모은 재활용품은 모두 얼마인가요?","options":[{"t":"7 kg 950 g","correct":true},{"t":"8 kg 950 g","mis":"M3-2-u5-X12"},{"t":"3 kg 550 g","mis":"M3-2-u5-X14"},{"t":"6 kg 950 g","mis":"M3-2-u5-X12"}],"explanation":["g끼리: 750 + 200 = 950.","kg끼리: 5 + 2 = 7.","5 kg 750 g + 2 kg 200 g = 7 kg 950 g."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_d#16','math',3,2,'u5','','g3_2_math_u5_review_d','unit_review','M3-2-u5-C10',2,'sa','auto','우유 90 L를 남김없이 나누어 담아요. 10 L 통 6개를 썼어요. 6 L 통은 몇 개 써야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M3-2-u5-C10","difficulty":2,"kind":"sa","stem":"우유 90 L를 남김없이 나누어 담아요. 10 L 통 6개를 썼어요. 6 L 통은 몇 개 써야 하나요? 숫자로 쓰세요.","answer":["5"],"explanation":["지금까지 담은 양: 60 L.","남은 양: 90 − 60 = 30 L.","30 ÷ 6 = 5 — 6 L 통 5개."],"variant_rule":{"alt":[{"stem":"우유 90 L를 남김없이 나누어 담아요. 6 L 통 5개, 5 L 통 6개를 썼어요. 10 L 통은 몇 개 써야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["지금까지 담은 양: 60 L.","남은 양: 90 − 60 = 30 L.","30 ÷ 10 = 3 — 10 L 통 3개."],"asset":null},{"stem":"우유 90 L를 남김없이 나누어 담아요. 10 L 통 4개, 6 L 통 5개를 썼어요. 5 L 통은 몇 개 써야 하나요? 숫자로 쓰세요.","answer":["4"],"explanation":["지금까지 담은 양: 70 L.","남은 양: 90 − 70 = 20 L.","20 ÷ 5 = 4 — 5 L 통 4개."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_d#17','math',3,2,'u5','','g3_2_math_u5_review_d','unit_review','M3-2-u5-C1',3,'mc','auto','㉮ 물통은 큰 컵으로 7번, ㉯ 물통은 작은 컵으로 8번 부어 가득 채웠어요. 이것만 보고 들이를 바르게 말한 것은 무엇인가요?',ARRAY['M3-2-u5-X03','M3-2-u5-X21']::text[],true,'{"seq":17,"concept":"M3-2-u5-C1","difficulty":3,"kind":"mc","stem":"㉮ 물통은 큰 컵으로 7번, ㉯ 물통은 작은 컵으로 8번 부어 가득 채웠어요. 이것만 보고 들이를 바르게 말한 것은 무엇인가요?","options":[{"t":"재는 컵이 달라서 알 수 없어요","correct":true},{"t":"㉯ 물통의 들이가 더 많아요","mis":"M3-2-u5-X03"},{"t":"㉮ 물통의 들이가 더 많아요","mis":"M3-2-u5-X03"},{"t":"두 물통의 들이가 같아요","mis":"M3-2-u5-X21"}],"explanation":["㉮는 큰 컵, ㉯는 작은 컵 — 재는 그릇이 달라요.","횟수만으로는 들이를 견줄 수 없어요.","같은 컵(같은 단위)으로 재야 견줄 수 있어요."],"variant_rule":{"alt":[{"stem":"㉮ 물통은 큰 컵으로 5번, ㉯ 물통은 작은 컵으로 6번 부어 가득 채웠어요. 이것만 보고 들이를 바르게 말한 것은 무엇인가요?","options":[{"t":"재는 컵이 달라서 알 수 없어요","correct":true},{"t":"㉯ 물통의 들이가 더 많아요","mis":"M3-2-u5-X03"},{"t":"㉮ 물통의 들이가 더 많아요","mis":"M3-2-u5-X03"},{"t":"두 물통의 들이가 같아요","mis":"M3-2-u5-X21"}],"explanation":["㉮는 큰 컵, ㉯는 작은 컵 — 재는 그릇이 달라요.","횟수만으로는 들이를 견줄 수 없어요.","같은 컵(같은 단위)으로 재야 견줄 수 있어요."],"asset":null},{"stem":"㉮ 물통은 큰 컵으로 3번, ㉯ 물통은 작은 컵으로 8번 부어 가득 채웠어요. 이것만 보고 들이를 바르게 말한 것은 무엇인가요?","options":[{"t":"재는 컵이 달라서 알 수 없어요","correct":true},{"t":"㉯ 물통의 들이가 더 많아요","mis":"M3-2-u5-X03"},{"t":"㉮ 물통의 들이가 더 많아요","mis":"M3-2-u5-X03"},{"t":"두 물통의 들이가 같아요","mis":"M3-2-u5-X21"}],"explanation":["㉮는 큰 컵, ㉯는 작은 컵 — 재는 그릇이 달라요.","횟수만으로는 들이를 견줄 수 없어요.","같은 컵(같은 단위)으로 재야 견줄 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_d#18','math',3,2,'u5','','g3_2_math_u5_review_d','unit_review','M3-2-u5-C4',3,'mc','auto','식혜가 한 병에 2 L 950 mL, 다른 병에 4 L 750 mL 있어요. 식혜는 모두 얼마인가요?',ARRAY['M3-2-u5-X12','M3-2-u5-X14']::text[],true,'{"seq":18,"concept":"M3-2-u5-C4","difficulty":3,"kind":"mc","stem":"식혜가 한 병에 2 L 950 mL, 다른 병에 4 L 750 mL 있어요. 식혜는 모두 얼마인가요?","options":[{"t":"7 L 700 mL","correct":true},{"t":"6 L 1700 mL","mis":"M3-2-u5-X12"},{"t":"6 L 700 mL","mis":"M3-2-u5-X12"},{"t":"1 L 800 mL","mis":"M3-2-u5-X14"}],"explanation":["mL끼리: 950 + 750 = 1700 — 1000 mL = 1 L로 올려요.","L끼리: 1 + 2 + 4 = 7.","2 L 950 mL + 4 L 750 mL = 7 L 700 mL."],"variant_rule":{"alt":[{"stem":"간장병에는 1 L 940 mL, 주스병에는 4 L 960 mL 들어 있어요. 두 병에 든 양은 모두 얼마인가요?","options":[{"t":"6 L 900 mL","correct":true},{"t":"5 L 1900 mL","mis":"M3-2-u5-X12"},{"t":"5 L 900 mL","mis":"M3-2-u5-X12"},{"t":"3 L 20 mL","mis":"M3-2-u5-X14"}],"explanation":["mL끼리: 940 + 960 = 1900 — 1000 mL = 1 L로 올려요.","L끼리: 1 + 1 + 4 = 6.","1 L 940 mL + 4 L 960 mL = 6 L 900 mL."],"asset":null},{"stem":"물통에 물이 2 L 250 mL 있었는데 3 L 950 mL를 더 부었어요. 물통의 물은 모두 얼마인가요?","options":[{"t":"6 L 200 mL","correct":true},{"t":"5 L 1200 mL","mis":"M3-2-u5-X12"},{"t":"5 L 200 mL","mis":"M3-2-u5-X12"},{"t":"1 L 700 mL","mis":"M3-2-u5-X14"}],"explanation":["mL끼리: 250 + 950 = 1200 — 1000 mL = 1 L로 올려요.","L끼리: 1 + 2 + 3 = 6.","2 L 250 mL + 3 L 950 mL = 6 L 200 mL."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_d#19','math',3,2,'u5','','g3_2_math_u5_review_d','unit_review','M3-2-u5-C5',3,'mc','auto','양팔저울 두 개로 키위, 레몬, 감의 무게를 견주었어요. 가장 무거운 것은 무엇인가요?',ARRAY['M3-2-u5-X20','M3-2-u5-X15','M3-2-u5-X21']::text[],true,'{"seq":19,"concept":"M3-2-u5-C5","difficulty":3,"kind":"mc","stem":"양팔저울 두 개로 키위, 레몬, 감의 무게를 견주었어요. 가장 무거운 것은 무엇인가요?","options":[{"t":"레몬","correct":true},{"t":"키위","mis":"M3-2-u5-X20"},{"t":"감","mis":"M3-2-u5-X15"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["저울마다 내려간 쪽이 더 무거워요.","레몬 > 감, 감 > 키위.","무게 순서 레몬 > 감 > 키위 — 가장 무거운 것은 레몬이에요."],"asset":{"type":"balance","scales":[{"l":{"name":"감","icon":"🟠"},"r":{"name":"레몬","icon":"🍋"},"down":"r"},{"l":{"name":"감","icon":"🟠"},"r":{"name":"키위","icon":"🥝"},"down":"l"}]},"variant_rule":{"alt":[{"stem":"양팔저울 두 개로 ㉮ 주머니, ㉯ 주머니, ㉰ 주머니의 무게를 견주었어요. 가장 무거운 것은 무엇인가요?","options":[{"t":"㉰ 주머니","correct":true},{"t":"㉯ 주머니","mis":"M3-2-u5-X20"},{"t":"㉮ 주머니","mis":"M3-2-u5-X15"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["저울마다 내려간 쪽이 더 무거워요.","㉰ 주머니 > ㉮ 주머니, ㉮ 주머니 > ㉯ 주머니.","무게 순서 ㉰ 주머니 > ㉮ 주머니 > ㉯ 주머니 — 가장 무거운 것은 ㉰ 주머니예요."],"asset":{"type":"balance","scales":[{"l":{"name":"㉰ 주머니","icon":"👜"},"r":{"name":"㉮ 주머니","icon":"👜"},"down":"l"},{"l":{"name":"㉯ 주머니","icon":"👜"},"r":{"name":"㉮ 주머니","icon":"👜"},"down":"r"}]}},{"stem":"양팔저울 두 개로 빨간 상자, 파란 상자, 노란 상자의 무게를 견주었어요. 가장 무거운 것은 무엇인가요?","options":[{"t":"파란 상자","correct":true},{"t":"빨간 상자","mis":"M3-2-u5-X20"},{"t":"노란 상자","mis":"M3-2-u5-X15"},{"t":"알 수 없어요","mis":"M3-2-u5-X21"}],"explanation":["저울마다 내려간 쪽이 더 무거워요.","파란 상자 > 노란 상자, 노란 상자 > 빨간 상자.","무게 순서 파란 상자 > 노란 상자 > 빨간 상자 — 가장 무거운 것은 파란 상자예요."],"asset":{"type":"balance","scales":[{"l":{"name":"노란 상자","icon":"📦"},"r":{"name":"파란 상자","icon":"📦"},"down":"r"},{"l":{"name":"노란 상자","icon":"📦"},"r":{"name":"빨간 상자","icon":"📦"},"down":"l"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_d#20','math',3,2,'u5','','g3_2_math_u5_review_d','unit_review','M3-2-u5-C8',3,'mc','auto','저울의 큰 눈금 0과 1 kg 사이가 똑같이 4칸으로 나뉘어 있어요. 빨랫비누 상자를 재었더니 바늘이 0에서부터 10칸째 눈금을 가리켜요. 몇 g인가요?',ARRAY['M3-2-u5-X07']::text[],true,'{"seq":20,"concept":"M3-2-u5-C8","difficulty":3,"kind":"mc","stem":"저울의 큰 눈금 0과 1 kg 사이가 똑같이 4칸으로 나뉘어 있어요. 빨랫비누 상자를 재었더니 바늘이 0에서부터 10칸째 눈금을 가리켜요. 몇 g인가요?","options":[{"t":"2500 g","correct":true},{"t":"10 g","mis":"M3-2-u5-X07"},{"t":"1000 g","mis":"M3-2-u5-X07"},{"t":"2750 g","mis":"M3-2-u5-X07"}],"explanation":["한 칸의 크기부터: 1 kg = 1000 g, 1000 ÷ 4 = 250 g.","10칸 → 250 × 10 = 2500.","2500 g이에요."],"variant_rule":{"alt":[{"stem":"저울의 큰 눈금 0과 1 kg 사이가 똑같이 10칸으로 나뉘어 있어요. 사과를 재었더니 바늘이 0에서부터 15칸째 눈금을 가리켜요. 몇 g인가요?","options":[{"t":"1500 g","correct":true},{"t":"15 g","mis":"M3-2-u5-X07"},{"t":"150 g","mis":"M3-2-u5-X07"},{"t":"1600 g","mis":"M3-2-u5-X07"}],"explanation":["한 칸의 크기부터: 1 kg = 1000 g, 1000 ÷ 10 = 100 g.","15칸 → 100 × 15 = 1500.","1500 g이에요."],"asset":null},{"stem":"저울의 큰 눈금 0과 1 kg 사이가 똑같이 5칸으로 나뉘어 있어요. 현미를 재었더니 바늘이 0에서부터 9칸째 눈금을 가리켜요. 몇 g인가요?","options":[{"t":"1800 g","correct":true},{"t":"9 g","mis":"M3-2-u5-X07"},{"t":"900 g","mis":"M3-2-u5-X07"},{"t":"2000 g","mis":"M3-2-u5-X07"}],"explanation":["한 칸의 크기부터: 1 kg = 1000 g, 1000 ÷ 5 = 200 g.","9칸 → 200 × 9 = 1800.","1800 g이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_d#21','math',3,2,'u5','','g3_2_math_u5_review_d','unit_review','M3-2-u5-C9',3,'mc','auto','흙 6 kg 100 g 중에서 4 kg 250 g을 화분에 담았어요. 남은 흙은 얼마인가요?',ARRAY['M3-2-u5-X13','M3-2-u5-X14']::text[],true,'{"seq":21,"concept":"M3-2-u5-C9","difficulty":3,"kind":"mc","stem":"흙 6 kg 100 g 중에서 4 kg 250 g을 화분에 담았어요. 남은 흙은 얼마인가요?","options":[{"t":"1 kg 850 g","correct":true},{"t":"2 kg 150 g","mis":"M3-2-u5-X13"},{"t":"2 kg 850 g","mis":"M3-2-u5-X13"},{"t":"10 kg 350 g","mis":"M3-2-u5-X14"}],"explanation":["100 g에서 250을 뺄 수 없어 1 kg을 1000 g으로 내려요: 1100 − 250 = 850.","kg끼리: 6 − 1 − 4 = 1.","6 kg 100 g − 4 kg 250 g = 1 kg 850 g."],"variant_rule":{"alt":[{"stem":"밀가루 3 kg 540 g 중에서 2 kg 860 g을 빵 만들기에 썼어요. 남은 밀가루는 얼마인가요?","options":[{"t":"680 g","correct":true},{"t":"1 kg 320 g","mis":"M3-2-u5-X13"},{"t":"1 kg 680 g","mis":"M3-2-u5-X13"},{"t":"6 kg 400 g","mis":"M3-2-u5-X14"}],"explanation":["540 g에서 860을 뺄 수 없어 1 kg을 1000 g으로 내려요: 1540 − 860 = 680.","kg끼리: 3 − 1 − 2 = 0.","3 kg 540 g − 2 kg 860 g = 680 g."],"asset":null},{"stem":"재활용품 9 kg 50 g 중에서 7 kg 900 g을 먼저 보냈어요. 남은 재활용품은 얼마인가요?","options":[{"t":"1 kg 150 g","correct":true},{"t":"2 kg 850 g","mis":"M3-2-u5-X13"},{"t":"2 kg 150 g","mis":"M3-2-u5-X13"},{"t":"16 kg 950 g","mis":"M3-2-u5-X14"}],"explanation":["50 g에서 900을 뺄 수 없어 1 kg을 1000 g으로 내려요: 1050 − 900 = 150.","kg끼리: 9 − 1 − 7 = 1.","9 kg 50 g − 7 kg 900 g = 1 kg 150 g."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_d#22','math',3,2,'u5','','g3_2_math_u5_review_d','unit_review','M3-2-u5-C10',3,'mc','auto','사료 30 kg을 5 kg, 4 kg, 2 kg 봉지(각각 5개)에 남김없이 나누어 담는 방법은 무엇인가요?',ARRAY['M3-2-u5-X18']::text[],true,'{"seq":22,"concept":"M3-2-u5-C10","difficulty":3,"kind":"mc","stem":"사료 30 kg을 5 kg, 4 kg, 2 kg 봉지(각각 5개)에 남김없이 나누어 담는 방법은 무엇인가요?","options":[{"t":"5 kg 봉지 4개, 4 kg 봉지 1개, 2 kg 봉지 3개","correct":true},{"t":"5 kg 봉지 6개, 2 kg 봉지 5개","mis":"M3-2-u5-X18"},{"t":"5 kg 봉지 6개, 2 kg 봉지 3개","mis":"M3-2-u5-X18"},{"t":"5 kg 봉지 5개, 4 kg 봉지 3개, 2 kg 봉지 4개","mis":"M3-2-u5-X18"}],"explanation":["보기마다 담은 양을 모두 더해 30 kg과 견주어요.","5 kg 봉지 4개, 4 kg 봉지 1개, 2 kg 봉지 3개 → 20 + 4 + 6 = 30 kg.","남김없이 꼭 맞는 것은 이것뿐이에요."],"variant_rule":{"alt":[{"stem":"우유 60 L를 10 L, 6 L, 5 L 통(각각 5개)에 남김없이 나누어 담는 방법은 무엇인가요?","options":[{"t":"10 L 통 1개, 6 L 통 5개, 5 L 통 4개","correct":true},{"t":"10 L 통 3개, 6 L 통 6개, 5 L 통 5개","mis":"M3-2-u5-X18"},{"t":"6 L 통 6개, 5 L 통 6개","mis":"M3-2-u5-X18"},{"t":"6 L 통 6개, 5 L 통 5개","mis":"M3-2-u5-X18"}],"explanation":["보기마다 담은 양을 모두 더해 60 L와 견주어요.","10 L 통 1개, 6 L 통 5개, 5 L 통 4개 → 10 + 30 + 20 = 60 L.","남김없이 꼭 맞는 것은 이것뿐이에요."],"asset":null},{"stem":"우유 70 L를 10 L, 6 L, 5 L 통(각각 6개)에 남김없이 나누어 담는 방법은 무엇인가요?","options":[{"t":"10 L 통 4개, 5 L 통 6개","correct":true},{"t":"10 L 통 3개, 5 L 통 6개","mis":"M3-2-u5-X18"},{"t":"10 L 통 3개, 6 L 통 1개, 5 L 통 8개","mis":"M3-2-u5-X18"},{"t":"10 L 통 4개, 6 L 통 1개, 5 L 통 7개","mis":"M3-2-u5-X18"}],"explanation":["보기마다 담은 양을 모두 더해 70 L와 견주어요.","10 L 통 4개, 5 L 통 6개 → 40 + 30 = 70 L.","남김없이 꼭 맞는 것은 이것뿐이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_d#23','math',3,2,'u5','','g3_2_math_u5_review_d','unit_review','M3-2-u5-C4',4,'mc','auto','물통의 들이는 2 L 100 mL예요. 그릇의 물은 ㉮ 900 mL, ㉯ 1 L 100 mL, ㉰ 300 mL, ㉱ 1 L 300 mL예요. 두 그릇을 골라 물통에 부어 넘치지 않으면서 가장 많이 채우려면 어느 두 그릇을 골라야 하나요?',ARRAY['M3-2-u5-X18','M3-2-u5-X20']::text[],true,'{"seq":23,"concept":"M3-2-u5-C4","difficulty":4,"kind":"mc","stem":"물통의 들이는 2 L 100 mL예요. 그릇의 물은 ㉮ 900 mL, ㉯ 1 L 100 mL, ㉰ 300 mL, ㉱ 1 L 300 mL예요. 두 그릇을 골라 물통에 부어 넘치지 않으면서 가장 많이 채우려면 어느 두 그릇을 골라야 하나요?","options":[{"t":"㉮, ㉯","correct":true},{"t":"㉮, ㉱","mis":"M3-2-u5-X18"},{"t":"㉯, ㉱","mis":"M3-2-u5-X18"},{"t":"㉰, ㉱","mis":"M3-2-u5-X20"}],"explanation":["두 그릇씩 더해 2 L 100 mL와 견주어요.","㉮, ㉯: 900 mL + 1 L 100 mL = 2 L.","넘치지 않는 합 가운데 가장 커요."],"variant_rule":{"alt":[{"stem":"물통의 들이는 1 L 700 mL예요. 그릇의 물은 ㉮ 600 mL, ㉯ 400 mL, ㉰ 700 mL, ㉱ 1 L 400 mL예요. 두 그릇을 골라 물통에 부어 넘치지 않으면서 가장 많이 채우려면 어느 두 그릇을 골라야 하나요?","options":[{"t":"㉮, ㉰","correct":true},{"t":"㉮, ㉱","mis":"M3-2-u5-X18"},{"t":"㉯, ㉱","mis":"M3-2-u5-X18"},{"t":"㉯, ㉰","mis":"M3-2-u5-X20"}],"explanation":["두 그릇씩 더해 1 L 700 mL와 견주어요.","㉮, ㉰: 600 mL + 700 mL = 1 L 300 mL.","넘치지 않는 합 가운데 가장 커요."],"asset":null},{"stem":"물통의 들이는 2 L예요. 그릇의 물은 ㉮ 600 mL, ㉯ 1 L 100 mL, ㉰ 1 L 200 mL, ㉱ 1 L예요. 두 그릇을 골라 물통에 부어 넘치지 않으면서 가장 많이 채우려면 어느 두 그릇을 골라야 하나요?","options":[{"t":"㉮, ㉰","correct":true},{"t":"㉯, ㉰","mis":"M3-2-u5-X18"},{"t":"㉯, ㉱","mis":"M3-2-u5-X18"},{"t":"㉮, ㉯","mis":"M3-2-u5-X20"}],"explanation":["두 그릇씩 더해 2 L와 견주어요.","㉮, ㉰: 600 mL + 1 L 200 mL = 1 L 800 mL.","넘치지 않는 합 가운데 가장 커요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_d#24','math',3,2,'u5','','g3_2_math_u5_review_d','unit_review','M3-2-u5-C10',4,'sa','auto','40 L를 10 L 통 4개, 5 L 통 8개에 남김없이 나누어 담는 방법은 모두 몇 가지인가요? 쓰지 않는 통이 있어도 돼요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M3-2-u5-C10","difficulty":4,"kind":"sa","stem":"40 L를 10 L 통 4개, 5 L 통 8개에 남김없이 나누어 담는 방법은 모두 몇 가지인가요? 쓰지 않는 통이 있어도 돼요. 숫자로 쓰세요.","answer":["5"],"explanation":["표로 큰 통부터 개수를 하나씩 바꾸어 봐요.","합이 40 L인 것만 세어요.","모두 5가지예요."],"variant_rule":{"alt":[{"stem":"20 kg을 5 kg 봉지 4개, 2 kg 봉지 10개에 남김없이 나누어 담는 방법은 모두 몇 가지인가요? 쓰지 않는 봉지가 있어도 돼요. 숫자로 쓰세요.","answer":["3"],"explanation":["표로 큰 봉지부터 개수를 하나씩 바꾸어 봐요.","합이 20 kg인 것만 세어요.","모두 3가지예요."],"asset":null},{"stem":"30 kg을 5 kg 봉지 6개, 3 kg 봉지 10개에 남김없이 나누어 담는 방법은 모두 몇 가지인가요? 쓰지 않는 봉지가 있어도 돼요. 숫자로 쓰세요.","answer":["3"],"explanation":["표로 큰 봉지부터 개수를 하나씩 바꾸어 봐요.","합이 30 kg인 것만 세어요.","모두 3가지예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u5_review_d#25','math',3,2,'u5','','g3_2_math_u5_review_d','unit_review','M3-2-u5-C8',4,'essay','teacher','재활용품 1 kg마다 교환권을 1장 줘요. 승우는 1300 g, 연아는 1100 g을 모았어요. 두 사람은 교환권을 몇 장씩 받는지 쓰고, 그렇게 생각한 까닭을 kg과 g의 관계로 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u5-C8","difficulty":4,"kind":"essay","stem":"재활용품 1 kg마다 교환권을 1장 줘요. 승우는 1300 g, 연아는 1100 g을 모았어요. 두 사람은 교환권을 몇 장씩 받는지 쓰고, 그렇게 생각한 까닭을 kg과 g의 관계로 설명해 보세요.","answer_guide":{"answer":"예: 둘 다 1장씩 받는다. 1300 g = 1 kg 300 g, 1100 g = 1 kg 100 g이라 두 사람 모두 1 kg은 넘지만 2 kg(2000 g)에는 모자라기 때문이다.","scoring_points":["둘 다 1장이라고 답했는가","1300 g·1100 g을 몇 kg 몇 g으로 바꾸었는가","2 kg에 모자란다고 설명했는가"]},"explanation":["1300 g = 1 kg 300 g.","1100 g = 1 kg 100 g.","둘 다 1 kg 이상 2 kg 미만 — 1장씩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
